CREATE OR REPLACE FUNCTION "extensions"."grant_pg_cron_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


ALTER FUNCTION "extensions"."grant_pg_cron_access"() OWNER TO "supabase_admin";


COMMENT ON FUNCTION "extensions"."grant_pg_cron_access"() IS 'Grants access to pg_cron';



CREATE OR REPLACE FUNCTION "extensions"."grant_pg_graphql_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


ALTER FUNCTION "extensions"."grant_pg_graphql_access"() OWNER TO "supabase_admin";


COMMENT ON FUNCTION "extensions"."grant_pg_graphql_access"() IS 'Grants access to pg_graphql';



CREATE OR REPLACE FUNCTION "extensions"."grant_pg_net_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "extensions"."grant_pg_net_access"() OWNER TO "supabase_admin";


COMMENT ON FUNCTION "extensions"."grant_pg_net_access"() IS 'Grants access to pg_net';



CREATE OR REPLACE FUNCTION "extensions"."pgrst_ddl_watch"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION "extensions"."pgrst_ddl_watch"() OWNER TO "supabase_admin";


CREATE OR REPLACE FUNCTION "extensions"."pgrst_drop_watch"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION "extensions"."pgrst_drop_watch"() OWNER TO "supabase_admin";


CREATE OR REPLACE FUNCTION "extensions"."set_graphql_placeholder"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION "extensions"."set_graphql_placeholder"() OWNER TO "supabase_admin";


COMMENT ON FUNCTION "extensions"."set_graphql_placeholder"() IS 'Reintroduces placeholder function for graphql_public.graphql';



CREATE OR REPLACE FUNCTION "public"."accept_invitation"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_user_name text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
  v_access_permissions jsonb := '{}'::jsonb;
  v_role_id uuid;
  v_profile_context record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT
    email,
    COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1))
  INTO v_user_email, v_user_name
  FROM auth.users
  WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now())
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');
  v_access_permissions := CASE
    WHEN jsonb_typeof(v_invite.metadata->'permissions') = 'object' THEN v_invite.metadata->'permissions'
    WHEN jsonb_typeof(v_invite.metadata->'access') = 'object' THEN v_invite.metadata->'access'
    ELSE '{}'::jsonb
  END;

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  SELECT id INTO v_role_id
  FROM public.roles
  WHERE name = v_role
    AND (is_system = true OR organization_id = v_invite.organization_id)
  ORDER BY is_system ASC
  LIMIT 1;

  IF v_role_id IS NOT NULL AND v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role_id, location_id, organization_id)
    VALUES (v_user_id, v_role_id, v_invite.location_id, v_invite.organization_id)
    ON CONFLICT (user_id, role_id) DO UPDATE
      SET location_id = EXCLUDED.location_id,
          organization_id = EXCLUDED.organization_id;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    tenant_id,
    role,
    organization_id,
    brand_id,
    location_id,
    coupon_code,
    payment_verified,
    business_verification_status,
    onboarding_status,
    onboarding_current_step,
    access_permissions,
    is_active
  )
  VALUES (
    v_user_id,
    v_user_email,
    COALESCE(v_user_name, split_part(v_user_email, '@', 1), 'User'),
    v_tenant_id,
    v_role,
    v_invite.organization_id,
    v_invite.brand_id,
    v_invite.location_id,
    v_coupon_code,
    false,
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
      ELSE 'not_started'
    END,
    'not_started',
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
      ELSE 'business_verification'
    END,
    v_access_permissions,
    true
  )
  ON CONFLICT (id) DO UPDATE
  SET email = EXCLUDED.email,
      full_name = COALESCE(NULLIF(public.profiles.full_name, ''), EXCLUDED.full_name),
      tenant_id = COALESCE(EXCLUDED.tenant_id, public.profiles.tenant_id),
      role = EXCLUDED.role,
      organization_id = COALESCE(EXCLUDED.organization_id, public.profiles.organization_id),
      brand_id = COALESCE(EXCLUDED.brand_id, public.profiles.brand_id),
      location_id = COALESCE(EXCLUDED.location_id, public.profiles.location_id),
      coupon_code = COALESCE(EXCLUDED.coupon_code, public.profiles.coupon_code),
      access_permissions = CASE WHEN v_access_permissions = '{}'::jsonb THEN public.profiles.access_permissions ELSE v_access_permissions END,
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE public.profiles.business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE public.profiles.onboarding_current_step
      END,
      is_active = true,
      updated_at = now();

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code,
        'permissions', v_access_permissions
      )
  WHERE id = v_invite.id
    AND accepted_at IS NULL
    AND closed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  SELECT
    role,
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    access_permissions
  INTO v_profile_context
  FROM public.profiles
  WHERE id = v_user_id;

  PERFORM public.sync_auth_metadata_from_profile(v_user_id);

  RETURN jsonb_build_object(
    'success', true,
    'role', v_profile_context.role,
    'tenant_id', v_profile_context.tenant_id,
    'organization_id', v_profile_context.organization_id,
    'brand_id', v_profile_context.brand_id,
    'location_id', v_profile_context.location_id,
    'access_permissions', v_profile_context.access_permissions,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;


ALTER FUNCTION "public"."accept_invitation"("p_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_invitation"("p_token" "text") IS 'Accepts a pending invitation by token. Safely maps old role names to new role names, assigns the user their invited role/org/brand/location, and syncs JWT metadata.';



CREATE OR REPLACE FUNCTION "public"."access_membership_readable"("p_target_user" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org uuid;
  v_tenant uuid;
  v_brand uuid;
  v_location uuid;
  v_target_org uuid;
  v_target_tenant uuid;
  v_target_brand uuid;
  v_target_location uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_target_user = auth.uid() THEN
    RETURN true;
  END IF;

  SELECT p.role, p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_role, v_org, v_tenant, v_brand, v_location
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  v_role := public.normalize_app_role(v_role);

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  SELECT p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_target_org, v_target_tenant, v_target_brand, v_target_location
  FROM public.profiles p
  WHERE p.id = p_target_user;

  v_target_org := COALESCE(v_target_org, p_organization_id);
  v_target_location := COALESCE(v_target_location, p_location_id);
  v_target_brand := COALESCE(v_target_brand, p_brand_id);

  IF v_target_tenant IS NULL AND v_target_org IS NOT NULL THEN
    SELECT tenant_id INTO v_target_tenant FROM public.organizations WHERE id = v_target_org;
  END IF;

  IF v_tenant IS NULL AND v_org IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant FROM public.organizations WHERE id = v_org;
  END IF;

  IF v_target_brand IS NULL AND v_target_location IS NOT NULL THEN
    SELECT l.brand_id INTO v_target_brand FROM public.locations l WHERE l.id = v_target_location;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_tenant IS NOT NULL AND v_target_tenant = v_tenant;
  END IF;

  IF v_org IS NULL OR v_target_org IS DISTINCT FROM v_org THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN v_brand IS NOT NULL AND v_target_brand = v_brand;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN v_location IS NOT NULL AND v_target_location = v_location;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."access_membership_readable"("p_target_user" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."access_membership_writable"("p_target_user" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_granted_role" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org uuid;
  v_tenant uuid;
  v_brand uuid;
  v_location uuid;
  v_target_org uuid;
  v_target_tenant uuid;
  v_target_brand uuid;
  v_target_location uuid;
  v_granted_role text;
  v_caller_rank integer;
  v_grant_rank integer;
BEGIN
  IF auth.uid() IS NULL OR p_target_user IS NULL OR p_target_user = auth.uid() THEN
    RETURN false;
  END IF;

  SELECT p.role, p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_role, v_org, v_tenant, v_brand, v_location
  FROM public.profiles p
  WHERE p.id = auth.uid();

  v_role := public.normalize_app_role(v_role);

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  SELECT p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_target_org, v_target_tenant, v_target_brand, v_target_location
  FROM public.profiles p
  WHERE p.id = p_target_user;

  v_target_org := COALESCE(v_target_org, p_organization_id);
  v_target_location := COALESCE(v_target_location, p_location_id);
  v_target_brand := COALESCE(v_target_brand, p_brand_id);

  IF v_target_tenant IS NULL AND v_target_org IS NOT NULL THEN
    SELECT tenant_id INTO v_target_tenant FROM public.organizations WHERE id = v_target_org;
  END IF;

  IF v_tenant IS NULL AND v_org IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant FROM public.organizations WHERE id = v_org;
  END IF;

  IF v_target_brand IS NULL AND v_target_location IS NOT NULL THEN
    SELECT l.brand_id INTO v_target_brand FROM public.locations l WHERE l.id = v_target_location;
  END IF;

  v_granted_role := COALESCE(public.normalize_app_role(p_granted_role), 'ground_staff');
  v_caller_rank := public.access_role_rank(v_role);
  v_grant_rank := public.access_role_rank(v_granted_role);

  IF v_caller_rank = 0 OR v_grant_rank = 0 OR v_grant_rank >= v_caller_rank THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_tenant IS NOT NULL AND v_target_tenant = v_tenant;
  END IF;

  IF v_org IS NULL OR v_target_org IS DISTINCT FROM v_org THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN v_granted_role IN ('ground_staff', 'location_manager', 'branch_manager');
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN v_grant_rank <= public.access_role_rank('location_manager')
       AND v_brand IS NOT NULL
       AND v_target_brand = v_brand;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN v_granted_role = 'ground_staff'
       AND v_location IS NOT NULL
       AND v_target_location = v_location;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."access_membership_writable"("p_target_user" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_granted_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."access_role_rank"("p_role" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE public.normalize_app_role(p_role)
    WHEN 'ground_staff' THEN 10
    WHEN 'location_manager' THEN 20
    WHEN 'branch_manager' THEN 30
    WHEN 'org_manager' THEN 40
    WHEN 'tenant_super_admin' THEN 50
    WHEN 'platform_admin' THEN 60
    ELSE 0
  END;
$$;


ALTER FUNCTION "public"."access_role_rank"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."access_user_role_name"("p_role_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT r.name
  FROM public.roles r
  WHERE r.id = p_role_id;
$$;


ALTER FUNCTION "public"."access_user_role_name"("p_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_inventory"("p_organization_id" "uuid", "p_location_id" "uuid", "p_inventory_id" "uuid", "p_new_quantity" numeric, "p_new_unit" "text" DEFAULT NULL::"text", "p_unit_cost" numeric DEFAULT NULL::numeric, "p_reason" "text" DEFAULT 'manual_adjustment'::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inventory public.inventory;
  v_previous_qty numeric;
  v_new_cost numeric;
  v_new_value numeric;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_location_id, true);

  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location is required';
  END IF;
  IF p_new_quantity IS NULL OR p_new_quantity < 0 THEN
    RAISE EXCEPTION 'Quantity must be zero or greater';
  END IF;

  SELECT * INTO v_inventory
  FROM public.inventory
  WHERE id = p_inventory_id
    AND organization_id = p_organization_id
    AND location_id = p_location_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_inventory.id IS NULL THEN
    RAISE EXCEPTION 'Inventory item not found for the active location';
  END IF;

  v_previous_qty := COALESCE(v_inventory.current_quantity, 0);
  v_new_cost := COALESCE(p_unit_cost, v_inventory.unit_cost, 0);
  v_new_value := p_new_quantity * v_new_cost;

  UPDATE public.inventory
     SET current_quantity = p_new_quantity,
         current_unit = COALESCE(NULLIF(p_new_unit, ''), current_unit),
         unit_cost = v_new_cost,
         current_value = v_new_value,
         previous_quantity = v_previous_qty,
         previous_value = COALESCE(v_inventory.current_value, v_previous_qty * v_new_cost),
         last_counted_date = CURRENT_DATE,
         last_counted_by = COALESCE(p_user_id, auth.uid()),
         updated_at = now()
   WHERE id = p_inventory_id;

  INSERT INTO public.inventory_movements (
    organization_id, location_id, inventory_id, movement_type, quantity,
    source_type, source_id, previous_quantity, new_quantity, created_by
  ) VALUES (
    p_organization_id, p_location_id, p_inventory_id, 'manual_adjustment',
    p_new_quantity - v_previous_qty, COALESCE(NULLIF(p_reason, ''), 'manual_adjustment'),
    p_inventory_id, v_previous_qty, p_new_quantity, COALESCE(p_user_id, auth.uid())
  );

  RETURN jsonb_build_object('success', true, 'previous_quantity', v_previous_qty, 'new_quantity', p_new_quantity);
END;
$$;


ALTER FUNCTION "public"."adjust_inventory"("p_organization_id" "uuid", "p_location_id" "uuid", "p_inventory_id" "uuid", "p_new_quantity" numeric, "p_new_unit" "text", "p_unit_cost" numeric, "p_reason" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_user"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    caller_role TEXT;
    v_email TEXT;
    v_full_name TEXT;
    v_role TEXT;
BEGIN
    -- 1. Check if caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- 2. Verify the caller is a platform_admin
    caller_role := COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '');
    
    IF caller_role != 'platform_admin' THEN
        RAISE EXCEPTION 'Insufficient permissions: only platform_admin can delete users permanently';
    END IF;

    -- 3. Prevent self-deletion via this route
    IF target_user_id = auth.uid() THEN
        RAISE EXCEPTION 'You cannot delete your own account.';
    END IF;

    -- 4. Gather user details before deletion for the archive
    SELECT email, full_name, role INTO v_email, v_full_name, v_role
    FROM public.profiles
    WHERE id = target_user_id;

    -- If profile was missing, fallback to auth.users for email
    IF v_email IS NULL THEN
        SELECT email INTO v_email FROM auth.users WHERE id = target_user_id;
    END IF;

    -- 5. Archive the user
    INSERT INTO public.archived_users (original_user_id, email, full_name, role, deleted_by)
    VALUES (target_user_id, v_email, v_full_name, v_role, auth.uid());

    -- 6. Delete the user from auth.users
    -- Because this function is SECURITY DEFINER, it runs with the privileges 
    -- of the user who created it (postgres superuser during migrations),
    -- allowing it to safely bypass the auth schema restrictions.
    DELETE FROM auth.users WHERE id = target_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_delete_user"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_submit_vendor_banking_info"("p_vendor_id" "uuid", "p_account" "text", "p_routing" "text", "p_intent" "text" DEFAULT 'add'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
  v_intent text := COALESCE(NULLIF(btrim(p_intent), ''), 'add');
BEGIN
  IF v_intent NOT IN ('add', 'replace') THEN
    RAISE EXCEPTION 'Invalid vendor banking intent: %', p_intent;
  END IF;

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL::timestamptz, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Same precondition issue_vendor_banking_link enforces (VO-RULE-005) -- the UI already greys
  -- this button out via canIssueBanking, but per this codebase's own rule that enforcement must
  -- be DB-side, not UI-only, the RPC needs its own copy of the check, not just a disabled prop.
  IF NOT EXISTS (
    SELECT 1
    FROM public.vendor_tax_information vti
    WHERE vti.vendor_id = p_vendor_id
      AND vti.verification_status = 'verified'
      AND vti.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Business is not verified';
  END IF;

  IF NOT public.vendor_has_required_onboarding_documents(p_vendor_id) THEN
    RAISE EXCEPTION 'Required vendor documents are not on file';
  END IF;

  IF regexp_replace(COALESCE(p_account, ''), '\D', '', 'g') !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number (4-17 digits) is required';
  END IF;

  IF regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g') !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF v_intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = p_vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    p_vendor_id,
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id,
    'pending',
    'pending',
    false,
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    p_vendor_id,
    v_bank.id,
    v_reason,
    auth.uid(),
    'on_file_contact',
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_request;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted'
   WHERE id = p_vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_id, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    auth.uid(),
    'admin',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'intent', v_intent,
      'entry_method', 'manual'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', p_vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$_$;


ALTER FUNCTION "public"."admin_submit_vendor_banking_info"("p_vendor_id" "uuid", "p_account" "text", "p_routing" "text", "p_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_submit_vendor_tax_info"("p_vendor_id" "uuid", "p_tax_id" "text", "p_legal_name" "text" DEFAULT NULL::"text", "p_tax_classification" "text" DEFAULT NULL::"text", "p_tax_id_type" "text" DEFAULT NULL::"text", "p_w9_document_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_tax public.vendor_tax_information%ROWTYPE;
  v_store_result jsonb;
  v_inferred_type text;
BEGIN
  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL::timestamptz, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Same floor as issue_vendor_link_token -- manual entry is functionally "issue a link and
  -- redeem it in the same step," so it shouldn't skip the gate the link-issuing path enforces.
  IF COALESCE(v_vendor.onboarding_status, 'invited') NOT IN (
    'otp_verified', 'pending_tax', 'tax_submitted', 'business_verified', 'verification_failed',
    'documents_on_file', 'pending_bank', 'banking_submitted', 'banking_verified',
    'method_selected', 'pending_approval', 'active', 'completed'
  ) THEN
    RAISE EXCEPTION 'Vendor OTP must be verified before entering tax info';
  END IF;

  IF p_w9_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.vendor_documents
    WHERE id = p_w9_document_id
      AND vendor_id = p_vendor_id
      AND document_type = 'w9'
      AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'W-9 document not found for this vendor -- upload it first, then link it here';
  END IF;

  v_inferred_type := COALESCE(
    NULLIF(p_tax_id_type, ''),
    CASE
      -- position() is 1-indexed in Postgres (unlike JS indexOf's 0-indexed 2 for "12-3456789") --
      -- an EIN's dash sits after the first 2 digits, so character position 3.
      WHEN regexp_replace(COALESCE(p_tax_id, ''), '\D', '', 'g') ~ '^\d{9}$' AND position('-' in p_tax_id) = 3 THEN 'ein'
      ELSE 'ssn'
    END
  );

  INSERT INTO public.vendor_tax_information (
    vendor_id, legal_name, tax_classification, tax_id_type,
    verification_status, w9_status, w9_document_id, created_by, updated_by
  ) VALUES (
    p_vendor_id,
    NULLIF(p_legal_name, ''),
    NULLIF(p_tax_classification, ''),
    v_inferred_type,
    'pending',
    CASE WHEN p_w9_document_id IS NOT NULL THEN 'received' ELSE 'requested' END,
    p_w9_document_id,
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_tax;

  v_store_result := public.store_vendor_tax_secret(v_tax.id, p_tax_id);

  UPDATE public.vendors
     SET onboarding_status = 'tax_submitted'
   WHERE id = p_vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_id, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    'tax_submitted',
    'tax_submitted',
    auth.uid(),
    'admin',
    jsonb_build_object('tax_row_id', v_tax.id, 'w9_document_id', p_w9_document_id, 'entry_method', 'manual')
  );

  RETURN jsonb_build_object(
    'success', true,
    'tax_row_id', v_tax.id,
    'tax_id_last4', v_store_result->>'tax_id_last4'
  );
END;
$_$;


ALTER FUNCTION "public"."admin_submit_vendor_tax_info"("p_vendor_id" "uuid", "p_tax_id" "text", "p_legal_name" "text", "p_tax_classification" "text", "p_tax_id_type" "text", "p_w9_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_user_role"("target_user_id" "uuid", "new_role" "text" DEFAULT NULL::"text", "new_status" "text" DEFAULT NULL::"text", "new_department" "text" DEFAULT NULL::"text", "new_location" "text" DEFAULT NULL::"text", "new_brand_id" "uuid" DEFAULT NULL::"uuid", "new_location_id" "uuid" DEFAULT NULL::"uuid", "new_access_level" "text" DEFAULT NULL::"text", "new_access_permissions" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  caller_role text;
  caller_org uuid;
  caller_tenant uuid;
  target_org uuid;
  target_tenant uuid;
  normalized_role text;
BEGIN
  IF new_location IS NOT NULL THEN
    -- Backward-compatible no-op.
  END IF;

  caller_role := public.get_auth_role();
  caller_org := public.get_auth_org();
  caller_tenant := public.get_auth_tenant();
  normalized_role := CASE WHEN new_role IS NULL THEN NULL ELSE public.normalize_app_role(new_role) END;

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: org_manager, tenant_super_admin, or platform_admin required';
  END IF;

  SELECT p.organization_id, COALESCE(p.tenant_id, o.tenant_id)
  INTO target_org, target_tenant
  FROM public.profiles p
  LEFT JOIN public.organizations o ON o.id = p.organization_id
  WHERE p.id = target_user_id;

  IF caller_role = 'tenant_super_admin' AND target_tenant IS DISTINCT FROM caller_tenant THEN
    RAISE EXCEPTION 'Cannot modify users outside your tenant';
  END IF;

  IF caller_role = 'org_manager' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND normalized_role IS NOT NULL THEN
    IF NOT public.can_invite_role(normalized_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND normalized_role IS NOT NULL AND normalized_role <> caller_role THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;

  IF normalized_role = 'tenant_super_admin' AND target_tenant IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (target_tenant, target_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF normalized_role IS NOT NULL AND target_org IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (target_org, target_user_id, normalized_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET role = COALESCE(normalized_role, role),
      status = COALESCE(new_status, status),
      department = COALESCE(new_department, department),
      brand_id = COALESCE(new_brand_id, brand_id),
      location_id = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      access_permissions = COALESCE(new_access_permissions, access_permissions),
      tenant_id = COALESCE(tenant_id, target_tenant),
      updated_at = now()
  WHERE id = target_user_id;

  PERFORM public.sync_auth_metadata_from_profile(target_user_id);

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_update_user_role"("target_user_id" "uuid", "new_role" "text", "new_status" "text", "new_department" "text", "new_location" "text", "new_brand_id" "uuid", "new_location_id" "uuid", "new_access_level" "text", "new_access_permissions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_invited_modules_to_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF NEW.owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.tenant_id IS NOT NULL THEN
    v_modules := public.sync_invited_modules_to_tenant(NEW.owner_id, NEW.tenant_id);
  ELSE
    v_modules := public.get_invited_enabled_modules(NEW.owner_id);
  END IF;

  IF v_modules IS NOT NULL
     AND COALESCE(jsonb_array_length(
       CASE
         WHEN jsonb_typeof(NEW.enabled_modules) = 'array' THEN NEW.enabled_modules
         ELSE '[]'::jsonb
       END
     ), 0) = 0 THEN
    NEW.enabled_modules := v_modules;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_invited_modules_to_organization"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_onboarding_coupon"("p_code" "text", "p_plan_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_user_email TEXT;
  v_coupon public.onboarding_coupons%ROWTYPE;
  v_invited_email TEXT;
  v_redemption_id UUID;
  v_trial_ends_at TIMESTAMPTZ;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_coupon
  FROM public.onboarding_coupons
  WHERE lower(code) = lower(btrim(p_code))
    AND active = true
    AND (starts_at IS NULL OR starts_at <= now())
    AND (expires_at IS NULL OR expires_at > now())
  LIMIT 1;

  IF v_coupon.id IS NULL THEN
    RAISE EXCEPTION 'Coupon is invalid or expired';
  END IF;

  v_invited_email := lower(NULLIF(v_coupon.metadata->>'invited_email', ''));
  IF v_invited_email IS NOT NULL AND v_invited_email <> lower(COALESCE(v_user_email, '')) THEN
    RAISE EXCEPTION 'Coupon is assigned to a different invited email';
  END IF;

  IF v_coupon.max_redemptions IS NOT NULL AND v_coupon.redeemed_count >= v_coupon.max_redemptions THEN
    RAISE EXCEPTION 'Coupon has reached its redemption limit';
  END IF;

  IF v_coupon.applies_to_plan_ids IS NOT NULL
     AND p_plan_id IS NOT NULL
     AND NOT (p_plan_id = ANY(v_coupon.applies_to_plan_ids)) THEN
    RAISE EXCEPTION 'Coupon does not apply to the selected plan';
  END IF;

  v_trial_ends_at := CASE
    WHEN v_coupon.discount_type = 'trial_days' AND v_coupon.trial_days > 0
    THEN now() + make_interval(days => v_coupon.trial_days)
    ELSE NULL
  END;

  INSERT INTO public.onboarding_coupon_redemptions (
    coupon_id,
    user_id,
    plan_id,
    discount_snapshot
  )
  VALUES (
    v_coupon.id,
    v_user_id,
    p_plan_id,
    jsonb_build_object(
      'code', v_coupon.code,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at,
      'invited_email', v_invited_email
    )
  )
  ON CONFLICT (coupon_id, user_id) DO UPDATE
  SET plan_id = EXCLUDED.plan_id,
      status = 'applied',
      discount_snapshot = EXCLUDED.discount_snapshot,
      redeemed_at = now()
  RETURNING id INTO v_redemption_id;

  UPDATE public.onboarding_coupons
  SET redeemed_count = (
    SELECT count(*) FROM public.onboarding_coupon_redemptions
    WHERE coupon_id = v_coupon.id AND status IN ('applied', 'consumed')
  )
  WHERE id = v_coupon.id;

  UPDATE public.profiles
  SET coupon_code = v_coupon.code,
      trial_ends_at = COALESCE(v_trial_ends_at, trial_ends_at),
      onboarding_current_step = 'hierarchy_setup',
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'redemption_id', v_redemption_id,
    'coupon', jsonb_build_object(
      'code', v_coupon.code,
      'description', v_coupon.description,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at
    )
  );
END;
$$;


ALTER FUNCTION "public"."apply_onboarding_coupon"("p_code" "text", "p_plan_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_product_category_suggestion"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_category_type text;
  v_accounting_category text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    v_product.deleted_at,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(COALESCE(v_product.suggested_category, '')), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No category suggestion is available');
  END IF;

  v_category_type := public.derive_product_category_type(NULL, v_product.suggested_category, v_product.name);
  v_accounting_category := public.product_accounting_category_for_type(v_category_type, v_product.suggested_category);

  UPDATE public.products
     SET category = v_product.suggested_category,
         accounting_category = v_accounting_category,
         category_confidence = v_product.category_confidence,
         category_source = 'approved',
         category_review_status = 'approved',
         category_reviewed_at = now(),
         category_reviewed_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  UPDATE public.inventory i
     SET category = v_product.suggested_category,
         accounting_category = v_accounting_category,
         updated_at = now()
   WHERE i.internal_product_id = p_product_id
     AND i.deleted_at IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'category', v_product.suggested_category,
    'accounting_category', v_accounting_category
  );
END;
$$;


ALTER FUNCTION "public"."apply_product_category_suggestion"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_business_verification"("p_user_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
  v_verification_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT id
  INTO v_verification_id
  FROM public.business_verifications
  WHERE user_id = p_user_id
  ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST, id DESC
  LIMIT 1;

  IF v_verification_id IS NULL THEN
    RAISE EXCEPTION 'Business verification row not found for user %', p_user_id;
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'verified',
      reviewed_by = v_actor,
      reviewed_at = now(),
      rejection_reason = NULL,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('admin_note', p_note),
      updated_at = now()
  WHERE id = v_verification_id;

  UPDATE public.profiles
  SET business_verification_status = 'verified',
      business_verified_at = now(),
      onboarding_status = 'in_progress',
      onboarding_current_step = 'payment_method',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'approve_business_verification', p_note);

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Business verification approved', 'Your business verification was approved. You can continue onboarding.', false);

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    p_user_id,
    'business_verification',
    'admin_approved',
    'verified',
    jsonb_build_object('actor_user_id', v_actor, 'verification_id', v_verification_id)
  );

  RETURN jsonb_build_object('success', true, 'status', 'verified', 'next_step', 'payment_method', 'verification_id', v_verification_id);
END;
$$;


ALTER FUNCTION "public"."approve_business_verification"("p_user_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_daily_pos_usage"("p_org_id" "uuid", "p_date" "date", "p_location_id" "uuid", "p_user_id" "uuid", "p_adjustments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_usage record;
  v_adj record;
  v_inventory public.inventory;
  v_change_amount numeric;
  v_count integer := 0;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_org_id, p_location_id, true);

  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location is required to approve POS usage';
  END IF;

  INSERT INTO public.inventory_pos_usage_approvals (
    organization_id, location_id, usage_date, approved_by, adjustments
  ) VALUES (
    p_org_id, p_location_id, p_date, COALESCE(p_user_id, auth.uid()), COALESCE(p_adjustments, '[]'::jsonb)
  )
  ON CONFLICT (organization_id, location_id, usage_date) DO NOTHING;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', true, 'already_approved', true, 'message', 'POS usage has already been approved for this date and location.', 'items_depleted', 0);
  END IF;

  FOR v_usage IN SELECT * FROM public.generate_daily_theoretical_usage(p_org_id, p_date)
  LOOP
    SELECT * INTO v_inventory
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND location_id = p_location_id
      AND deleted_at IS NULL
      AND (internal_product_id = v_usage.ingredient_id OR product_id = v_usage.ingredient_id::text)
    LIMIT 1
    FOR UPDATE;

    IF v_inventory.id IS NULL THEN
      CONTINUE;
    END IF;

    v_change_amount := -1 * COALESCE(v_usage.theoretical_usage, 0);

    UPDATE public.inventory
       SET current_quantity = GREATEST(0, COALESCE(current_quantity, 0) + v_change_amount),
           previous_quantity = current_quantity,
           current_value = GREATEST(0, COALESCE(current_quantity, 0) + v_change_amount) * COALESCE(unit_cost, 0),
           previous_value = current_value,
           updated_at = now()
     WHERE id = v_inventory.id;

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_org_id, p_location_id, v_inventory.id, 'sales_depletion', v_change_amount,
      'pos_daily_usage', NULL, COALESCE(v_inventory.current_quantity, 0),
      GREATEST(0, COALESCE(v_inventory.current_quantity, 0) + v_change_amount), COALESCE(p_user_id, auth.uid())
    );

    v_count := v_count + 1;
  END LOOP;

  FOR v_adj IN
    SELECT * FROM jsonb_to_recordset(COALESCE(p_adjustments, '[]'::jsonb)) AS x(product_id uuid, quantity numeric, reason text)
  LOOP
    SELECT * INTO v_inventory
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND location_id = p_location_id
      AND deleted_at IS NULL
      AND (internal_product_id = v_adj.product_id OR product_id = v_adj.product_id::text)
    LIMIT 1
    FOR UPDATE;

    IF v_inventory.id IS NOT NULL AND COALESCE(v_adj.quantity, 0) <> 0 THEN
      UPDATE public.inventory
         SET current_quantity = GREATEST(0, COALESCE(current_quantity, 0) + v_adj.quantity),
             previous_quantity = current_quantity,
             current_value = GREATEST(0, COALESCE(current_quantity, 0) + v_adj.quantity) * COALESCE(unit_cost, 0),
             previous_value = current_value,
             updated_at = now()
       WHERE id = v_inventory.id;

      INSERT INTO public.inventory_movements (
        organization_id, location_id, inventory_id, movement_type, quantity,
        source_type, source_id, previous_quantity, new_quantity, created_by
      ) VALUES (
        p_org_id, p_location_id, v_inventory.id, COALESCE(NULLIF(v_adj.reason, ''), 'pos_adjustment'),
        v_adj.quantity, 'pos_daily_adjustment', NULL, COALESCE(v_inventory.current_quantity, 0),
        GREATEST(0, COALESCE(v_inventory.current_quantity, 0) + v_adj.quantity), COALESCE(p_user_id, auth.uid())
      );
    END IF;
  END LOOP;

  UPDATE public.inventory_pos_usage_approvals
     SET depletion_count = v_count
   WHERE organization_id = p_org_id
     AND location_id = p_location_id
     AND usage_date = p_date;

  RETURN jsonb_build_object('success', true, 'already_approved', false, 'message', 'Successfully depleted ' || v_count || ' ingredients based on POS sales.', 'items_depleted', v_count);
END;
$$;


ALTER FUNCTION "public"."approve_daily_pos_usage"("p_org_id" "uuid", "p_date" "date", "p_location_id" "uuid", "p_user_id" "uuid", "p_adjustments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_invoice_with_limit"("p_invoice_id" "uuid", "p_user_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_limit numeric;
  v_has_unlimited boolean;
  v_invoice public.invoices%ROWTYPE;
  v_amount numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Approval user must match the authenticated user';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
    INTO v_user_limit, v_has_unlimited
  FROM public.profiles
  WHERE id = p_user_id
    AND deleted_at IS NULL;

  v_amount := COALESCE(p_amount, v_invoice.total_amount, 0);

  IF NOT v_has_unlimited AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
    RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
      COALESCE(v_user_limit, 0), v_amount;
  END IF;

  UPDATE public.invoices
     SET status = 'approved',
         ap_status = 'approved',
         approved_by = auth.uid(),
         approved_date = now(),
         updated_at = now()
   WHERE id = p_invoice_id;

  -- Sync products right after approval
  PERFORM public.sync_invoice_products(p_invoice_id);

  RETURN jsonb_build_object('success', true, 'message', 'Invoice approved successfully');
END;
$_$;


ALTER FUNCTION "public"."approve_invoice_with_limit"("p_invoice_id" "uuid", "p_user_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_onboarding_hierarchy"("p_user_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_hierarchy JSONB;
  v_result JSONB;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT hierarchy_payload INTO v_hierarchy
  FROM public.onboarding_hierarchy_submissions
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF v_hierarchy IS NULL THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  v_result := public.setup_onboarding_hierarchy(p_user_id, v_hierarchy);

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'approved',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      rejection_reason = NULLIF(btrim(COALESCE(p_note, '')), ''),
      updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  UPDATE public.profiles SET hierarchy_review_status = 'approved' WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  SELECT p_user_id, (v_result->>'primary_org_id')::uuid, 'system', 'Workspace approved',
         'Your organization workspace has been approved and created.', false;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."approve_onboarding_hierarchy"("p_user_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_product_change"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT v_existing.pending_approval THEN
    RAISE EXCEPTION 'This product has no pending change to approve';
  END IF;

  IF public.get_auth_role() NOT IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to approve product changes';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to approve this product change';
  END IF;

  IF v_existing.pending_action = 'delete' THEN
    UPDATE public.products SET
      deleted_at = now(), deleted_by = auth.uid(),
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSE
    UPDATE public.products SET
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."approve_product_change"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_deleted_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
  -- Insert into the exact schema where the delete occurred
  EXECUTE format(
    'INSERT INTO %I.archived_invoices (id, organization_id, vendor_name, invoice_number, total_amount, status, file_url, original_created_at, deleted_by) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)',
    TG_TABLE_SCHEMA
  )
  USING OLD.id, OLD.organization_id, OLD.vendor_name, OLD.invoice_number, OLD.total_amount, OLD.status, OLD.file_url, OLD.created_at, auth.uid();
  RETURN OLD;
END;
$_$;


ALTER FUNCTION "public"."archive_deleted_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_record_on_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_archive_table TEXT := 'archived_' || TG_TABLE_NAME;
  v_columns TEXT;
  v_values TEXT;
BEGIN
  SELECT
    string_agg(format('%I', archive_columns.column_name), ', ' ORDER BY archive_columns.ordinal_position),
    string_agg(format('($1).%I', archive_columns.column_name), ', ' ORDER BY archive_columns.ordinal_position)
    INTO v_columns, v_values
  FROM information_schema.columns archive_columns
  JOIN information_schema.columns source_columns
    ON source_columns.table_schema = TG_TABLE_SCHEMA
   AND source_columns.table_name = TG_TABLE_NAME
   AND source_columns.column_name = archive_columns.column_name
  WHERE archive_columns.table_schema = TG_TABLE_SCHEMA
    AND archive_columns.table_name = v_archive_table
    AND archive_columns.column_name NOT IN ('archived_at', 'archived_by');

  IF v_columns IS NULL THEN
    RETURN OLD;
  END IF;

  EXECUTE format(
    'INSERT INTO %I.%I (%s, archived_at, archived_by) VALUES (%s, now(), auth.uid())',
    TG_TABLE_SCHEMA,
    v_archive_table,
    v_columns,
    v_values
  )
  USING OLD;

  RETURN OLD;
END;
$_$;


ALTER FUNCTION "public"."archive_record_on_delete"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."archive_record_on_delete"() IS 'Archives deleted rows by matching shared source/archive column names instead of relying on brittle column order.';



CREATE OR REPLACE FUNCTION "public"."archive_vendor"("p_vendor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  -- SECURITY DEFINER's internal UPDATE bypasses RLS, so this needs its own explicit scope
  -- check -- same floor operational_vendors_update already uses.
  SELECT * INTO v_vendor FROM public.vendors WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, v_vendor.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_vendor.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Vendor is already archived';
  END IF;

  UPDATE public.vendors SET deleted_at = now() WHERE id = p_vendor_id;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type)
  VALUES (p_vendor_id, 'vendor_archived', auth.uid(), 'admin');
END;
$$;


ALTER FUNCTION "public"."archive_vendor"("p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_can_approve_invoice_scope"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_tenant_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id, tenant_id
    INTO v_role, v_org_id, v_tenant_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    IF v_tenant_id = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-tenant invoice approval denied';
  END IF;

  IF p_organization_id IS NULL OR v_org_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization invoice approval denied';
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN;
  END IF;

  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RAISE EXCEPTION 'Org-level invoice approval requires org_manager or platform_admin';
  END IF;

  IF v_role = 'branch_manager' THEN
    IF p_brand_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.get_my_accessible_brand_ids() b(id)
      WHERE b.id = p_brand_id
    ) THEN
      RETURN;
    END IF;

    IF p_location_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.locations l
      JOIN public.get_my_accessible_brand_ids() b(id) ON b.id = l.brand_id
      WHERE l.id = p_location_id
    ) THEN
      RETURN;
    END IF;
  END IF;

  IF v_role = 'location_manager' THEN
    IF p_location_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.get_my_accessible_location_ids() l(id)
      WHERE l.id = p_location_id
    ) THEN
      RETURN;
    END IF;
  END IF;

  RAISE EXCEPTION 'Invoice approval denied for role % outside accessible scope', v_role;
END;
$$;


ALTER FUNCTION "public"."assert_can_approve_invoice_scope"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_can_approve_vendor_scope"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    IF public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-tenant vendor approval denied';
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       p_location_id,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;


ALTER FUNCTION "public"."assert_can_approve_vendor_scope"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_financial_actor"("p_organization_id" "uuid", "p_allowed_roles" "text"[] DEFAULT ARRAY['location_manager'::"text", 'branch_manager'::"text", 'brand_manager'::"text", 'org_manager'::"text", 'tenant_super_admin'::"text", 'platform_admin'::"text", 'org_owner'::"text", 'owner'::"text", 'admin'::"text"]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
  v_profile_tenant UUID;
  v_org_tenant UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id, tenant_id
    INTO v_role, v_profile_org, v_profile_tenant
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    SELECT tenant_id INTO v_org_tenant
    FROM public.organizations
    WHERE id = p_organization_id;

    IF v_profile_tenant IS DISTINCT FROM v_org_tenant THEN
      RAISE EXCEPTION 'Cross-tenant financial access denied';
    END IF;
  ELSIF v_role <> 'platform_admin' AND v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization financial access denied';
  END IF;

  IF NOT v_role = ANY(p_allowed_roles) THEN
    RAISE EXCEPTION 'Insufficient financial permissions';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_financial_actor"("p_organization_id" "uuid", "p_allowed_roles" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_financial_actor"("p_organization_id" "uuid", "p_allowed_roles" "text"[]) IS 'Shared guard for tenant-safe financial RPCs. Validates authenticated user role and organization scope before money-moving mutations.';



CREATE OR REPLACE FUNCTION "public"."assert_inventory_rpc_access"("p_organization_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_require_manager" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Authenticated profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM v_org_id THEN
    RAISE EXCEPTION 'Access denied: organization mismatch';
  END IF;

  IF p_require_manager AND v_role NOT IN (
    'manager', 'owner', 'admin', 'branch_manager', 'location_manager',
    'org_manager', 'org_owner', 'tenant_super_admin'
  ) THEN
    RAISE EXCEPTION 'Access denied: manager role required';
  END IF;

  IF p_location_id IS NOT NULL AND p_location_id IS DISTINCT FROM v_location_id THEN
    RAISE EXCEPTION 'Access denied: active location mismatch';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_inventory_rpc_access"("p_organization_id" "uuid", "p_location_id" "uuid", "p_require_manager" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_org_actor"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id
    INTO v_role, v_profile_org
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    IF p_organization_id IN (SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;

  IF v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_org_actor"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_performance_location_access"("p_organization_id" "uuid", "p_location_id" "uuid", "p_write" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
  v_auth_brand uuid;
  v_auth_location uuid;
  v_location_org uuid;
  v_location_brand uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    IF p_organization_id IS NULL OR p_location_id IS NULL THEN
      RAISE EXCEPTION 'Performance requires organization and location context'
        USING ERRCODE = '22023';
    END IF;
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL OR p_location_id IS NULL THEN
    RAISE EXCEPTION 'Performance requires one selected location'
      USING ERRCODE = '22023';
  END IF;

  SELECT public.normalize_app_role(p.role),
         p.organization_id,
         p.brand_id,
         p.location_id
    INTO v_role, v_auth_org, v_auth_brand, v_auth_location
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Authenticated profile not found'
      USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_manager_or_above() THEN
    RAISE EXCEPTION 'Role is not authorized for Performance'
      USING ERRCODE = '42501';
  END IF;

  SELECT l.organization_id, l.brand_id
    INTO v_location_org, v_location_brand
  FROM public.locations l
  WHERE l.id = p_location_id
    AND l.deleted_at IS NULL;

  IF v_location_org IS NULL OR v_location_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Location does not belong to the active organization'
      USING ERRCODE = '42501';
  END IF;

  -- platform_admin follows the existing project-wide cross-organization
  -- exception, but still must name a real location in the named organization.
  IF v_role <> 'platform_admin' AND (
    v_auth_org IS DISTINCT FROM p_organization_id
    OR v_auth_location IS DISTINCT FROM p_location_id
    OR v_auth_brand IS NULL
    OR v_auth_brand IS DISTINCT FROM v_location_brand
  ) THEN
    RAISE EXCEPTION 'Performance location is outside the active hierarchy context'
      USING ERRCODE = '42501';
  END IF;

  IF p_write AND NOT public.is_manager_or_above() THEN
    RAISE EXCEPTION 'Role is not authorized to manage Performance budgets'
      USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_performance_location_access"("p_organization_id" "uuid", "p_location_id" "uuid", "p_write" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_performance_report_bounds"("p_date_from" "date", "p_date_to" "date", "p_max_days" integer DEFAULT 548) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  IF p_date_to < p_date_from THEN
    RAISE EXCEPTION 'date_to must be on or after date_from';
  END IF;

  IF (p_date_to - p_date_from) + 1 > p_max_days THEN
    RAISE EXCEPTION 'Performance report range exceeds % days', p_max_days;
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_performance_report_bounds"("p_date_from" "date", "p_date_to" "date", "p_max_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_performance_report_bounds"("p_date_from" "date", "p_date_to" "date", "p_max_days" integer) IS 'Rejects missing, reversed, or overly broad interactive Performance reporting ranges.';



CREATE OR REPLACE FUNCTION "public"."assert_tenant_scope"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  caller_org UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  caller_org := public.get_my_org();

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = caller_org) THEN
    RAISE EXCEPTION 'Organization is outside caller tenant';
  END IF;

  IF p_brand_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.brands b
      WHERE b.brand_id = p_brand_id
        AND b.organization_id = p_organization_id
        AND (
          public.is_platform_admin()
          OR (SELECT auth.role()) = 'service_role'
          OR p_brand_id IN (SELECT public.get_my_accessible_brand_ids())
        )
    ) THEN
      RAISE EXCEPTION 'Brand is outside caller tenant scope';
    END IF;
  END IF;

  IF p_location_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.locations l
      WHERE l.id = p_location_id
        AND l.organization_id = p_organization_id
        AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
        AND (
          public.is_platform_admin()
          OR (SELECT auth.role()) = 'service_role'
          OR p_location_id IN (SELECT public.get_my_accessible_location_ids())
        )
    ) THEN
      RAISE EXCEPTION 'Location is outside caller tenant scope';
    END IF;
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."assert_tenant_scope"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_tenant_scope"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") IS 'Validates organization/brand/location scope before backend code routes tenant data access.';



CREATE OR REPLACE FUNCTION "public"."attach_invoice_document"("p_document_id" "uuid", "p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc public.invoice_documents%ROWTYPE;
BEGIN
  SELECT * INTO v_doc FROM public.invoice_documents WHERE id = p_document_id;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Document not found';
  END IF;

  PERFORM public.assert_org_actor(v_doc.organization_id);

  UPDATE public.invoice_documents
  SET invoice_id = p_invoice_id, updated_at = now()
  WHERE id = p_document_id;
END;
$$;


ALTER FUNCTION "public"."attach_invoice_document"("p_document_id" "uuid", "p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_log_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN p_organization_id IS NOT NULL
       AND p_organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       );
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id;
  END IF;

  IF v_role IN ('branch_manager', 'brand_manager') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_brand_id IS NOT NULL
       AND p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  IF v_role IN ('location_manager', 'ground_staff') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_location_id IS NOT NULL
       AND (
         p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id)
         OR p_location_id = v_location_id
       );
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."audit_log_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_product_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action text;
BEGIN
  v_action := CASE TG_OP
    WHEN 'INSERT' THEN 'product_created'
    WHEN 'UPDATE' THEN 'product_updated'
    ELSE 'product_deleted'
  END;

  INSERT INTO public.audit_logs (
    organization_id, brand_id, location_id, user_id, action, table_name,
    record_id, old_data, new_data, created_at
  ) VALUES (
    COALESCE(NEW.organization_id, OLD.organization_id),
    COALESCE(NEW.brand_id, OLD.brand_id),
    COALESCE(NEW.location_id, OLD.location_id),
    auth.uid(),
    v_action,
    'products',
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END,
    now()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."audit_product_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_match_statement_lines"("p_statement_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_vendor_id UUID;
    v_org_id UUID;
    v_matched_count INTEGER := 0;
    v_line RECORD;
    v_invoice_id UUID;
BEGIN
    SELECT vendor_id, organization_id INTO v_vendor_id, v_org_id 
    FROM public.vendor_statements WHERE id = p_statement_id;

    FOR v_line IN SELECT * FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status = 'unmatched' LOOP
        -- Try to find an exact match on invoice_number and amount and vendor
        SELECT id INTO v_invoice_id
        FROM public.invoices
        WHERE organization_id = v_org_id 
          AND vendor_id = v_vendor_id
          AND invoice_number = v_line.invoice_number
          AND total_amount = v_line.amount
        LIMIT 1;

        IF v_invoice_id IS NOT NULL THEN
            UPDATE public.vendor_statement_lines
            SET status = 'matched', matched_invoice_id = v_invoice_id
            WHERE id = v_line.id;
            
            v_matched_count := v_matched_count + 1;
        END IF;
    END LOOP;

    -- Update parent statement status if all lines are matched
    IF NOT EXISTS (SELECT 1 FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status != 'matched') THEN
        UPDATE public.vendor_statements SET status = 'matched' WHERE id = p_statement_id;
    ELSE
        UPDATE public.vendor_statements SET status = 'needs_review' WHERE id = p_statement_id;
    END IF;

    RETURN v_matched_count;
END;
$$;


ALTER FUNCTION "public"."auto_match_statement_lines"("p_statement_id" "uuid") OWNER TO "postgres";


