CREATE OR REPLACE FUNCTION "public"."batch3b_org_visible"("p_organization_id" "uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF public.is_platform_admin() THEN
    RETURN true;
  END IF;

  RETURN p_organization_id IS NOT NULL
     AND p_organization_id = public.get_auth_org();
END;
$$;


