CREATE OR REPLACE FUNCTION "public"."batch3b_org_writable"("p_organization_id" "uuid", "p_admin_only" boolean DEFAULT false, "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF public.is_platform_admin() THEN
    RETURN true;
  END IF;

  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM public.get_auth_org() THEN
    RETURN false;
  END IF;

  IF p_admin_only THEN
    RETURN public.is_admin();
  END IF;

  RETURN public.is_manager_or_above();
END;
$$;


