CREATE OR REPLACE FUNCTION "public"."bulk_process_invoices"("p_invoice_ids" "uuid"[], "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_processed int := 0;
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF p_status IS NULL THEN
    RAISE EXCEPTION 'Status is required';
  END IF;

  FOREACH v_id IN ARRAY COALESCE(p_invoice_ids, ARRAY[]::uuid[]) LOOP
    SELECT *
      INTO v_invoice
    FROM public.invoices
    WHERE id = v_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_invoice.id IS NULL THEN
      RAISE EXCEPTION 'Invoice % not found', v_id;
    END IF;

    IF p_status = 'approved' THEN
      PERFORM public.assert_can_approve_invoice_scope(
        v_invoice.organization_id,
        v_invoice.brand_id,
        v_invoice.location_id
      );
    END IF;

    UPDATE public.invoices
       SET status = p_status,
           ap_status = CASE WHEN p_status = 'approved' THEN 'approved' ELSE ap_status END,
           approved_by = CASE WHEN p_status = 'approved' THEN auth.uid() ELSE approved_by END,
           approved_date = CASE WHEN p_status = 'approved' THEN now() ELSE approved_date END,
           updated_at = now()
     WHERE id = v_id;

    IF p_status = 'approved' THEN
      PERFORM public.sync_invoice_products(v_id);
    ELSIF p_status = 'pending_approval' THEN
      PERFORM public.evaluate_invoice_approval_policy(v_id);
    END IF;

    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('status', 'success', 'processed', v_processed);
END;
$$;


ALTER FUNCTION "public"."bulk_process_invoices"("p_invoice_ids" "uuid"[], "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_invoice_allocations"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id UUID;
  v_tax NUMERIC;
  v_fuel NUMERIC;
  v_delivery NUMERIC;
  v_other NUMERIC;
  v_cat_record RECORD;
BEGIN
  SELECT organization_id,
         COALESCE(tax_amount, 0),
         COALESCE(fuel_surcharge, 0),
         COALESCE(delivery_fee, 0),
         COALESCE(other_charges, 0)
  INTO v_org_id, v_tax, v_fuel, v_delivery, v_other
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  DELETE FROM public.invoice_allocations WHERE invoice_id = p_invoice_id;

  FOR v_cat_record IN (
    SELECT
      COALESCE(p.category, 'uncategorized') AS cat_name,
      SUM(COALESCE(ili.total_price, ili.quantity * ili.unit_price, 0)) AS total_amount
    FROM public.invoice_line_items ili
    LEFT JOIN public.products p ON ili.internal_product_id = p.id
    WHERE ili.invoice_id = p_invoice_id
    GROUP BY COALESCE(p.category, 'uncategorized')
  ) LOOP
    IF COALESCE(v_cat_record.total_amount, 0) > 0 THEN
      INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, gl_code, amount)
      SELECT
        v_org_id,
        p_invoice_id,
        'line_items',
        v_cat_record.cat_name,
        (SELECT gl_code FROM public.gl_mappings WHERE organization_id = v_org_id AND LOWER(category) = LOWER(v_cat_record.cat_name) LIMIT 1),
        v_cat_record.total_amount;
    END IF;
  END LOOP;

  IF v_tax > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'tax', 'Tax', v_tax);
  END IF;

  IF v_delivery > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'delivery', 'Delivery Fee', v_delivery);
  END IF;

  IF v_fuel > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'fuel', 'Fuel Surcharge', v_fuel);
  END IF;

  IF v_other > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'other', 'Other Charges', v_other);
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Allocations calculated');
END;
$$;


ALTER FUNCTION "public"."calculate_invoice_allocations"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_theoretical_depletion"("p_org_id" "uuid", "p_sales_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
    RAISE EXCEPTION 'Access Denied: Tenant context violation.';
  END IF;

  WITH sales AS (
    SELECT
      (elem->>'name')::TEXT AS sale_name,
      COALESCE((elem->>'qty')::NUMERIC, 0) AS sale_qty
    FROM jsonb_array_elements(p_sales_json) elem
  ),
  matched_recipes AS (
    SELECT
      s.sale_qty,
      r.id AS recipe_id
    FROM sales s
    JOIN public.recipes r ON lower(trim(r.name)) = lower(trim(s.sale_name))
    WHERE r.organization_id = p_org_id
  ),
  depletions AS (
    SELECT
      ri.product_id,
      COALESCE(p.name, ri.product_id::text) AS product_name,
      SUM(ri.quantity * mr.sale_qty) AS total_used,
      MAX(ri.unit) AS unit
    FROM matched_recipes mr
    JOIN public.recipe_ingredients ri ON ri.recipe_id = mr.recipe_id
    LEFT JOIN public.products p ON p.id = ri.product_id
    WHERE ri.organization_id = p_org_id
    GROUP BY ri.product_id, COALESCE(p.name, ri.product_id::text)
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'product_id', d.product_id,
      'product_name', d.product_name,
      'total_used', d.total_used,
      'unit', d.unit
    ) ORDER BY d.total_used DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM depletions d;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."calculate_theoretical_depletion"("p_org_id" "uuid", "p_sales_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_dashboard_scope"("p_org_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_scope" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND (
        p.role = 'platform_admin'
        OR (
          p.organization_id = p_org_id
          AND (
            p.role IN ('org_manager', 'tenant_super_admin')
            OR (p_scope = 'brand' AND p.role = 'branch_manager' AND (p.brand_id IS NULL OR p.brand_id = p_brand_id))
            OR (p_scope IN ('location', 'staff') AND p.role IN ('location_manager', 'ground_staff') AND (p.location_id IS NULL OR p.location_id = p_location_id))
            OR (p_scope IN ('location', 'staff') AND p.role = 'branch_manager' AND (p.brand_id IS NULL OR p.brand_id = p_brand_id))
          )
        )
      )
  );
$$;


ALTER FUNCTION "public"."can_access_dashboard_scope"("p_org_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_invite_role"("target_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  caller_role text := public.get_auth_role();
  normalized_target text := public.normalize_app_role(target_role);
BEGIN
  IF caller_role = 'platform_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin');
  END IF;

  IF caller_role = 'tenant_super_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin');
  END IF;

  IF caller_role = 'org_manager' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager');
  END IF;

  IF caller_role = 'branch_manager' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager');
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_invite_role"("target_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_invite_role"("target_role" "text") IS 'Returns TRUE if the authenticated user''s role is above the given target_role. Used in RLS policies to prevent privilege escalation on invitations.';



CREATE OR REPLACE FUNCTION "public"."capture_product_price_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_history jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.average_price := COALESCE(NEW.average_price, NEW.latest_price);
    NEW.price_history := COALESCE(NEW.price_history, '[]'::jsonb);
    RETURN NEW;
  END IF;

  IF NEW.latest_price IS DISTINCT FROM OLD.latest_price THEN
    v_history := COALESCE(OLD.price_history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'price', OLD.latest_price,
      'changed_at', now(),
      'changed_by', auth.uid(),
      'source', 'product_update'
    ));

    NEW.price_history := v_history;
    SELECT avg((entry->>'price')::numeric)
      INTO NEW.average_price
    FROM jsonb_array_elements(v_history || jsonb_build_array(jsonb_build_object('price', NEW.latest_price))) entry
    WHERE NULLIF(entry->>'price', '') IS NOT NULL;
  END IF;

  NEW.version_number := COALESCE(OLD.version_number, 1) + 1;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."capture_product_price_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_tenant_payment_signature"("p_bank_account_id" "uuid", "p_signer_full_name" "text", "p_signer_title" "text", "p_consent_version" "text", "p_consent_text" "text", "p_signature_sha256" "text", "p_signature_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_signature_storage_path" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_auth_id UUID;
  v_run_id UUID;
  v_account public.onboarding_bank_accounts%ROWTYPE;
  v_all_signed BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
  INTO v_account
  FROM public.onboarding_bank_accounts
  WHERE id = p_bank_account_id AND user_id = v_user_id AND status <> 'inactive';

  IF v_account.id IS NULL THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signer_full_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signer full name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signature_sha256, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signature hash is required';
  END IF;

  IF v_account.billing_address_source = 'custom' THEN
    IF NULLIF(btrim(v_account.billing_address_line1), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_city), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_state), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_postal_code), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_country), '') IS NULL THEN
      RAISE EXCEPTION 'A complete custom billing address (line 1, city, state, postal code, country) is required';
    END IF;
  END IF;

  UPDATE public.tenant_payment_authorizations
  SET status = 'revoked',
      updated_at = now()
  WHERE onboarding_bank_account_id = p_bank_account_id
    AND user_id = v_user_id
    AND status = 'active';

  INSERT INTO public.tenant_payment_authorizations (
    user_id,
    onboarding_bank_account_id,
    signer_full_name,
    signer_title,
    consent_version,
    consent_text,
    consent_accepted,
    signature_storage_path,
    signature_sha256,
    signature_payload,
    user_agent,
    status
  )
  VALUES (
    v_user_id,
    p_bank_account_id,
    btrim(p_signer_full_name),
    NULLIF(btrim(COALESCE(p_signer_title, '')), ''),
    COALESCE(NULLIF(btrim(p_consent_version), ''), 'tenant-bank-authorization-v1'),
    p_consent_text,
    true,
    NULLIF(btrim(COALESCE(p_signature_storage_path, '')), ''),
    btrim(p_signature_sha256),
    COALESCE(p_signature_payload, '{}'::jsonb),
    NULLIF(btrim(COALESCE(p_user_agent, '')), ''),
    'active'
  )
  RETURNING id INTO v_auth_id;

  UPDATE public.onboarding_bank_accounts
  SET status = 'authorized'
  WHERE id = p_bank_account_id;

  -- Onboarding is only "done" once every non-inactive account the tenant added has moved past
  -- pending_signature -- not after the first one, since Task 4 made multi-account real.
  SELECT NOT EXISTS (
    SELECT 1 FROM public.onboarding_bank_accounts
    WHERE user_id = v_user_id AND status = 'pending_signature'
  ) INTO v_all_signed;

  IF v_all_signed THEN
    UPDATE public.profiles
    SET banking_onboarding_completed = true,
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'signature_captured',
    'authorized',
    jsonb_build_object('onboarding_bank_account_id', p_bank_account_id, 'authorization_id', v_auth_id, 'all_accounts_signed', v_all_signed)
  );

  RETURN jsonb_build_object(
    'success', true,
    'authorization_id', v_auth_id,
    'bank_account_id', p_bank_account_id,
    'status', 'authorized',
    'all_accounts_signed', v_all_signed
  );
END;
$$;


ALTER FUNCTION "public"."capture_tenant_payment_signature"("p_bank_account_id" "uuid", "p_signer_full_name" "text", "p_signer_title" "text", "p_consent_version" "text", "p_consent_text" "text", "p_signature_sha256" "text", "p_signature_payload" "jsonb", "p_signature_storage_path" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cascade_invoice_prices"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    r RECORD;
BEGIN
    -- Only run when status changes to 'validated' or 'approved'
    IF NEW.status IN ('validated', 'approved') AND OLD.status NOT IN ('validated', 'approved') THEN
        -- Loop through all line items for this invoice
        FOR r IN 
            SELECT inventory_item_id, unit_price 
            FROM public.invoice_line_items 
            WHERE invoice_id = NEW.id AND inventory_item_id IS NOT NULL
        LOOP
            -- 1. Update products table
            -- This will automatically trigger `recalculate_recipe_costs_on_price_change` (Migration 044)
            UPDATE public.products
            SET 
                latest_price = r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id 
              AND organization_id = NEW.organization_id;

            -- 2. Update inventory table
            UPDATE public.inventory
            SET 
                unit_cost = r.unit_price,
                current_value = current_quantity * r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id
              AND organization_id = NEW.organization_id;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."cascade_invoice_prices"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_email_exists"("email_to_check" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE email = email_to_check
  );
END;
$$;


ALTER FUNCTION "public"."check_email_exists"("email_to_check" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_file_security"("bucket" "text", "metadata" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    file_size int;
    mime_type text;
BEGIN
    file_size := (metadata->>'size')::int;
    mime_type := metadata->>'mimetype';

    -- 1. Restrict File Size to 10MB (10 * 1024 * 1024 = 10485760 bytes)
    IF file_size > 10485760 THEN
        RETURN false;
    END IF;

    -- 2. Restrict MIME Types
    IF bucket = 'avatars' THEN
        IF mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp') THEN
            RETURN false;
        END IF;
    ELSIF bucket = 'invoices' THEN
        IF mime_type NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'text/csv') THEN
            RETURN false;
        END IF;
    ELSE
        -- Fallback for any future bucket
        IF mime_type NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'text/csv', 'image/webp') THEN
            RETURN false;
        END IF;
    END IF;

    RETURN true;
END;
$$;


ALTER FUNCTION "public"."check_file_security"("bucket" "text", "metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_three_way_match_before_invoice_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_match_data JSONB;
  v_match_status TEXT;
BEGIN
  -- Only evaluate when moving TO 'approved' or 'pending_payment'
  -- and only when a purchase_order_id is present
  IF NEW.purchase_order_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('approved', 'pending_payment') THEN
    RETURN NEW;
  END IF;

  -- Allow managers to force-approve from pending_match_approval
  -- (this is the explicit override path)
  IF OLD.status = 'pending_match_approval' THEN
    RETURN NEW;
  END IF;

  -- Evaluate the 3-way match
  v_match_data := public.get_three_way_match_status(NEW.purchase_order_id);
  v_match_status := v_match_data->>'match_status';

  IF v_match_status IN ('price_variance', 'critical_variance') THEN
    -- Raise an exception instead of silently rewriting the status.
    RAISE EXCEPTION 'THREE_WAY_MATCH_BLOCKED: Invoice cannot be approved due to a %-variance (%) between the PO and invoice. Variance amount: $%. Please review the 3-way match or force-approve from the match review screen.',
      v_match_data->>'variance_percent',
      v_match_status,
      v_match_data->>'variance_amount'
    USING
      ERRCODE = 'P0002',
      DETAIL = v_match_data::TEXT;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."check_three_way_match_before_invoice_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_bank_account_default_for_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.default_for_owner IS TRUE AND NEW.is_active IS TRUE AND NEW.deleted_at IS NULL THEN
    UPDATE public.bank_accounts
       SET default_for_owner = false,
           updated_at = now()
     WHERE id <> NEW.id
       AND default_for_owner = true
       AND is_active = true
       AND deleted_at IS NULL
       AND COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(NEW.tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND COALESCE(organization_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(NEW.organization_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND COALESCE(brand_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(NEW.brand_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND COALESCE(location_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(NEW.location_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND owner_type = NEW.owner_type
       AND owner_id = NEW.owner_id
       AND purpose = NEW.purpose;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."clear_bank_account_default_for_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_inventory_count_session"("p_organization_id" "uuid", "p_session_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.count_sessions;
BEGIN
  SELECT * INTO v_row
  FROM public.count_sessions
  WHERE id = p_session_id
    AND organization_id = p_organization_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Inventory count session not found';
  END IF;

  PERFORM public.assert_inventory_rpc_access(p_organization_id, v_row.location_id, false);

  UPDATE public.count_sessions
     SET status = 'closed',
         completed_at = COALESCE(completed_at, now()),
         closed_at = COALESCE(closed_at, now()),
         updated_at = now(),
         counted_by = COALESCE(counted_by, p_user_id, auth.uid())
   WHERE id = p_session_id
   RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."close_inventory_count_session"("p_organization_id" "uuid", "p_session_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commissary_route_scope_visible"("p_organization_id" "uuid", "p_route_id" "uuid", "p_origin_location_id" "uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_deleted_at IS NULL
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_origin_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          OR EXISTS (
            SELECT 1
            FROM public.commissary_route_stops crs
            WHERE crs.route_id = p_route_id
              AND crs.destination_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          )
        )
      )
    );
$$;


ALTER FUNCTION "public"."commissary_route_scope_visible"("p_organization_id" "uuid", "p_route_id" "uuid", "p_origin_location_id" "uuid", "p_deleted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commissary_route_scope_writable"("p_organization_id" "uuid", "p_origin_location_id" "uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.is_manager_or_above()
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_origin_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


ALTER FUNCTION "public"."commissary_route_scope_writable"("p_organization_id" "uuid", "p_origin_location_id" "uuid", "p_deleted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_product_import"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.product_import_jobs%ROWTYPE;
  v_import_row public.product_import_rows%ROWTYPE;
  v_product public.products%ROWTYPE;
  v_committed integer := 0;
  v_skipped integer := 0;
BEGIN
  SELECT * INTO v_job FROM public.product_import_jobs WHERE id = p_job_id FOR UPDATE;
  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Product import job not found';
  END IF;
  IF NOT public.product_write_allowed(v_job.organization_id, v_job.brand_id, v_job.location_id) THEN
    RAISE EXCEPTION 'Not authorized to commit this product import';
  END IF;

  FOR v_import_row IN
    SELECT * FROM public.product_import_rows
    WHERE job_id = v_job.id
    ORDER BY row_number
  LOOP
    IF v_import_row.status <> 'valid' THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.products (
      organization_id, brand_id, location_id, product_id, name, description,
      category, accounting_category, report_by_unit, base_unit, latest_price,
      is_inventoried, is_tax_exempt, location_specific, created_by, updated_at
    ) VALUES (
      v_job.organization_id,
      v_job.brand_id,
      v_job.location_id,
      NULLIF(btrim(COALESCE(v_import_row.payload->>'product_id', v_import_row.payload->>'Product ID', v_import_row.payload->>'sku', '')), ''),
      upper(btrim(COALESCE(v_import_row.payload->>'name', v_import_row.payload->>'Product Name', v_import_row.payload->>'product_name'))),
      NULLIF(btrim(COALESCE(v_import_row.payload->>'description', v_import_row.payload->>'Description', '')), ''),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'category', v_import_row.payload->>'Category', '')), ''), 'Uncategorized'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'accounting_category', v_import_row.payload->>'Accounting Category', '')), ''), '5110'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'report_by_unit', v_import_row.payload->>'Report By Unit', '')), ''), 'Each'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'base_unit', v_import_row.payload->>'Base Unit', '')), ''), 'Each'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'latest_price', v_import_row.payload->>'Latest Price', '')), '')::numeric, 0),
      CASE lower(btrim(COALESCE(v_import_row.payload->>'is_inventoried', v_import_row.payload->>'On Inventory', '')))
        WHEN 'true' THEN true
        WHEN 'yes' THEN true
        WHEN '1' THEN true
        ELSE false
      END,
      CASE lower(btrim(COALESCE(v_import_row.payload->>'is_tax_exempt', v_import_row.payload->>'Tax Exempt', '')))
        WHEN 'true' THEN true
        WHEN 'yes' THEN true
        WHEN '1' THEN true
        ELSE false
      END,
      v_job.location_id IS NOT NULL,
      auth.uid(),
      now()
    )
    RETURNING * INTO v_product;

    UPDATE public.product_import_rows
       SET status = 'committed', product_id = v_product.id
     WHERE id = v_import_row.id;

    IF v_product.is_inventoried THEN
      PERFORM public.set_product_inventory_tracking(v_product.id, true);
    END IF;

    v_committed := v_committed + 1;
  END LOOP;

  UPDATE public.product_import_jobs
     SET status = 'committed',
         committed_at = now(),
         summary = COALESCE(summary, '{}'::jsonb) || jsonb_build_object('committed_rows', v_committed, 'skipped_rows', v_skipped)
   WHERE id = v_job.id;

  RETURN jsonb_build_object('success', true, 'job_id', v_job.id, 'committed_rows', v_committed, 'skipped_rows', v_skipped);
END;
$$;


ALTER FUNCTION "public"."commit_product_import"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_count_session"("p_organization_id" "uuid", "p_location_id" "uuid", "p_count_sheet_id" "uuid", "p_counts" "jsonb", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sheet record;
  v_item jsonb;
  v_inv_id uuid;
  v_counted_qty numeric;
  v_expected_qty numeric;
  v_variance_qty numeric;
  v_unit_cost numeric;
  v_variance_dollar numeric;
  v_total_variance_value numeric := 0;
  v_counted_data jsonb := '{}'::jsonb;
  v_variance_data jsonb := '{}'::jsonb;
  v_count_session_id uuid;
  v_gl_id uuid;
  v_is_favorable boolean;
  v_current_inventory public.inventory;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_location_id, false);

  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location is required to complete a count session';
  END IF;

  SELECT * INTO v_sheet
  FROM public.count_sheets
  WHERE id = p_count_sheet_id
    AND organization_id = p_organization_id
    AND location_id = p_location_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_sheet.id IS NULL THEN
    RAISE EXCEPTION 'Count sheet not found for active location';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_sheet.items)
  LOOP
    v_inv_id := (v_item->>'inventory_id')::uuid;
    v_expected_qty := COALESCE((v_item->>'expected_quantity')::numeric, 0);
    v_counted_qty := CASE
      WHEN p_counts ? v_inv_id::text THEN COALESCE((p_counts->>v_inv_id::text)::numeric, 0)
      ELSE v_expected_qty
    END;

    SELECT * INTO v_current_inventory
    FROM public.inventory
    WHERE id = v_inv_id
      AND organization_id = p_organization_id
      AND location_id = p_location_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_current_inventory.id IS NULL THEN
      CONTINUE;
    END IF;

    v_unit_cost := COALESCE(v_current_inventory.unit_cost, 0);
    v_variance_qty := v_counted_qty - v_expected_qty;
    v_variance_dollar := v_variance_qty * v_unit_cost;

    IF v_variance_dollar <> 0 THEN
      v_total_variance_value := v_total_variance_value + v_variance_dollar;
      v_variance_data := jsonb_set(v_variance_data, ARRAY[v_inv_id::text], jsonb_build_object('qty', v_variance_qty, 'value', v_variance_dollar));
    END IF;

    v_counted_data := jsonb_set(
      v_counted_data,
      ARRAY[v_inv_id::text],
      jsonb_build_object(
        'product_name', v_current_inventory.product_name,
        'expected_quantity', v_expected_qty,
        'counted_quantity', v_counted_qty,
        'unit', COALESCE(v_current_inventory.current_unit, 'ea'),
        'unit_cost', v_unit_cost,
        'variance', v_variance_dollar
      )
    );

    IF v_counted_qty <> v_expected_qty THEN
      UPDATE public.inventory
         SET current_quantity = v_counted_qty,
             current_value = v_counted_qty * v_unit_cost,
             previous_quantity = v_expected_qty,
             previous_value = v_current_inventory.current_value,
             last_counted_date = CURRENT_DATE,
             last_counted_by = COALESCE(p_user_id, auth.uid()),
             updated_at = now()
       WHERE id = v_inv_id;
    END IF;
  END LOOP;

  IF abs(v_total_variance_value) > 0.01 THEN
    v_is_favorable := v_total_variance_value > 0;

    INSERT INTO public.general_ledger_entries (
      organization_id, date, reference, description,
      debit_account, credit_account, amount, created_by
    ) VALUES (
      p_organization_id,
      now(),
      'INV-VAR-' || extract(epoch from now())::text,
      'Inventory Count Variance Adjustment',
      CASE WHEN v_is_favorable THEN 'Inventory Asset (1210)' ELSE 'COGS - Variance (5100)' END,
      CASE WHEN v_is_favorable THEN 'COGS - Variance (5100)' ELSE 'Inventory Asset (1210)' END,
      abs(v_total_variance_value),
      COALESCE(p_user_id, auth.uid())
    )
    RETURNING id INTO v_gl_id;

    INSERT INTO public.accounting_export_queue (organization_id, entity_type, entity_id, status)
    VALUES (p_organization_id, 'journal_entry', v_gl_id, 'ready')
    ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO public.count_sessions (
    organization_id, location_id, brand_id, count_sheet_id, status, counted_data,
    variance_data, completed_at, counted_by, count_date, items, total_value, item_count
  ) VALUES (
    p_organization_id, p_location_id, v_sheet.brand_id, p_count_sheet_id, 'completed',
    v_counted_data, v_variance_data, now(), COALESCE(p_user_id, auth.uid()),
    CURRENT_DATE, v_sheet.items, abs(v_total_variance_value), jsonb_array_length(v_sheet.items)
  )
  RETURNING id INTO v_count_session_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_sheet.items)
  LOOP
    v_inv_id := (v_item->>'inventory_id')::uuid;
    v_expected_qty := COALESCE((v_item->>'expected_quantity')::numeric, 0);
    v_counted_qty := CASE
      WHEN p_counts ? v_inv_id::text THEN COALESCE((p_counts->>v_inv_id::text)::numeric, 0)
      ELSE v_expected_qty
    END;

    IF v_counted_qty <> v_expected_qty THEN
      INSERT INTO public.inventory_movements (
        organization_id, location_id, inventory_id, movement_type, quantity,
        source_type, source_id, previous_quantity, new_quantity, created_by
      ) VALUES (
        p_organization_id, p_location_id, v_inv_id, 'count_variance',
        v_counted_qty - v_expected_qty, 'count_session', v_count_session_id,
        v_expected_qty, v_counted_qty, COALESCE(p_user_id, auth.uid())
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'count_session_id', v_count_session_id, 'total_variance', v_total_variance_value);
END;
$$;


ALTER FUNCTION "public"."complete_count_session"("p_organization_id" "uuid", "p_location_id" "uuid", "p_count_sheet_id" "uuid", "p_counts" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_inventory_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.transfers;
  v_item jsonb;
  v_qty numeric;
  v_source_inv public.inventory;
  v_dest_inv public.inventory;
  v_dest_inv_id uuid;
  v_unit_cost numeric;
  v_dest_previous_quantity numeric;
BEGIN
  SELECT * INTO v_transfer
  FROM public.transfers
  WHERE id = p_transfer_id
    AND organization_id = p_organization_id
  FOR UPDATE;

  IF v_transfer.id IS NULL THEN
    RAISE EXCEPTION 'Transfer not found';
  END IF;

  PERFORM public.assert_inventory_rpc_access(p_organization_id, v_transfer.from_location_id, true);

  IF v_transfer.status NOT IN ('pending', 'in_transit') THEN
    RETURN jsonb_build_object('success', true, 'already_completed', true, 'message', 'Transfer already completed');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_transfer.items)
  LOOP
    v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;
    v_unit_cost := COALESCE((v_item->>'unit_cost')::numeric, 0);

    SELECT * INTO v_source_inv
    FROM public.inventory
    WHERE id = (v_item->>'inventory_id')::uuid
      AND organization_id = p_organization_id
      AND location_id = v_transfer.from_location_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_source_inv.id IS NULL THEN
      RAISE EXCEPTION 'Source inventory item not found for transfer';
    END IF;

    UPDATE public.inventory
       SET current_quantity = GREATEST(0, COALESCE(v_source_inv.current_quantity, 0) - v_qty),
           current_value = GREATEST(0, COALESCE(v_source_inv.current_quantity, 0) - v_qty) * COALESCE(unit_cost, v_unit_cost),
           previous_quantity = COALESCE(v_source_inv.current_quantity, 0),
           previous_value = COALESCE(v_source_inv.current_value, 0),
           updated_at = now()
     WHERE id = v_source_inv.id;

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_organization_id, v_transfer.from_location_id, v_source_inv.id, 'transfer_out',
      -v_qty, 'transfer', p_transfer_id, COALESCE(v_source_inv.current_quantity, 0),
      GREATEST(0, COALESCE(v_source_inv.current_quantity, 0) - v_qty), COALESCE(p_user_id, auth.uid())
    );

    v_dest_inv := NULL;
    IF NULLIF(v_item->>'product_id', '') IS NOT NULL THEN
      SELECT * INTO v_dest_inv
      FROM public.inventory
      WHERE product_id = v_item->>'product_id'
        AND organization_id = p_organization_id
        AND location_id = v_transfer.to_location_id
        AND deleted_at IS NULL
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_dest_inv.id IS NULL THEN
      SELECT * INTO v_dest_inv
      FROM public.inventory
      WHERE lower(product_name) = lower(v_item->>'product_name')
        AND organization_id = p_organization_id
        AND location_id = v_transfer.to_location_id
        AND deleted_at IS NULL
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_dest_inv.id IS NOT NULL THEN
      v_dest_inv_id := v_dest_inv.id;
      v_dest_previous_quantity := COALESCE(v_dest_inv.current_quantity, 0);

      UPDATE public.inventory
         SET current_quantity = v_dest_previous_quantity + v_qty,
             current_value = (v_dest_previous_quantity + v_qty) * COALESCE(unit_cost, v_unit_cost),
             previous_quantity = v_dest_previous_quantity,
             previous_value = COALESCE(v_dest_inv.current_value, 0),
             updated_at = now()
       WHERE id = v_dest_inv.id;
    ELSE
      v_dest_previous_quantity := 0;

      INSERT INTO public.inventory (
        organization_id, brand_id, location_id, product_id, product_name, current_quantity,
        current_unit, unit_cost, current_value, accounting_category, par_level,
        reorder_point, previous_quantity, previous_value
      ) VALUES (
        p_organization_id, v_source_inv.brand_id, v_transfer.to_location_id,
        COALESCE(NULLIF(v_item->>'product_id', ''), v_source_inv.product_id, 'PRD-' || extract(epoch from now())::text),
        COALESCE(NULLIF(v_item->>'product_name', ''), v_source_inv.product_name),
        v_qty, COALESCE(v_item->>'unit', v_source_inv.current_unit, 'ea'), COALESCE(NULLIF(v_unit_cost, 0), v_source_inv.unit_cost, 0),
        v_qty * COALESCE(NULLIF(v_unit_cost, 0), v_source_inv.unit_cost, 0), COALESCE(v_source_inv.accounting_category, 'food'),
        0, 0, 0, 0
      )
      RETURNING id INTO v_dest_inv_id;
    END IF;

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_organization_id, v_transfer.to_location_id, v_dest_inv_id, 'transfer_in',
      v_qty, 'transfer', p_transfer_id, v_dest_previous_quantity,
      v_dest_previous_quantity + v_qty, COALESCE(p_user_id, auth.uid())
    );
  END LOOP;

  UPDATE public.transfers
     SET status = 'completed',
         completed_at = now(),
         completed_by = COALESCE(p_user_id, auth.uid()),
         updated_at = now()
   WHERE id = p_transfer_id;

  RETURN jsonb_build_object('success', true, 'transfer_id', p_transfer_id);
END;
$$;


ALTER FUNCTION "public"."complete_inventory_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_onboarding"("p_user_id" "uuid", "p_org_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  caller_org_id uuid;
  org_owner uuid;
  v_current_role text;
BEGIN
  -- Verify caller is the user being updated
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Can only complete onboarding for yourself';
  END IF;

  -- Verify the user does NOT already have an org (prevents re-onboarding abuse)
  SELECT organization_id, role INTO caller_org_id, v_current_role FROM public.profiles WHERE id = p_user_id;
  IF caller_org_id IS NOT NULL THEN
    RAISE EXCEPTION 'User already belongs to an organization';
  END IF;

  -- Verify the org exists and the user is the owner
  SELECT owner_id INTO org_owner FROM public.organizations WHERE id = p_org_id;
  IF org_owner IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Organization does not belong to this user';
  END IF;

  -- Update the profile with org hierarchy and preserve platform_admin
  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles SET
    organization_id = p_org_id,
    brand_id = p_brand_id,
    location_id = p_location_id,
    role = CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
    access_level = CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
    updated_at = now()
  WHERE id = p_user_id;

  -- Sync JWT metadata
  UPDATE auth.users SET
    raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
      'access_level', CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
      'organization_id', p_org_id,
      'brand_id', p_brand_id,
      'location_id', p_location_id
    )
  WHERE id = p_user_id;

  -- Audit log
  INSERT INTO public.audit_logs (organization_id, user_id, action, table_name, record_id, new_data)
  VALUES (p_org_id, p_user_id, 'ONBOARDING_COMPLETE', 'profiles', p_user_id,
          jsonb_build_object('org_id', p_org_id, 'brand_id', p_brand_id, 'location_id', p_location_id));
END;
$$;


ALTER FUNCTION "public"."complete_onboarding"("p_user_id" "uuid", "p_org_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_workflow"("p_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  SELECT *
    INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_payment.id IS NULL THEN
    RAISE EXCEPTION 'Payment not found';
  END IF;

  PERFORM public.assert_financial_actor(v_payment.organization_id);

  UPDATE public.payments
     SET status = 'completed',
         updated_at = now()
   WHERE id = p_payment_id
   RETURNING * INTO v_payment;

  RETURN to_jsonb(v_payment);
END;
$$;


ALTER FUNCTION "public"."confirm_payment_workflow"("p_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_vendor_banking_callback"("p_request_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
BEGIN
  SELECT * INTO v_request
  FROM public.vendor_banking_change_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'Banking change request not found';
  END IF;

  IF NOT public.reference_scope_writable(v_request.organization_id, v_request.brand_id, v_request.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_change_requests
     SET callback_status = 'confirmed',
         confirmed_by = auth.uid(),
         confirmed_at = now(),
         notes = COALESCE(p_notes, notes),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_request_id
   RETURNING * INTO v_request;

  UPDATE public.vendor_banking_details
     SET callback_status = 'confirmed',
         verification_state = 'verified',
         verified_at = COALESCE(verified_at, now()),
         is_default = CASE
           WHEN v_request.request_reason IN ('onboarding', 'vendor_requested_update')
             OR NOT EXISTS (
               SELECT 1
               FROM public.vendor_banking_details existing
               WHERE existing.vendor_id = v_request.vendor_id
                 AND existing.is_default = true
                 AND existing.is_active = true
                 AND existing.deleted_at IS NULL
                 AND existing.id IS DISTINCT FROM v_request.banking_detail_id
             )
           THEN true
           ELSE is_default
         END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = v_request.banking_detail_id
   RETURNING * INTO v_bank;

  UPDATE public.vendors
     SET onboarding_status = 'banking_verified',
         updated_at = now()
   WHERE id = v_request.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_request.vendor_id,
    'callback_confirmed',
    'banking_verified',
    'admin',
    jsonb_build_object('banking_row_id', v_bank.id, 'change_request_id', v_request.id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_request.vendor_id,
    'banking_row_id', v_bank.id,
    'change_request_id', v_request.id,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status,
    'is_default', v_bank.is_default
  );
END;
$$;


ALTER FUNCTION "public"."confirm_vendor_banking_callback"("p_request_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_tenant_reporting_rows"("p_schema_name" "text", "p_table_name" "text", "p_organization_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  row_count BIGINT := 0;
  has_org_column BOOLEAN := false;
BEGIN
  IF p_schema_name IS NULL OR p_table_name IS NULL THEN
    RETURN 0;
  END IF;

  IF p_schema_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' OR p_table_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
    RAISE EXCEPTION 'Unsafe schema or table name for tenant reporting count';
  END IF;

  IF to_regclass(format('%I.%I', p_schema_name, p_table_name)) IS NULL THEN
    RETURN 0;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = p_schema_name
      AND c.table_name = p_table_name
      AND c.column_name = 'organization_id'
  ) INTO has_org_column;

  IF has_org_column THEN
    EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', p_schema_name, p_table_name)
    INTO row_count
    USING p_organization_id;
  ELSE
    EXECUTE format('SELECT count(*) FROM %I.%I', p_schema_name, p_table_name)
    INTO row_count;
  END IF;

  RETURN COALESCE(row_count, 0);
END;
$_$;


ALTER FUNCTION "public"."count_tenant_reporting_rows"("p_schema_name" "text", "p_table_name" "text", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_account_workflow"("p_account" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id UUID;
  v_account RECORD;
  v_last_four TEXT;
BEGIN
  v_org_id := COALESCE(NULLIF(p_account->>'organization_id', '')::UUID, public.get_my_org());
  PERFORM public.assert_financial_actor(v_org_id);

  v_last_four := COALESCE(NULLIF(p_account->>'last_four', ''), NULLIF(p_account->>'account_number_last4', ''));

  INSERT INTO public.payment_accounts (
    organization_id,
    brand_id,
    location_id,
    name,
    account_type,
    payment_method,
    provider,
    provider_reference,
    last_four,
    is_default,
    is_active,
    metadata,
    created_by,
    updated_by
  ) VALUES (
    v_org_id,
    NULLIF(p_account->>'brand_id', '')::UUID,
    NULLIF(p_account->>'location_id', '')::UUID,
    NULLIF(trim(p_account->>'name'), ''),
    COALESCE(NULLIF(p_account->>'account_type', ''), 'checking'),
    NULLIF(p_account->>'payment_method', ''),
    NULLIF(p_account->>'provider', ''),
    NULLIF(p_account->>'provider_reference', ''),
    v_last_four,
    COALESCE((p_account->>'is_default')::BOOLEAN, false),
    true,
    COALESCE(p_account->'metadata', '{}'::jsonb) || jsonb_build_object(
      'routing_number_last4', NULLIF(p_account->>'routing_number_last4', ''),
      'account_number_last4', NULLIF(p_account->>'account_number_last4', '')
    ),
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_account;

  IF v_account.name IS NULL THEN
    RAISE EXCEPTION 'Payment account name is required';
  END IF;

  RETURN to_jsonb(v_account);
END;
$$;


ALTER FUNCTION "public"."create_payment_account_workflow"("p_account" "jsonb") OWNER TO "postgres";

