CREATE OR REPLACE FUNCTION "public"."deactivate_payment_account_workflow"("p_payment_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_account RECORD;
BEGIN
  SELECT *
    INTO v_account
  FROM public.payment_accounts
  WHERE id = p_payment_account_id
  FOR UPDATE;

  IF v_account.id IS NULL THEN
    RAISE EXCEPTION 'Payment account not found';
  END IF;

  PERFORM public.assert_financial_actor(v_account.organization_id);

  UPDATE public.payment_accounts
     SET is_active = false,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_payment_account_id
   RETURNING * INTO v_account;

  RETURN to_jsonb(v_account);
END;
$$;


