CREATE OR REPLACE FUNCTION "public"."delete_inventory_count_session"("p_organization_id" "uuid", "p_session_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.count_sessions;
BEGIN
  SELECT * INTO v_row
  FROM public.count_sessions
  WHERE id = p_session_id
    AND organization_id = p_organization_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN false;
  END IF;

  PERFORM public.assert_inventory_rpc_access(p_organization_id, v_row.location_id, false);

  UPDATE public.count_sessions
     SET deleted_at = now(), updated_at = now()
   WHERE id = p_session_id;

  RETURN true;
END;
$$;


