CREATE OR REPLACE FUNCTION "public"."delete_recipe_category"("p_category_id" "uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."recipe_categories"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
  v_old public.recipe_categories;
  v_row public.recipe_categories;
  v_count bigint := 0;
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() OR NOT public.is_manager_or_above() THEN
    RAISE EXCEPTION 'Not authorized to delete recipe categories';
  END IF;

  IF p_category_id IS NULL THEN
    RAISE EXCEPTION 'Category id is required';
  END IF;

  SELECT *
  INTO v_old
  FROM public.recipe_categories rc
  WHERE rc.id = p_category_id
    AND rc.organization_id = v_org
    AND rc.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category not found';
  END IF;

  SELECT COUNT(*)::bigint
  INTO v_count
  FROM public.recipes r
  WHERE r.organization_id = v_org
    AND r.deleted_at IS NULL
    AND lower(COALESCE(r.category, '')) = lower(v_old.slug);

  IF v_count > 0 THEN
    RAISE EXCEPTION 'This category is used by % recipes and cannot be deleted.', v_count;
  END IF;

  UPDATE public.recipe_categories rc
  SET
    deleted_at = now(),
    is_active = false,
    updated_at = now()
  WHERE rc.id = v_old.id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."delete_recipe_category"("p_category_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_product_category"("p_category" "text", "p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_category, '')), '') IS NOT NULL
      AND lower(trim(p_category)) <> 'uncategorized'
      THEN trim(p_category)
    WHEN lower(COALESCE(p_name, '')) ~ '(lettuce|tomato|potato|onion|pepper|celery|carrot|cucumber|lemon|okra|coleslaw|produce)'
      THEN 'Produce'
    WHEN lower(COALESCE(p_name, '')) ~ '(cheese|milk|cream|butter|buttermilk|dairy)'
      THEN 'Dairy'
    WHEN lower(COALESCE(p_name, '')) ~ '(chicken|wing|breast|tender|poultry)'
      THEN 'Poultry'
    WHEN lower(COALESCE(p_name, '')) ~ '(beef|bacon|pork|meat|patty)'
      THEN 'Meat'
    WHEN lower(COALESCE(p_name, '')) ~ '(beer|ale|lager)'
      THEN 'Beer'
    WHEN lower(COALESCE(p_name, '')) ~ '(wine|pinot|cabernet|chardonnay)'
      THEN 'Wine'
    WHEN lower(COALESCE(p_name, '')) ~ '(vodka|gin|rum|tequila|whiskey|liquor)'
      THEN 'Liquor'
    WHEN lower(COALESCE(p_name, '')) ~ '(container|towel|scrubber|glove|kit, ctly|napkin|paper|bleach)'
      THEN 'Restaurant Supplies'
    WHEN lower(COALESCE(p_name, '')) ~ '(flour|bread|roll|macaroni|ketchup|mayonnaise|sauce|shortening|tortilla|breade?r|syrup)'
      THEN 'Grocery and Dry Goods'
    ELSE 'Uncategorized'
  END;
$$;


ALTER FUNCTION "public"."derive_product_category"("p_category" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_product_category_type"("p_accounting_category" "text", "p_category" "text", "p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  WITH src AS (
    SELECT
      lower(COALESCE(p_accounting_category, '')) AS accounting,
      lower(COALESCE(p_category, '')) AS category,
      lower(COALESCE(p_name, '')) AS name
  )
  SELECT CASE
    WHEN accounting = '5230' OR category ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer)' OR name ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer)' THEN 'Beer'
    WHEN accounting = '5240' OR category ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel)' OR name ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel)' THEN 'Wine'
    WHEN accounting = '5220' OR category ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur)' OR name ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur)' THEN 'Liquor'
    WHEN accounting IN ('5200','5210') OR category ~ '(n-a bev|n/a bev|na bev|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|water|fountain|syrup)' OR name ~ '(n-a bev|n/a bev|na bev|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|water|fountain|syrup)' THEN 'N-A Bev'
    WHEN accounting = '5300' OR category ~ '(retail|merchandise|apparel|shirt|hat|gift ?card|merch)' OR name ~ '(retail|merchandise|apparel|shirt|hat|gift ?card|merch)' THEN 'Retail'
    WHEN accounting LIKE '51%' OR accounting IN ('food','food_cogs','5100') OR category ~ '(bakery|meat|poultry|seafood|dairy|produce|frozen|grocery|food)' THEN 'Food'
    ELSE 'Other'
  END
  FROM src;
$$;


ALTER FUNCTION "public"."derive_product_category_type"("p_accounting_category" "text", "p_category" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_product_report_unit"("p_vendor_unit" "text" DEFAULT NULL::"text", "p_pack_size" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_pack text := upper(regexp_replace(trim(COALESCE(p_pack_size, '')), '[^A-Z0-9./ ]', ' ', 'g'));
  v_vendor text := trim(COALESCE(p_vendor_unit, ''));
  v_vendor_label text := public.normalize_product_unit_label(v_vendor);
BEGIN
  IF v_pack = '' AND v_vendor ~ '[0-9]' THEN
    v_pack := upper(regexp_replace(v_vendor, '[^A-Z0-9./ ]', ' ', 'g'));
  END IF;

  IF v_pack <> '' THEN
    RETURN COALESCE(public.normalize_product_unit_label(v_pack), v_pack);
  END IF;

  RETURN COALESCE(v_vendor_label, NULLIF(v_vendor, ''), 'Each');
END;
$$;


ALTER FUNCTION "public"."derive_product_report_unit"("p_vendor_unit" "text", "p_pack_size" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_webhook_queue"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_url text;
  v_functions_url text;
  v_service_role_key text;
BEGIN
  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for dispatch_webhook_queue';
  END IF;

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/webhook-dispatcher';

  PERFORM net.http_post(
    url := v_url,
    body := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_role_key
    )
  );
END;
$$;


ALTER FUNCTION "public"."dispatch_webhook_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_domain_event"("p_event_name" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_org_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_event_id UUID;
BEGIN
    IF p_org_id IS NOT NULL AND NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
        RAISE EXCEPTION 'Cannot emit domain events for another organization';
    END IF;

    INSERT INTO public.event_logs (event_name, entity_type, entity_id, organization_id, payload)
    VALUES (p_event_name, p_entity_type, p_entity_id, p_org_id, p_payload)
    RETURNING id INTO v_event_id;

    -- Automatically queue a webhook if there are active subscriptions
    -- This unifies Real-Time UI events and Webhooks!
    IF p_org_id IS NOT NULL THEN
        INSERT INTO public.webhook_events_queue (organization_id, endpoint_id, event_type, payload)
        SELECT we.organization_id, we.id, p_event_name, p_payload
        FROM public.webhook_endpoints we
        JOIN public.webhook_subscriptions ws ON we.id = ws.endpoint_id
        WHERE we.organization_id = p_org_id
          AND we.status = 'active'
          AND (ws.event_type = p_event_name OR ws.event_type = '*');
    END IF;

    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."emit_domain_event"("p_event_name" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_org_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_business_verification_contact_otp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_profile RECORD;
  v_email TEXT;
  v_phone TEXT;
BEGIN
  IF public.get_auth_role() = 'platform_admin' THEN
    RETURN NEW;
  END IF;

  v_email := public.normalize_contact_target('email', NEW.metadata->>'email');
  v_phone := public.normalize_contact_target('phone', NEW.metadata->>'phone');

  SELECT business_email, business_email_verified_at, business_phone, business_phone_verified_at
  INTO v_profile
  FROM public.profiles
  WHERE id = NEW.user_id;

  IF v_profile.business_email_verified_at IS NULL OR v_profile.business_email IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'Business email must be verified by OTP before business verification';
  END IF;

  IF v_profile.business_phone_verified_at IS NULL OR v_profile.business_phone IS DISTINCT FROM v_phone THEN
    RAISE EXCEPTION 'Business phone must be verified by OTP before business verification';
  END IF;

  NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb) || jsonb_build_object(
    'email_verified', true,
    'email_verified_at', v_profile.business_email_verified_at,
    'phone_verified', true,
    'phone_verified_at', v_profile.business_phone_verified_at
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_business_verification_contact_otp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_business_verification_identifier_type"() RETURNS "trigger"
