CREATE OR REPLACE FUNCTION "public"."enforce_notification_delivery_preference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_module_key text;
  v_is_critical boolean;
  v_in_app_enabled boolean;
  v_critical_only boolean;
  v_email_enabled boolean;
  v_phone_enabled boolean;
  v_send_email boolean;
  v_send_sms boolean;
  v_functions_url text;
  v_service_role_key text;
  v_url text;
BEGIN
  v_module_key := COALESCE(
    NEW.metadata->>'module_key',
    CASE NEW.type
      WHEN 'approval' THEN 'invoices'
      WHEN 'invoice' THEN 'invoices'
      WHEN 'invoice_approved' THEN 'invoices'
      WHEN 'payment' THEN 'payments'
      WHEN 'payment_failed' THEN 'payments'
      WHEN 'billing' THEN 'payments'
      WHEN 'inventory' THEN 'inventory'
      WHEN 'low_inventory' THEN 'inventory'
      WHEN 'order' THEN 'inventory'
      WHEN 'vendor_update' THEN 'vendors'
      WHEN 'labor_alert' THEN 'labor'
      ELSE 'dashboard'
    END
  );

  v_is_critical := COALESCE((NEW.metadata->>'critical')::boolean, false)
    OR NEW.metadata->>'priority' = 'critical'
    OR NEW.type IN ('error', 'warning', 'payment_failed', 'low_inventory', 'AI_alert');

  SELECT in_app_enabled, critical_only, email_enabled, phone_enabled
    INTO v_in_app_enabled, v_critical_only, v_email_enabled, v_phone_enabled
  FROM public.notification_delivery_preferences
  WHERE user_id = NEW.user_id AND module_key = v_module_key;

  IF NOT FOUND THEN
    v_in_app_enabled := true;
    v_critical_only := false;
    v_email_enabled := false;
    v_phone_enabled := false;
  END IF;

  IF NOT v_in_app_enabled THEN
    RETURN NULL;
  END IF;

  IF v_critical_only AND NOT v_is_critical THEN
    RETURN NULL;
  END IF;

  IF NEW.metadata->>'skip_channel_dispatch' = 'true' THEN
    RETURN NEW;
  END IF;

  v_send_email := v_email_enabled OR v_is_critical;
  v_send_sms := v_phone_enabled;

  IF v_send_email OR v_send_sms THEN
    BEGIN
      SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
      SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

      IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
        v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/notify-channel-dispatch';

        PERFORM net.http_post(
          url := v_url,
          body := jsonb_build_object(
            'notification_id', NEW.id,
            'user_id', NEW.user_id,
            'title', NEW.title,
            'message', COALESCE(NEW.message, NEW.body),
            'send_email', v_send_email,
            'send_sms', v_send_sms
          ),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_role_key
          )
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Same rule as before: a dispatch failure must never block the in-app row landing.
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_notification_delivery_preference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_products_product_id_unique"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.deleted_at IS NULL AND NULLIF(btrim(COALESCE(NEW.product_id, '')), '') IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.products p
      WHERE p.id IS DISTINCT FROM NEW.id
        AND p.deleted_at IS NULL
        AND lower(btrim(p.product_id)) = lower(btrim(NEW.product_id))
    ) THEN
      RAISE EXCEPTION 'Product ID "%" is already in use. Choose a different one.', NEW.product_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_products_product_id_unique"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_vendor_approval_authorization"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.approval_status IN ('pending_approval', 'approved', 'suspended', 'rejected') THEN
      IF NEW.approval_status = 'approved' AND NEW.created_by IS NOT NULL AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Vendor submitters cannot approve their own vendors';
      END IF;

      PERFORM public.assert_can_approve_vendor_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    IF NEW.approval_status = 'approved' AND NEW.created_by IS NOT NULL AND NEW.created_by = auth.uid() THEN
      RAISE EXCEPTION 'Vendor submitters cannot approve their own vendors';
    END IF;

    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_vendor_approval_authorization"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_vendor_banking_default_replacement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Ponytail: replace deactivates the prior default at the single "becoming
  -- default" point, so link submit and manual promotion cannot diverge. Ceiling:
  -- a future "switch default but keep both active" flow needs an explicit flag.
  IF NEW.is_default IS TRUE
     AND (TG_OP = 'INSERT' OR OLD.is_default IS DISTINCT FROM TRUE) THEN
    UPDATE public.vendor_banking_details
       SET is_default = false,
           is_active = false,
           updated_at = now()
     WHERE vendor_id = NEW.vendor_id
       AND id IS DISTINCT FROM NEW.id
       AND is_default = true
       AND is_active = true
       AND deleted_at IS NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_vendor_banking_default_replacement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_default_recipe_categories"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.recipe_categories (
    organization_id, name, slug, display_order, is_active, is_system
  )
  SELECT
    p_organization_id,
    d.name,
    d.slug,
    d.display_order,
    true,
    true
  FROM (
    VALUES
      ('Appetizer', 'appetizer', 10),
      ('Main Course', 'main_course', 20),
      ('Dessert', 'dessert', 30),
      ('Beverage', 'beverage', 40),
      ('Side', 'side', 50),
      ('Sauce', 'sauce', 60)
  ) AS d(name, slug, display_order)
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.recipe_categories rc
    WHERE rc.organization_id = p_organization_id
      AND lower(rc.slug) = d.slug
  );
END;
$$;


ALTER FUNCTION "public"."ensure_default_recipe_categories"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_dim_date"("p_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_date_key integer;
BEGIN
  IF p_date IS NULL THEN
    RETURN NULL;
  END IF;

  v_date_key := to_char(p_date, 'YYYYMMDD')::integer;

  INSERT INTO public.dim_date (
    date_key,
    full_date,
    day_of_week,
    day_name,
    day_of_month,
    day_of_year,
    week_of_year,
    month_number,
    month_name,
    quarter,
    year,
    is_weekend,
    is_month_end,
    fiscal_quarter
  ) VALUES (
    v_date_key,
    p_date,
    extract(dow from p_date)::smallint,
    trim(to_char(p_date, 'Day')),
    extract(day from p_date)::smallint,
    extract(doy from p_date)::smallint,
    extract(week from p_date)::smallint,
    extract(month from p_date)::smallint,
    trim(to_char(p_date, 'Month')),
    extract(quarter from p_date)::smallint,
    extract(year from p_date)::smallint,
    extract(dow from p_date) in (0, 6),
    p_date = (date_trunc('month', p_date)::date + interval '1 month - 1 day')::date,
    'FY' || extract(year from p_date)::text || '-Q' || extract(quarter from p_date)::text
  )
  ON CONFLICT (date_key) DO NOTHING;

  RETURN v_date_key;
END;
$$;


ALTER FUNCTION "public"."ensure_dim_date"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_inventory_for_invoiced_products"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_created_count integer := 0;
  v_marked_count integer := 0;
BEGIN
  WITH invoice_products AS (
    SELECT DISTINCT
      i.organization_id,
      i.brand_id,
      i.location_id,
      l.name AS location_name,
      p.id AS internal_product_id,
      p.product_id,
      p.name AS product_name,
      p.category,
      p.accounting_category,
      COALESCE(p.report_by_unit, p.base_unit, 'Each') AS unit,
      COALESCE(p.latest_price, 0) AS unit_cost
    FROM public.invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    JOIN public.products p ON p.id = ili.internal_product_id
    LEFT JOIN public.locations l ON l.id = i.location_id
    WHERE i.id = p_invoice_id
      AND i.deleted_at IS NULL
      AND p.deleted_at IS NULL
      AND ili.internal_product_id IS NOT NULL
  ), marked AS (
    UPDATE public.products p
       SET is_inventoried = true,
           updated_at = now()
      FROM invoice_products ip
     WHERE p.id = ip.internal_product_id
       AND COALESCE(p.is_inventoried, false) IS DISTINCT FROM true
    RETURNING p.id
  ), inserted AS (
    INSERT INTO public.inventory (
      organization_id,
      brand_id,
      location_id,
      internal_product_id,
      product_id,
      product_name,
      category,
      accounting_category,
      location,
      current_quantity,
      current_unit,
      current_value,
      previous_quantity,
      previous_value,
      unit_cost,
      report_by,
      conversion_rates,
      created_at,
      updated_at
    )
    SELECT
      ip.organization_id,
      ip.brand_id,
      ip.location_id,
      ip.internal_product_id,
      ip.product_id,
      ip.product_name,
      ip.category,
      ip.accounting_category,
      ip.location_name,
      0,
      ip.unit,
      0,
      0,
      0,
      ip.unit_cost,
      ip.unit,
      '{}'::jsonb,
      now(),
      now()
    FROM invoice_products ip
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.inventory inv
      WHERE inv.organization_id = ip.organization_id
        AND inv.location_id IS NOT DISTINCT FROM ip.location_id
        AND inv.internal_product_id = ip.internal_product_id
        AND inv.deleted_at IS NULL
    )
    RETURNING id
  )
  SELECT
    (SELECT count(*) FROM marked),
    (SELECT count(*) FROM inserted)
  INTO v_marked_count, v_created_count;

  RETURN jsonb_build_object(
    'status', 'success',
    'marked_products_count', v_marked_count,
    'created_inventory_count', v_created_count
  );
END;
$$;


ALTER FUNCTION "public"."ensure_inventory_for_invoiced_products"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_invoice_line_items_from_json"("p_invoice_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_existing_count integer;
  v_inserted_count integer := 0;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF v_invoice.id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT count(*)
    INTO v_existing_count
  FROM public.invoice_line_items
  WHERE invoice_id = p_invoice_id;

  IF v_existing_count > 0 THEN
    RETURN 0;
  END IF;

  IF jsonb_typeof(COALESCE(v_invoice.line_items, '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(COALESCE(v_invoice.line_items, '[]'::jsonb)) = 0 THEN
    RETURN 0;
  END IF;

  INSERT INTO public.invoice_line_items (
    invoice_id,
    organization_id,
    vendor_id,
    internal_product_id,
    item_name,
    quantity,
    unit_price,
    total_price,
    vendor_item_code,
    vendor_unit
  )
  SELECT
    v_invoice.id,
    v_invoice.organization_id,
    v_invoice.vendor_id,
    CASE
      WHEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id')::uuid
      ELSE NULL
    END,
    trim(COALESCE(
      NULLIF(item.value->>'description', ''),
      NULLIF(item.value->>'item_name', ''),
      NULLIF(item.value->>'name', ''),
      'Unknown Item'
    )),
    amounts.quantity,
    amounts.unit_price,
    COALESCE(amounts.extended_price, amounts.total_price, amounts.quantity * amounts.unit_price),
    NULLIF(item.value->>'vendor_item_code', ''),
    COALESCE(NULLIF(item.value->>'vendor_unit', ''), NULLIF(item.value->>'unit', ''))
  FROM jsonb_array_elements(v_invoice.line_items) WITH ORDINALITY AS item(value, ordinal)
  CROSS JOIN LATERAL (
    SELECT
      COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'quantity', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 1) AS quantity,
      COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'unit_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 0) AS unit_price,
      NULLIF(regexp_replace(COALESCE(item.value->>'extended_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS extended_price,
      NULLIF(regexp_replace(COALESCE(item.value->>'total_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS total_price
  ) amounts
  WHERE NULLIF(trim(COALESCE(
    item.value->>'description',
    item.value->>'item_name',
    item.value->>'name',
    ''
  )), '') IS NOT NULL;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  RETURN v_inserted_count;
END;
$_$;


ALTER FUNCTION "public"."ensure_invoice_line_items_from_json"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_ledger_bill_workflow"("p_invoice_id" "uuid", "p_status" "text" DEFAULT 'pending'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
  v_bill RECORD;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_org_actor(v_invoice.organization_id);

  SELECT *
    INTO v_bill
  FROM public.ledger_bills
  WHERE invoice_id = v_invoice.id
    AND organization_id = v_invoice.organization_id
    AND deleted_at IS NULL
  LIMIT 1
  FOR UPDATE;

  IF v_bill.id IS NOT NULL THEN
    UPDATE public.ledger_bills
       SET vendor_id = v_invoice.vendor_id,
           subtotal = COALESCE(v_invoice.subtotal, 0),
           tax = COALESCE(v_invoice.tax_amount, 0),
           total = COALESCE(v_invoice.total_amount, 0),
           due_date = v_invoice.due_date,
           status = CASE WHEN v_bill.status = 'paid' THEN 'paid' ELSE COALESCE(p_status, 'pending') END,
           updated_at = now()
     WHERE id = v_bill.id
     RETURNING * INTO v_bill;
  ELSE
    INSERT INTO public.ledger_bills (
      organization_id,
      vendor_id,
      invoice_id,
      subtotal,
      tax,
      total,
      due_date,
      status
    ) VALUES (
      v_invoice.organization_id,
      v_invoice.vendor_id,
      v_invoice.id,
      COALESCE(v_invoice.subtotal, 0),
      COALESCE(v_invoice.tax_amount, 0),
      COALESCE(v_invoice.total_amount, 0),
      v_invoice.due_date,
      COALESCE(p_status, 'pending')
    )
    RETURNING * INTO v_bill;
  END IF;

  RETURN to_jsonb(v_bill);
END;
$$;


ALTER FUNCTION "public"."ensure_ledger_bill_workflow"("p_invoice_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_onboarding_contact_verified"("p_email" "text", "p_phone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_email TEXT := public.normalize_contact_target('email', p_email);
  v_phone TEXT := public.normalize_contact_target('phone', p_phone);
  v_profile RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT business_email, business_email_verified_at, business_phone, business_phone_verified_at
  INTO v_profile
  FROM public.profiles
  WHERE id = v_user_id;

  IF v_profile.business_email_verified_at IS NULL OR v_profile.business_email IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'Business email must be verified by OTP before business verification';
  END IF;

  IF v_profile.business_phone_verified_at IS NULL OR v_profile.business_phone IS DISTINCT FROM v_phone THEN
    RAISE EXCEPTION 'Business phone must be verified by OTP before business verification';
  END IF;
END;
$$;


ALTER FUNCTION "public"."ensure_onboarding_contact_verified"("p_email" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_invoice_approval_policy"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_amount NUMERIC;
  v_instance_id UUID;
  v_policy RECORD;
  v_steps_created INT := 0;
BEGIN
  -- Get invoice details
  SELECT organization_id, total_amount INTO v_org_id, v_amount
  FROM public.invoices WHERE id = p_invoice_id;

  -- Cancel any existing pending instances for this invoice (e.g. if it was edited)
  UPDATE public.approval_instances 
  SET status = 'cancelled', updated_at = now()
  WHERE invoice_id = p_invoice_id AND status = 'pending';

  -- Create a new instance
  INSERT INTO public.approval_instances (invoice_id, status)
  VALUES (p_invoice_id, 'pending')
  RETURNING id INTO v_instance_id;

  -- Find matching policies
  FOR v_policy IN (
    SELECT required_role FROM public.approval_policies
    WHERE organization_id = v_org_id
      AND (min_amount IS NULL OR v_amount >= min_amount)
      AND (max_amount IS NULL OR v_amount <= max_amount)
  ) LOOP
    -- Insert a step for this policy
    -- Parallel approvals: We insert them all. Any user with the required_role can approve their step.
    INSERT INTO public.approval_steps (instance_id, required_role)
    VALUES (v_instance_id, v_policy.required_role);
    
    v_steps_created := v_steps_created + 1;
  END LOOP;

  IF v_steps_created = 0 THEN
    -- Auto-approve if no policies apply
    UPDATE public.approval_instances SET status = 'approved', updated_at = now() WHERE id = v_instance_id;
    UPDATE public.invoices SET status = 'approved', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'auto_approved');
  ELSE
    -- Set to pending approval
    UPDATE public.invoices SET status = 'pending_approval', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'pending_approval', 'steps', v_steps_created);
  END IF;
END;
$$;


ALTER FUNCTION "public"."evaluate_invoice_approval_policy"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_approval_step"("p_step_id" "uuid", "p_status" "text", "p_comments" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_instance_id uuid;
  v_invoice_id uuid;
  v_pending_count int;
  v_required_role text;
  v_actor_role text;
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Unsupported approval step status %', p_status;
  END IF;

  SELECT s.instance_id, s.required_role, ai.invoice_id
    INTO v_instance_id, v_required_role, v_invoice_id
  FROM public.approval_steps s
  JOIN public.approval_instances ai ON ai.id = s.instance_id
  WHERE s.id = p_step_id
    AND s.status = 'pending'
  FOR UPDATE OF s;

  IF v_instance_id IS NULL THEN
    RAISE EXCEPTION 'Pending approval step not found';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  v_actor_role := public.get_auth_role();

  IF NOT (
    v_actor_role = v_required_role
    OR v_actor_role IN ('platform_admin', 'tenant_super_admin')
    OR (v_actor_role = 'org_manager'
        AND v_required_role IN ('location_manager', 'branch_manager', 'org_manager', 'org_admin'))
    OR (v_actor_role = 'branch_manager'
        AND v_required_role IN ('location_manager', 'branch_manager'))
  ) THEN
    RAISE EXCEPTION 'Role % cannot act on approval step requiring %',
      v_actor_role, v_required_role;
  END IF;

  UPDATE public.approval_steps
     SET status = p_status::approval_step_status,
         approver_id = auth.uid(),
         comments = p_comments,
         acted_at = now()
   WHERE id = p_step_id;

  IF p_status = 'rejected' THEN
    UPDATE public.approval_instances
       SET status = 'rejected',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'rejected',
           ap_status = 'rejected',
           updated_at = now()
     WHERE id = v_invoice_id;

    RETURN jsonb_build_object('status', 'rejected');
  END IF;

  SELECT count(*)
    INTO v_pending_count
  FROM public.approval_steps
  WHERE instance_id = v_instance_id
    AND status = 'pending';

  IF v_pending_count = 0 THEN
    UPDATE public.approval_instances
       SET status = 'approved',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'approved',
           ap_status = 'approved',
           approved_by = auth.uid(),
           approved_date = now(),
           updated_at = now()
     WHERE id = v_invoice_id;

    -- Sync products now that it is fully approved
    PERFORM public.sync_invoice_products(v_invoice_id);

    RETURN jsonb_build_object('status', 'fully_approved');
  END IF;

  RETURN jsonb_build_object('status', 'partially_approved', 'pending_steps', v_pending_count);
END;
$$;


ALTER FUNCTION "public"."execute_approval_step"("p_step_id" "uuid", "p_status" "text", "p_comments" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_internal_transfer"("p_organization_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_items" "jsonb", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer_id uuid;
  v_result jsonb;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_from_location_id, true);

  IF p_from_location_id IS NULL OR p_to_location_id IS NULL THEN
    RAISE EXCEPTION 'Both source and destination locations are required';
  END IF;
  IF p_from_location_id = p_to_location_id THEN
    RAISE EXCEPTION 'Source and destination locations must be different';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.locations
    WHERE id = p_to_location_id
      AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Destination location is not part of the organization';
  END IF;

  INSERT INTO public.transfers (
    organization_id, from_location_id, to_location_id, status,
    items, created_by, created_at, updated_at
  ) VALUES (
    p_organization_id, p_from_location_id, p_to_location_id, 'pending',
    COALESCE(p_items, '[]'::jsonb), COALESCE(p_user_id, auth.uid()), now(), now()
  )
  RETURNING id INTO v_transfer_id;

  v_result := public.complete_inventory_transfer(p_organization_id, v_transfer_id, COALESCE(p_user_id, auth.uid()));

  RETURN v_result || jsonb_build_object('transfer_id', v_transfer_id);
END;
$$;


ALTER FUNCTION "public"."execute_internal_transfer"("p_organization_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_items" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_inventory_depletion"("p_org_id" "uuid", "p_depletion_json" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_elem jsonb;
  v_inv public.inventory;
  v_old_qty numeric;
  v_new_qty numeric;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_org_id, NULL, true);

  FOR v_elem IN SELECT * FROM jsonb_array_elements(COALESCE(p_depletion_json, '[]'::jsonb))
  LOOP
    SELECT * INTO v_inv
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND product_id = (v_elem->>'product_id')::text
      AND deleted_at IS NULL
    ORDER BY created_at
    LIMIT 1
    FOR UPDATE;

    IF v_inv.id IS NOT NULL THEN
      PERFORM public.assert_inventory_rpc_access(p_org_id, v_inv.location_id, true);
      v_old_qty := COALESCE(v_inv.current_quantity, 0);
      v_new_qty := GREATEST(0, v_old_qty - (v_elem->>'total_used')::numeric);
      UPDATE public.inventory
         SET current_quantity = v_new_qty,
             previous_quantity = v_old_qty,
             current_value = v_new_qty * COALESCE(unit_cost, 0),
             previous_value = COALESCE(current_value, v_old_qty * COALESCE(unit_cost, 0)),
             updated_at = now()
       WHERE id = v_inv.id;
      INSERT INTO public.inventory_movements (
        organization_id, location_id, inventory_id, movement_type, quantity,
        source_type, previous_quantity, new_quantity, created_by
      ) VALUES (
        p_org_id, v_inv.location_id, v_inv.id, 'sales_depletion',
        -1 * ((v_elem->>'total_used')::numeric), 'manual_depletion',
        v_old_qty, v_new_qty, auth.uid()
      );
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."execute_inventory_depletion"("p_org_id" "uuid", "p_depletion_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_user_access_tree"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_agg(
    jsonb_build_object(
      'organization', row_to_json(o.*),
      'role', om.role,
      'brands', (
        SELECT jsonb_agg(
          jsonb_build_object(
            'brand', row_to_json(b.*),
            'role', bm.role,
            'locations', (
              SELECT jsonb_agg(
                jsonb_build_object(
                  'location', row_to_json(l.*),
                  'role', lm.role
                )
              )
              FROM public.location_members lm
              JOIN public.locations l ON l.id = lm.location_id
              WHERE lm.user_id = auth.uid() AND l.brand_id = b.brand_id
            )
          )
        )
        FROM public.brand_members bm
        JOIN public.brands b ON b.brand_id = bm.brand_id
        WHERE bm.user_id = auth.uid() AND b.organization_id = o.id
      )
    )
  )
  FROM public.organization_members om
  JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = auth.uid();
$$;


ALTER FUNCTION "public"."fetch_user_access_tree"() OWNER TO "postgres";


