CREATE OR REPLACE FUNCTION "public"."find_duplicate_invoice_documents"("p_organization_id" "uuid", "p_file_hash" "text") RETURNS TABLE("document_id" "uuid", "invoice_id" "uuid", "vendor_name" "text", "invoice_number" "text", "invoice_date" "date", "status" "text", "uploaded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  v_org_id := COALESCE(p_organization_id, public.get_my_org());

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  PERFORM public.assert_org_actor(v_org_id);

  IF p_file_hash IS NULL OR p_file_hash = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.id,
    d.invoice_id,
    i.vendor_name,
    i.invoice_number,
    i.invoice_date,
    i.status,
    d.created_at
  FROM public.invoice_documents d
  LEFT JOIN public.invoices i ON i.id = d.invoice_id
  WHERE d.organization_id = v_org_id
    AND d.file_hash = p_file_hash
    AND (i.id IS NULL OR i.deleted_at IS NULL)
  ORDER BY d.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."find_duplicate_invoice_documents"("p_organization_id" "uuid", "p_file_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_duplicate_products"("p_organization_id" "uuid", "p_name" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "product_id" "text", "name" "text", "similarity" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p.id, p.product_id, p.name,
         CASE
           WHEN lower(p.name) = lower(COALESCE(p_name, '')) THEN 1::numeric
           WHEN lower(p.name) LIKE '%' || lower(COALESCE(p_name, '')) || '%'
             OR lower(COALESCE(p_name, '')) LIKE '%' || lower(p.name) || '%' THEN 0.85::numeric
           ELSE 0.5::numeric
         END AS similarity
  FROM public.products p
  WHERE p.organization_id = p_organization_id
    AND p.deleted_at IS NULL
    AND NULLIF(btrim(COALESCE(p_name, '')), '') IS NOT NULL
    AND (
      lower(p.name) = lower(p_name)
      OR lower(p.name) LIKE '%' || lower(p_name) || '%'
      OR lower(p_name) LIKE '%' || lower(p.name) || '%'
    )
    AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
  ORDER BY similarity DESC, p.name
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 10), 1), 50);
$$;


ALTER FUNCTION "public"."find_duplicate_products"("p_organization_id" "uuid", "p_name" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_duplicate_vendors"("p_organization_id" "uuid", "p_name" "text", "p_email" "text" DEFAULT NULL::"text", "p_tax_id_last4" "text" DEFAULT NULL::"text") RETURNS TABLE("vendor_id" "uuid", "name" "text", "approval_status" "text", "status" "text", "confidence" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- ponytail: exact-match-after-normalize only. Ceiling: spelling variants
  -- like "Sysco" vs "Sysco Foods" are missed; upgrade path is pg_trgm
  -- similarity if duplicate review proves it is worth the index and tuning.
  WITH input AS (
    SELECT
      lower(btrim(COALESCE(p_name, ''))) AS normalized_name,
      lower(btrim(NULLIF(p_email, ''))) AS normalized_email,
      btrim(NULLIF(p_tax_id_last4, '')) AS normalized_tax_last4
  )
  SELECT
    v.id AS vendor_id,
    v.name,
    v.approval_status,
    v.status,
    CASE
      WHEN (
        i.normalized_email IS NOT NULL
        AND lower(btrim(COALESCE(v.email, ''))) = i.normalized_email
      ) OR (
        i.normalized_tax_last4 IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.vendor_tax_information vti
          WHERE vti.vendor_id = v.id
            AND vti.deleted_at IS NULL
            AND btrim(COALESCE(vti.tax_id_last4, '')) = i.normalized_tax_last4
        )
      ) THEN 'likely'
      ELSE 'possible'
    END AS confidence
  FROM public.vendors v
  CROSS JOIN input i
  WHERE p_organization_id IS NOT NULL
    AND i.normalized_name <> ''
    AND v.organization_id = p_organization_id
    AND lower(btrim(v.name)) = i.normalized_name
    AND public.reference_scope_visible(v.organization_id, v.brand_id, v.location_id, NULL)
  ORDER BY
    CASE
      WHEN (
        i.normalized_email IS NOT NULL
        AND lower(btrim(COALESCE(v.email, ''))) = i.normalized_email
      ) OR (
        i.normalized_tax_last4 IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.vendor_tax_information vti
          WHERE vti.vendor_id = v.id
            AND vti.deleted_at IS NULL
            AND btrim(COALESCE(vti.tax_id_last4, '')) = i.normalized_tax_last4
        )
      ) THEN 0
      ELSE 1
    END,
    v.name,
    v.id;
$$;


ALTER FUNCTION "public"."find_duplicate_vendors"("p_organization_id" "uuid", "p_name" "text", "p_email" "text", "p_tax_id_last4" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."format_product_unit_quantity"("p_quantity" numeric) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT regexp_replace(regexp_replace(COALESCE(p_quantity, 0)::text, '0+$', ''), '\.$', '');
$_$;


ALTER FUNCTION "public"."format_product_unit_quantity"("p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fulfill_intercompany_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.intercompany_transfers;
  v_item jsonb;
  v_qty numeric;
  v_unit_cost numeric;
  v_item_name text;
  v_source_inv public.inventory;
  v_dest_inv public.inventory;
  v_dest_inv_id uuid;
  v_source_previous numeric;
  v_dest_previous numeric;
  v_total_value numeric := 0;
  v_gl_id uuid;
BEGIN
  SELECT * INTO v_transfer
  FROM public.intercompany_transfers
  WHERE id = p_transfer_id
    AND organization_id = p_organization_id
  FOR UPDATE;

  IF v_transfer.id IS NULL THEN
    RAISE EXCEPTION 'Intercompany transfer not found';
  END IF;

  PERFORM public.assert_inventory_rpc_access(p_organization_id, v_transfer.from_location_id, true);

  IF v_transfer.status = 'fulfilled' THEN
    RETURN jsonb_build_object('success', true, 'already_fulfilled', true, 'transfer_id', p_transfer_id);
  END IF;
  IF v_transfer.status <> 'pending' THEN
    RAISE EXCEPTION 'Only pending intercompany transfers can be fulfilled';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(v_transfer.items_json, '[]'::jsonb))
  LOOP
    v_item_name := NULLIF(v_item->>'name', '');
    v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
    v_unit_cost := COALESCE((v_item->>'unit_cost')::numeric, 0);

    IF v_item_name IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    SELECT * INTO v_source_inv
    FROM public.inventory
    WHERE organization_id = p_organization_id
      AND location_id = v_transfer.from_location_id
      AND deleted_at IS NULL
      AND lower(product_name) = lower(v_item_name)
    LIMIT 1
    FOR UPDATE;

    IF v_source_inv.id IS NULL THEN
      RAISE EXCEPTION 'No commissary inventory item found for "%"', v_item_name;
    END IF;

    v_source_previous := COALESCE(v_source_inv.current_quantity, 0);
    v_unit_cost := COALESCE(NULLIF(v_unit_cost, 0), v_source_inv.unit_cost, 0);
    v_total_value := v_total_value + (v_qty * v_unit_cost);

    UPDATE public.inventory
       SET current_quantity = GREATEST(0, v_source_previous - v_qty),
           current_value = GREATEST(0, v_source_previous - v_qty) * v_unit_cost,
           previous_quantity = v_source_previous,
           previous_value = COALESCE(v_source_inv.current_value, v_source_previous * v_unit_cost),
           updated_at = now()
     WHERE id = v_source_inv.id;

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_organization_id, v_transfer.from_location_id, v_source_inv.id, 'transfer_out',
      -v_qty, 'intercompany_transfer', p_transfer_id, v_source_previous,
      GREATEST(0, v_source_previous - v_qty), COALESCE(p_user_id, auth.uid())
    );

    SELECT * INTO v_dest_inv
    FROM public.inventory
    WHERE organization_id = p_organization_id
      AND location_id = v_transfer.to_location_id
      AND deleted_at IS NULL
      AND lower(product_name) = lower(v_item_name)
    LIMIT 1
    FOR UPDATE;

    IF v_dest_inv.id IS NOT NULL THEN
      v_dest_inv_id := v_dest_inv.id;
      v_dest_previous := COALESCE(v_dest_inv.current_quantity, 0);
      UPDATE public.inventory
         SET current_quantity = v_dest_previous + v_qty,
             unit_cost = v_unit_cost,
             current_value = (v_dest_previous + v_qty) * v_unit_cost,
             previous_quantity = v_dest_previous,
             previous_value = COALESCE(v_dest_inv.current_value, v_dest_previous * v_unit_cost),
             updated_at = now()
       WHERE id = v_dest_inv.id;
    ELSE
      v_dest_previous := 0;
      INSERT INTO public.inventory (
        organization_id, brand_id, location_id, product_id, product_name,
        category, accounting_category, current_quantity, current_unit,
        unit_cost, current_value, previous_quantity, previous_value
      ) VALUES (
        p_organization_id, v_source_inv.brand_id, v_transfer.to_location_id,
        COALESCE(v_source_inv.product_id, 'PRD-' || extract(epoch from now())::text),
        v_source_inv.product_name, v_source_inv.category, v_source_inv.accounting_category,
        v_qty, COALESCE(v_item->>'unit', v_source_inv.current_unit, 'ea'),
        v_unit_cost, v_qty * v_unit_cost, 0, 0
      )
      RETURNING id INTO v_dest_inv_id;
    END IF;

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_organization_id, v_transfer.to_location_id, v_dest_inv_id, 'transfer_in',
      v_qty, 'intercompany_transfer', p_transfer_id, v_dest_previous,
      v_dest_previous + v_qty, COALESCE(p_user_id, auth.uid())
    );
  END LOOP;

  UPDATE public.intercompany_transfers
     SET status = 'fulfilled',
         fulfilled_at = now(),
         fulfilled_by = COALESCE(p_user_id, auth.uid()),
         updated_at = now()
   WHERE id = p_transfer_id;

  IF v_total_value > 0 THEN
    INSERT INTO public.general_ledger_entries (
      organization_id, date, reference, description,
      debit_account, credit_account, amount, created_by
    ) VALUES (
      p_organization_id, now(), 'ICT-' || p_transfer_id::text,
      'Intercompany commissary inventory transfer',
      'Destination Inventory Asset (1210)',
      'Commissary Inventory Asset (1210)',
      v_total_value,
      COALESCE(p_user_id, auth.uid())
    )
    RETURNING id INTO v_gl_id;

    INSERT INTO public.accounting_export_queue (organization_id, entity_type, entity_id, status)
    VALUES (p_organization_id, 'journal_entry', v_gl_id, 'ready')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object('success', true, 'transfer_id', p_transfer_id, 'total_value', v_total_value, 'journal_entry_id', v_gl_id);
END;
$$;


ALTER FUNCTION "public"."fulfill_intercompany_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_daily_theoretical_usage"("p_org_id" "uuid", "p_date" "date") RETURNS TABLE("ingredient_id" "uuid", "ingredient_name" "text", "unit" "text", "theoretical_usage" numeric, "cost_value" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
    RAISE EXCEPTION 'Access Denied: Tenant context violation.';
  END IF;

  RETURN QUERY
  WITH daily_sales AS (
    SELECT psd.pos_item_id, SUM(psd.quantity_sold) AS total_sold
    FROM public.pos_sales_data psd
    WHERE psd.organization_id = p_org_id
      AND psd.date = p_date
    GROUP BY psd.pos_item_id
  ),
  mapped_recipes AS (
    SELECT ds.pos_item_id, ds.total_sold, pmm.recipe_id
    FROM daily_sales ds
    JOIN public.pos_menu_mapping pmm
      ON pmm.pos_item_id = ds.pos_item_id
     AND pmm.organization_id = p_org_id
  ),
  recipe_ingredients_exploded AS (
    SELECT
      ri.product_id AS ingredient_id,
      (ri.quantity * mr.total_sold) AS ingredient_usage,
      p.name AS ingredient_name,
      COALESCE(ri.unit, p.base_unit, 'ea') AS unit,
      COALESCE(p.latest_price, p.average_price, 0) AS cost_per_unit
    FROM mapped_recipes mr
    JOIN public.recipe_ingredients ri ON ri.recipe_id = mr.recipe_id
    JOIN public.products p ON p.id = ri.product_id
  )
  SELECT
    rie.ingredient_id,
    rie.ingredient_name,
    rie.unit,
    SUM(rie.ingredient_usage) AS theoretical_usage,
    SUM(rie.ingredient_usage * rie.cost_per_unit) AS cost_value
  FROM recipe_ingredients_exploded rie
  GROUP BY rie.ingredient_id, rie.ingredient_name, rie.unit
  ORDER BY theoretical_usage DESC;
END;
$$;


ALTER FUNCTION "public"."generate_daily_theoretical_usage"("p_org_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_restops_product_id"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_next bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('public.products.product_id'));

  SELECT COALESCE(MAX(((regexp_match(product_id, '^PRD-([0-9]+)$'))[1])::bigint), 0) + 1
    INTO v_next
  FROM public.products
  WHERE product_id ~ '^PRD-[0-9]+$';

  RETURN 'PRD-' || lpad(v_next::text, 6, '0');
END;
$_$;


ALTER FUNCTION "public"."generate_restops_product_id"() OWNER TO "postgres";


