CREATE OR REPLACE FUNCTION "public"."get_avt_variance_report"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("id" "uuid", "ingredient" "text", "theoretical" numeric, "actual" numeric, "unit" "text", "costPerUnit" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id,
    i.product_name AS ingredient,
    COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion') THEN ABS(im.quantity) ELSE 0 END), 0) AS theoretical,
    COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'wastage', 'spoilage', 'stock_count', 'count_variance', 'manual_adjustment') AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) AS actual,
    i.current_unit AS unit,
    COALESCE(i.unit_cost, 0) AS "costPerUnit",
    CASE
      WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'wastage', 'spoilage', 'stock_count', 'count_variance', 'manual_adjustment') AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0)
         > COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion') THEN ABS(im.quantity) ELSE 0 END), 0) * 1.10 THEN 'critical'
      WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'wastage', 'spoilage', 'stock_count', 'count_variance', 'manual_adjustment') AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0)
         > COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion') THEN ABS(im.quantity) ELSE 0 END), 0) * 1.05 THEN 'warning'
      ELSE 'good'
    END AS status
  FROM public.inventory i
  JOIN public.inventory_movements im
    ON im.inventory_id = i.id
   AND im.organization_id = i.organization_id
   AND DATE(im.created_at) BETWEEN p_start_date AND p_end_date
  WHERE i.organization_id = public.get_auth_org()
    AND i.deleted_at IS NULL
  GROUP BY i.id, i.product_name, i.current_unit, i.unit_cost
  HAVING COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion') THEN ABS(im.quantity) ELSE 0 END), 0) > 0;
END;
$$;


ALTER FUNCTION "public"."get_avt_variance_report"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_account_secret_for_provider"("p_bank_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
BEGIN
  SELECT secret_id INTO v_secret_id
  FROM public.bank_accounts
  WHERE id = p_bank_account_id
    AND is_active = true
    AND deleted_at IS NULL;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'Bank account secret for row % not found', p_bank_account_id;
  END IF;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  INSERT INTO public.payment_provider_events (
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    provider,
    provider_event_type,
    owner_type,
    owner_id,
    bank_account_id,
    status,
    payload
  )
  SELECT
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    'internal',
    'bank_secret_retrieved_for_provider',
    owner_type,
    owner_id,
    id,
    'processed',
    jsonb_build_object('bank_account_id', id, 'retrieved_at', now())
  FROM public.bank_accounts
  WHERE id = p_bank_account_id;

  RETURN v_secret::jsonb;
END;
$$;


ALTER FUNCTION "public"."get_bank_account_secret_for_provider"("p_bank_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_category_performance_drilldown"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_category" "text" DEFAULT NULL::"text", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_category text := COALESCE(NULLIF(trim(p_category), ''), 'Uncategorized');
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  WITH eligible AS (
    SELECT
      ia.invoice_id,
      ia.amount,
      COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') AS category_name,
      COALESCE(ia.location_id, i.location_id) AS effective_location_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.invoice_number,
      i.status,
      i.location_id,
      l.name AS location_name
    FROM public.invoice_allocations ia
    JOIN public.invoices i ON i.id = ia.invoice_id
    LEFT JOIN public.locations l ON l.id = COALESCE(ia.location_id, i.location_id)
    WHERE ia.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND ia.allocation_type = 'line_items'
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = v_category
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR COALESCE(ia.location_id, i.location_id) = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  current_rows AS (
    SELECT * FROM eligible
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM eligible
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  summary AS (
    SELECT
      round(COALESCE(sum(amount), 0)::numeric, 2) AS total_spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id) FILTER (WHERE vendor_id IS NOT NULL)::bigint AS vendor_count
    FROM current_rows
  ),
  prev_total AS (
    SELECT round(COALESCE(sum(amount), 0)::numeric, 2) AS previous_spend
    FROM previous_rows
  ),
  vendors AS (
    SELECT
      cr.vendor_id,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS spend,
      count(DISTINCT cr.invoice_id)::bigint AS invoice_count,
      COALESCE((
        SELECT round(sum(pr.amount)::numeric, 2)
        FROM previous_rows pr
        WHERE pr.vendor_id IS NOT DISTINCT FROM cr.vendor_id
      ), 0) AS previous_spend
    FROM current_rows cr
    GROUP BY cr.vendor_id, cr.vendor_name
  ),
  products AS (
    SELECT *
    FROM (
      SELECT
        COALESCE(p.id, ili.internal_product_id) AS product_id,
        COALESCE(p.name, ili.item_name, 'Unknown product') AS product,
        round(sum(COALESCE(ili.quantity, 0))::numeric, 4) AS quantity_purchased,
        (array_agg(ili.unit_price ORDER BY i.invoice_date DESC NULLS LAST))[1] AS current_unit_price,
        CASE WHEN sum(COALESCE(ili.quantity, 0)) = 0 THEN 0
             ELSE round(sum(COALESCE(ili.total_price, 0)) / NULLIF(sum(COALESCE(ili.quantity, 0)), 0), 4)
        END AS average_unit_price,
        round(sum(COALESCE(ili.total_price, 0))::numeric, 2) AS total_spend,
        (array_agg(COALESCE(i.vendor_name, 'Unknown vendor') ORDER BY i.invoice_date DESC NULLS LAST))[1] AS vendor
      FROM public.invoices i
      JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
      LEFT JOIN public.products p ON p.id = ili.internal_product_id
      WHERE i.organization_id = v_org_id
        AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
        AND i.invoice_date >= p_date_from
        AND i.invoice_date <= p_date_to
        AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
        AND COALESCE(NULLIF(trim(COALESCE(p.category, '')), ''), 'Uncategorized') = v_category
        AND (
          p_location_ids IS NULL OR cardinality(p_location_ids) = 0
          OR i.location_id = ANY (p_location_ids)
        )
        AND (
          p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
          OR i.vendor_id = ANY (p_vendor_ids)
        )
      GROUP BY COALESCE(p.id, ili.internal_product_id), COALESCE(p.name, ili.item_name, 'Unknown product')
      ORDER BY sum(COALESCE(ili.total_price, 0)) DESC
      LIMIT 200
    ) ranked_products
  ),
  invoices AS (
    SELECT
      cr.invoice_id,
      cr.invoice_number,
      cr.invoice_date,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS amount,
      cr.status,
      cr.location_name AS location
    FROM current_rows cr
    GROUP BY cr.invoice_id, cr.invoice_number, cr.invoice_date, cr.vendor_name, cr.status, cr.location_name
    ORDER BY cr.invoice_date DESC
    LIMIT 500
  )
  SELECT jsonb_build_object(
    'category', v_category,
    'summary', jsonb_build_object(
      'totalSpend', s.total_spend,
      'previousSpend', pt.previous_spend,
      'absoluteChange', s.total_spend - pt.previous_spend,
      'percentageChange', CASE
        WHEN pt.previous_spend = 0 AND s.total_spend = 0 THEN 0
        WHEN pt.previous_spend = 0 THEN NULL
        ELSE round(((s.total_spend - pt.previous_spend) / abs(pt.previous_spend)) * 100, 2)
      END,
      'invoiceCount', s.invoice_count,
      'vendorCount', s.vendor_count,
      'averageInvoiceValue', CASE WHEN s.invoice_count = 0 THEN 0 ELSE round(s.total_spend / s.invoice_count, 2) END
    ),
    'vendors', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'vendor', v.vendor,
          'vendorId', v.vendor_id,
          'spend', v.spend,
          'sharePercentage', CASE WHEN s.total_spend = 0 THEN 0 ELSE round((v.spend / s.total_spend) * 100, 2) END,
          'invoiceCount', v.invoice_count,
          'averageInvoice', CASE WHEN v.invoice_count = 0 THEN 0 ELSE round(v.spend / v.invoice_count, 2) END,
          'absoluteChange', v.spend - v.previous_spend,
          'percentageChange', CASE
            WHEN v.previous_spend = 0 AND v.spend = 0 THEN 0
            WHEN v.previous_spend = 0 THEN NULL
            ELSE round(((v.spend - v.previous_spend) / abs(v.previous_spend)) * 100, 2)
          END
        )
        ORDER BY v.spend DESC
      )
      FROM vendors v
      CROSS JOIN summary s
    ), '[]'::jsonb),
    'products', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'product', p.product,
          'productId', p.product_id,
          'quantityPurchased', p.quantity_purchased,
          'currentUnitPrice', p.current_unit_price,
          'averageUnitPrice', p.average_unit_price,
          'totalSpend', p.total_spend,
          'vendor', p.vendor,
          'priceChange', CASE
            WHEN p.average_unit_price IS NULL OR p.current_unit_price IS NULL THEN NULL
            ELSE round(p.current_unit_price - p.average_unit_price, 4)
          END
        )
      )
      FROM products p
    ), '[]'::jsonb),
    'invoices', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'invoiceId', i.invoice_id,
          'invoiceNumber', i.invoice_number,
          'date', i.invoice_date,
          'vendor', i.vendor,
          'amount', i.amount,
          'status', i.status,
          'location', i.location
        )
        ORDER BY i.invoice_date DESC
      )
      FROM invoices i
    ), '[]'::jsonb)
  )
  INTO v_result
  FROM summary s
  CROSS JOIN prev_total pt;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_category_performance_drilldown"("p_organization_id" "uuid", "p_category" "text", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_vendor_ids" "uuid"[], "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_category_performance_report"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_category_names" "text"[] DEFAULT NULL::"text"[], "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text", "p_selected_category" "text" DEFAULT NULL::"text", "p_trend_categories" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_days int;
  v_granularity text;
  v_min_spend numeric;
  v_result jsonb;
  v_has_budget boolean := false;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  v_days := GREATEST(1, (p_date_to - p_date_from) + 1);
  IF v_days <= 31 THEN
    v_granularity := 'day';
  ELSIF v_days <= 120 THEN
    v_granularity := 'week';
  ELSE
    v_granularity := 'month';
  END IF;

  -- Product-category budgets are uncommon; detect any overlapping budget_targets
  -- whose category string matches an allocation category_name in scope.
  SELECT EXISTS (
    SELECT 1
    FROM public.budget_targets bt
    WHERE bt.organization_id = v_org_id
      AND bt.period_start <= p_date_to
      AND bt.period_end >= p_date_from
      AND EXISTS (
        SELECT 1
        FROM public.invoice_allocations ia
        JOIN public.invoices i ON i.id = ia.invoice_id
        WHERE ia.organization_id = v_org_id
          AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
          AND COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = bt.category
      )
  ) INTO v_has_budget;

  WITH eligible AS (
    SELECT
      ia.id AS allocation_id,
      ia.invoice_id,
      ia.amount,
      ia.allocation_type,
      COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') AS category_name,
      COALESCE(ia.location_id, i.location_id) AS effective_location_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.invoice_number,
      i.status,
      i.ap_status,
      i.brand_id,
      i.organization_id
    FROM public.invoice_allocations ia
    JOIN public.invoices i ON i.id = ia.invoice_id
    WHERE ia.organization_id = v_org_id
      AND i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND ia.allocation_type = 'line_items'
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL
        OR cardinality(p_location_ids) = 0
        OR COALESCE(ia.location_id, i.location_id) = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL
        OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
      AND (
        p_category_names IS NULL
        OR cardinality(p_category_names) = 0
        OR COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = ANY (p_category_names)
      )
  ),
  current_rows AS (
    SELECT * FROM eligible e
    WHERE e.invoice_date >= p_date_from
      AND e.invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM eligible e
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND e.invoice_date >= p_comparison_date_from
      AND e.invoice_date <= p_comparison_date_to
  ),
  current_by_cat AS (
    SELECT
      category_name,
      round(sum(amount)::numeric, 2) AS spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id) FILTER (WHERE vendor_id IS NOT NULL)::bigint AS vendor_count
    FROM current_rows
    GROUP BY category_name
  ),
  previous_by_cat AS (
    SELECT
      category_name,
      round(sum(amount)::numeric, 2) AS spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count
    FROM previous_rows
    GROUP BY category_name
  ),
  all_categories AS (
    SELECT category_name FROM current_by_cat
    UNION
    SELECT category_name FROM previous_by_cat
  ),
  category_join AS (
    SELECT
      c.category_name,
      COALESCE(cur.spend, 0)::numeric AS current_spend,
      COALESCE(prev.spend, 0)::numeric AS previous_spend,
      COALESCE(cur.invoice_count, 0)::bigint AS invoice_count,
      COALESCE(cur.vendor_count, 0)::bigint AS vendor_count,
      (COALESCE(cur.spend, 0) - COALESCE(prev.spend, 0))::numeric AS absolute_variance,
      CASE
        WHEN COALESCE(prev.spend, 0) = 0 AND COALESCE(cur.spend, 0) = 0 THEN 0::numeric
        WHEN COALESCE(prev.spend, 0) = 0 THEN NULL
        ELSE round(((COALESCE(cur.spend, 0) - prev.spend) / abs(prev.spend)) * 100, 2)
      END AS percentage_variance
    FROM all_categories c
    LEFT JOIN current_by_cat cur ON cur.category_name = c.category_name
    LEFT JOIN previous_by_cat prev ON prev.category_name = c.category_name
  ),
  totals AS (
    SELECT
      COALESCE((SELECT sum(current_spend) FROM category_join), 0)::numeric AS total_spend,
      COALESCE((SELECT sum(previous_spend) FROM category_join), 0)::numeric AS previous_spend,
      COALESCE((SELECT count(DISTINCT invoice_id) FROM current_rows), 0)::bigint AS invoice_count
  ),
  largest_vendor_by_cat AS (
    SELECT DISTINCT ON (category_name)
      category_name,
      vendor_name,
      round(sum(amount)::numeric, 2) AS vendor_spend
    FROM current_rows
    GROUP BY category_name, vendor_name
    ORDER BY category_name, sum(amount) DESC
  ),
  budget_by_cat AS (
    SELECT
      bt.category AS category_name,
      round(sum(bt.target_amount)::numeric, 2) AS budget_amount
    FROM public.budget_targets bt
    WHERE bt.organization_id = v_org_id
      AND bt.period_start <= p_date_to
      AND bt.period_end >= p_date_from
    GROUP BY bt.category
  ),
  table_enriched AS (
    SELECT
      cj.*,
      CASE
        WHEN t.total_spend = 0 THEN 0
        ELSE round((cj.current_spend / t.total_spend) * 100, 2)
      END AS percentage_of_total,
      CASE
        WHEN cj.invoice_count = 0 THEN 0
        ELSE round(cj.current_spend / cj.invoice_count, 2)
      END AS average_invoice_value,
      lv.vendor_name AS largest_vendor,
      bb.budget_amount,
      CASE
        WHEN bb.budget_amount IS NULL THEN NULL
        ELSE round(cj.current_spend - bb.budget_amount, 2)
      END AS budget_variance,
      CASE
        WHEN cj.percentage_variance IS NULL THEN 'new'
        WHEN cj.percentage_variance > 5 THEN 'up'
        WHEN cj.percentage_variance < -5 THEN 'down'
        ELSE 'flat'
      END AS trend_status
    FROM category_join cj
    CROSS JOIN totals t
    LEFT JOIN largest_vendor_by_cat lv ON lv.category_name = cj.category_name
    LEFT JOIN budget_by_cat bb ON bb.category_name = cj.category_name
  ),
  ranked AS (
    SELECT *
    FROM table_enriched
    ORDER BY current_spend DESC
  ),
  summary_calc AS (
    SELECT
      t.total_spend,
      t.previous_spend,
      (t.total_spend - t.previous_spend) AS absolute_change,
      CASE
        WHEN t.previous_spend = 0 AND t.total_spend = 0 THEN 0::numeric
        WHEN t.previous_spend = 0 THEN NULL
        ELSE round(((t.total_spend - t.previous_spend) / abs(t.previous_spend)) * 100, 2)
      END AS percentage_change,
      t.invoice_count,
      CASE
        WHEN t.invoice_count = 0 THEN 0
        ELSE round(t.total_spend / t.invoice_count, 2)
      END AS average_invoice_value,
      (SELECT count(*) FROM ranked WHERE current_spend > 0)::int AS active_category_count,
      COALESCE((
        SELECT round((sum(s.current_spend) / NULLIF(t.total_spend, 0)) * 100, 2)
        FROM (SELECT current_spend FROM ranked ORDER BY current_spend DESC LIMIT 3) s
      ), 0) AS top_three_concentration_percentage
    FROM totals t
  ),
  largest AS (
    SELECT jsonb_build_object(
      'category', r.category_name,
      'spend', r.current_spend,
      'percentageOfTotal', r.percentage_of_total
    ) AS obj
    FROM ranked r
    WHERE r.current_spend > 0
    ORDER BY r.current_spend DESC
    LIMIT 1
  ),
  fastest AS (
    SELECT jsonb_build_object(
      'category', r.category_name,
      'currentSpend', r.current_spend,
      'previousSpend', r.previous_spend,
      'percentageChange', r.percentage_variance,
      'absoluteChange', r.absolute_variance
    ) AS obj
    FROM ranked r
    CROSS JOIN summary_calc sc
    WHERE r.current_spend >= GREATEST(100::numeric, sc.total_spend * 0.01)
      AND r.percentage_variance IS NOT NULL
    ORDER BY r.percentage_variance DESC
    LIMIT 1
  ),
  over_budget AS (
    SELECT count(*)::int AS cnt
    FROM ranked r
    WHERE r.budget_amount IS NOT NULL
      AND r.current_spend > r.budget_amount
  ),
  -- Distribution: top 8 + Other
  dist_ranked AS (
    SELECT
      category_name,
      current_spend,
      row_number() OVER (ORDER BY current_spend DESC) AS rn
    FROM ranked
    WHERE current_spend > 0
  ),
  distribution AS (
    SELECT category_name AS category, current_spend AS spend, false AS is_other
    FROM dist_ranked
    WHERE rn <= 8
    UNION ALL
    SELECT 'Other', COALESCE(sum(current_spend), 0), true
    FROM dist_ranked
    WHERE rn > 8
    HAVING sum(current_spend) > 0
  ),
  pareto AS (
    SELECT
      category_name AS category,
      current_spend AS spend,
      row_number() OVER (ORDER BY current_spend DESC) AS rank,
      round((current_spend / NULLIF(sum(current_spend) OVER (), 0)) * 100, 2) AS share_percentage,
      round((sum(current_spend) OVER (ORDER BY current_spend DESC rows unbounded preceding) / NULLIF(sum(current_spend) OVER (), 0)) * 100, 2) AS cumulative_percentage
    FROM ranked
    WHERE current_spend > 0
  ),
  -- Trend buckets for top categories
  top_trend_cats AS (
    SELECT category_name
    FROM ranked
    WHERE current_spend > 0
      AND (
        p_trend_categories IS NULL
        OR cardinality(p_trend_categories) = 0
        OR category_name = ANY (p_trend_categories)
      )
    ORDER BY current_spend DESC
    LIMIT CASE
      WHEN p_trend_categories IS NOT NULL AND cardinality(p_trend_categories) > 0 THEN 20
      ELSE 5
    END
  ),
  bucketed AS (
    SELECT
      CASE v_granularity
        WHEN 'day' THEN cr.invoice_date::text
        WHEN 'week' THEN to_char(date_trunc('week', cr.invoice_date::timestamp), 'IYYY-"W"IW')
        ELSE to_char(date_trunc('month', cr.invoice_date::timestamp), 'YYYY-MM')
      END AS bucket,
      CASE v_granularity
        WHEN 'day' THEN cr.invoice_date
        WHEN 'week' THEN date_trunc('week', cr.invoice_date::timestamp)::date
        ELSE date_trunc('month', cr.invoice_date::timestamp)::date
      END AS bucket_start,
      cr.category_name,
      sum(cr.amount) AS spend
    FROM current_rows cr
    WHERE cr.category_name IN (SELECT category_name FROM top_trend_cats)
    GROUP BY 1, 2, 3
  ),
  trend_json AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', b.bucket,
        'bucketStart', b.bucket_start,
        'category', b.category_name,
        'spend', round(b.spend::numeric, 2)
      )
      ORDER BY b.bucket_start, b.category_name
    ), '[]'::jsonb) AS arr
    FROM bucketed b
  ),
  vendor_for_selected AS (
    SELECT
      COALESCE(p_selected_category, (SELECT category_name FROM ranked WHERE current_spend > 0 ORDER BY current_spend DESC LIMIT 1)) AS selected_category
  ),
  vendor_current AS (
    SELECT
      vfs.selected_category AS category,
      cr.vendor_id,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS spend,
      count(DISTINCT cr.invoice_id)::bigint AS invoice_count
    FROM current_rows cr
    CROSS JOIN vendor_for_selected vfs
    WHERE cr.category_name = vfs.selected_category
    GROUP BY vfs.selected_category, cr.vendor_id, cr.vendor_name
  ),
  vendor_previous AS (
    SELECT
      pr.vendor_id,
      round(sum(pr.amount)::numeric, 2) AS spend
    FROM previous_rows pr
    CROSS JOIN vendor_for_selected vfs
    WHERE pr.category_name = vfs.selected_category
    GROUP BY pr.vendor_id
  ),
  vendor_contrib AS (
    SELECT
      vc.category,
      vc.vendor,
      vc.vendor_id,
      vc.spend,
      vc.invoice_count,
      CASE
        WHEN sum(vc.spend) OVER () = 0 THEN 0
        ELSE round((vc.spend / sum(vc.spend) OVER ()) * 100, 2)
      END AS share_percentage,
      COALESCE(vp.spend, 0) AS previous_spend,
      (vc.spend - COALESCE(vp.spend, 0)) AS absolute_change,
      CASE
        WHEN COALESCE(vp.spend, 0) = 0 AND vc.spend = 0 THEN 0::numeric
        WHEN COALESCE(vp.spend, 0) = 0 THEN NULL
        ELSE round(((vc.spend - vp.spend) / abs(vp.spend)) * 100, 2)
      END AS percentage_change
    FROM vendor_current vc
    LEFT JOIN vendor_previous vp ON vp.vendor_id IS NOT DISTINCT FROM vc.vendor_id
  ),
  filter_categories AS (
    SELECT COALESCE(jsonb_agg(DISTINCT category_name ORDER BY category_name), '[]'::jsonb) AS arr
    FROM (
      SELECT category_name FROM eligible
      UNION
      SELECT category_name FROM ranked
    ) x
  ),
  filter_vendors AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object('id', vendor_id, 'name', vendor_name)
      ORDER BY vendor_name
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT DISTINCT vendor_id, vendor_name
      FROM eligible
      WHERE vendor_id IS NOT NULL
    ) v
  ),
  uncategorized_amt AS (
    SELECT COALESCE(sum(current_spend), 0)::numeric AS amount
    FROM ranked
    WHERE category_name = 'Uncategorized'
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'totalSpend', sc.total_spend,
      'previousSpend', sc.previous_spend,
      'absoluteChange', sc.absolute_change,
      'percentageChange', sc.percentage_change,
      'largestCategory', (SELECT obj FROM largest),
      'fastestGrowingCategory', (SELECT obj FROM fastest),
      'activeCategoryCount', sc.active_category_count,
      'topThreeConcentrationPercentage', sc.top_three_concentration_percentage,
      'averageInvoiceValue', sc.average_invoice_value,
      'categoriesOverBudget', CASE WHEN v_has_budget THEN (SELECT cnt FROM over_budget) ELSE NULL END,
      'invoiceCount', sc.invoice_count,
      'uncategorizedSpend', (SELECT amount FROM uncategorized_amt)
    ),
    'categoryBreakdown', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', r.category_name,
          'currentSpend', r.current_spend,
          'previousSpend', r.previous_spend,
          'absoluteVariance', r.absolute_variance,
          'percentageVariance', r.percentage_variance,
          'percentageOfTotal', r.percentage_of_total
        )
        ORDER BY r.current_spend DESC
      )
      FROM ranked r
    ), '[]'::jsonb),
    'trend', (SELECT arr FROM trend_json),
    'distribution', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', d.category,
          'spend', d.spend,
          'isOther', d.is_other,
          'percentageOfTotal', CASE WHEN sc.total_spend = 0 THEN 0 ELSE round((d.spend / sc.total_spend) * 100, 2) END
        )
        ORDER BY d.spend DESC
      )
      FROM distribution d
      CROSS JOIN summary_calc sc
    ), '[]'::jsonb),
    'pareto', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', p.category,
          'spend', p.spend,
          'rank', p.rank,
          'sharePercentage', p.share_percentage,
          'cumulativePercentage', p.cumulative_percentage
        )
        ORDER BY p.rank
      )
      FROM pareto p
    ), '[]'::jsonb),
    'vendorContribution', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', v.category,
          'vendor', v.vendor,
          'vendorId', v.vendor_id,
          'spend', v.spend,
          'sharePercentage', v.share_percentage,
          'invoiceCount', v.invoice_count,
          'previousSpend', v.previous_spend,
          'absoluteChange', v.absolute_change,
          'percentageChange', v.percentage_change
        )
        ORDER BY v.spend DESC
      )
      FROM vendor_contrib v
    ), '[]'::jsonb),
    'tableRows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', r.category_name,
          'currentSpend', r.current_spend,
          'previousSpend', r.previous_spend,
          'absoluteVariance', r.absolute_variance,
          'percentageVariance', r.percentage_variance,
          'percentageOfTotal', r.percentage_of_total,
          'invoiceCount', r.invoice_count,
          'vendorCount', r.vendor_count,
          'averageInvoiceValue', r.average_invoice_value,
          'largestVendor', r.largest_vendor,
          'budget', r.budget_amount,
          'budgetVariance', r.budget_variance,
          'trendStatus', r.trend_status
        )
        ORDER BY r.current_spend DESC
      )
      FROM ranked r
    ), '[]'::jsonb),
    'insights', '[]'::jsonb,
    'metadata', jsonb_build_object(
      'currency', 'USD',
      'timezone', v_tz,
      'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'),
      'hasBudgetData', v_has_budget,
      'granularity', v_granularity,
          'spendDefinition', 'Net purchasing spend from invoice line-item allocations on purchasing-eligible invoices (approved/scheduled/partially_paid/paid or matching ap_status), dated by invoice_date. Credits reduce allocation amounts when present. Excludes deleted, rejected, and duplicate invoices.',
      'filterOptions', jsonb_build_object(
        'categories', (SELECT arr FROM filter_categories),
        'vendors', (SELECT arr FROM filter_vendors)
      ),
      'selectedCategory', (SELECT selected_category FROM vendor_for_selected)
    )
  )
  INTO v_result
  FROM summary_calc sc;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_category_performance_report"("p_organization_id" "uuid", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_category_names" "text"[], "p_vendor_ids" "uuid"[], "p_timezone" "text", "p_selected_category" "text", "p_trend_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cross_location_benchmarks"("p_org_id" "uuid") RETURNS TABLE("name" "text", "sales" numeric, "laborCost" numeric, "cogs" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization data.';
    END IF;

    RETURN QUERY
    WITH date_range AS (
        SELECT (now() - interval '30 days') AS start_date
    ),
    sales_by_location AS (
        SELECT ps.location_id, COALESCE(SUM(ps.revenue), 0) AS sales
        FROM public.pos_sales_data ps
        WHERE ps.date >= (SELECT start_date FROM date_range)
        GROUP BY ps.location_id
    ),
    cogs_by_location AS (
        SELECT i.location_id, COALESCE(SUM(i.total_amount), 0) AS cogs
        FROM public.invoices i
        WHERE COALESCE(i.invoice_date, i.created_at::date) >= (SELECT start_date::date FROM date_range)
        GROUP BY i.location_id
    ),
    location_sales AS (
        SELECT
            l.id AS location_id,
            l.name AS location_name,
            COALESCE(s.sales, 0) AS sales,
            COALESCE(c.cogs, 0) AS cogs
        FROM public.locations l
        LEFT JOIN sales_by_location s ON l.id = s.location_id
        LEFT JOIN cogs_by_location c ON l.id = c.location_id
        WHERE l.organization_id = p_org_id
        GROUP BY l.id, l.name, s.sales, c.cogs
    ),
    location_labor AS (
        SELECT
            l.id AS location_id,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.locations l
        LEFT JOIN public.employees e ON l.id = e.location_id
        LEFT JOIN public.employee_shifts es
            ON e.id = es.employee_id
            AND es.start_time >= (SELECT start_date FROM date_range)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id
    )
    SELECT
        ls.location_name AS name,
        ROUND(ls.sales, 2) AS sales,
        ROUND(ll.labor_cost::NUMERIC, 2) AS "laborCost",
        ROUND(ls.cogs, 2) AS cogs
    FROM location_sales ls
    JOIN location_labor ll ON ls.location_id = ll.location_id
    ORDER BY ls.sales DESC;
END;
$$;


ALTER FUNCTION "public"."get_cross_location_benchmarks"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_metrics"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_org_id, NULL, false);

  SELECT jsonb_build_object(
    'total_inventory_value', COALESCE((
      SELECT SUM(COALESCE(current_quantity, 0) * COALESCE(unit_cost, 0))
      FROM public.inventory
      WHERE organization_id = p_org_id
        AND deleted_at IS NULL
    ), 0),
    'active_vendors', COALESCE((
      SELECT COUNT(*)
      FROM public.vendors
      WHERE organization_id = p_org_id
        AND COALESCE(status, 'active') = 'active'
        AND deleted_at IS NULL
    ), 0),
    'pending_orders', COALESCE((
      SELECT COUNT(*)
      FROM public.auto_orders
      WHERE organization_id = p_org_id
        AND COALESCE(status, 'pending') IN ('pending', 'approved', 'sent', 'ordered', 'partially_received')
    ), 0),
    'recent_alerts', COALESCE((
      SELECT COUNT(*)
      FROM public.notifications
      WHERE organization_id = p_org_id
        AND created_at >= now() - interval '7 days'
        AND COALESCE(is_read, false) = false
    ), 0)
  ) INTO v_payload;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."get_dashboard_metrics"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_flagged_vendor_items"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "vendor_item_name" "text", "vendor_name" "text", "internal_product_id" "uuid", "internal_product_name" "text", "previous_price" numeric, "latest_price" numeric, "variance_percent" numeric, "invoice_date" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_organization_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
    END IF;

    RETURN QUERY
    SELECT
        vi.id,
        vi.vendor_item_name,
        v.name AS vendor_name,
        vim.internal_product_id,
        p.name AS internal_product_name,
        vi.previous_price,
        vi.last_price AS latest_price,
        vi.last_price_change_percent AS variance_percent,
        i.invoice_date::timestamptz
    FROM public.vendor_items vi
    JOIN public.vendors v ON vi.vendor_id = v.id
    LEFT JOIN public.vendor_item_mappings vim ON vim.vendor_item_id = vi.id
    LEFT JOIN public.products p ON vim.internal_product_id = p.id
    LEFT JOIN public.invoices i ON vi.last_invoice_id = i.id
    WHERE vi.organization_id = p_organization_id
      AND vi.price_variance_flag = true
    ORDER BY vi.updated_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_flagged_vendor_items"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_totals"("p_org_id" "uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
BEGIN
  -- Strict multi-tenant enforcement
  IF NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
    RAISE EXCEPTION 'Access Denied: Tenant Context Violations Precluded Processing.';
  END IF;

  WITH filtered_inventory AS (
    SELECT *
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND (p_search_term IS NULL OR p_search_term = '' OR product_name ILIKE '%' || p_search_term || '%')
  ),
  filtered_wastage AS (
    SELECT value
    FROM public.wastage_logs
    WHERE organization_id = p_org_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND created_at >= date_trunc('month', now())
  )
  SELECT jsonb_build_object(
    'totalItems', count(*),
    'totalValue', coalesce(sum(current_quantity * unit_cost), 0),
    'lowStock', count(*) FILTER (WHERE current_quantity <= coalesce(reorder_point, 5)),
    'totalWastageValue', coalesce((SELECT sum(value) FROM filtered_wastage), 0)
  )
  INTO v_payload
  FROM filtered_inventory;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."get_inventory_totals"("p_org_id" "uuid", "p_search_term" "text", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_usage_drilldown"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_inventory_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_inv_id uuid := p_inventory_id;
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;
  IF v_inv_id IS NULL AND p_product_id IS NULL THEN
    RAISE EXCEPTION 'inventory_id or product_id is required';
  END IF;

  IF v_inv_id IS NULL THEN
    SELECT id INTO v_inv_id
    FROM public.inventory
    WHERE organization_id = v_org_id
      AND deleted_at IS NULL
      AND internal_product_id = p_product_id
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR location_id = ANY (p_location_ids)
      )
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  WITH inv AS (
    SELECT
      i.*,
      COALESCE(p.name, i.product_name) AS product,
      COALESCE(NULLIF(trim(COALESCE(p.category, i.category)), ''), 'Uncategorized') AS category,
      COALESCE(loc.name, i.location, 'Unknown') AS location_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(i.current_unit), ''), NULLIF(trim(p.report_by_unit), ''), 'Each')
      ) AS unit,
      COALESCE(i.unit_cost, p.latest_price, 0)::numeric AS unit_cost
    FROM public.inventory i
    LEFT JOIN public.products p ON p.id = i.internal_product_id
    LEFT JOIN public.locations loc ON loc.id = i.location_id
    WHERE i.id = v_inv_id
      AND i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
  ),
  counts AS (
    SELECT
      cs.id AS session_id,
      (cs.completed_at AT TIME ZONE v_tz)::date AS count_date,
      cs.completed_at,
      COALESCE(
        NULLIF(cs.counted_data->(v_inv_id::text)->>'counted_quantity', '')::numeric,
        NULLIF(cs.counted_data->(v_inv_id::text)->>'count', '')::numeric
      ) AS counted_qty,
      cs.status
    FROM public.count_sessions cs
    JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    WHERE cs.organization_id = v_org_id
      AND lower(cs.status) = 'completed'
      AND cs.counted_data ? (v_inv_id::text)
      AND (cs.completed_at AT TIME ZONE v_tz)::date >= p_date_from - 90
      AND (cs.completed_at AT TIME ZONE v_tz)::date <= p_date_to
    ORDER BY cs.completed_at DESC
    LIMIT 50
  ),
  movements AS (
    SELECT
      im.id,
      im.movement_type,
      im.quantity,
      im.source_type,
      im.source_id,
      im.created_at,
      (im.created_at AT TIME ZONE v_tz)::date AS movement_date,
      CASE
        WHEN im.movement_type IN ('purchase_order', 'invoice_received') THEN 'receipt'
        WHEN im.movement_type IN ('transfer_in') OR (im.movement_type = 'transfer' AND im.quantity >= 0) THEN 'transfer_in'
        WHEN im.movement_type IN ('transfer_out') OR (im.movement_type = 'transfer' AND im.quantity < 0) THEN 'transfer_out'
        WHEN im.movement_type IN ('wastage', 'spoilage') THEN 'waste'
        WHEN im.movement_type = 'manual_adjustment' THEN 'adjustment'
        WHEN im.movement_type IN ('count_variance', 'stock_count') THEN 'count_variance'
        WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'pos_adjustment') THEN 'pos_excluded'
        ELSE 'other'
      END AS class
    FROM public.inventory_movements im
    WHERE im.organization_id = v_org_id
      AND im.inventory_id = v_inv_id
      AND (im.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (im.created_at AT TIME ZONE v_tz)::date <= p_date_to
  ),
  waste AS (
    SELECT
      w.id,
      w.quantity,
      w.unit,
      w.value,
      w.reason,
      w.created_at,
      (w.created_at AT TIME ZONE v_tz)::date AS waste_date
    FROM public.wastage_logs w
    JOIN inv ON true
    WHERE w.organization_id = v_org_id
      AND (
        (w.product_id IS NOT NULL AND w.product_id = inv.product_id)
        OR lower(w.product_name) = lower(inv.product_name)
      )
      AND (w.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (w.created_at AT TIME ZONE v_tz)::date <= p_date_to
    ORDER BY w.created_at DESC
    LIMIT 50
  ),
  usage_trend AS (
    SELECT
      movement_date AS bucket,
      round(sum(CASE WHEN class = 'receipt' THEN quantity ELSE 0 END)::numeric, 4) AS received,
      round(sum(CASE WHEN class = 'transfer_in' THEN quantity ELSE 0 END)::numeric, 4) AS transfers_in,
      round(sum(CASE WHEN class = 'transfer_out' THEN abs(quantity) ELSE 0 END)::numeric, 4) AS transfers_out,
      round(sum(CASE WHEN class = 'waste' THEN abs(quantity) ELSE 0 END)::numeric, 4) AS waste_qty,
      round(sum(CASE WHEN class = 'adjustment' THEN quantity ELSE 0 END)::numeric, 4) AS adjustments
    FROM movements
    WHERE class <> 'pos_excluded'
    GROUP BY movement_date
    ORDER BY movement_date
  ),
  location_comp AS (
    SELECT
      COALESCE(loc.name, i.location, 'Unknown') AS location,
      i.location_id,
      i.current_quantity,
      COALESCE(i.unit_cost, 0) AS unit_cost,
      round(i.current_quantity * COALESCE(i.unit_cost, 0), 2) AS value
    FROM public.inventory i
    LEFT JOIN public.locations loc ON loc.id = i.location_id
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
      AND (
        ((SELECT internal_product_id FROM inv) IS NOT NULL AND i.internal_product_id = (SELECT internal_product_id FROM inv))
        OR lower(i.product_name) = lower((SELECT product FROM inv))
      )
  )
  SELECT jsonb_build_object(
    'inventoryId', v_inv_id,
    'summary', jsonb_build_object(
      'product', (SELECT product FROM inv),
      'category', (SELECT category FROM inv),
      'location', (SELECT location_name FROM inv),
      'unit', (SELECT unit FROM inv),
      'unitCost', (SELECT unit_cost FROM inv),
      'currentQuantity', (SELECT current_quantity FROM inv),
      'lastCountedDate', (SELECT last_counted_date FROM inv)
    ),
    'countHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'sessionId', session_id,
        'date', count_date,
        'countedQuantity', counted_qty,
        'status', status
      ) ORDER BY completed_at DESC)
      FROM counts
    ), '[]'::jsonb),
    'receiptHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'sourceType', source_type,
        'sourceId', source_id,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class = 'receipt'
    ), '[]'::jsonb),
    'wasteHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id,
        'date', waste_date,
        'quantity', quantity,
        'unit', unit,
        'value', value,
        'reason', reason
      ) ORDER BY created_at DESC)
      FROM waste
    ), '[]'::jsonb),
    'transferHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'class', class,
        'sourceId', source_id,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class IN ('transfer_in', 'transfer_out')
    ), '[]'::jsonb),
    'adjustmentHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'sourceType', source_type,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class IN ('adjustment', 'count_variance')
    ), '[]'::jsonb),
    'usageTrend', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'bucket', bucket,
        'received', received,
        'transfersIn', transfers_in,
        'transfersOut', transfers_out,
        'wasteQty', waste_qty,
        'adjustments', adjustments
      ) ORDER BY bucket)
      FROM usage_trend
    ), '[]'::jsonb),
    'locationComparison', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'location', location,
        'locationId', location_id,
        'currentQuantity', current_quantity,
        'unitCost', unit_cost,
        'value', value
      ))
      FROM location_comp
    ), '[]'::jsonb),
    'normalization', jsonb_build_object(
      'reportUnit', (SELECT unit FROM inv),
      'formula', 'Actual Usage = Opening + Receipts + Transfers In - Transfers Out + Adjustments(signed) - Closing',
      'wasteRule', 'Waste is reported separately and is not added into Actual Usage',
      'posExcluded', true
    )
  )
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_inventory_usage_drilldown"("p_organization_id" "uuid", "p_inventory_id" "uuid", "p_product_id" "uuid", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_usage_report"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_category_names" "text"[] DEFAULT NULL::"text"[], "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Organization context is required'; END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN RAISE EXCEPTION 'date_from and date_to are required'; END IF;

  WITH scoped_inventory AS (
    SELECT inv.id AS inventory_id, inv.organization_id, inv.location_id, COALESCE(loc.name, inv.location, 'Unknown location') AS location_name,
      inv.internal_product_id AS product_id, COALESCE(p.name, inv.product_name, 'Unknown product') AS product, COALESCE(NULLIF(trim(COALESCE(p.category, inv.category)), ''), 'Uncategorized') AS category,
      public.normalize_product_report_unit(COALESCE(NULLIF(trim(inv.current_unit), ''), NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(p.base_unit), ''), 'Each')) AS unit,
      COALESCE(inv.unit_cost, p.latest_price, 0)::numeric AS unit_cost, COALESCE(inv.current_quantity, 0)::numeric AS current_quantity, inv.last_counted_date
    FROM public.inventory inv
    LEFT JOIN public.products p ON p.id = inv.internal_product_id AND p.deleted_at IS NULL
    LEFT JOIN public.locations loc ON loc.id = inv.location_id
    WHERE inv.organization_id = v_org_id AND inv.deleted_at IS NULL AND public.tenant_scope_visible(inv.organization_id, inv.brand_id, inv.location_id, inv.deleted_at)
      AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR inv.location_id = ANY (p_location_ids))
      AND (p_category_names IS NULL OR cardinality(p_category_names) = 0 OR COALESCE(NULLIF(trim(COALESCE(p.category, inv.category)), ''), 'Uncategorized') = ANY (p_category_names))
  ),
  count_object_lines AS (
    SELECT cs.id AS session_id, cs.completed_at, (cs.completed_at AT TIME ZONE v_tz)::date AS count_date, sh.location_id, (e.key)::uuid AS inventory_id,
      COALESCE(NULLIF(e.value->>'counted_quantity', '')::numeric, NULLIF(e.value->>'count', '')::numeric, NULLIF(e.value->>'quantity', '')::numeric) AS counted_qty,
      public.normalize_product_report_unit(COALESCE(NULLIF(trim(e.value->>'unit'), ''), 'Each')) AS unit
    FROM public.count_sessions cs JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(cs.counted_data) = 'object' THEN cs.counted_data ELSE '{}'::jsonb END) e
    WHERE cs.organization_id = v_org_id AND lower(cs.status) = 'completed' AND cs.completed_at IS NOT NULL AND e.key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR sh.location_id = ANY (p_location_ids))
  ),
  count_array_lines AS (
    SELECT cs.id AS session_id, cs.completed_at, (cs.completed_at AT TIME ZONE v_tz)::date AS count_date, sh.location_id, NULLIF(elem->>'inventory_id', '')::uuid AS inventory_id,
      COALESCE(NULLIF(elem->>'counted_quantity', '')::numeric, NULLIF(elem->>'count', '')::numeric, NULLIF(elem->>'quantity', '')::numeric) AS counted_qty,
      public.normalize_product_report_unit(COALESCE(NULLIF(trim(elem->>'unit'), ''), 'Each')) AS unit
    FROM public.count_sessions cs JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(cs.counted_data) = 'array' THEN cs.counted_data ELSE '[]'::jsonb END) elem
    WHERE cs.organization_id = v_org_id AND lower(cs.status) = 'completed' AND cs.completed_at IS NOT NULL AND NULLIF(elem->>'inventory_id', '') IS NOT NULL
      AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR sh.location_id = ANY (p_location_ids))
  ),
  count_lines AS (SELECT * FROM count_object_lines WHERE counted_qty IS NOT NULL UNION ALL SELECT * FROM count_array_lines WHERE counted_qty IS NOT NULL AND inventory_id IS NOT NULL),
  opening_counts AS (SELECT DISTINCT ON (inventory_id) inventory_id, counted_qty AS opening_qty, count_date AS opening_count_date, session_id AS opening_session_id, unit AS opening_unit FROM count_lines WHERE count_date <= p_date_from ORDER BY inventory_id, count_date DESC, completed_at DESC),
  closing_counts AS (SELECT DISTINCT ON (inventory_id) inventory_id, counted_qty AS closing_qty, count_date AS closing_count_date, session_id AS closing_session_id, unit AS closing_unit FROM count_lines WHERE count_date <= p_date_to ORDER BY inventory_id, count_date DESC, completed_at DESC),
  period_movements AS (
    SELECT im.id, im.inventory_id, im.location_id, im.movement_type, im.quantity::numeric AS quantity, im.source_type, im.source_id, im.created_at, (im.created_at AT TIME ZONE v_tz)::date AS movement_date,
      CASE WHEN im.movement_type IN ('purchase_order', 'invoice_received') AND im.quantity > 0 THEN 'receipt' WHEN im.movement_type = 'transfer_in' OR (im.movement_type = 'transfer' AND im.quantity >= 0) THEN 'transfer_in' WHEN im.movement_type = 'transfer_out' OR (im.movement_type = 'transfer' AND im.quantity < 0) THEN 'transfer_out' WHEN im.movement_type IN ('wastage', 'spoilage') THEN 'waste' WHEN im.movement_type = 'manual_adjustment' THEN 'adjustment' WHEN im.movement_type IN ('count_variance', 'stock_count') THEN 'count_variance' WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'pos_adjustment') THEN 'pos_excluded' ELSE 'other' END AS class
    FROM public.inventory_movements im
    WHERE im.organization_id = v_org_id AND (im.created_at AT TIME ZONE v_tz)::date >= p_date_from AND (im.created_at AT TIME ZONE v_tz)::date <= p_date_to
      AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR im.location_id = ANY (p_location_ids))
  ),
  movement_agg AS (
    SELECT inventory_id, round(sum(quantity) FILTER (WHERE class = 'receipt'), 4) AS received_qty, round(sum(quantity) FILTER (WHERE class = 'transfer_in'), 4) AS transfers_in_qty, round(sum(abs(quantity)) FILTER (WHERE class = 'transfer_out'), 4) AS transfers_out_qty, round(sum(quantity) FILTER (WHERE class = 'adjustment'), 4) AS adjustment_qty, round(sum(abs(quantity)) FILTER (WHERE class = 'waste'), 4) AS waste_qty_from_movements, max(movement_date) AS last_movement_date
    FROM period_movements WHERE class <> 'pos_excluded' GROUP BY inventory_id
  ),
  waste_from_logs AS (
    SELECT inv.id AS inventory_id, round(sum(w.quantity)::numeric, 4) AS waste_qty, round(sum(COALESCE(w.value, w.quantity * COALESCE(inv.unit_cost, 0)))::numeric, 2) AS waste_value
    FROM public.wastage_logs w JOIN public.inventory inv ON inv.organization_id = w.organization_id AND inv.deleted_at IS NULL AND ((w.product_id IS NOT NULL AND inv.product_id = w.product_id) OR lower(inv.product_name) = lower(w.product_name)) AND (w.location_id IS NULL OR inv.location_id IS NOT DISTINCT FROM w.location_id)
    WHERE w.organization_id = v_org_id AND (w.created_at AT TIME ZONE v_tz)::date >= p_date_from AND (w.created_at AT TIME ZONE v_tz)::date <= p_date_to AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR w.location_id = ANY (p_location_ids) OR (w.location_id IS NULL AND inv.location_id = ANY (p_location_ids)))
    GROUP BY inv.id
  ),
  base AS (
    SELECT si.*, oc.opening_qty, oc.opening_count_date, oc.opening_unit, cc.closing_qty, cc.closing_count_date, cc.closing_unit, COALESCE(ma.received_qty, 0) AS received_qty, COALESCE(ma.transfers_in_qty, 0) AS transfers_in_qty, COALESCE(ma.transfers_out_qty, 0) AS transfers_out_qty, COALESCE(ma.adjustment_qty, 0) AS adjustment_qty, COALESCE(wl.waste_qty, ma.waste_qty_from_movements, 0) AS waste_qty, COALESCE(wl.waste_value, COALESCE(ma.waste_qty_from_movements, 0) * si.unit_cost) AS waste_value, ma.last_movement_date,
      CASE WHEN oc.opening_qty IS NULL OR cc.closing_qty IS NULL THEN 'not_calculable' WHEN oc.opening_unit IS DISTINCT FROM cc.closing_unit AND oc.opening_unit IS NOT NULL AND cc.closing_unit IS NOT NULL THEN 'not_calculable' ELSE 'calculable' END AS data_quality_status,
      CASE WHEN oc.opening_qty IS NULL OR cc.closing_qty IS NULL THEN NULL WHEN oc.opening_unit IS DISTINCT FROM cc.closing_unit AND oc.opening_unit IS NOT NULL AND cc.closing_unit IS NOT NULL THEN NULL ELSE round(oc.opening_qty + COALESCE(ma.received_qty, 0) + COALESCE(ma.transfers_in_qty, 0) - COALESCE(ma.transfers_out_qty, 0) + COALESCE(ma.adjustment_qty, 0) - cc.closing_qty, 4) END AS actual_usage
    FROM scoped_inventory si LEFT JOIN opening_counts oc ON oc.inventory_id = si.inventory_id LEFT JOIN closing_counts cc ON cc.inventory_id = si.inventory_id LEFT JOIN movement_agg ma ON ma.inventory_id = si.inventory_id LEFT JOIN waste_from_logs wl ON wl.inventory_id = si.inventory_id
  ),
  enriched AS (
    SELECT b.*, CASE WHEN b.actual_usage IS NULL THEN NULL ELSE round(b.actual_usage * b.unit_cost, 2) END AS usage_value, CASE WHEN b.opening_qty IS NULL THEN NULL ELSE round(b.opening_qty * b.unit_cost, 2) END AS opening_value, CASE WHEN b.closing_qty IS NULL THEN NULL ELSE round(b.closing_qty * b.unit_cost, 2) END AS closing_value, CASE WHEN b.opening_qty IS NULL OR b.closing_qty IS NULL THEN NULL ELSE round((b.closing_qty - b.opening_qty) * b.unit_cost, 2) END AS inventory_value_change, round(b.received_qty * b.unit_cost, 2) AS received_value, round(b.transfers_in_qty * b.unit_cost, 2) AS transfers_in_value, round(b.transfers_out_qty * b.unit_cost, 2) AS transfers_out_value, round(b.adjustment_qty * b.unit_cost, 2) AS adjustment_value FROM base b
  ),
  calculable AS (SELECT * FROM enriched WHERE data_quality_status = 'calculable' AND actual_usage IS NOT NULL),
  abc_ranked AS (SELECT e.*, sum(COALESCE(e.usage_value, 0)) OVER (ORDER BY COALESCE(e.usage_value, 0) DESC, e.product) AS cum_usage_value, sum(COALESCE(e.usage_value, 0)) OVER () AS total_usage_value FROM calculable e),
  with_abc AS (SELECT e.*, CASE WHEN e.data_quality_status <> 'calculable' OR e.usage_value IS NULL THEN 'n/a' WHEN ar.total_usage_value <= 0 THEN 'C' WHEN ar.cum_usage_value <= ar.total_usage_value * 0.80 THEN 'A' WHEN ar.cum_usage_value <= ar.total_usage_value * 0.95 THEN 'B' ELSE 'C' END AS abc_class FROM enriched e LEFT JOIN abc_ranked ar ON ar.inventory_id = e.inventory_id),
  summary AS (
    SELECT round(sum(opening_value)::numeric, 2) AS opening_inventory_value, round(sum(closing_value)::numeric, 2) AS closing_inventory_value, round(sum(received_value)::numeric, 2) AS inventory_received, round(sum(usage_value)::numeric, 2) AS actual_inventory_usage, round(sum(waste_value)::numeric, 2) AS waste_value, round(sum(transfers_in_value)::numeric, 2) AS transfers_in, round(sum(transfers_out_value)::numeric, 2) AS transfers_out, round(sum(adjustment_value)::numeric, 2) AS inventory_adjustments, round(sum(inventory_value_change)::numeric, 2) AS inventory_value_change, count(*) FILTER (WHERE opening_qty IS NULL OR closing_qty IS NULL OR last_counted_date IS NULL)::int AS uncounted_or_missing, count(*)::int AS total_products, count(*) FILTER (WHERE data_quality_status = 'calculable')::int AS calculable_products FROM with_abc
  ),
  highest_usage_category AS (SELECT jsonb_build_object('category', category, 'usageValue', round(sum(usage_value)::numeric, 2), 'usageQty', round(sum(actual_usage)::numeric, 4)) AS obj FROM calculable GROUP BY category ORDER BY sum(usage_value) DESC NULLS LAST LIMIT 1),
  highest_waste_product AS (SELECT jsonb_build_object('product', product, 'category', category, 'wasteValue', waste_value, 'wasteQty', waste_qty) AS obj FROM with_abc WHERE waste_qty > 0 ORDER BY waste_value DESC NULLS LAST LIMIT 1),
  waterfall AS (SELECT jsonb_build_array(jsonb_build_object('step', 'Opening', 'value', (SELECT opening_inventory_value FROM summary)), jsonb_build_object('step', 'Receipts', 'value', (SELECT inventory_received FROM summary)), jsonb_build_object('step', 'Transfers In', 'value', (SELECT transfers_in FROM summary)), jsonb_build_object('step', 'Transfers Out', 'value', -abs(COALESCE((SELECT transfers_out FROM summary), 0))), jsonb_build_object('step', 'Adjustments', 'value', (SELECT inventory_adjustments FROM summary)), jsonb_build_object('step', 'Closing', 'value', -abs(COALESCE((SELECT closing_inventory_value FROM summary), 0))), jsonb_build_object('step', 'Actual Usage', 'value', (SELECT actual_inventory_usage FROM summary))) AS arr),
  usage_by_category AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('category', category, 'usageValue', usage_value, 'usageQty', usage_qty, 'wasteValue', waste_value, 'productCount', product_count) ORDER BY usage_value DESC NULLS LAST), '[]'::jsonb) AS arr FROM (SELECT category, round(sum(usage_value)::numeric, 2) AS usage_value, round(sum(actual_usage)::numeric, 4) AS usage_qty, round(sum(waste_value)::numeric, 2) AS waste_value, count(*)::int AS product_count FROM calculable GROUP BY category) c
  ),
  value_trend AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('bucket', bucket, 'receivedValue', received_value, 'usageProxyValue', usage_proxy_value, 'wasteValue', waste_value) ORDER BY bucket), '[]'::jsonb) AS arr FROM (SELECT to_char(date_trunc('week', m.created_at AT TIME ZONE v_tz), 'YYYY-MM-DD') AS bucket, round(sum(CASE WHEN m.class = 'receipt' THEN m.quantity * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS received_value, round(sum(CASE WHEN m.class = 'transfer_out' THEN abs(m.quantity) * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS usage_proxy_value, round(sum(CASE WHEN m.class = 'waste' THEN abs(m.quantity) * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS waste_value FROM period_movements m LEFT JOIN scoped_inventory si ON si.inventory_id = m.inventory_id WHERE m.class <> 'pos_excluded' GROUP BY 1) t
  ),
  waste_trend AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('bucket', bucket, 'wasteValue', waste_value, 'wasteQty', waste_qty) ORDER BY bucket), '[]'::jsonb) AS arr FROM (SELECT ((created_at AT TIME ZONE v_tz)::date)::text AS bucket, round(COALESCE(sum(value), 0)::numeric, 2) AS waste_value, round(COALESCE(sum(quantity), 0)::numeric, 4) AS waste_qty FROM public.wastage_logs WHERE organization_id = v_org_id AND public.tenant_scope_visible(organization_id, brand_id, location_id) AND (created_at AT TIME ZONE v_tz)::date >= p_date_from AND (created_at AT TIME ZONE v_tz)::date <= p_date_to AND (p_location_ids IS NULL OR cardinality(p_location_ids) = 0 OR location_id = ANY (p_location_ids)) GROUP BY 1) w
  ),
  product_ranking AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('product', product, 'productId', product_id, 'inventoryId', inventory_id, 'category', category, 'location', location_name, 'actualUsage', actual_usage, 'usageValue', usage_value, 'wasteValue', waste_value) ORDER BY usage_value DESC NULLS LAST), '[]'::jsonb) AS arr FROM (SELECT * FROM calculable ORDER BY usage_value DESC NULLS LAST LIMIT 20) top_u
  ),
  location_comparison AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('location', location_name, 'locationId', location_id, 'openingValue', opening_value, 'closingValue', closing_value, 'usageValue', usage_value, 'wasteValue', waste_value, 'receivedValue', received_value) ORDER BY usage_value DESC NULLS LAST), '[]'::jsonb) AS arr FROM (SELECT location_id, location_name, round(sum(opening_value)::numeric, 2) AS opening_value, round(sum(closing_value)::numeric, 2) AS closing_value, round(sum(usage_value)::numeric, 2) AS usage_value, round(sum(waste_value)::numeric, 2) AS waste_value, round(sum(received_value)::numeric, 2) AS received_value FROM with_abc GROUP BY location_id, location_name) loc
  ),
  heatmap AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('category', category, 'location', location_name, 'usageValue', usage_value, 'wasteValue', waste_value)), '[]'::jsonb) AS arr FROM (SELECT category, location_name, round(sum(usage_value)::numeric, 2) AS usage_value, round(sum(waste_value)::numeric, 2) AS waste_value FROM with_abc GROUP BY category, location_name) h
  ),
  abc AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('class', abc_class, 'productCount', product_count, 'usageValue', usage_value) ORDER BY abc_class), '[]'::jsonb) AS arr FROM (SELECT abc_class, count(*)::int AS product_count, round(sum(COALESCE(usage_value, 0))::numeric, 2) AS usage_value FROM with_abc WHERE abc_class <> 'n/a' GROUP BY abc_class) a
  ),
  insights AS (
    SELECT COALESCE(jsonb_agg(ins ORDER BY (ins->>'impact')::numeric DESC), '[]'::jsonb) AS arr
    FROM (
      SELECT jsonb_build_object('id', 'usage-total', 'impact', abs(COALESCE(s.actual_inventory_usage, 0)), 'text', format('Calculable actual inventory usage value is $%s across %s products.', to_char(COALESCE(s.actual_inventory_usage, 0), 'FM999,999,990'), s.calculable_products)) AS ins FROM summary s
      UNION ALL
      SELECT jsonb_build_object('id', 'waste', 'impact', abs(COALESCE(s.waste_value, 0)), 'text', format('Waste value in period is $%s (reported separately; not added into Actual Usage).', to_char(COALESCE(s.waste_value, 0), 'FM999,999,990'))) FROM summary s WHERE COALESCE(s.waste_value, 0) > 0
      UNION ALL
      SELECT jsonb_build_object('id', 'uncounted', 'impact', s.uncounted_or_missing, 'text', format('%s inventory items are missing opening/closing counts (Actual Usage = Not Calculable).', s.uncounted_or_missing)) FROM summary s WHERE s.uncounted_or_missing > 0
      UNION ALL
      SELECT jsonb_build_object('id', 'top-cat', 'impact', COALESCE((SELECT (obj->>'usageValue')::numeric FROM highest_usage_category), 0), 'text', format('%s is the highest-usage category.', (SELECT obj->>'category' FROM highest_usage_category))) WHERE EXISTS (SELECT 1 FROM highest_usage_category WHERE obj IS NOT NULL)
    ) x
  ),
  filter_options AS (
    SELECT COALESCE((SELECT jsonb_agg(DISTINCT category ORDER BY category) FROM with_abc WHERE category IS NOT NULL), '[]'::jsonb) AS categories,
      COALESCE((SELECT jsonb_agg(jsonb_build_object('id', location_id, 'name', location_name) ORDER BY location_name) FROM (SELECT DISTINCT location_id, location_name FROM with_abc WHERE location_id IS NOT NULL) l), '[]'::jsonb) AS locations
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object('openingInventoryValue', s.opening_inventory_value, 'closingInventoryValue', s.closing_inventory_value, 'inventoryReceived', s.inventory_received, 'actualInventoryUsage', s.actual_inventory_usage, 'wasteValue', s.waste_value, 'transfersIn', s.transfers_in, 'transfersOut', s.transfers_out, 'inventoryAdjustments', s.inventory_adjustments, 'highestUsageCategory', (SELECT obj FROM highest_usage_category), 'highestWasteProduct', (SELECT obj FROM highest_waste_product), 'inventoryValueChange', s.inventory_value_change, 'uncountedOrMissing', s.uncounted_or_missing, 'totalProducts', s.total_products, 'calculableProducts', s.calculable_products),
    'waterfall', (SELECT arr FROM waterfall), 'usageByCategory', (SELECT arr FROM usage_by_category), 'valueTrend', (SELECT arr FROM value_trend), 'wasteTrend', (SELECT arr FROM waste_trend), 'productRanking', (SELECT arr FROM product_ranking), 'locationComparison', (SELECT arr FROM location_comparison), 'heatmap', (SELECT arr FROM heatmap), 'abc', (SELECT arr FROM abc),
    'tableRows', COALESCE((SELECT jsonb_agg(jsonb_build_object('inventoryId', w.inventory_id, 'productId', w.product_id, 'product', w.product, 'category', w.category, 'location', w.location_name, 'locationId', w.location_id, 'openingQuantity', w.opening_qty, 'receivedQuantity', w.received_qty, 'transfersIn', w.transfers_in_qty, 'transfersOut', w.transfers_out_qty, 'wasteQuantity', w.waste_qty, 'adjustmentQuantity', w.adjustment_qty, 'closingQuantity', w.closing_qty, 'actualUsage', w.actual_usage, 'unit', w.unit, 'unitCost', w.unit_cost, 'usageValue', w.usage_value, 'wasteValue', w.waste_value, 'countDate', w.closing_count_date, 'lastMovementDate', w.last_movement_date, 'dataQualityStatus', w.data_quality_status, 'abcClass', w.abc_class) ORDER BY COALESCE(w.usage_value, 0) DESC, w.product) FROM with_abc w), '[]'::jsonb),
    'insights', (SELECT arr FROM insights), 'metadata', jsonb_build_object('currency', 'USD', 'timezone', v_tz, 'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'), 'usageDefinition', 'Actual Usage = Opening + Receipts + Transfers In - Transfers Out + Adjustments(signed) - Closing. Waste is reported separately and not added into Actual Usage. POS/theoretical movements are excluded. Official usage requires opening and closing completed counts.', 'filterOptions', jsonb_build_object('categories', (SELECT categories FROM filter_options), 'locations', (SELECT locations FROM filter_options)))
  ) INTO v_result FROM summary s;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."get_inventory_usage_report"("p_organization_id" "uuid", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_category_names" "text"[], "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invite_details"("invite_token" "text") RETURNS TABLE("id" "uuid", "email" "text", "role" "text", "organization_id" "uuid", "organization_name" "text", "invited_by" "uuid", "expires_at" timestamp with time zone, "metadata" "jsonb", "status" "text", "status_message" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    i.id,
    i.email,
    i.role,
    i.organization_id,
    o.name AS organization_name,
    i.invited_by,
    i.expires_at,
    i.metadata,
    CASE
      WHEN i.accepted_at IS NOT NULL THEN 'accepted'
      WHEN i.closed_at IS NOT NULL THEN 'closed'
      WHEN i.expires_at IS NOT NULL AND i.expires_at <= now() THEN 'expired'
      ELSE 'active'
    END AS status,
    CASE
      WHEN i.accepted_at IS NOT NULL THEN 'This invitation was already accepted. Please sign in instead.'
      WHEN i.closed_at IS NOT NULL THEN 'This invitation was closed by the Platform Admin. Please ask for a new invite.'
      WHEN i.expires_at IS NOT NULL AND i.expires_at <= now() THEN 'This invitation link has expired. Please ask the Platform Admin to reissue the invite.'
      ELSE 'Invitation is active.'
    END AS status_message
  FROM public.invitations i
  LEFT JOIN public.organizations o ON o.id = i.organization_id
  WHERE btrim(i.token) = btrim(invite_token)
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_invite_details"("invite_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invited_enabled_modules"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_modules jsonb;
  v_user_email text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT lower(email) INTO v_user_email
  FROM auth.users
  WHERE id = p_user_id;

  WITH latest_invite AS (
    SELECT public.normalize_invited_module_keys(i.metadata->'modules') AS modules
    FROM public.invitations i
    WHERE (
        i.accepted_by = p_user_id
        OR lower(i.email) = v_user_email
        OR i.id::text = (
          SELECT t.metadata->>'invitation_id'
          FROM public.tenants t
          WHERE t.owner_id = p_user_id
          ORDER BY t.created_at DESC
          LIMIT 1
        )
      )
      AND jsonb_typeof(i.metadata->'modules') = 'array'
    ORDER BY COALESCE(i.accepted_at, i.created_at) DESC, i.created_at DESC
    LIMIT 1
  )
  SELECT modules INTO v_modules
  FROM latest_invite
  WHERE modules IS NOT NULL;

  RETURN v_modules;
END;
$$;


ALTER FUNCTION "public"."get_invited_enabled_modules"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_labor_forecast"("p_location_id" "uuid") RETURNS TABLE("date" "text", "salesForecast" numeric, "scheduledLabor" numeric, "suggestedLabor" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT l.organization_id FROM public.locations l WHERE l.id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000)
    INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id
      AND ps.date >= (now() - interval '30 days');

    RETURN QUERY
    WITH forecast_dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS forecast_day
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(fd.forecast_day, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM forecast_dates fd
    LEFT JOIN scheduled s ON fd.forecast_day = s.shift_date
    ORDER BY fd.forecast_day ASC;
END;
$$;


ALTER FUNCTION "public"."get_labor_forecast"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_labor_schedule_variance"("p_start_date" "date", "p_end_date" "date", "p_location_id" "uuid") RETURNS TABLE("date" "date", "projected_sales" numeric, "scheduled_labor" numeric, "suggested_labor" numeric, "variance_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'A specific location is required for this report.';
  END IF;
  IF NOT public.is_platform_admin() AND p_location_id NOT IN (SELECT public.get_my_accessible_location_ids()) THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
  END IF;

  RETURN QUERY
  WITH date_series AS (
    SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)::date AS d
  ),
  daily_sales AS (
    SELECT
      m.date,
      SUM(m.total_revenue) as projected_sales
    FROM public.mv_daily_sales_summary m
    WHERE m.date >= p_start_date AND m.date <= p_end_date
      AND (p_location_id IS NULL OR m.location_id = p_location_id)
    GROUP BY m.date
  ),
  daily_labor AS (
    SELECT
      s.shift_start::date AS date,
      SUM(s.labor_cost) as scheduled_labor
    FROM public.employee_shifts s
    WHERE s.shift_start >= p_start_date AND s.shift_start <= p_end_date
      AND (p_location_id IS NULL OR s.location_id = p_location_id)
    GROUP BY s.shift_start::date
  )
  SELECT
    ds.d AS date,
    COALESCE(s.projected_sales, 0) AS projected_sales,
    COALESCE(l.scheduled_labor, 0) AS scheduled_labor,
    (COALESCE(s.projected_sales, 0) * 0.25)::numeric(15,2) AS suggested_labor,
    (COALESCE(l.scheduled_labor, 0) - (COALESCE(s.projected_sales, 0) * 0.25))::numeric(15,2) AS variance_amount
  FROM date_series ds
  LEFT JOIN daily_sales s ON ds.d = s.date
  LEFT JOIN daily_labor l ON ds.d = l.date
  ORDER BY ds.d;
END;
$$;


ALTER FUNCTION "public"."get_labor_schedule_variance"("p_start_date" "date", "p_end_date" "date", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_benchmarks"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("location_id" "uuid", "location_name" "text", "total_revenue" numeric, "total_cogs" numeric, "total_labor" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles p
     WHERE p.id = auth.uid()
       AND p.organization_id = p_organization_id
       AND p.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      m.location_id,
      SUM(m.total_revenue) AS rev
    FROM public.mv_daily_sales_summary m
    WHERE m.organization_id = p_organization_id
      AND m.date >= p_start_date
      AND m.date <= p_end_date
    GROUP BY m.location_id
  ),
  cogs AS (
    SELECT
      i.location_id,
      SUM(i.total_amount) AS cogs
    FROM public.invoices i
    WHERE i.organization_id = p_organization_id
      AND i.invoice_date >= p_start_date
      AND i.invoice_date <= p_end_date
    GROUP BY i.location_id
  ),
  labor AS (
    SELECT
      s.location_id,
      SUM(s.labor_cost) AS labor
    FROM public.employee_shifts s
    WHERE s.organization_id = p_organization_id
      AND DATE(s.shift_start) >= p_start_date
      AND DATE(s.shift_start) <= p_end_date
    GROUP BY s.location_id
  )
  SELECT
    l.id AS location_id,
    l.name AS location_name,
    COALESCE(s.rev, 0)::numeric AS total_revenue,
    COALESCE(c.cogs, 0)::numeric AS total_cogs,
    COALESCE(lab.labor, 0)::numeric AS total_labor
  FROM public.locations l
  LEFT JOIN sales s ON l.id = s.location_id
  LEFT JOIN cogs c ON l.id = c.location_id
  LEFT JOIN labor lab ON l.id = lab.location_id
  WHERE l.organization_id = p_organization_id
  ORDER BY COALESCE(s.rev, 0) DESC;
END;
$$;


ALTER FUNCTION "public"."get_location_benchmarks"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_category_performance_drilldown"("p_organization_id" "uuid", "p_location_id" "uuid", "p_category" "text", "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_timezone text;
BEGIN
  PERFORM public.assert_performance_location_access(
    p_organization_id, p_location_id, false
  );
  v_timezone := public.resolve_performance_location_timezone(p_organization_id, p_location_id);
  RETURN public.get_category_performance_drilldown(
    p_organization_id,
    p_category,
    ARRAY[p_location_id],
    p_date_from,
    p_date_to,
    p_comparison_date_from,
    p_comparison_date_to,
    p_vendor_ids,
    v_timezone
  );
END;
$$;


ALTER FUNCTION "public"."get_location_category_performance_drilldown"("p_organization_id" "uuid", "p_location_id" "uuid", "p_category" "text", "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_vendor_ids" "uuid"[], "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_category_performance_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_category_names" "text"[] DEFAULT NULL::"text"[], "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text", "p_selected_category" "text" DEFAULT NULL::"text", "p_trend_categories" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_location_brand_id uuid;
  v_timezone text;
  v_result jsonb;
  v_table_rows jsonb;
BEGIN
  PERFORM public.assert_performance_location_access(
    p_organization_id, p_location_id, false
  );

  v_timezone := public.resolve_performance_location_timezone(p_organization_id, p_location_id);

  SELECT l.brand_id
    INTO v_location_brand_id
  FROM public.locations l
  WHERE l.id = p_location_id
    AND l.organization_id = p_organization_id
    AND l.deleted_at IS NULL;

  v_result := public.get_category_performance_report(
    p_organization_id,
    ARRAY[p_location_id],
    p_date_from,
    p_date_to,
    p_comparison_date_from,
    p_comparison_date_to,
    p_category_names,
    p_vendor_ids,
    v_timezone,
    p_selected_category,
    p_trend_categories
  );

  WITH rows AS (
    SELECT source.row_data, source.ordinality
    FROM jsonb_array_elements(COALESCE(v_result->'tableRows', '[]'::jsonb))
      WITH ORDINALITY AS source(row_data, ordinality)
  ), scoped_budgets AS (
    SELECT
      btrim(bt.category) AS category,
      sum(bt.target_amount)::numeric AS budget
    FROM public.budget_targets bt
    WHERE bt.organization_id = p_organization_id
      AND bt.location_id = p_location_id
      AND bt.brand_id IS NOT DISTINCT FROM v_location_brand_id
      AND bt.period_start = p_date_from
      AND bt.period_end = p_date_to
      AND bt.category IS NOT NULL
    GROUP BY btrim(bt.category)
  )
  SELECT COALESCE(
    jsonb_agg(
      rows.row_data
      || jsonb_build_object(
        'budget', scoped_budgets.budget,
        'budgetVariance', CASE
          WHEN scoped_budgets.budget IS NULL THEN NULL
          ELSE round(
            COALESCE(NULLIF(rows.row_data->>'currentSpend', '')::numeric, 0)
            - scoped_budgets.budget,
            2
          )
        END
      )
      ORDER BY rows.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_table_rows
  FROM rows
  LEFT JOIN scoped_budgets
    ON scoped_budgets.category = btrim(rows.row_data->>'category');

  RETURN jsonb_set(
    jsonb_set(
      COALESCE(v_result, '{}'::jsonb),
      '{tableRows}',
      v_table_rows,
      true
    ),
    '{metadata}',
    COALESCE(v_result->'metadata', '{}'::jsonb)
      || jsonb_build_object(
        'timezone', v_timezone,
        'timezoneSource', 'locations.timezone',
        'timezoneFallback', CASE WHEN v_timezone = 'UTC' THEN 'UTC when missing or invalid' ELSE NULL END,
        'budgetScope', 'exact_location_brand_period_category',
        'budgetPeriodRule', 'exact_period_match'
      ),
    true
  );
END;
$$;


ALTER FUNCTION "public"."get_location_category_performance_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_category_names" "text"[], "p_vendor_ids" "uuid"[], "p_timezone" "text", "p_selected_category" "text", "p_trend_categories" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_location_category_performance_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_category_names" "text"[], "p_vendor_ids" "uuid"[], "p_timezone" "text", "p_selected_category" "text", "p_trend_categories" "text"[]) IS 'Secured single-location Performance Category report with exact active-location brand, location, period, and category budget matching.';



CREATE OR REPLACE FUNCTION "public"."get_location_inventory_usage_drilldown"("p_organization_id" "uuid", "p_location_id" "uuid", "p_inventory_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_timezone text;
BEGIN
  PERFORM public.assert_performance_location_access(
    p_organization_id, p_location_id, false
  );
  v_timezone := public.resolve_performance_location_timezone(p_organization_id, p_location_id);
  RETURN public.get_inventory_usage_drilldown(
    p_organization_id,
    p_inventory_id,
    p_product_id,
    ARRAY[p_location_id],
    p_date_from,
    p_date_to,
    v_timezone
  );
END;
$$;


ALTER FUNCTION "public"."get_location_inventory_usage_drilldown"("p_organization_id" "uuid", "p_location_id" "uuid", "p_inventory_id" "uuid", "p_product_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_inventory_usage_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_category_names" "text"[] DEFAULT NULL::"text"[], "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_timezone text;
  v_result jsonb;
  v_table_rows jsonb;
BEGIN
  PERFORM public.assert_performance_location_access(
    p_organization_id, p_location_id, false
  );

  v_timezone := public.resolve_performance_location_timezone(p_organization_id, p_location_id);

  v_result := public.get_inventory_usage_report(
    p_organization_id,
    ARRAY[p_location_id],
    p_date_from,
    p_date_to,
    p_category_names,
    v_timezone
  );

  SELECT COALESCE(
    jsonb_agg(
      source.row_data
      || jsonb_build_object(
        'currentOnHandQuantity', evidence.current_on_hand_quantity,
        'reorderPoint', evidence.reorder_point,
        'unitCost', evidence.unit_cost,
        'unitCostSource', evidence.unit_cost_source,
        'usageValue', CASE
          WHEN NULLIF(source.row_data->>'actualUsage', '') IS NULL
            OR evidence.unit_cost IS NULL
          THEN NULL
          ELSE round(
            (source.row_data->>'actualUsage')::numeric * evidence.unit_cost,
            2
          )
        END,
        'currentInventoryValue', evidence.current_inventory_value,
        'currentInventoryValueSource', evidence.current_inventory_value_source
      )
      ORDER BY source.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_table_rows
  FROM jsonb_array_elements(COALESCE(v_result->'tableRows', '[]'::jsonb))
    WITH ORDINALITY AS source(row_data, ordinality)
  LEFT JOIN LATERAL (
    SELECT
      inv.current_quantity::numeric AS current_on_hand_quantity,
      CASE
        WHEN inv.reorder_point > 0 THEN inv.reorder_point::numeric
        WHEN inv.par_level > 0 THEN inv.par_level::numeric
        ELSE NULL
      END AS reorder_point,
      CASE
        WHEN inv.unit_cost > 0 THEN inv.unit_cost::numeric
        WHEN product.latest_price > 0 THEN product.latest_price::numeric
        ELSE NULL
      END AS unit_cost,
      CASE
        WHEN inv.unit_cost > 0 THEN 'inventory.unit_cost'
        WHEN product.latest_price > 0 THEN 'products.latest_price'
        ELSE 'unavailable'
      END AS unit_cost_source,
      CASE
        WHEN inv.current_value IS NOT NULL THEN inv.current_value::numeric
        WHEN inv.current_quantity IS NOT NULL
          AND (
            CASE
              WHEN inv.unit_cost > 0 THEN inv.unit_cost
              WHEN product.latest_price > 0 THEN product.latest_price
              ELSE NULL
            END
          ) IS NOT NULL
        THEN round(
          inv.current_quantity
          * CASE
              WHEN inv.unit_cost > 0 THEN inv.unit_cost
              WHEN product.latest_price > 0 THEN product.latest_price
            END,
          2
        )
        ELSE NULL
      END AS current_inventory_value,
      CASE
        WHEN inv.current_value IS NOT NULL THEN 'inventory.current_value'
        WHEN inv.current_quantity IS NOT NULL
          AND (inv.unit_cost > 0 OR product.latest_price > 0)
        THEN 'calculated_current_quantity_x_unit_cost'
        ELSE 'unavailable'
      END AS current_inventory_value_source
    FROM public.inventory inv
    LEFT JOIN public.products product
      ON product.id = inv.internal_product_id
     AND product.organization_id = p_organization_id
     AND product.deleted_at IS NULL
    WHERE inv.id = NULLIF(source.row_data->>'inventoryId', '')::uuid
      AND inv.organization_id = p_organization_id
      AND inv.location_id = p_location_id
      AND inv.deleted_at IS NULL
    LIMIT 1
  ) evidence ON TRUE;

  RETURN jsonb_set(
    jsonb_set(
      COALESCE(v_result, '{}'::jsonb),
      '{tableRows}',
      v_table_rows,
      true
    ),
    '{metadata}',
    COALESCE(v_result->'metadata', '{}'::jsonb)
      || jsonb_build_object(
        'timezone', v_timezone,
        'timezoneSource', 'locations.timezone',
        'timezoneFallback', CASE WHEN v_timezone = 'UTC' THEN 'UTC when missing or invalid' ELSE NULL END
      ),
    true
  );
END;
$$;


ALTER FUNCTION "public"."get_location_inventory_usage_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_category_names" "text"[], "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_location_inventory_usage_report"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_category_names" "text"[], "p_timezone" "text") IS 'Secured single-location Performance Inventory Usage report enriched with current on-hand, reorder, cost provenance, current-value evidence, and server-derived location timezone.';



CREATE OR REPLACE FUNCTION "public"."get_location_performance_overview_rollup"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_timezone text;
  v_brand_id uuid;
  v_result jsonb;
BEGIN
  PERFORM public.assert_performance_location_access(p_organization_id, p_location_id, false);
  PERFORM public.assert_performance_report_bounds(p_date_from, p_date_to);

  v_timezone := public.resolve_performance_location_timezone(p_organization_id, p_location_id);

  SELECT l.brand_id
    INTO v_brand_id
  FROM public.locations l
  WHERE l.id = p_location_id
    AND l.organization_id = p_organization_id
    AND l.deleted_at IS NULL;

  WITH invoice_scope AS (
    SELECT
      i.id,
      i.total_amount,
      COALESCE(i.paid_amount, 0) AS paid_amount,
      COALESCE(i.credit_applied, 0) AS credit_applied,
      lower(COALESCE(i.payment_status, '')) AS payment_status
    FROM public.invoices i
    WHERE i.organization_id = p_organization_id
      AND i.location_id = p_location_id
      AND i.deleted_at IS NULL
      AND i.invoice_date >= p_date_from
      AND i.invoice_date <= p_date_to
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
  ),
  invoice_rollup AS (
    SELECT
      COALESCE(sum(GREATEST(0, total_amount - paid_amount - credit_applied))
        FILTER (WHERE payment_status IN ('unpaid', 'partial', 'processing')), 0)::numeric AS unpaid_balance,
      count(*) FILTER (WHERE payment_status IN ('unpaid', 'partial', 'processing'))::int AS unpaid_count
    FROM invoice_scope
  ),
  payment_rollup AS (
    SELECT
      COALESCE(sum(amount) FILTER (WHERE lower(COALESCE(status, '')) IN ('completed', 'paid')), 0)::numeric AS completed_amount,
      COALESCE(sum(amount) FILTER (WHERE lower(COALESCE(status, '')) IN ('pending', 'processing', 'scheduled')), 0)::numeric AS scheduled_amount,
      COALESCE(sum(amount) FILTER (WHERE lower(COALESCE(status, '')) IN ('failed', 'cancelled', 'refunded')), 0)::numeric AS failed_amount,
      count(*)::int AS payment_count
    FROM public.payments p
    WHERE p.organization_id = p_organization_id
      AND p.location_id = p_location_id
      AND p.deleted_at IS NULL
      AND COALESCE(p.payment_date, (p.created_at AT TIME ZONE v_timezone)::date) >= p_date_from
      AND COALESCE(p.payment_date, (p.created_at AT TIME ZONE v_timezone)::date) <= p_date_to
      AND public.tenant_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
  ),
  product_rollup AS (
    SELECT
      count(*)::int AS total_products,
      count(*) FILTER (WHERE NULLIF(btrim(COALESCE(category, accounting_category)), '') IS NOT NULL)::int AS categorized_products
    FROM public.products p
    WHERE p.organization_id = p_organization_id
      AND p.deleted_at IS NULL
      AND (
        p.location_id = p_location_id
        OR (p.location_id IS NULL AND p.brand_id IS NOT DISTINCT FROM v_brand_id)
        OR (p.location_id IS NULL AND p.brand_id IS NULL)
      )
  ),
  inventory_rollup AS (
    SELECT
      COALESCE(sum(current_value), 0)::numeric AS current_inventory_value,
      count(*) FILTER (
        WHERE COALESCE(reorder_point, par_level, 0) > 0
          AND COALESCE(current_quantity, 0) <= COALESCE(reorder_point, par_level, 0)
      )::int AS low_stock_count,
      count(*)::int AS inventory_count
    FROM public.inventory inv
    WHERE inv.organization_id = p_organization_id
      AND inv.location_id = p_location_id
      AND inv.deleted_at IS NULL
      AND public.tenant_scope_visible(inv.organization_id, inv.brand_id, inv.location_id, inv.deleted_at)
  ),
  recipe_base AS (
    SELECT
      COALESCE(cost_per_serving, total_cost, 0)::numeric AS cost,
      COALESCE(selling_price, suggested_price, 0)::numeric AS price,
      COALESCE(target_margin_percent, 0)::numeric AS target_margin
    FROM public.recipes r
    WHERE r.organization_id = p_organization_id
      AND r.deleted_at IS NULL
      AND (
        r.location_id = p_location_id
        OR (r.location_id IS NULL AND r.brand_id IS NOT DISTINCT FROM v_brand_id)
        OR (r.location_id IS NULL AND r.brand_id IS NULL)
      )
      AND public.tenant_scope_visible(r.organization_id, r.brand_id, r.location_id, r.deleted_at)
  ),
  recipe_rollup AS (
    SELECT
      count(*)::int AS recipe_count,
      COALESCE(avg(((price - cost) / NULLIF(price, 0)) * 100) FILTER (WHERE price > 0), 0)::numeric AS average_recipe_margin,
      count(*) FILTER (
        WHERE price > 0
          AND target_margin > 0
          AND ((price - cost) / NULLIF(price, 0)) * 100 < target_margin
      )::int AS recipe_margin_risk_count
    FROM recipe_base
  )
  SELECT jsonb_build_object(
    'payments', jsonb_build_object(
      'completedAmount', pr.completed_amount,
      'scheduledAmount', pr.scheduled_amount,
      'failedAmount', pr.failed_amount,
      'paymentCount', pr.payment_count,
      'invoiceUnpaidBalance', ir.unpaid_balance,
      'invoiceUnpaidCount', ir.unpaid_count
    ),
    'products', jsonb_build_object(
      'totalProducts', prod.total_products,
      'categorizedProducts', prod.categorized_products
    ),
    'inventory', jsonb_build_object(
      'currentInventoryValue', inv.current_inventory_value,
      'lowStockCount', inv.low_stock_count,
      'inventoryCount', inv.inventory_count
    ),
    'recipes', jsonb_build_object(
      'recipeCount', rec.recipe_count,
      'averageRecipeMargin', round(rec.average_recipe_margin, 2),
      'recipeMarginRiskCount', rec.recipe_margin_risk_count
    ),
    'metadata', jsonb_build_object(
      'timezone', v_timezone,
      'aggregation', 'server_rollup',
      'maxInteractiveRangeDays', 548,
      'queryDurationMs', round((EXTRACT(epoch FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  )
  INTO v_result
  FROM invoice_rollup ir, payment_rollup pr, product_rollup prod, inventory_rollup inv, recipe_rollup rec;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_location_performance_overview_rollup"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_location_performance_overview_rollup"("p_organization_id" "uuid", "p_location_id" "uuid", "p_date_from" "date", "p_date_to" "date") IS 'Server-side bounded rollup for the Performance overview, replacing browser aggregation over large entity lists.';



