CREATE OR REPLACE FUNCTION "public"."get_my_access_level"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(access_level, 'location') FROM profiles WHERE id = auth.uid();
$$;


ALTER FUNCTION "public"."get_my_access_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_accessible_brand_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT b.brand_id
  FROM public.brands b
  WHERE public.is_platform_admin()
     OR (
       public.get_auth_role() = 'tenant_super_admin'
       AND b.organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       )
     )
     OR (
       public.get_auth_role() = 'org_manager'
       AND b.organization_id = public.get_auth_org()
     )
     OR (
       public.get_auth_role() = 'branch_manager'
       AND b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
     );
$$;


ALTER FUNCTION "public"."get_my_accessible_brand_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_accessible_brand_ids"() IS 'Returns brand IDs the caller can access via profile scope or user_roles assignments.';



CREATE OR REPLACE FUNCTION "public"."get_my_accessible_location_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT l.id
  FROM public.locations l
  WHERE public.is_platform_admin()
     OR (
       public.get_auth_role() = 'tenant_super_admin'
       AND l.organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       )
     )
     OR (
       public.get_auth_role() = 'org_manager'
       AND l.organization_id = public.get_auth_org()
     )
     OR (
       public.get_auth_role() = 'branch_manager'
       AND l.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
     )
     OR (
       public.get_auth_role() = 'location_manager'
       AND l.id = (SELECT p.location_id FROM public.profiles p WHERE p.id = auth.uid())
     );
$$;


ALTER FUNCTION "public"."get_my_accessible_location_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_accessible_location_ids"() IS 'Returns location IDs the caller can access via profiles or user_roles assignments.';



CREATE OR REPLACE FUNCTION "public"."get_my_accessible_org_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE 
    WHEN p.role = 'platform_admin' THEN o.id
    WHEN p.access_level = 'platform' THEN o.id
    ELSE NULL
  END
  FROM profiles p, organizations o
  WHERE p.id = auth.uid()
    AND (p.role = 'platform_admin' OR p.access_level = 'platform')
  UNION
  -- Owner: sees all orgs they own
  SELECT o.id FROM organizations o WHERE o.owner_id = auth.uid()
  UNION
  -- Org/brand/location level: sees only their assigned org
  SELECT p.organization_id FROM profiles p WHERE p.id = auth.uid() AND p.organization_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."get_my_accessible_org_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_business_verification_draft"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_profile RECORD;
  v_verification RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT onboarding_draft, onboarding_current_step, onboarding_status, business_verification_status
  INTO v_profile
  FROM public.profiles
  WHERE id = auth.uid();

  SELECT rejection_reason, metadata
  INTO v_verification
  FROM public.business_verifications
  WHERE user_id = auth.uid()
  ORDER BY created_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'draft', COALESCE(v_profile.onboarding_draft, '{}'::jsonb),
    'current_step', v_profile.onboarding_current_step,
    'status', v_profile.onboarding_status,
    'business_verification_status', v_profile.business_verification_status,
    'rejection_reason', v_verification.rejection_reason,
    'more_info_reason', v_verification.metadata->>'more_info_reason'
  );
END;
$$;


ALTER FUNCTION "public"."get_my_business_verification_draft"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_onboarding_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_profile JSONB;
  v_verification JSONB;
  v_payment JSONB;
  v_coupon JSONB;
  v_run JSONB;
  v_hierarchy JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_user_id;

  SELECT to_jsonb(bv) INTO v_verification
  FROM public.business_verifications bv
  WHERE bv.user_id = v_user_id
  ORDER BY bv.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(pm) INTO v_payment
  FROM public.onboarding_payment_methods pm
  WHERE pm.user_id = v_user_id
  ORDER BY pm.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(r) INTO v_coupon
  FROM public.onboarding_coupon_redemptions r
  WHERE r.user_id = v_user_id
    AND r.status = 'applied'
  ORDER BY r.redeemed_at DESC
  LIMIT 1;

  SELECT to_jsonb(w) INTO v_run
  FROM public.onboarding_workflow_runs w
  WHERE w.user_id = v_user_id
  ORDER BY w.started_at DESC
  LIMIT 1;

  SELECT jsonb_build_object('status', h.status, 'rejection_reason', h.rejection_reason) INTO v_hierarchy
  FROM public.onboarding_hierarchy_submissions h
  WHERE h.user_id = v_user_id
  ORDER BY h.created_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'workflow_run', v_run,
    'business_verification', v_verification,
    'payment_method', v_payment,
    'coupon_redemption', v_coupon,
    'hierarchy_submission', v_hierarchy
  );
END;
$$;


