CREATE OR REPLACE FUNCTION "public"."get_payment_account_banking_for_audit"("p_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
BEGIN
  -- service-role only, same as get_vendor_banking_for_audit: used exclusively by
  -- create-dwolla-funding-source to retrieve the org's real bank details for the Dwolla API call.
  SELECT banking_secret_id
    INTO v_secret_id
  FROM public.payment_accounts
  WHERE id = p_account_id;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'Payment account banking secret for % not found', p_account_id;
  END IF;

  SELECT decrypted_secret
    INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  RETURN v_secret::jsonb;
END;
$$;


ALTER FUNCTION "public"."get_payment_account_banking_for_audit"("p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_approval_settings"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT public.is_platform_admin() AND p_organization_id != public.get_auth_org() THEN '{}'::jsonb
    ELSE COALESCE((
      SELECT os.settings
      FROM public.operational_settings os
      WHERE os.organization_id = p_organization_id
        AND os.category = 'payments'
        AND (
          (p_location_id IS NOT NULL AND os.location_id = p_location_id)
          OR (p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL)
          OR (os.brand_id IS NULL AND os.location_id IS NULL)
        )
      ORDER BY
        CASE
          WHEN p_location_id IS NOT NULL AND os.location_id = p_location_id THEN 1
          WHEN p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL THEN 2
          ELSE 3
        END,
        os.updated_at DESC NULLS LAST
      LIMIT 1
    ), '{}'::jsonb)
  END;
$$;


ALTER FUNCTION "public"."get_payment_approval_settings"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_performance_dashboard_metrics"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_total_sales NUMERIC := 0;
  v_total_cogs NUMERIC := 0;
  v_total_labor NUMERIC := 0;
  v_today_sales NUMERIC := 0;
  v_today_cogs NUMERIC := 0;
  v_today_labor NUMERIC := 0;
  v_trend_data JSONB := '[]'::jsonb;
  v_movers_data JSONB := '[]'::jsonb;
  v_category_data JSONB := '[]'::jsonb;
  v_pending_invoices_count INT := 0;
BEGIN
  IF NOT public.is_platform_admin() AND public.get_my_org() != p_organization_id THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
  END IF;

  SELECT
    COALESCE(SUM(total_revenue), 0),
    COALESCE(SUM(CASE WHEN date = CURRENT_DATE THEN total_revenue ELSE 0 END), 0)
  INTO v_total_sales, v_today_sales
  FROM public.mv_daily_sales_summary
  WHERE organization_id = p_organization_id
    AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND (p_location_id IS NULL OR location_id = p_location_id)
    AND date >= p_start_date
    AND date <= p_end_date;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'date', s.date,
      'name', to_char(s.date, 'Dy'),
      'actual', s.total_revenue,
      'forecast', s.total_revenue * 1.05
    )
  ), '[]'::jsonb)
  INTO v_trend_data
  FROM (
    SELECT date, total_revenue
    FROM public.mv_daily_sales_summary
    WHERE organization_id = p_organization_id
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND date >= p_start_date
      AND date <= p_end_date
    ORDER BY date ASC
  ) s;

  SELECT
    COALESCE(SUM(total_amount), 0),
    COALESCE(SUM(CASE WHEN invoice_date = CURRENT_DATE THEN total_amount ELSE 0 END), 0),
    COUNT(CASE WHEN status IN ('pending_review', 'validated', 'flagged') THEN 1 END)
  INTO v_total_cogs, v_today_cogs, v_pending_invoices_count
  FROM public.invoices
  WHERE organization_id = p_organization_id
    AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND (p_location_id IS NULL OR location_id = p_location_id)
    AND invoice_date >= p_start_date
    AND invoice_date <= p_end_date;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('name', COALESCE(category_name, 'Uncategorized'), 'spend', amount)
  ), '[]'::jsonb)
  INTO v_category_data
  FROM (
    SELECT category_name, SUM(amount) AS amount
    FROM public.invoice_allocations
    WHERE organization_id = p_organization_id
      AND created_at::DATE >= p_start_date
      AND created_at::DATE <= p_end_date
    GROUP BY category_name
    ORDER BY amount DESC
    LIMIT 8
  ) c;

  SELECT COALESCE(SUM(labor_cost), 0)
  INTO v_total_labor
  FROM public.employee_shifts
  WHERE organization_id = p_organization_id
    AND (p_location_id IS NULL OR location_id = p_location_id)
    AND COALESCE(shift_start, start_time)::DATE >= p_start_date
    AND COALESCE(shift_start, start_time)::DATE <= p_end_date;

  SELECT COALESCE(SUM(labor_cost), 0)
  INTO v_today_labor
  FROM public.employee_shifts
  WHERE organization_id = p_organization_id
    AND (p_location_id IS NULL OR location_id = p_location_id)
    AND COALESCE(shift_start, start_time)::DATE = CURRENT_DATE;

  RETURN jsonb_build_object(
    'sales', jsonb_build_object('total', v_total_sales, 'today', v_today_sales),
    'cogs', jsonb_build_object('total', v_total_cogs, 'today', v_today_cogs),
    'labor', jsonb_build_object('total', v_total_labor, 'today', v_today_labor),
    'trend', v_trend_data,
    'categories', v_category_data,
    'movers', v_movers_data,
    'pending_invoices_count', v_pending_invoices_count
  );
END;
$$;


ALTER FUNCTION "public"."get_performance_dashboard_metrics"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pnl_summary"("p_org_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_total_revenue NUMERIC(15,2) := 0;
  v_total_labor NUMERIC(15,2) := 0;
  v_total_cogs_allocated NUMERIC(15,2) := 0;
  v_total_invoices_raw NUMERIC(15,2) := 0;
  v_total_cogs NUMERIC(15,2) := 0;
BEGIN
  IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
  END IF;

  SELECT COALESCE(SUM(total_revenue), 0) INTO v_total_revenue
  FROM public.mv_daily_sales_summary
  WHERE organization_id = p_org_id
    AND date >= p_start_date
    AND date <= p_end_date
    AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND (p_location_id IS NULL OR location_id = p_location_id);

  SELECT COALESCE(SUM(labor_cost), 0) INTO v_total_labor
  FROM public.employee_shifts
  WHERE organization_id = p_org_id
    AND shift_start >= p_start_date
    AND shift_start <= p_end_date
    AND (p_location_id IS NULL OR location_id = p_location_id);

  SELECT COALESCE(SUM(a.amount), 0) INTO v_total_cogs_allocated
  FROM public.invoice_allocations a
  JOIN public.invoices i ON i.id = a.invoice_id
  WHERE a.organization_id = p_org_id
    AND a.allocation_type = 'line_items'
    AND i.invoice_date >= p_start_date
    AND i.invoice_date <= p_end_date
    AND (p_brand_id IS NULL OR i.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR i.location_id = p_location_id);

  IF v_total_cogs_allocated > 0 THEN
    v_total_cogs := v_total_cogs_allocated;
  ELSE
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_invoices_raw
    FROM public.invoices
    WHERE organization_id = p_org_id
      AND invoice_date >= p_start_date
      AND invoice_date <= p_end_date
      AND status != 'void'
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id);

    v_total_cogs := v_total_invoices_raw;
  END IF;

  RETURN jsonb_build_object(
    'total_revenue', v_total_revenue,
    'total_labor_cost', v_total_labor,
    'total_cogs', v_total_cogs,
    'prime_cost', (v_total_cogs + v_total_labor)
  );
END;
$$;


ALTER FUNCTION "public"."get_pnl_summary"("p_org_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_prepared_item_dependencies"("p_recipe_id" "uuid") RETURNS TABLE("recipe_id" "uuid", "recipe_name" "text", "recipe_status" "text", "quantity" numeric, "unit" "text", "yield_percentage" numeric, "cost_contribution" numeric, "is_prepared_item" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select r.id, r.name, r.status, ri.quantity, ri.unit, ri.yield_percentage,
         coalesce(ri.quantity * ri.unit_cost_snapshot / nullif(ri.yield_percentage / 100.0, 0), 0),
         coalesce(r.is_batch, false)
  from public.recipe_ingredients ri
  join public.recipes r on r.id = ri.recipe_id and r.organization_id = ri.organization_id
  where ri.sub_recipe_id = p_recipe_id
    and ri.organization_id = public.get_my_org()
  order by r.name;
$$;


ALTER FUNCTION "public"."get_prepared_item_dependencies"("p_recipe_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_price_movers_drilldown"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_product_name" "text" DEFAULT NULL::"text", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;
  IF p_product_id IS NULL AND NULLIF(trim(COALESCE(p_product_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'product_id or product_name is required';
  END IF;

  WITH eligible_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  lines AS (
    SELECT
      ili.id AS line_id,
      ili.invoice_id,
      i.invoice_number,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      l.name AS location_name,
      ili.internal_product_id,
      COALESCE(p.name, ili.item_name) AS product_name,
      COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') AS category_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(ili.vendor_unit), ''), 'Each')
      ) AS report_unit,
      COALESCE(ili.quantity, 0)::numeric AS quantity,
      COALESCE(ili.unit_price, 0)::numeric AS unit_price,
      COALESCE(ili.total_price, 0)::numeric AS total_price,
      COALESCE(vim.conversion_multiplier, 1)::numeric AS conversion_multiplier,
      CASE
        WHEN ili.internal_product_id IS NULL THEN 'unmapped'
        WHEN vim.is_verified IS TRUE THEN 'verified'
        WHEN vim.internal_product_id IS NOT NULL THEN 'mapped'
        ELSE 'mapped'
      END AS mapping_status,
      NULLIF(trim(ili.vendor_unit), '') AS vendor_unit,
      NULLIF(trim(vi.pack_size), '') AS pack_size,
      i.status
    FROM eligible_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id
    LEFT JOIN public.locations l ON l.id = i.location_id
    LEFT JOIN LATERAL (
      SELECT m.conversion_multiplier, m.is_verified, m.internal_product_id
      FROM public.vendor_item_mappings m
      WHERE m.internal_product_id = ili.internal_product_id
      ORDER BY m.is_verified DESC NULLS LAST
      LIMIT 1
    ) vim ON TRUE
    LEFT JOIN public.vendor_items vi ON vi.id = ili.vendor_item_id
    WHERE (
      (p_product_id IS NOT NULL AND ili.internal_product_id = p_product_id)
      OR (
        p_product_id IS NULL
        AND lower(COALESCE(p.name, ili.item_name, '')) = lower(trim(p_product_name))
      )
    )
  ),
  priced AS (
    SELECT
      *,
      quantity * conversion_multiplier AS normalized_qty,
      CASE WHEN quantity * conversion_multiplier = 0 THEN NULL
           ELSE round(total_price / (quantity * conversion_multiplier), 6)
      END AS normalized_unit_cost
    FROM lines
  ),
  current_rows AS (
    SELECT * FROM priced
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM priced
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  summary AS (
    SELECT
      (SELECT product_name FROM current_rows LIMIT 1) AS product,
      (SELECT category_name FROM current_rows LIMIT 1) AS category,
      (SELECT report_unit FROM current_rows LIMIT 1) AS unit,
      (SELECT pack_size FROM current_rows WHERE pack_size IS NOT NULL LIMIT 1) AS pack_size,
      (array_agg(mapping_status ORDER BY CASE mapping_status WHEN 'verified' THEN 0 WHEN 'mapped' THEN 1 ELSE 2 END))[1] AS mapping_status,
      round(sum(normalized_qty)::numeric, 4) AS current_qty,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6) END AS current_price,
      (SELECT CASE WHEN sum(pr.normalized_qty) = 0 THEN NULL
                   ELSE round(sum(pr.total_price) / sum(pr.normalized_qty), 6) END
       FROM previous_rows pr) AS previous_price,
      round(sum(total_price)::numeric, 2) AS current_spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id)::bigint AS vendor_count
    FROM current_rows
  ),
  price_history_rows AS (
    SELECT
      invoice_date,
      round(avg(normalized_unit_cost)::numeric, 6) AS unit_cost,
      round(sum(total_price)::numeric, 2) AS spend,
      round(sum(normalized_qty)::numeric, 4) AS quantity
    FROM current_rows
    WHERE normalized_unit_cost IS NOT NULL
    GROUP BY invoice_date
  ),
  price_history AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'date', invoice_date,
        'unitCost', unit_cost,
        'spend', spend,
        'quantity', quantity
      )
      ORDER BY invoice_date
    ), '[]'::jsonb) AS arr
    FROM price_history_rows
  ),
  vendor_comparison_rows AS (
    SELECT
      vendor_id,
      vendor_name,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6) END AS current_price,
      round(sum(total_price)::numeric, 2) AS spend,
      count(DISTINCT invoice_id) AS invoice_count,
      (array_agg(report_unit))[1] AS unit
    FROM current_rows
    GROUP BY vendor_id, vendor_name
  ),
  vendor_comparison AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'vendor', vendor_name,
        'vendorId', vendor_id,
        'currentPrice', current_price,
        'spend', spend,
        'invoiceCount', invoice_count,
        'unit', unit
      )
      ORDER BY spend DESC
    ), '[]'::jsonb) AS arr
    FROM vendor_comparison_rows
  ),
  purchases AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'invoiceId', invoice_id,
        'invoiceNumber', invoice_number,
        'date', invoice_date,
        'vendor', vendor_name,
        'quantity', quantity,
        'unitPrice', unit_price,
        'normalizedUnitCost', normalized_unit_cost,
        'amount', total_price,
        'unit', report_unit,
        'status', status,
        'location', location_name
      )
      ORDER BY invoice_date DESC
    ), '[]'::jsonb) AS arr
    FROM current_rows
  ),
  normalization AS (
    SELECT jsonb_build_object(
      'reportUnit', (SELECT unit FROM summary),
      'packSize', (SELECT pack_size FROM summary),
      'conversionMultiplier', (SELECT conversion_multiplier FROM current_rows LIMIT 1),
      'formula', 'normalized_unit_cost = total_price / (quantity * COALESCE(conversion_multiplier, 1))',
      'comparabilityRule', 'Same internal_product_id and normalized UOM required across periods'
    ) AS obj
  )
  SELECT jsonb_build_object(
    'productId', p_product_id,
    'summary', jsonb_build_object(
      'product', s.product,
      'category', s.category,
      'unit', s.unit,
      'packSize', s.pack_size,
      'currentPrice', s.current_price,
      'previousPrice', s.previous_price,
      'priceChange', CASE WHEN s.current_price IS NULL OR s.previous_price IS NULL THEN NULL
                          ELSE round(s.current_price - s.previous_price, 6) END,
      'percentageChange', CASE
        WHEN s.current_price IS NULL OR s.previous_price IS NULL THEN NULL
        WHEN s.previous_price = 0 AND s.current_price = 0 THEN 0
        WHEN s.previous_price = 0 THEN NULL
        ELSE round(((s.current_price - s.previous_price) / abs(s.previous_price)) * 100, 2)
      END,
      'currentSpend', s.current_spend,
      'estimatedImpact', CASE WHEN s.current_price IS NULL OR s.previous_price IS NULL OR s.current_qty IS NULL OR s.current_qty = 0 THEN NULL ELSE round((s.current_price - s.previous_price) * s.current_qty, 2) END,
      'normalizedPurchasedQuantity', s.current_qty,
      'normalizedQuantityUnit', s.unit,
      'currentWeightedUnitPrice', s.current_price,
      'comparisonWeightedUnitPrice', s.previous_price,
      'unitPriceDifference', CASE WHEN s.current_price IS NULL OR s.previous_price IS NULL THEN NULL ELSE round(s.current_price - s.previous_price, 6) END,
      'mappingConfidence', CASE s.mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE s.mapping_status END,
      'impactEvidenceComplete', (
        s.mapping_status = 'verified'
        AND s.current_price IS NOT NULL
        AND s.previous_price IS NOT NULL
        AND s.current_qty IS NOT NULL
        AND s.current_qty <> 0
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity',
      'invoiceCount', s.invoice_count,
      'vendorCount', s.vendor_count
    ),
    'priceHistory', (SELECT arr FROM price_history),
    'vendorComparison', (SELECT arr FROM vendor_comparison),
    'purchaseHistory', (SELECT arr FROM purchases),
    'normalization', (SELECT obj FROM normalization)
  )
  INTO v_result
  FROM summary s;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_price_movers_drilldown"("p_organization_id" "uuid", "p_product_id" "uuid", "p_product_name" "text", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_vendor_ids" "uuid"[], "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_price_movers_report"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_comparison_date_from" "date" DEFAULT NULL::"date", "p_comparison_date_to" "date" DEFAULT NULL::"date", "p_category_names" "text"[] DEFAULT NULL::"text"[], "p_vendor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_timezone" "text" DEFAULT 'UTC'::"text", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_result jsonb;
  v_outlier_threshold numeric := 50; -- abs % change above this flagged as outlier
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  WITH eligible_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  mapped_lines AS (
    SELECT
      ili.id AS line_id,
      ili.invoice_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.location_id,
      ili.internal_product_id,
      COALESCE(p.name, ili.item_name, 'Unknown product') AS product_name,
      COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') AS category_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(ili.vendor_unit), ''), 'Each')
      ) AS report_unit,
      COALESCE(ili.quantity, 0)::numeric AS quantity,
      COALESCE(ili.unit_price, 0)::numeric AS unit_price,
      COALESCE(ili.total_price, COALESCE(ili.quantity, 0) * COALESCE(ili.unit_price, 0))::numeric AS total_price,
      COALESCE(vim.conversion_multiplier, 1)::numeric AS conversion_multiplier,
      CASE
        WHEN ili.internal_product_id IS NULL THEN 'unmapped'
        WHEN vim.is_verified IS TRUE THEN 'verified'
        WHEN vim.internal_product_id IS NOT NULL THEN 'mapped'
        ELSE 'mapped'
      END AS mapping_status,
      NULLIF(trim(ili.vendor_unit), '') AS vendor_unit,
      NULLIF(trim(vi.pack_size), '') AS pack_size
    FROM eligible_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id AND p.deleted_at IS NULL
    LEFT JOIN LATERAL (
      SELECT m.conversion_multiplier, m.is_verified, m.internal_product_id
      FROM public.vendor_item_mappings m
      WHERE m.internal_product_id = ili.internal_product_id
        AND (ili.vendor_item_id IS NULL OR m.vendor_item_id = ili.vendor_item_id)
      ORDER BY m.is_verified DESC NULLS LAST
      LIMIT 1
    ) vim ON TRUE
    LEFT JOIN public.vendor_items vi ON vi.id = ili.vendor_item_id
    WHERE (
        p_category_names IS NULL OR cardinality(p_category_names) = 0
        OR COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') = ANY (p_category_names)
      )
      AND (p_product_id IS NULL OR ili.internal_product_id = p_product_id)
  ),
  priced AS (
    SELECT
      ml.*,
      (ml.quantity * ml.conversion_multiplier) AS normalized_qty,
      CASE
        WHEN (ml.quantity * ml.conversion_multiplier) = 0 THEN NULL
        ELSE round(ml.total_price / (ml.quantity * ml.conversion_multiplier), 6)
      END AS normalized_unit_cost
    FROM mapped_lines ml
  ),
  current_rows AS (
    SELECT * FROM priced
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM priced
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  current_agg AS (
    SELECT
      internal_product_id,
      product_name,
      category_name,
      report_unit,
      (array_agg(vendor_name ORDER BY total_price DESC))[1] AS primary_vendor,
      (array_agg(vendor_id ORDER BY total_price DESC))[1] AS primary_vendor_id,
      (array_agg(mapping_status ORDER BY CASE mapping_status WHEN 'verified' THEN 0 WHEN 'mapped' THEN 1 ELSE 2 END))[1] AS mapping_status,
      (array_agg(pack_size) FILTER (WHERE pack_size IS NOT NULL))[1] AS pack_size,
      round(sum(total_price)::numeric, 2) AS current_spend,
      round(sum(normalized_qty)::numeric, 4) AS current_qty,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6)
      END AS current_price,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      max(invoice_date) AS last_purchase
    FROM current_rows
    GROUP BY internal_product_id, product_name, category_name, report_unit
  ),
  previous_agg AS (
    SELECT
      internal_product_id,
      report_unit,
      round(sum(total_price)::numeric, 2) AS previous_spend,
      round(sum(normalized_qty)::numeric, 4) AS previous_qty,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6)
      END AS previous_price
    FROM previous_rows
    GROUP BY internal_product_id, report_unit
  ),
  joined AS (
    SELECT
      c.internal_product_id AS product_id,
      c.product_name AS product,
      c.primary_vendor AS vendor,
      c.primary_vendor_id AS vendor_id,
      c.category_name AS category,
      c.report_unit AS unit,
      c.pack_size,
      c.current_price,
      p.previous_price,
      c.current_spend,
      COALESCE(p.previous_spend, 0) AS previous_spend,
      c.current_qty,
      c.invoice_count,
      c.last_purchase,
      c.mapping_status,
      CASE
        WHEN c.internal_product_id IS NULL THEN 'not_comparable'
        WHEN c.current_price IS NULL THEN 'not_comparable'
        WHEN p.previous_price IS NULL THEN 'not_comparable'
        WHEN c.report_unit IS DISTINCT FROM p.report_unit THEN 'not_comparable'
        ELSE 'comparable'
      END AS comparability_status,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
        THEN NULL
        ELSE round(c.current_price - p.previous_price, 6)
      END AS price_change,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
        THEN NULL
        WHEN p.previous_price = 0 AND c.current_price = 0 THEN 0
        WHEN p.previous_price = 0 THEN NULL
        ELSE round(((c.current_price - p.previous_price) / abs(p.previous_price)) * 100, 2)
      END AS percentage_change,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
          OR c.current_qty IS NULL OR c.current_qty = 0
        THEN NULL
        ELSE round((c.current_price - p.previous_price) * c.current_qty, 2)
      END AS estimated_impact
    FROM current_agg c
    LEFT JOIN previous_agg p
      ON p.internal_product_id IS NOT DISTINCT FROM c.internal_product_id
     AND p.report_unit = c.report_unit
  ),
  enriched AS (
    SELECT
      j.*,
      CASE
        WHEN j.comparability_status <> 'comparable' OR j.percentage_change IS NULL THEN 'n/a'
        WHEN abs(j.percentage_change) >= v_outlier_threshold THEN 'outlier'
        ELSE 'normal'
      END AS outlier_status
    FROM joined j
  ),
  comparable AS (
    SELECT * FROM enriched WHERE comparability_status = 'comparable'
  ),
  summary AS (
    SELECT
      (SELECT count(*) FROM comparable WHERE price_change > 0)::int AS products_with_increases,
      (SELECT count(*) FROM comparable WHERE price_change < 0)::int AS products_with_decreases,
      (SELECT round(avg(percentage_change)::numeric, 2) FROM comparable WHERE percentage_change IS NOT NULL) AS average_price_change,
      (SELECT round(coalesce(sum(estimated_impact), 0)::numeric, 2) FROM comparable WHERE estimated_impact > 0) AS estimated_unfavorable_impact,
      (SELECT round(coalesce(sum(estimated_impact), 0)::numeric, 2) FROM comparable WHERE estimated_impact < 0) AS estimated_favorable_impact,
      (SELECT count(*) FROM enriched WHERE comparability_status = 'not_comparable')::int AS non_comparable_count,
      (SELECT count(*) FROM enriched)::int AS total_products,
      (SELECT count(DISTINCT vendor_id) FROM comparable WHERE price_change > 0 AND vendor_id IS NOT NULL)::int AS vendors_driving_increases
  ),
  largest_increase AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'priceChange', price_change,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact,
      'normalizedPurchasedQuantity', current_qty,
      'normalizedQuantityUnit', unit,
      'currentWeightedUnitPrice', current_price,
      'comparisonWeightedUnitPrice', previous_price,
      'unitPriceDifference', price_change,
      'mappingConfidence', CASE mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE mapping_status END,
      'impactEvidenceComplete', (
        comparability_status = 'comparable'
        AND mapping_status = 'verified'
        AND estimated_impact IS NOT NULL
        AND current_qty IS NOT NULL
        AND current_qty <> 0
        AND price_change IS NOT NULL
        AND unit IS NOT NULL
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity'
    ) AS obj
    FROM comparable
    WHERE price_change IS NOT NULL
    ORDER BY price_change DESC NULLS LAST
    LIMIT 1
  ),
  largest_decrease AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'priceChange', price_change,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact,
      'normalizedPurchasedQuantity', current_qty,
      'normalizedQuantityUnit', unit,
      'currentWeightedUnitPrice', current_price,
      'comparisonWeightedUnitPrice', previous_price,
      'unitPriceDifference', price_change,
      'mappingConfidence', CASE mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE mapping_status END,
      'impactEvidenceComplete', (
        comparability_status = 'comparable'
        AND mapping_status = 'verified'
        AND estimated_impact IS NOT NULL
        AND current_qty IS NOT NULL
        AND current_qty <> 0
        AND price_change IS NOT NULL
        AND unit IS NOT NULL
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity'
    ) AS obj
    FROM comparable
    WHERE price_change IS NOT NULL
    ORDER BY price_change ASC NULLS LAST
    LIMIT 1
  ),
  most_volatile AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact,
      'normalizedPurchasedQuantity', current_qty,
      'normalizedQuantityUnit', unit,
      'currentWeightedUnitPrice', current_price,
      'comparisonWeightedUnitPrice', previous_price,
      'unitPriceDifference', price_change,
      'mappingConfidence', CASE mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE mapping_status END,
      'impactEvidenceComplete', (
        comparability_status = 'comparable'
        AND mapping_status = 'verified'
        AND estimated_impact IS NOT NULL
        AND current_qty IS NOT NULL
        AND current_qty <> 0
        AND price_change IS NOT NULL
        AND unit IS NOT NULL
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity'
    ) AS obj
    FROM comparable
    WHERE percentage_change IS NOT NULL
    ORDER BY abs(percentage_change) DESC NULLS LAST
    LIMIT 1
  ),
  ranking AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'product', product,
        'productId', product_id,
        'vendor', vendor,
        'category', category,
        'percentageChange', percentage_change,
        'priceChange', price_change,
        'estimatedImpact', estimated_impact,
        'currentPrice', current_price,
      'normalizedPurchasedQuantity', current_qty,
      'normalizedQuantityUnit', unit,
      'currentWeightedUnitPrice', current_price,
      'comparisonWeightedUnitPrice', previous_price,
      'unitPriceDifference', price_change,
      'mappingConfidence', CASE mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE mapping_status END,
      'impactEvidenceComplete', (
        comparability_status = 'comparable'
        AND mapping_status = 'verified'
        AND estimated_impact IS NOT NULL
        AND current_qty IS NOT NULL
        AND current_qty <> 0
        AND price_change IS NOT NULL
        AND unit IS NOT NULL
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity'
      )
      ORDER BY estimated_impact DESC NULLS LAST
    ) AS arr
    FROM (
      SELECT * FROM comparable
      WHERE estimated_impact IS NOT NULL
      ORDER BY estimated_impact DESC NULLS LAST
      LIMIT 20
    ) top_impact
  ),
  -- Histogram buckets of percentage change
  hist AS (
    SELECT
      width_bucket(percentage_change, -50, 50, 10) AS bucket,
      count(*)::int AS count
    FROM comparable
    WHERE percentage_change IS NOT NULL
      AND percentage_change BETWEEN -50 AND 50
    GROUP BY 1
  ),
  distribution AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', bucket,
        'label', CASE bucket
          WHEN 1 THEN '-50 to -40'
          WHEN 2 THEN '-40 to -30'
          WHEN 3 THEN '-30 to -20'
          WHEN 4 THEN '-20 to -10'
          WHEN 5 THEN '-10 to 0'
          WHEN 6 THEN '0 to 10'
          WHEN 7 THEN '10 to 20'
          WHEN 8 THEN '20 to 30'
          WHEN 9 THEN '30 to 40'
          WHEN 10 THEN '40 to 50'
          ELSE 'other'
        END,
        'count', count
      )
      ORDER BY bucket
    ), '[]'::jsonb) AS arr
    FROM hist
  ),
  scatter AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'productId', product_id,
        'product', product,
        'percentageChange', percentage_change,
        'estimatedImpact', estimated_impact,
        'currentSpend', current_spend,
        'category', category,
      'normalizedPurchasedQuantity', current_qty,
      'normalizedQuantityUnit', unit,
      'currentWeightedUnitPrice', current_price,
      'comparisonWeightedUnitPrice', previous_price,
      'unitPriceDifference', price_change,
      'mappingConfidence', CASE mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE mapping_status END,
      'impactEvidenceComplete', (
        comparability_status = 'comparable'
        AND mapping_status = 'verified'
        AND estimated_impact IS NOT NULL
        AND current_qty IS NOT NULL
        AND current_qty <> 0
        AND price_change IS NOT NULL
        AND unit IS NOT NULL
      ),
      'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity'
      )
    ), '[]'::jsonb) AS arr
    FROM comparable
    WHERE percentage_change IS NOT NULL AND estimated_impact IS NOT NULL
  ),
  category_inflation AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'averagePercentageChange', average_percentage_change,
        'unfavorableImpact', unfavorable_impact,
        'productCount', product_count
      )
      ORDER BY average_percentage_change DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        category,
        round(avg(percentage_change)::numeric, 2) AS average_percentage_change,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact > 0)::numeric, 2) AS unfavorable_impact,
        count(*)::int AS product_count
      FROM comparable
      WHERE percentage_change IS NOT NULL
      GROUP BY category
    ) cat
  ),
  vendor_impact AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'vendor', vendor,
        'vendorId', vendor_id,
        'unfavorableImpact', unfavorable_impact,
        'favorableImpact', favorable_impact,
        'netImpact', net_impact,
        'productsIncreased', products_increased,
        'productCount', product_count
      )
      ORDER BY unfavorable_impact DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        vendor,
        vendor_id,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact > 0)::numeric, 2) AS unfavorable_impact,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact < 0)::numeric, 2) AS favorable_impact,
        round(sum(estimated_impact)::numeric, 2) AS net_impact,
        count(*) FILTER (WHERE price_change > 0)::int AS products_increased,
        count(*)::int AS product_count
      FROM comparable
      WHERE vendor IS NOT NULL AND estimated_impact IS NOT NULL
      GROUP BY vendor, vendor_id
    ) ven
  ),
  -- Trend for top volatile / impact products (daily or weekly points in current period)
  top_trend_products AS (
    SELECT product_id
    FROM comparable
    WHERE product_id IS NOT NULL AND percentage_change IS NOT NULL
    ORDER BY abs(COALESCE(estimated_impact, 0)) DESC
    LIMIT 5
  ),
  trend AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', t.bucket,
        'bucketStart', t.bucket_start,
        'product', t.product_name,
        'productId', t.internal_product_id,
        'unitCost', t.unit_cost
      )
      ORDER BY t.bucket_start, t.product_name
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        cr.invoice_date::text AS bucket,
        cr.invoice_date AS bucket_start,
        cr.internal_product_id,
        cr.product_name,
        round(avg(cr.normalized_unit_cost)::numeric, 6) AS unit_cost
      FROM current_rows cr
      WHERE cr.internal_product_id IN (SELECT product_id FROM top_trend_products)
        AND cr.normalized_unit_cost IS NOT NULL
      GROUP BY cr.invoice_date, cr.internal_product_id, cr.product_name
    ) t
  ),
  filter_options AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(DISTINCT category_name ORDER BY category_name)
        FROM priced WHERE category_name IS NOT NULL
      ), '[]'::jsonb) AS categories,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', vendor_id, 'name', vendor_name) ORDER BY vendor_name)
        FROM (
          SELECT DISTINCT vendor_id, vendor_name FROM priced WHERE vendor_id IS NOT NULL
        ) v
      ), '[]'::jsonb) AS vendors
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'productsWithIncreases', s.products_with_increases,
      'productsWithDecreases', s.products_with_decreases,
      'averagePriceChange', s.average_price_change,
      'estimatedUnfavorableImpact', s.estimated_unfavorable_impact,
      'estimatedFavorableImpact', s.estimated_favorable_impact,
      'largestPriceIncrease', (SELECT obj FROM largest_increase),
      'largestPriceDecrease', (SELECT obj FROM largest_decrease),
      'mostVolatileProduct', (SELECT obj FROM most_volatile),
      'vendorsDrivingIncreases', s.vendors_driving_increases,
      'nonComparableProducts', s.non_comparable_count,
      'totalProducts', s.total_products
    ),
    'ranking', COALESCE((SELECT arr FROM ranking), '[]'::jsonb),
    'trend', COALESCE((SELECT arr FROM trend), '[]'::jsonb),
    'distribution', COALESCE((SELECT arr FROM distribution), '[]'::jsonb),
    'scatter', COALESCE((SELECT arr FROM scatter), '[]'::jsonb),
    'categoryInflation', COALESCE((SELECT arr FROM category_inflation), '[]'::jsonb),
    'vendorImpact', COALESCE((SELECT arr FROM vendor_impact), '[]'::jsonb),
    'tableRows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'productId', e.product_id,
          'product', e.product,
          'vendor', e.vendor,
          'vendorId', e.vendor_id,
          'category', e.category,
          'unit', e.unit,
          'packSize', e.pack_size,
          'currentPrice', e.current_price,
          'previousPrice', e.previous_price,
          'priceChange', e.price_change,
          'percentageChange', e.percentage_change,
          'currentSpend', e.current_spend,
          'estimatedImpact', e.estimated_impact,
          'normalizedPurchasedQuantity', e.current_qty,
          'normalizedQuantityUnit', e.unit,
          'currentWeightedUnitPrice', e.current_price,
          'comparisonWeightedUnitPrice', e.previous_price,
          'unitPriceDifference', e.price_change,
          'mappingConfidence', CASE e.mapping_status WHEN 'verified' THEN 'verified' WHEN 'mapped' THEN 'mapped_unverified' ELSE e.mapping_status END,
          'impactEvidenceComplete', (
            e.comparability_status = 'comparable'
            AND e.mapping_status = 'verified'
            AND e.estimated_impact IS NOT NULL
            AND e.current_qty IS NOT NULL
            AND e.current_qty <> 0
            AND e.price_change IS NOT NULL
            AND e.unit IS NOT NULL
          ),
          'impactFormula', 'unitPriceDifference * normalizedPurchasedQuantity',
          'invoiceCount', e.invoice_count,
          'lastPurchase', e.last_purchase,
          'mappingStatus', e.mapping_status,
          'comparabilityStatus', e.comparability_status,
          'outlierStatus', e.outlier_status
        )
        ORDER BY COALESCE(e.estimated_impact, 0) DESC
      )
      FROM enriched e
    ), '[]'::jsonb),
    'insights', COALESCE((
      SELECT jsonb_agg(ins ORDER BY (ins->>'impact')::numeric DESC)
      FROM (
        SELECT jsonb_build_object(
          'id', 'unfavorable-impact',
          'impact', abs(s.estimated_unfavorable_impact),
          'text', format(
            'Estimated unfavorable purchasing impact from price increases is $%s.',
            to_char(s.estimated_unfavorable_impact, 'FM999,999,990')
          )
        ) AS ins
        WHERE s.estimated_unfavorable_impact > 0
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'avg-change',
          'impact', abs(COALESCE(s.average_price_change, 0)) * 100,
          'text', format(
            'Average comparable price change is %s%% across %s products.',
            to_char(COALESCE(s.average_price_change, 0), 'FM990.0'),
            s.products_with_increases + s.products_with_decreases
          )
        )
        WHERE s.average_price_change IS NOT NULL
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'non-comparable',
          'impact', s.non_comparable_count,
          'text', format(
            '%s products are not comparable due to missing product mapping or incompatible units.',
            s.non_comparable_count
          )
        )
        WHERE s.non_comparable_count > 0
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'largest-inc',
          'impact', abs(COALESCE((SELECT (obj->>'estimatedImpact')::numeric FROM largest_increase), 0)),
          'text', format(
            '%s had the largest price increase (%s%%).',
            (SELECT obj->>'product' FROM largest_increase),
            (SELECT obj->>'percentageChange' FROM largest_increase)
          )
        )
        WHERE EXISTS (SELECT 1 FROM largest_increase WHERE obj IS NOT NULL)
      ) insight_rows
    ), '[]'::jsonb),
    'metadata', jsonb_build_object(
      'currency', 'USD',
      'timezone', v_tz,
      'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'),
      'priceDefinition', 'Normalized weighted-average unit cost = line total_price / (quantity * COALESCE(conversion_multiplier, 1)). Estimated impact evidence is unitPriceDifference * normalizedPurchasedQuantity. Complete evidence requires a verified unit mapping, non-zero normalized quantity, same internal product, and same normalized UOM.',
      'outlierThresholdPercent', v_outlier_threshold,
      'filterOptions', jsonb_build_object(
        'categories', (SELECT categories FROM filter_options),
        'vendors', (SELECT vendors FROM filter_options)
      )
    )
  )
  INTO v_result
  FROM summary s;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."get_price_movers_report"("p_organization_id" "uuid", "p_location_ids" "uuid"[], "p_date_from" "date", "p_date_to" "date", "p_comparison_date_from" "date", "p_comparison_date_to" "date", "p_category_names" "text"[], "p_vendor_ids" "uuid"[], "p_timezone" "text", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_approval_setting"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT public.is_platform_admin() AND p_organization_id != public.get_auth_org() THEN false
    ELSE COALESCE(
      (SELECT (settings->>'require_location_manager_approval')::boolean
       FROM public.operational_settings
       WHERE organization_id = p_organization_id
         AND scope = 'organization'
         AND brand_id IS NULL
         AND location_id IS NULL
         AND category = 'product_approval'),
      false
    )
  END;
$$;


ALTER FUNCTION "public"."get_product_approval_setting"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_catalog"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_sort_by" "text" DEFAULT 'name'::"text", "p_page" integer DEFAULT 0, "p_page_size" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "product_id" "text", "name" "text", "description" "text", "category" "text", "accounting_category" "text", "category_confidence" numeric, "category_source" "text", "category_review_status" "text", "suggested_category" "text", "suggested_category_type" "text", "suggested_accounting_category" "text", "category_reason" "text", "is_inventoried" boolean, "is_tax_exempt" boolean, "report_by_unit" "text", "base_unit" "text", "latest_price" numeric, "location_specific" boolean, "organization_id" "uuid", "brand_id" "uuid", "location_id" "uuid", "created_at" timestamp with time zone, "item_count" bigint, "vendor_item_count" bigint, "inventory_item_id" "uuid", "vendor_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_page integer := GREATEST(COALESCE(p_page, 0), 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 100);
  v_sort_by text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      -- Inclusive hierarchy filter: org-level + matching brand-shared + exact location.
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
      )
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p_search IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR COALESCE(p.product_id, '') ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    p.category_confidence,
    p.category_source,
    p.category_review_status,
    p.suggested_category,
    p.suggested_category_type,
    p.suggested_accounting_category,
    p.category_reason,
    p.is_inventoried,
    p.is_tax_exempt,
    p.report_by_unit,
    p.base_unit,
    p.latest_price,
    p.location_specific,
    p.organization_id,
    p.brand_id,
    p.location_id,
    p.created_at,
    COALESCE(vendor_info.vendor_item_count, 0) AS item_count,
    COALESCE(vendor_info.vendor_item_count, 0) AS vendor_item_count,
    inv.id AS inventory_item_id,
    vendor_info.vendor_name
  FROM product_scope p
  LEFT JOIN LATERAL (
    SELECT
      count(DISTINCT vim.vendor_item_id)::bigint AS vendor_item_count,
      string_agg(DISTINCT v.name, ', ' ORDER BY v.name) AS vendor_name
    FROM public.vendor_item_mappings vim
    JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    WHERE vim.internal_product_id = p.id
      AND vim.organization_id = p.organization_id
      AND vi.organization_id = p.organization_id
  ) vendor_info ON true
  LEFT JOIN LATERAL (
    SELECT i.id
    FROM public.inventory i
    WHERE i.organization_id = p.organization_id
      AND i.deleted_at IS NULL
      AND (
        i.internal_product_id = p.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = p.product_id)
      )
      AND (p.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p.location_id)
    ORDER BY
      CASE WHEN i.internal_product_id = p.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1
  ) inv ON true
  ORDER BY
    CASE WHEN v_sort_by = 'name' THEN p.name END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-name' THEN p.name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'category' THEN p.category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-category' THEN p.category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'accounting_category' THEN p.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-accounting_category' THEN p.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'is_inventoried' THEN p.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-is_inventoried' THEN p.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'latest_price' THEN p.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-latest_price' THEN p.latest_price END DESC NULLS LAST,
    p.name ASC NULLS LAST,
    p.created_at DESC NULLS LAST
  LIMIT v_page_size
  OFFSET v_page * v_page_size;
END;
$$;


ALTER FUNCTION "public"."get_product_catalog"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_search" "text", "p_sort_by" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_dashboard_summary"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("total_products" bigint, "inventoried_count" bigint, "tax_exempt_count" bigint, "category_count" bigint, "missing_product_id_count" bigint, "uncategorized_count" bigint, "unmapped_vendor_item_count" bigint, "price_variance_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH scoped AS (
    SELECT *
    FROM public.products p
    WHERE p.organization_id = p_organization_id
      AND (public.is_platform_admin() OR p_organization_id = public.get_auth_org())
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
  )
  SELECT
    COUNT(*)::bigint,
    COUNT(*) FILTER (WHERE is_inventoried IS TRUE)::bigint,
    COUNT(*) FILTER (WHERE is_tax_exempt IS TRUE)::bigint,
    COUNT(DISTINCT NULLIF(accounting_category, ''))::bigint,
    COUNT(*) FILTER (WHERE COALESCE(product_id, '') = '')::bigint,
    COUNT(*) FILTER (WHERE COALESCE(category, '') = '' OR category = 'Uncategorized')::bigint,
    COUNT(*) FILTER (
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.vendor_item_mappings vim
        WHERE vim.internal_product_id = scoped.id
          AND vim.organization_id = scoped.organization_id
      )
    )::bigint,
    0::bigint
  FROM scoped;
$$;


ALTER FUNCTION "public"."get_product_dashboard_summary"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_purchase_report"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_category_type" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS TABLE("restaurant" "text", "product_id" "uuid", "restops_product_id" "text", "product_name" "text", "category_type" "text", "category" "text", "report_by" "text", "invoice_count" bigint, "line_count" bigint, "purchased_units" numeric, "purchased_amount" numeric, "latest_cost" numeric, "avg_cost" numeric, "last_purchased_at" "date")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH approved_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (i.status = 'approved' OR i.ap_status = 'approved')
      AND (p_brand_id IS NULL OR i.brand_id IS NOT DISTINCT FROM p_brand_id OR i.brand_id IS NULL)
      AND (p_location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p_location_id OR i.location_id IS NULL)
      AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
  ),
  normalized_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      ili.id AS line_id,
      ili.item_name,
      ili.quantity,
      ili.unit_price,
      ili.total_price,
      ili.vendor_unit,
      ili.pack_size,
      ili.internal_product_id,
      ili.inventory_item_id::text AS inventory_item_id
    FROM approved_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    WHERE public.tenant_scope_visible(ili.organization_id, i.brand_id, i.location_id, NULL)
  ),
  json_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      gen_random_uuid() AS line_id,
      trim(COALESCE(
        NULLIF(item.value->>'description', ''),
        NULLIF(item.value->>'item_name', ''),
        NULLIF(item.value->>'name', ''),
        'Unknown Item'
      )) AS item_name,
      amounts.quantity,
      amounts.unit_price,
      COALESCE(amounts.extended_price, amounts.total_price, amounts.quantity * amounts.unit_price) AS total_price,
      COALESCE(NULLIF(item.value->>'vendor_unit', ''), NULLIF(item.value->>'unit', '')) AS vendor_unit,
      COALESCE(
        NULLIF(item.value->>'pack_size', ''),
        NULLIF(item.value->>'PackSize', ''),
        NULLIF(item.value->>'pack', ''),
        NULLIF(item.value->>'size', '')
      ) AS pack_size,
      CASE
        WHEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id')::uuid
        ELSE NULL
      END AS internal_product_id,
      NULLIF(item.value->>'inventory_item_id', '') AS inventory_item_id
    FROM approved_invoices i
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.line_items, '[]'::jsonb)) WITH ORDINALITY AS item(value, ordinal)
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'quantity', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 1) AS quantity,
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'unit_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 0) AS unit_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'extended_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS extended_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'total_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS total_price
    ) amounts
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.invoice_line_items ili
        WHERE ili.invoice_id = i.id
      )
      AND NULLIF(trim(COALESCE(
        item.value->>'description',
        item.value->>'item_name',
        item.value->>'name',
        ''
      )), '') IS NOT NULL
  ),
  approved_lines AS (
    SELECT * FROM normalized_lines
    UNION ALL
    SELECT * FROM json_lines
  ),
  enriched AS (
    SELECT
      COALESCE(l.name, 'Current Store') AS restaurant,
      p.id AS product_id,
      p.product_id AS restops_product_id,
      COALESCE(p.name, al.item_name) AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, al.item_name)) AS category_type,
      public.derive_product_category(p.category, COALESCE(p.name, al.item_name)) AS category,
      public.best_product_report_unit(p.report_by_unit, al.vendor_unit, al.pack_size) AS report_by,
      al.invoice_id,
      al.line_id,
      COALESCE(al.quantity, 0) AS quantity,
      COALESCE(al.total_price, COALESCE(al.quantity, 0) * COALESCE(al.unit_price, 0)) AS total_price,
      COALESCE(al.unit_price, 0) AS unit_price,
      al.invoice_date
    FROM approved_lines al
    LEFT JOIN public.products p
      ON p.id = al.internal_product_id
      OR (al.inventory_item_id IS NOT NULL AND p.product_id = al.inventory_item_id)
    LEFT JOIN public.locations l ON l.id = al.location_id
    WHERE (p_search IS NULL OR COALESCE(p.name, al.item_name, '') ILIKE '%' || p_search || '%')
  )
  SELECT
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by,
    count(DISTINCT e.invoice_id) AS invoice_count,
    count(e.line_id) AS line_count,
    round(sum(e.quantity), 4) AS purchased_units,
    round(sum(e.total_price), 2) AS purchased_amount,
    (array_agg(e.unit_price ORDER BY e.invoice_date DESC NULLS LAST, e.line_id DESC))[1] AS latest_cost,
    round(sum(e.total_price) / NULLIF(sum(e.quantity), 0), 4) AS avg_cost,
    max(e.invoice_date) AS last_purchased_at
  FROM enriched e
  WHERE (p_category_type IS NULL OR p_category_type = 'all' OR e.category_type = p_category_type)
    AND (p_category IS NULL OR p_category = 'all' OR e.category = p_category)
  GROUP BY
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by
  ORDER BY e.product_name;
END;
$_$;


ALTER FUNCTION "public"."get_product_purchase_report"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_category_type" "text", "p_category" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_verification_queue"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS TABLE("internal_product_id" "uuid", "product_id" "text", "name" "text", "description" "text", "category" "text", "accounting_category" "text", "suggested_category" "text", "suggested_accounting_category" "text", "category_confidence" numeric, "category_review_status" "text", "latest_price" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    NULL::text,
    NULL::text,
    NULL::numeric,
    'verified'::text,
    p.latest_price
  FROM public.products p
  WHERE p.organization_id = p_organization_id
    AND (public.is_platform_admin() OR p_organization_id = public.get_auth_org())
    AND p.deleted_at IS NULL
    AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
    AND (
      COALESCE(NULLIF(p_search, ''), NULL) IS NULL
      OR p.name ILIKE '%' || p_search || '%'
      OR p.description ILIKE '%' || p_search || '%'
      OR p.product_id ILIKE '%' || p_search || '%'
    )
  ORDER BY p.updated_at DESC
  LIMIT 100;
$$;


ALTER FUNCTION "public"."get_product_verification_queue"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_status" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recipe_category_counts"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("category_id" "uuid", "slug" "text", "name" "text", "display_order" integer, "recipe_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() THEN
    RAISE EXCEPTION 'Not authorized to read recipe category counts';
  END IF;

  PERFORM public.ensure_default_recipe_categories(v_org);

  -- Count menu-style recipes only. Avoid recipe_types / recipe_type_id so this
  -- works on QA clones that have not yet received later recipe-type migrations.
  RETURN QUERY
  SELECT
    rc.id AS category_id,
    rc.slug,
    rc.name,
    rc.display_order,
    COALESCE(cnt.recipe_count, 0)::bigint AS recipe_count
  FROM public.recipe_categories rc
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::bigint AS recipe_count
    FROM public.recipes r
    WHERE r.organization_id = v_org
      AND r.deleted_at IS NULL
      AND COALESCE(r.is_batch, false) = false
      AND COALESCE(r.category, '') IS DISTINCT FROM 'prepared_item'
      AND COALESCE(r.category, '') IS DISTINCT FROM 'beverage'
      AND lower(COALESCE(r.category, '')) = lower(rc.slug)
  ) cnt ON true
  WHERE rc.organization_id = v_org
    AND rc.deleted_at IS NULL
    AND rc.is_active
  ORDER BY rc.display_order ASC, rc.name ASC;
END;
$$;


ALTER FUNCTION "public"."get_recipe_category_counts"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_role_dashboard_summary"("p_scope" "text", "p_org_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_period_start" "date" DEFAULT ("date_trunc"('month'::"text", "now"()))::"date", "p_period_end" "date" DEFAULT ((("date_trunc"('month'::"text", "now"()) + '1 mon'::interval) - '1 day'::interval))::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today DATE := current_date;
  v_week_start DATE := date_trunc('week', current_date)::date;
  v_last_week_start DATE := (date_trunc('week', current_date) - interval '7 days')::date;
  v_last_year_week_start DATE := (date_trunc('week', current_date) - interval '1 year')::date;
  v_payload JSONB;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization id is required.';
  END IF;

  IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
  END IF;

  IF p_scope NOT IN ('org', 'brand', 'location', 'staff') THEN
    RAISE EXCEPTION 'Invalid dashboard scope: %', p_scope;
  END IF;

  WITH scoped_locations AS (
    SELECT l.id
    FROM public.locations l
    WHERE l.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND l.brand_id = p_brand_id)
        OR (p_scope IN ('location', 'staff') AND l.id = p_location_id)
      )
  ),
  scoped_sales_mv AS (
    SELECT mv.*
    FROM public.mv_daily_sales_summary mv
    WHERE mv.organization_id = p_org_id
      AND mv.date BETWEEN (v_last_year_week_start - interval '7 days')::date AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (mv.brand_id = p_brand_id OR mv.brand_id = '00000000-0000-0000-0000-000000000000'::uuid))
        OR (p_scope IN ('location', 'staff') AND (mv.location_id = p_location_id OR mv.location_id = '00000000-0000-0000-0000-000000000000'::uuid))
      )
  ),
  -- REAL-TIME INVOICE SPEND (Replaces Materialized View)
  scoped_invoice_spend AS (
    SELECT 
      COUNT(*) as invoice_count,
      COALESCE(SUM(total_amount), 0) as total_spend,
      COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'unpaid' OR status = 'approved'), 0) as unpaid_amount,
      COUNT(*) FILTER (WHERE status = 'pending_review') as pending_count
    FROM public.invoices i
    WHERE i.organization_id = p_org_id
      AND COALESCE(i.invoice_date, (i.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.brand_id = p_brand_id OR (i.brand_id IS NULL AND i.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  -- REAL-TIME INVENTORY (Replaces Materialized View)
  scoped_inventory AS (
    SELECT 
      COUNT(*) as total_items,
      COALESCE(SUM(current_value), 0) as total_valuation,
      COUNT(*) FILTER (WHERE current_quantity <= COALESCE(reorder_point, 5)) as low_stock_items
    FROM public.inventory i
    WHERE i.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.location_id IN (SELECT id FROM scoped_locations)))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  period_invoices AS (
    SELECT i.id
    FROM public.invoices i
    WHERE i.organization_id = p_org_id
      AND COALESCE(i.invoice_date, (i.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.brand_id = p_brand_id OR (i.brand_id IS NULL AND i.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  -- FAST CATEGORY SPEND (No JSON array elements!)
  category_spend AS (
    SELECT 
      COALESCE(p.accounting_category, 'Other') AS category, 
      SUM(ili.total_price) AS amount
    FROM public.invoice_line_items ili
    JOIN period_invoices pi ON pi.id = ili.invoice_id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id
    GROUP BY COALESCE(p.accounting_category, 'Other')
    HAVING SUM(ili.total_price) > 0
  ),
  scoped_products AS (
    SELECT COUNT(*) as product_count
    FROM public.products p
    WHERE p.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_orders AS (
    SELECT COUNT(*) as open_orders_count
    FROM public.auto_orders ao
    WHERE ao.organization_id = p_org_id
      AND COALESCE(status, 'pending') NOT IN ('completed', 'received', 'cancelled')
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (ao.brand_id = p_brand_id OR (ao.brand_id IS NULL AND ao.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (ao.location_id = p_location_id OR ao.location_id IS NULL))
      )
  ),
  scoped_payments AS (
    SELECT COUNT(*) as payments_count
    FROM public.payments p
    WHERE p.organization_id = p_org_id
      AND COALESCE(p.payment_date, (p.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_wastage AS (
    SELECT w.*
    FROM public.wastage_logs w
    WHERE w.organization_id = p_org_id
      AND COALESCE(w.created_at::date, v_today) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (w.brand_id = p_brand_id OR (w.brand_id IS NULL AND w.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (w.location_id = p_location_id OR w.location_id IS NULL))
      )
  ),
  scoped_shifts AS (
    SELECT es.*
    FROM public.employee_shifts es
    WHERE es.organization_id = p_org_id
      AND COALESCE(es.shift_start::date, es.start_time::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND es.location_id IN (SELECT id FROM scoped_locations))
        OR (p_scope IN ('location', 'staff') AND es.location_id = p_location_id)
      )
  ),
  budget_targets AS (
    SELECT bt.*
    FROM public.budget_targets bt
    WHERE bt.organization_id = p_org_id
      AND bt.period_start = p_period_start
      AND bt.period_end = p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (bt.brand_id = p_brand_id OR bt.brand_id IS NULL))
        OR (p_scope IN ('location', 'staff') AND (bt.location_id = p_location_id OR bt.location_id IS NULL))
      )
  ),
  kpis AS (
    SELECT
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date = v_today), 0) AS sales_today,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_week_start AND (v_week_start + 6)), 0) AS sales_week_to_date,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_week_start AND (v_last_week_start + 6)), 0) AS sales_last_week,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_year_week_start AND (v_last_year_week_start + 6)), 0) AS sales_last_year,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN p_period_start AND p_period_end), 0) AS sales_period
    FROM scoped_sales_mv ps
  ),
  costs AS (
    SELECT
      (SELECT total_spend FROM scoped_invoice_spend) AS invoice_spend,
      COALESCE((SELECT SUM(labor_cost) FROM scoped_shifts), 0) AS labor_cost,
      COALESCE((SELECT SUM(value) FROM scoped_wastage), 0) AS wastage_cost,
      (SELECT unpaid_amount FROM scoped_invoice_spend) AS unpaid_amount,
      (SELECT pending_count FROM scoped_invoice_spend) AS pending_invoices,
      (SELECT low_stock_items FROM scoped_inventory) AS low_stock_items,
      (SELECT open_orders_count FROM scoped_orders) AS open_orders,
      (SELECT invoice_count FROM scoped_invoice_spend) AS total_invoices,
      (SELECT payments_count FROM scoped_payments) AS total_payments,
      (SELECT product_count FROM scoped_products) AS total_products,
      (SELECT total_items FROM scoped_inventory) AS total_inventory_items
  ),
  sales_rows AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', to_char(day_date, 'Dy'),
        'actual', actual,
        'lastWeek', last_week,
        'lastYear', last_year,
        'vsLastWeek', CASE WHEN last_week = 0 THEN 0 ELSE ((actual - last_week) / last_week) * 100 END,
        'vsLastYear', CASE WHEN last_year = 0 THEN 0 ELSE ((actual - last_year) / last_year) * 100 END
      )
      ORDER BY day_date
    ) AS rows
    FROM (
      SELECT
        d::date AS day_date,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = d::date), 0) AS actual,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '7 days')::date), 0) AS last_week,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '1 year')::date), 0) AS last_year
      FROM generate_series(v_week_start, v_week_start + 6, interval '1 day') AS d
    ) s
  ),
  spend_payload AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('name', category, 'value', amount) ORDER BY amount DESC), '[]'::jsonb) AS items
    FROM category_spend
  ),
  budget_payload AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'actual', actual,
        'target', target,
        'remaining', target - actual,
        'pacing', CASE WHEN target = 0 THEN 0 ELSE ((actual - target) / target) * 100 END,
        'isGood', CASE WHEN category = 'Sales' THEN actual >= target ELSE actual <= target END
      )
      ORDER BY sort_order, category
    ), '[]'::jsonb) AS items
    FROM (
      SELECT 1 AS sort_order, 'Sales'::text AS category, (SELECT sales_period FROM kpis) AS actual, COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Sales' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 1.05, 0), 0) AS target
      UNION ALL
      SELECT 2, 'COGS', (SELECT invoice_spend FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'COGS' LIMIT 1), NULLIF((SELECT invoice_spend FROM costs) * 0.95, 0), 0)
      UNION ALL
      SELECT 3, 'Labor', (SELECT labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Labor' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.28, 0), 0)
      UNION ALL
      SELECT 4, 'Prime Cost', (SELECT invoice_spend + labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Prime Cost' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.6, 0), 0)
    ) b
  ),
  alerts_payload AS (
    SELECT jsonb_agg(alert_obj) AS items
    FROM (
      SELECT jsonb_build_object('tone', 'red', 'title', low_stock_items || ' low stock items', 'body', 'Review reorder points and replenishment orders.', 'href', 'Inventory') AS alert_obj
      FROM costs WHERE low_stock_items > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'orange', 'title', pending_invoices || ' invoices pending', 'body', 'Clear pending review so AP and inventory stay current.', 'href', 'Invoices')
      FROM costs WHERE pending_invoices > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'blue', 'title', 'POS sales not flowing yet', 'body', 'Connect or map POS data to unlock daily sales benchmarking.', 'href', 'RestaurantSetup?tab=pos')
      FROM kpis WHERE sales_period = 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'red', 'title', 'Labor above target', 'body', 'Labor is above the 28% operating target for this period.', 'href', 'Labor')
      FROM kpis, costs WHERE sales_period > 0 AND (labor_cost / sales_period) > 0.28
    ) a
  )
  SELECT jsonb_build_object(
    'scope', p_scope,
    'period', jsonb_build_object('start', p_period_start, 'end', p_period_end),
    'kpis', jsonb_build_object(
      'salesToday', k.sales_today,
      'salesWeekToDate', k.sales_week_to_date,
      'salesLastWeek', k.sales_last_week,
      'salesLastYear', k.sales_last_year,
      'salesPeriod', k.sales_period,
      'salesVsLastWeek', CASE WHEN k.sales_last_week = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_week) / k.sales_last_week) * 100 END,
      'salesVsLastYear', CASE WHEN k.sales_last_year = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_year) / k.sales_last_year) * 100 END,
      'invoiceSpend', c.invoice_spend,
      'laborCost', c.labor_cost,
      'cogsPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END,
      'laborPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END,
      'primeCostPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END,
      'unpaidAmount', c.unpaid_amount,
      'pendingInvoices', c.pending_invoices,
      'lowStockItems', c.low_stock_items,
      'openOrders', c.open_orders,
      'wastageCost', c.wastage_cost
    ),
    'salesPerformance', COALESCE(sr.rows, '[]'::jsonb),
    'budgetPacing', bp.items,
    'spendByCategory', sp.items,
    'workflows', jsonb_build_object(
      'invoices', c.total_invoices,
      'payments', c.total_payments,
      'openOrders', c.open_orders,
      'lowStock', c.low_stock_items,
      'products', c.total_products,
      'inventoryItems', c.total_inventory_items,
      'wasteCost', c.wastage_cost
    ),
    'alerts', COALESCE(ap.items, '[]'::jsonb),
    'benchmarks', jsonb_build_array(
      jsonb_build_object('name', 'Sales', 'actual', k.sales_week_to_date, 'benchmark', COALESCE(NULLIF(k.sales_last_week, 0), k.sales_week_to_date)),
      jsonb_build_object('name', 'COGS', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END, 'benchmark', 32),
      jsonb_build_object('name', 'Labor', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END, 'benchmark', 28),
      jsonb_build_object('name', 'Prime', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END, 'benchmark', 60)
    )
  )
  INTO v_payload
  FROM kpis k
  CROSS JOIN costs c
  CROSS JOIN sales_rows sr
  CROSS JOIN spend_payload sp
  CROSS JOIN budget_payload bp
  CROSS JOIN alerts_payload ap;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."get_role_dashboard_summary"("p_scope" "text", "p_org_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_period_start" "date", "p_period_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_enabled_modules"("p_tenant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(
    public.normalize_invited_module_keys(metadata->'enabled_modules'),
    public.normalize_invited_module_keys(metadata->'invite_modules')
  )
  INTO v_modules
  FROM public.tenants
  WHERE id = p_tenant_id;

  RETURN v_modules;
END;
$$;


ALTER FUNCTION "public"."get_tenant_enabled_modules"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_three_way_match_status"("p_purchase_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po record;
  v_invoice record;
  v_po_total numeric := 0;
  v_inv_total numeric := 0;
  v_rec_qty numeric := 0;
  v_po_qty numeric := 0;
  v_variance_amount numeric := 0;
  v_variance_percent numeric := 0;
  v_status text := 'matched';
BEGIN
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'PO not found');
  END IF;

  v_po_total := v_po.total_amount;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE purchase_order_id = p_purchase_order_id
   ORDER BY created_at DESC
   LIMIT 1;

  IF FOUND THEN
    v_inv_total := v_invoice.total_amount;
  END IF;

  SELECT COALESCE(SUM(quantity), 0)
    INTO v_po_qty
    FROM public.purchase_order_items
   WHERE purchase_order_id = p_purchase_order_id;

  SELECT COALESCE(SUM(ri.quantity_received), 0)
    INTO v_rec_qty
    FROM public.receivings r
    JOIN public.receiving_items ri ON ri.receiving_id = r.id
   WHERE r.purchase_order_id = p_purchase_order_id;

  IF v_inv_total > 0 AND v_po_total > 0 THEN
    v_variance_amount := ABS(v_inv_total - v_po_total);
    v_variance_percent := (v_variance_amount / v_po_total) * 100;
  END IF;

  IF v_rec_qty < v_po_qty THEN
    v_status := 'quantity_variance';
  END IF;

  IF v_variance_percent > 5 OR v_variance_amount > 50 THEN
    v_status := 'price_variance';
  END IF;

  IF v_rec_qty < v_po_qty AND (v_variance_percent > 5 OR v_variance_amount > 50) THEN
    v_status := 'critical_variance';
  END IF;

  RETURN jsonb_build_object(
    'po_total', v_po_total,
    'invoice_total', v_inv_total,
    'po_quantity', v_po_qty,
    'received_quantity', v_rec_qty,
    'variance_amount', v_variance_amount,
    'variance_percent', v_variance_percent,
    'match_status', v_status
  );
END;
$$;


ALTER FUNCTION "public"."get_three_way_match_status"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trusted_global_vendor_item_suggestions"() RETURNS TABLE("id" "uuid", "item_name" "text", "mapping_count" integer, "most_common_category" "text", "confidence_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    gvi.id,
    gvi.item_name,
    gvi.mapping_count,
    public.normalize_global_vendor_category(gvi.most_common_category) AS most_common_category,
    gvi.confidence_score
  FROM public.global_vendor_items gvi
  WHERE gvi.mapping_count >= 50
    AND gvi.confidence_score >= 90
    AND public.normalize_global_vendor_category(gvi.most_common_category) IS NOT NULL
  ORDER BY gvi.mapping_count DESC
  LIMIT 500;
$$;


ALTER FUNCTION "public"."get_trusted_global_vendor_item_suggestions"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_trusted_global_vendor_item_suggestions"() IS 'Returns only high-confidence, high-count, COGS-category global vendor item suggestions. Tenant clients must not read raw global mappings for auto-apply decisions.';



CREATE OR REPLACE FUNCTION "public"."get_vendor_banking_for_audit"("p_banking_row_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
  v_vendor_id uuid;
BEGIN
  -- Ponytail: service-role/audit/dispute path ONLY, never user-facing.
  SELECT banking_secret_id, vendor_id
    INTO v_secret_id, v_vendor_id
  FROM public.vendor_banking_details
  WHERE id = p_banking_row_id
    AND deleted_at IS NULL;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'Vendor banking secret for row % not found', p_banking_row_id;
  END IF;

  SELECT decrypted_secret
    INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type, metadata)
  VALUES (
    v_vendor_id,
    'banking_secret_decrypted',
    auth.uid(),
    'system',
    jsonb_build_object('banking_row_id', p_banking_row_id, 'secret_id', v_secret_id)
  );

  RETURN v_secret::jsonb;
END;
$$;


ALTER FUNCTION "public"."get_vendor_banking_for_audit"("p_banking_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vendor_payment_account"("p_vendor_id" "uuid") RETURNS TABLE("id" "uuid", "banking_secret_id" "uuid", "account_last4" "text", "is_default" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT vbd.id,
         vbd.banking_secret_id,
         vbd.account_last4,
         vbd.is_default
  FROM public.vendor_banking_details vbd
  WHERE vbd.vendor_id = p_vendor_id
    AND vbd.is_active = true
    AND vbd.verification_state = 'verified'
    AND vbd.callback_status = 'confirmed'
    AND vbd.banking_secret_id IS NOT NULL
    AND vbd.deleted_at IS NULL
  ORDER BY vbd.is_default DESC, vbd.created_at ASC, vbd.id ASC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_vendor_payment_account"("p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vendor_provider_link"("p_vendor_id" "uuid", "p_provider" "text") RETURNS TABLE("id" "uuid", "vendor_id" "uuid", "organization_id" "uuid", "brand_id" "uuid", "location_id" "uuid", "provider" "text", "provider_customer_ref" "text", "provider_funding_ref" "text", "provider_status" "text", "is_active" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Ponytail: provider-links hold vendor/destination keys only. Tenant/source
  -- funding refs stay on payment_accounts. Checkbook creates a row here only
  -- if a future adapter registers a reusable vendor token to store.
  SELECT vpl.id,
         vpl.vendor_id,
         vpl.organization_id,
         vpl.brand_id,
         vpl.location_id,
         vpl.provider,
         vpl.provider_customer_ref,
         vpl.provider_funding_ref,
         vpl.provider_status,
         vpl.is_active
  FROM public.vendor_payment_provider_links vpl
  WHERE vpl.vendor_id = p_vendor_id
    AND vpl.provider = lower(btrim(p_provider))
    AND vpl.is_active = true
    AND vpl.deleted_at IS NULL
  ORDER BY vpl.updated_at DESC, vpl.created_at DESC, vpl.id DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_vendor_provider_link"("p_vendor_id" "uuid", "p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vendor_tax_for_audit"("p_tax_row_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
