  SELECT decrypted_secret
    INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type, metadata)
  VALUES (
    v_vendor_id,
    'tax_secret_decrypted',
    auth.uid(),
    'system',
    jsonb_build_object('tax_row_id', p_tax_row_id, 'secret_id', v_secret_id)
  );

  RETURN v_secret;
END;
$$;


ALTER FUNCTION "public"."get_vendor_tax_for_audit"("p_tax_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_locked_invoice_financial_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_protected jsonb;
  v_new_protected jsonb;
BEGIN
  IF OLD.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR OLD.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(OLD.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(OLD.paid_amount, 0) > 0 THEN

    v_old_protected := to_jsonb(OLD)
      - 'status'
      - 'ap_status'
      - 'payment_status'
      - 'paid_amount'
      - 'payment_reference'
      - 'approved_by'
      - 'approved_date'
      - 'ap_routing_destination'
      - 'ap_routing_resolved_at'
      - 'file_destination'
      - 'payment_account_id'
      - 'scheduled_payment_date'
      - 'validation_results'
      - 'validation_notes'
      - 'ap_metadata'
      - 'action_required_reason'
      - 'action_required_details'
      - 'assigned_reviewer_id'
      - 'closed_at'
      - 'closed_by'
      - 'updated_at'
      - 'version_number';

    v_new_protected := to_jsonb(NEW)
      - 'status'
      - 'ap_status'
      - 'payment_status'
      - 'paid_amount'
      - 'payment_reference'
      - 'approved_by'
      - 'approved_date'
      - 'ap_routing_destination'
      - 'ap_routing_resolved_at'
      - 'file_destination'
      - 'payment_account_id'
      - 'scheduled_payment_date'
      - 'validation_results'
      - 'validation_notes'
      - 'ap_metadata'
      - 'action_required_reason'
      - 'action_required_details'
      - 'assigned_reviewer_id'
      - 'closed_at'
      - 'closed_by'
      - 'updated_at'
      - 'version_number';

    IF v_new_protected IS DISTINCT FROM v_old_protected THEN
      RAISE EXCEPTION 'Approved, scheduled, partially paid, or paid invoice financial fields are immutable';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_locked_invoice_financial_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_locked_invoice_line_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice record;
  v_invoice_id uuid;
  v_old_protected jsonb;
  v_new_protected jsonb;
BEGIN
  IF current_setting('app.invoice_product_sync', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT status, ap_status, payment_status, paid_amount
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id;

  IF v_invoice.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR v_invoice.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(v_invoice.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(v_invoice.paid_amount, 0) > 0 THEN

    IF TG_OP = 'UPDATE' THEN
      v_old_protected := to_jsonb(OLD)
        - 'vendor_id'
        - 'vendor_item_id'
        - 'internal_product_id'
        - 'price_variance_flag'
        - 'price_variance_percent'
        - 'updated_at';

      v_new_protected := to_jsonb(NEW)
        - 'vendor_id'
        - 'vendor_item_id'
        - 'internal_product_id'
        - 'price_variance_flag'
        - 'price_variance_percent'
        - 'updated_at';

      IF v_new_protected = v_old_protected THEN
        RETURN NEW;
      END IF;
    END IF;

    RAISE EXCEPTION 'Invoice line items are immutable after approval or payment activity';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."guard_locked_invoice_line_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_payment_reference_uniqueness"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.invoice_id IS NOT NULL
    AND NULLIF(trim(COALESCE(NEW.transaction_id, '')), '') IS NOT NULL
    AND COALESCE(NEW.status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
    AND EXISTS (
      SELECT 1
      FROM public.payments p
      WHERE p.invoice_id = NEW.invoice_id
        AND p.id IS DISTINCT FROM NEW.id
        AND p.transaction_id = NEW.transaction_id
        AND COALESCE(p.status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
    ) THEN
    RAISE EXCEPTION 'A non-reversed payment with reference % already exists for this invoice', NEW.transaction_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_payment_reference_uniqueness"() OWNER TO "postgres";


