CREATE OR REPLACE FUNCTION "public"."hard_delete_invoice_workflow"("p_invoice_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
BEGIN
  SELECT id, organization_id
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  -- Cascading deletes of approved/paid invoice_line_items pass through the
  -- same internal bypass used by product sync. This keeps edit protection in
  -- place while allowing an intentional invoice hard delete to complete.
  PERFORM set_config('app.invoice_product_sync', 'on', true);

  DELETE FROM public.invoices
   WHERE id = p_invoice_id;

  PERFORM set_config('app.invoice_product_sync', '', true);

  RETURN FOUND;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;


ALTER FUNCTION "public"."hard_delete_invoice_workflow"("p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hard_delete_invoice_workflow"("p_invoice_id" "uuid") IS 'Permanently deletes an invoice row after financial actor authorization. Related rows follow their foreign key cascade/set-null rules.';



CREATE OR REPLACE FUNCTION "public"."ingest_email_invoice"("p_recipient_email" "text", "p_fallback_organization_id" "uuid" DEFAULT NULL::"uuid", "p_invoice" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recipient_email text;
  v_location_email public.location_email_addresses%ROWTYPE;
  v_vendor_name text;
  v_invoice_number text;
  v_total_amount numeric := 0;
  v_invoice_id uuid;
  v_system_user_id uuid := '99999999-9999-9999-9999-999999999999'::uuid;
  v_metadata jsonb;
BEGIN
  v_recipient_email := lower(btrim(COALESCE(p_recipient_email, '')));

  IF v_recipient_email = '' THEN
    v_recipient_email := NULL;
  END IF;

  v_vendor_name := COALESCE(NULLIF(btrim(p_invoice->>'vendor_name'), ''), 'Unknown Vendor (Auto-Ingested)');
  v_invoice_number := COALESCE(
    NULLIF(btrim(p_invoice->>'invoice_number'), ''),
    'EMAIL-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || substr(gen_random_uuid()::text, 1, 8)
  );

  BEGIN
    v_total_amount := COALESCE(NULLIF(btrim(p_invoice->>'total_amount'), '')::numeric, 0);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    v_total_amount := 0;
  END;

  SELECT lea.*
    INTO v_location_email
  FROM public.location_email_addresses lea
  WHERE lower(lea.email) = v_recipient_email
    AND lea.is_active = true
    AND lea.deleted_at IS NULL
  LIMIT 1;

  IF FOUND THEN
    v_metadata := COALESCE(p_invoice->'ap_metadata', '{}'::jsonb)
      || jsonb_build_object(
        'ingest_recipient', v_recipient_email,
        'received_at', now(),
        'matched_location_email_id', v_location_email.id,
        'source', 'email_import'
      );

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      ap_status,
      source,
      file_url,
      organization_id,
      brand_id,
      location_id,
      created_by,
      ap_metadata
    ) VALUES (
      v_vendor_name,
      v_invoice_number,
      v_total_amount,
      'extracting',
      'processing',
      'email_import',
      NULLIF(p_invoice->>'file_url', ''),
      v_location_email.organization_id,
      v_location_email.brand_id,
      v_location_email.location_id,
      v_system_user_id,
      v_metadata
    )
    RETURNING id INTO v_invoice_id;

    RETURN jsonb_build_object(
      'invoice_id', v_invoice_id,
      'matched', true,
      'organization_id', v_location_email.organization_id,
      'brand_id', v_location_email.brand_id,
      'location_id', v_location_email.location_id,
      'recipient_email', v_recipient_email
    );
  END IF;

  RETURN jsonb_build_object(
    'invoice_id', NULL,
    'matched', false,
    'organization_id', p_fallback_organization_id,
    'recipient_email', v_recipient_email,
    'warning', 'no_location_email_match'
  );
END;
$$;


ALTER FUNCTION "public"."ingest_email_invoice"("p_recipient_email" "text", "p_fallback_organization_id" "uuid", "p_invoice" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_onboarding_address"("p_user_id" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_address_type" "text", "p_location_name" "text", "p_address" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_address_id uuid;
  v_zip_code text;
  v_country text;
BEGIN
  IF p_address IS NULL OR COALESCE(jsonb_typeof(p_address), 'null') <> 'object' THEN
    RETURN NULL;
  END IF;

  v_zip_code := COALESCE(
    NULLIF(btrim(p_address->>'postalCode'), ''),
    NULLIF(btrim(p_address->>'zipCode'), ''),
    NULLIF(btrim(p_address->>'zip'), '')
  );

  IF NULLIF(btrim(p_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(p_address->>'city'), '') IS NULL
     OR NULLIF(btrim(p_address->>'state'), '') IS NULL
     OR v_zip_code IS NULL THEN
    RAISE EXCEPTION 'Address is incomplete';
  END IF;

  v_country := COALESCE(NULLIF(btrim(p_address->>'country'), ''), 'US');
  IF lower(v_country) IN ('us', 'usa', 'united states', 'united states of america') THEN
    v_country := 'US';
  END IF;

  INSERT INTO public.organization_addresses (
    user_id,
    organization_id,
    brand_id,
    location_id,
    address_type,
    location_name,
    address_line_1,
    address_line_2,
    city,
    state,
    zip_code,
    country,
    usps_verified,
    usps_standardized,
    usps_validation_code
  )
  VALUES (
    p_user_id,
    p_organization_id,
    p_brand_id,
    p_location_id,
    p_address_type,
    NULLIF(btrim(p_location_name), ''),
    btrim(p_address->>'line1'),
    NULLIF(btrim(p_address->>'line2'), ''),
    btrim(p_address->>'city'),
    btrim(p_address->>'state'),
    v_zip_code,
    v_country,
    false,
    false,
    'ONBOARDING_CAPTURED'
  )
  RETURNING id INTO v_address_id;

  RETURN v_address_id;
END;
$$;


ALTER FUNCTION "public"."insert_onboarding_address"("p_user_id" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_address_type" "text", "p_location_name" "text", "p_address" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspect_database_architecture"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'generated_at', now(),
    'schemas', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', n.nspname,
        'owner', pg_catalog.pg_get_userbyid(n.nspowner)
      ) ORDER BY n.nspname), '[]'::jsonb)
      FROM pg_catalog.pg_namespace n
      WHERE n.nspname NOT LIKE 'pg_%'
        AND n.nspname <> 'information_schema'
    ),
    'extensions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'extension_name', e.extname,
        'schema_name', ns.nspname,
        'version', e.extversion
      ) ORDER BY e.extname), '[]'::jsonb)
      FROM pg_catalog.pg_extension e
      JOIN pg_catalog.pg_namespace ns ON ns.oid = e.extnamespace
    ),
    'tables', (
      SELECT COALESCE(jsonb_agg(table_payload ORDER BY table_payload->>'schema_name', table_payload->>'table_name'), '[]'::jsonb)
      FROM (
        SELECT jsonb_build_object(
          'schema_name', ns.nspname,
          'table_name', c.relname,
          'kind', CASE c.relkind
            WHEN 'r' THEN 'table'
            WHEN 'p' THEN 'partitioned_table'
            WHEN 'v' THEN 'view'
            WHEN 'm' THEN 'materialized_view'
            WHEN 'f' THEN 'foreign_table'
            ELSE c.relkind::TEXT
          END,
          'owner', pg_catalog.pg_get_userbyid(c.relowner),
          'rls_enabled', c.relrowsecurity,
          'rls_forced', c.relforcerowsecurity,
          'estimated_rows', c.reltuples::BIGINT,
          'columns', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'column_name', a.attname,
              'ordinal', a.attnum,
              'data_type', pg_catalog.format_type(a.atttypid, a.atttypmod),
              'not_null', a.attnotnull,
              'default', pg_catalog.pg_get_expr(ad.adbin, ad.adrelid),
              'identity', a.attidentity,
              'generated', a.attgenerated
            ) ORDER BY a.attnum), '[]'::jsonb)
            FROM pg_catalog.pg_attribute a
            LEFT JOIN pg_catalog.pg_attrdef ad
              ON ad.adrelid = a.attrelid
             AND ad.adnum = a.attnum
            WHERE a.attrelid = c.oid
              AND a.attnum > 0
              AND NOT a.attisdropped
          ),
          'policies', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'policy_name', p.polname,
              'command', CASE p.polcmd
                WHEN 'r' THEN 'select'
                WHEN 'a' THEN 'insert'
                WHEN 'w' THEN 'update'
                WHEN 'd' THEN 'delete'
                WHEN '*' THEN 'all'
                ELSE p.polcmd::TEXT
              END,
              'permissive', p.polpermissive,
              'roles', (
                SELECT COALESCE(jsonb_agg(r.rolname ORDER BY r.rolname), '[]'::jsonb)
                FROM unnest(p.polroles) AS role_oid
                JOIN pg_catalog.pg_roles r ON r.oid = role_oid
              ),
              'using_expression', pg_catalog.pg_get_expr(p.polqual, p.polrelid),
              'check_expression', pg_catalog.pg_get_expr(p.polwithcheck, p.polrelid)
            ) ORDER BY p.polname), '[]'::jsonb)
            FROM pg_catalog.pg_policy p
            WHERE p.polrelid = c.oid
          ),
          'triggers', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'trigger_name', t.tgname,
              'enabled', t.tgenabled,
              'is_internal', t.tgisinternal,
              'definition', pg_catalog.pg_get_triggerdef(t.oid, true)
            ) ORDER BY t.tgname), '[]'::jsonb)
            FROM pg_catalog.pg_trigger t
            WHERE t.tgrelid = c.oid
              AND NOT t.tgisinternal
          )
        ) AS table_payload
        FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace ns ON ns.oid = c.relnamespace
        WHERE ns.nspname NOT LIKE 'pg_%'
          AND ns.nspname <> 'information_schema'
          AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
      ) table_rows
    ),
    'indexes', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', schemaname,
        'table_name', tablename,
        'index_name', indexname,
        'definition', indexdef
      ) ORDER BY schemaname, tablename, indexname), '[]'::jsonb)
      FROM pg_catalog.pg_indexes
      WHERE schemaname NOT LIKE 'pg_%'
        AND schemaname <> 'information_schema'
    ),
    'constraints', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', ns.nspname,
        'table_name', c.relname,
        'constraint_name', con.conname,
        'constraint_type', con.contype,
        'definition', pg_catalog.pg_get_constraintdef(con.oid, true)
      ) ORDER BY ns.nspname, c.relname, con.conname), '[]'::jsonb)
      FROM pg_catalog.pg_constraint con
      JOIN pg_catalog.pg_class c ON c.oid = con.conrelid
      JOIN pg_catalog.pg_namespace ns ON ns.oid = c.relnamespace
      WHERE ns.nspname NOT LIKE 'pg_%'
        AND ns.nspname <> 'information_schema'
    ),
    'functions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', ns.nspname,
        'function_name', p.proname,
        'identity_arguments', pg_catalog.pg_get_function_identity_arguments(p.oid),
        'result_type', pg_catalog.pg_get_function_result(p.oid),
        'language', l.lanname,
        'security_definer', p.prosecdef,
        'volatility', p.provolatile,
        'parallel', p.proparallel,
        'owner', pg_catalog.pg_get_userbyid(p.proowner)
      ) ORDER BY ns.nspname, p.proname, pg_catalog.pg_get_function_identity_arguments(p.oid)), '[]'::jsonb)
      FROM pg_catalog.pg_proc p
      JOIN pg_catalog.pg_namespace ns ON ns.oid = p.pronamespace
      JOIN pg_catalog.pg_language l ON l.oid = p.prolang
      WHERE ns.nspname NOT LIKE 'pg_%'
        AND ns.nspname <> 'information_schema'
    )
  )
  INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."inspect_database_architecture"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."inspect_database_architecture"() IS 'Service-role-only metadata inspection RPC for architecture audits. Returns schemas, tables, columns, RLS policies, triggers, functions, indexes, constraints, and extensions.';



CREATE OR REPLACE FUNCTION "public"."intercompany_from_scope_writable"("p_organization_id" "uuid", "p_from_location_id" "uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.get_auth_role() IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


