CREATE OR REPLACE FUNCTION "public"."limit_performance_jsonb_array"("p_rows" "jsonb", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    jsonb_agg(row_data ORDER BY ordinality),
    '[]'::jsonb
  )
  FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb))
    WITH ORDINALITY AS source(row_data, ordinality)
  WHERE ordinality > GREATEST(COALESCE(p_offset, 0), 0)
    AND ordinality <= GREATEST(COALESCE(p_offset, 0), 0) + LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
$$;


ALTER FUNCTION "public"."limit_performance_jsonb_array"("p_rows" "jsonb", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."limit_performance_jsonb_array"("p_rows" "jsonb", "p_limit" integer, "p_offset" integer) IS 'Applies a bounded slice to report detail arrays before returning them to the browser.';



CREATE OR REPLACE FUNCTION "public"."link_onboarding_bank_to_payment_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_bank_id UUID;
  v_bank public.onboarding_bank_accounts%ROWTYPE;
  v_payment_account_id UUID;
BEGIN
  IF NEW.organization_id IS NULL OR COALESCE(OLD.organization_id, '00000000-0000-0000-0000-000000000000'::uuid) = NEW.organization_id THEN
    RETURN NEW;
  END IF;

  v_bank_id := NULLIF(NEW.metadata->>'onboarding_bank_account_id', '')::uuid;
  IF v_bank_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_bank
  FROM public.onboarding_bank_accounts
  WHERE id = v_bank_id AND user_id = NEW.user_id;

  IF v_bank.id IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_bank.payment_account_id IS NOT NULL THEN
    v_payment_account_id := v_bank.payment_account_id;
  ELSE
    IF v_bank.is_default THEN
      UPDATE public.payment_accounts
      SET is_default = false
      WHERE organization_id = NEW.organization_id
        AND payment_method IN ('ach', 'check')
        AND is_active = true;
    END IF;

    INSERT INTO public.payment_accounts (
      organization_id,
      name,
      account_type,
      payment_method,
      provider,
      provider_reference,
      last_four,
      is_default,
      is_active,
      metadata,
      created_by,
      updated_by
    )
    VALUES (
      NEW.organization_id,
      COALESCE(NULLIF(v_bank.nickname, ''), v_bank.bank_name || ' ****' || v_bank.account_number_last4),
      'checking',
      'ach',
      'tenant_bank_vault',
      v_bank.id::text,
      v_bank.account_number_last4,
      v_bank.is_default,
      true,
      jsonb_build_object(
        'source', 'tenant_onboarding',
        'onboarding_bank_account_id', v_bank.id,
        'routing_number_last4', v_bank.routing_number_last4,
        'billing_address_source', v_bank.billing_address_source,
        'authorization_status', v_bank.status
      ),
      NEW.user_id,
      NEW.user_id
    )
    RETURNING id INTO v_payment_account_id;
  END IF;

  UPDATE public.onboarding_bank_accounts
  SET organization_id = NEW.organization_id,
      payment_account_id = v_payment_account_id,
      updated_at = now()
  WHERE id = v_bank.id;

  UPDATE public.tenant_payment_authorizations
  SET organization_id = NEW.organization_id,
      payment_account_id = v_payment_account_id,
      updated_at = now()
  WHERE onboarding_bank_account_id = v_bank.id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."link_onboarding_bank_to_payment_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_recipe_categories"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_include_inactive" boolean DEFAULT false) RETURNS SETOF "public"."recipe_categories"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() THEN
    RAISE EXCEPTION 'Not authorized to list recipe categories';
  END IF;

  PERFORM public.ensure_default_recipe_categories(v_org);

  RETURN QUERY
  SELECT rc.*
  FROM public.recipe_categories rc
  WHERE rc.organization_id = v_org
    AND rc.deleted_at IS NULL
    AND (p_include_inactive OR rc.is_active)
  ORDER BY rc.display_order ASC, rc.name ASC;
END;
$$;


ALTER FUNCTION "public"."list_recipe_categories"("p_organization_id" "uuid", "p_include_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_audit_event"("p_entry" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_record_id UUID;
  v_row public.audit_logs%ROWTYPE;
  v_details TEXT;
BEGIN
  IF p_entry IS NULL OR jsonb_typeof(p_entry) <> 'object' THEN
    RAISE EXCEPTION 'Audit entry must be a JSON object';
  END IF;

  v_org_id := NULLIF(COALESCE(p_entry->>'organization_id', p_entry->>'org_id', p_entry->>'orgId'), '')::UUID;
  v_brand_id := NULLIF(COALESCE(p_entry->>'brand_id', p_entry->>'brandId'), '')::UUID;
  v_location_id := NULLIF(COALESCE(p_entry->>'location_id', p_entry->>'locationId'), '')::UUID;

  IF v_org_id IS NOT NULL THEN
    PERFORM public.assert_org_actor(v_org_id);
  ELSIF auth.role() <> 'service_role' AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'organization_id is required for non-platform audit events';
  END IF;

  v_record_id := CASE
    WHEN COALESCE(p_entry->>'record_id', p_entry->>'recordId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(p_entry->>'record_id', p_entry->>'recordId')::UUID
    ELSE NULL
  END;

  v_details := CASE
    WHEN p_entry ? 'details' AND jsonb_typeof(p_entry->'details') IN ('object', 'array') THEN (p_entry->'details')::TEXT
    WHEN p_entry ? 'details' THEN p_entry->>'details'
    ELSE NULL
  END;

  INSERT INTO public.audit_logs (
    organization_id,
    brand_id,
    location_id,
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    module,
    field_changed,
    old_value,
    new_value,
    user_email,
    details
  ) VALUES (
    v_org_id,
    v_brand_id,
    v_location_id,
    COALESCE(NULLIF(p_entry->>'user_id', '')::UUID, auth.uid()),
    COALESCE(NULLIF(p_entry->>'action', ''), 'audit'),
    COALESCE(NULLIF(p_entry->>'table_name', ''), NULLIF(p_entry->>'tableName', ''), NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'module', ''), 'system'),
    v_record_id,
    CASE WHEN p_entry ? 'old_data' THEN p_entry->'old_data' WHEN p_entry ? 'oldData' THEN p_entry->'oldData' ELSE NULL END,
    CASE WHEN p_entry ? 'new_data' THEN p_entry->'new_data' WHEN p_entry ? 'newData' THEN p_entry->'newData' ELSE NULL END,
    NULLIF(p_entry->>'ip_address', ''),
    NULLIF(p_entry->>'user_agent', ''),
    COALESCE(NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'action', ''), 'unknown'),
    COALESCE(NULLIF(p_entry->>'entity_id', ''), NULLIF(p_entry->>'entityId', ''), NULLIF(p_entry->>'target_user_id', ''), NULLIF(p_entry->>'record_id', ''), NULLIF(p_entry->>'recordId', '')),
    NULLIF(p_entry->>'module', ''),
    COALESCE(NULLIF(p_entry->>'field_changed', ''), NULLIF(p_entry->>'fieldChanged', '')),
    COALESCE(NULLIF(p_entry->>'old_value', ''), NULLIF(p_entry->>'oldValue', '')),
    COALESCE(NULLIF(p_entry->>'new_value', ''), NULLIF(p_entry->>'newValue', '')),
    COALESCE(NULLIF(p_entry->>'user_email', ''), NULLIF(p_entry->>'userEmail', '')),
    v_details
  )
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$_$;


ALTER FUNCTION "public"."log_audit_event"("p_entry" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_audit_event"("p_entry" "jsonb") IS 'Scoped audit writer. Normalizes audit payloads and enforces organization scope for authenticated users.';



CREATE OR REPLACE FUNCTION "public"."log_audit_events"("p_entries" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_entry JSONB;
  v_rows JSONB := '[]'::jsonb;
BEGIN
  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' THEN
    RAISE EXCEPTION 'Audit entries must be a JSON array';
  END IF;

  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_entries) LOOP
    v_rows := v_rows || public.log_audit_event(v_entry);
  END LOOP;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."log_audit_events"("p_entries" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_frontend_event"("p_event_name" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_org_id UUID;
    v_role TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    v_org_id := public.get_my_org();
    v_role := public.get_auth_role();

    IF v_org_id IS NULL AND v_role <> 'platform_admin' THEN
        RAISE EXCEPTION 'Cannot emit event without organization context';
    END IF;

    RETURN public.emit_domain_event(p_event_name, p_entity_type, p_entity_id, v_org_id, p_payload);
END;
$$;


ALTER FUNCTION "public"."log_frontend_event"("p_event_name" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_inventory_waste"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_inventory_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "text" DEFAULT NULL::"text", "p_product_name" "text" DEFAULT NULL::"text", "p_quantity" numeric DEFAULT 0, "p_unit" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT 'other'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inventory public.inventory;
  v_previous_qty numeric;
  v_new_qty numeric;
  v_unit_cost numeric;
  v_waste_id uuid;
  v_reason text;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_location_id, true);

  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location is required to log inventory waste';
  END IF;
  IF COALESCE(p_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Waste quantity must be greater than zero';
  END IF;

  v_reason := CASE WHEN p_reason IN ('expired', 'damaged', 'spoiled', 'overproduction', 'customer_return', 'other')
    THEN p_reason ELSE 'other' END;

  SELECT * INTO v_inventory
  FROM public.inventory
  WHERE id = p_inventory_id
    AND organization_id = p_organization_id
    AND location_id = p_location_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_inventory.id IS NULL THEN
    RAISE EXCEPTION 'Inventory item not found for the active location';
  END IF;

  v_previous_qty := COALESCE(v_inventory.current_quantity, 0);
  v_new_qty := GREATEST(0, v_previous_qty - p_quantity);
  v_unit_cost := COALESCE(v_inventory.unit_cost, 0);

  INSERT INTO public.wastage_logs (
    organization_id, brand_id, location_id, product_id, product_name,
    quantity, unit, value, reason, notes, location, logged_by, created_at
  ) VALUES (
    p_organization_id,
    COALESCE(p_brand_id, v_inventory.brand_id),
    p_location_id,
    COALESCE(p_product_id, v_inventory.product_id),
    COALESCE(NULLIF(p_product_name, ''), v_inventory.product_name),
    p_quantity,
    COALESCE(NULLIF(p_unit, ''), v_inventory.current_unit, 'ea'),
    p_quantity * v_unit_cost,
    v_reason,
    p_notes,
    v_inventory.location,
    COALESCE(p_user_id, auth.uid()),
    now()
  )
  RETURNING id INTO v_waste_id;

  UPDATE public.inventory
     SET current_quantity = v_new_qty,
         current_value = v_new_qty * v_unit_cost,
         previous_quantity = v_previous_qty,
         previous_value = COALESCE(v_inventory.current_value, v_previous_qty * v_unit_cost),
         updated_at = now()
   WHERE id = v_inventory.id;

  INSERT INTO public.inventory_movements (
    organization_id, location_id, inventory_id, movement_type, quantity,
    source_type, source_id, previous_quantity, new_quantity, created_by
  ) VALUES (
    p_organization_id, p_location_id, v_inventory.id,
    CASE WHEN v_reason = 'spoiled' THEN 'spoilage' ELSE 'wastage' END,
    -p_quantity, 'wastage_log', v_waste_id, v_previous_qty, v_new_qty, COALESCE(p_user_id, auth.uid())
  );

  RETURN jsonb_build_object('success', true, 'wastage_log_id', v_waste_id, 'previous_quantity', v_previous_qty, 'new_quantity', v_new_qty);
END;
$$;


ALTER FUNCTION "public"."log_inventory_waste"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_inventory_id" "uuid", "p_product_id" "text", "p_product_name" "text", "p_quantity" numeric, "p_unit" "text", "p_reason" "text", "p_notes" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_invitation_opened"("p_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_invite RECORD;
BEGIN
    SELECT * INTO v_invite FROM public.invitations WHERE token = p_token;
    
    IF FOUND THEN
        -- Only log if it hasn't been accepted or expired
        IF v_invite.accepted_at IS NULL AND v_invite.expires_at > now() THEN
            -- Update the invitation status if we want to track it directly
            -- but for this architecture, we emit the domain event:
            PERFORM public.emit_domain_event(
                'user.invitation.opened',
                'invitation',
                v_invite.id,
                v_invite.organization_id, -- Note: could be NULL for platform invites
                jsonb_build_object('email', v_invite.email, 'role', v_invite.role)
            );
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."log_invitation_opened"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_invoice_audit_event"("p_invoice_id" "uuid", "p_action" "text", "p_description" "text" DEFAULT NULL::"text", "p_old_value" "jsonb" DEFAULT NULL::"jsonb", "p_new_value" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.invoices WHERE id = p_invoice_id;

  IF v_org_id IS NOT NULL THEN
    INSERT INTO public.invoice_audit_events (
      invoice_id, organization_id, user_id, action, description, old_value, new_value
    ) VALUES (
      p_invoice_id, v_org_id, auth.uid(), p_action, p_description, p_old_value, p_new_value
    );

    -- Best-effort mirror into the common audit_logs ledger. Must never block the invoice
    -- write itself: log_audit_event requires an authenticated/service-role actor context
    -- (assert_org_actor), which isn't present for direct-SQL/cron-driven invoice updates.
    BEGIN
      PERFORM public.log_audit_event(jsonb_build_object(
        'organization_id', v_org_id,
        'action', p_action,
        'table_name', 'invoices',
        'record_id', p_invoice_id::text,
        'entity_type', 'invoice',
        'entity_id', p_invoice_id::text,
        'old_data', p_old_value,
        'new_data', p_new_value,
        'details', p_description
      ));
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
END;
$$;


ALTER FUNCTION "public"."log_invoice_audit_event"("p_invoice_id" "uuid", "p_action" "text", "p_description" "text", "p_old_value" "jsonb", "p_new_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_onboarding_contact_verified"("p_channel" "text", "p_target" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_run_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  IF v_channel = 'email' THEN
    UPDATE public.profiles
    SET business_email = v_target,
        business_email_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    UPDATE public.profiles
    SET business_phone = v_target,
        business_phone_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'verified',
    'verified',
    jsonb_build_object('target', v_target, 'provider', 'supabase_auth')
  );

  RETURN jsonb_build_object(
    'success', true,
    'channel', v_channel,
    'target', v_target,
    'verified_at', now(),
    'provider', 'supabase_auth'
  );
END;
$$;


ALTER FUNCTION "public"."mark_onboarding_contact_verified"("p_channel" "text", "p_target" "text") OWNER TO "postgres";


