CREATE OR REPLACE FUNCTION "public"."normalize_app_role"("p_role" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE lower(NULLIF(trim(p_role), ''))
    WHEN 'owner' THEN 'org_manager'
    WHEN 'org_owner' THEN 'org_manager'
    WHEN 'organization_owner' THEN 'org_manager'
    WHEN 'manager' THEN 'branch_manager'
    WHEN 'brand_manager' THEN 'branch_manager'
    WHEN 'admin' THEN 'platform_admin'
    ELSE lower(NULLIF(trim(p_role), ''))
  END;
$$;


ALTER FUNCTION "public"."normalize_app_role"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_contact_target"("p_channel" "text", "p_target" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_target TEXT;
  v_digits TEXT;
BEGIN
  IF p_channel = 'email' THEN
    v_target := lower(btrim(COALESCE(p_target, '')));
    RETURN v_target;
  ELSIF p_channel = 'phone' THEN
    v_digits := regexp_replace(COALESCE(p_target, ''), '\D', '', 'g');
    IF length(v_digits) = 10 THEN
      RETURN '+1' || v_digits;
    ELSIF length(v_digits) = 11 AND left(v_digits, 1) = '1' THEN
      RETURN '+' || v_digits;
    ELSE
      RETURN v_digits;
    END IF;
  END IF;

  RETURN btrim(COALESCE(p_target, ''));
END;
$$;


ALTER FUNCTION "public"."normalize_contact_target"("p_channel" "text", "p_target" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_global_vendor_category"("p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN p_category = ANY (ARRAY[
      '5100', '5110', '5120', '5130', '5140', '5150', '5160', '5170', '5190',
      '5200', '5210', '5220', '5230', '5240', '5290',
      '5300'
    ]) THEN p_category
    WHEN p_category = 'food_cogs' THEN '5100'
    WHEN p_category = 'beverage_cogs' THEN '5200'
    WHEN p_category = 'merchandise_cogs' THEN '5300'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."normalize_global_vendor_category"("p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_invitation_role_before_check"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  v_role := lower(trim(COALESCE(NEW.role, '')));
  v_role := replace(replace(v_role, '-', '_'), ' ', '_');

  NEW.role := CASE
    WHEN v_role IN ('tenant', 'tenant_admin', 'tenant_superadmin', 'tenant_super_admin') THEN 'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner') AND NEW.organization_id IS NULL THEN 'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner', 'org_manager', 'organization_manager') THEN 'org_manager'
    WHEN v_role IN ('brand_manager', 'branch_manager') THEN 'branch_manager'
    WHEN v_role IN ('manager', 'location_manager') THEN 'location_manager'
    WHEN v_role IN ('ground_staff', 'staff') THEN 'ground_staff'
    WHEN v_role IN ('admin', 'platform_admin') THEN 'platform_admin'
    ELSE v_role
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_invitation_role_before_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_invited_module_keys"("p_modules" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  WITH allowed_modules(module_key) AS (
    VALUES
      ('dashboard'),
      ('dashboard_reports'),
      ('performance'),
      ('executive_bi'),
      ('custom_reports'),
      ('invoices'),
      ('payments'),
      ('billing'),
      ('products'),
      ('inventory'),
      ('orders'),
      ('smartprep'),
      ('commissary'),
      ('recipes'),
      ('vendors'),
      ('labor'),
      ('accounting'),
      ('admin'),
      ('setup'),
      ('food_safety'),
      ('kitchen_displays'),
      ('integrations'),
      ('crm_marketing'),
      ('ai_insights')
  ), normalized AS (
    SELECT DISTINCT lower(btrim(module_key.value)) AS module_key
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(p_modules) = 'array' THEN p_modules ELSE '[]'::jsonb END
    ) AS module_key(value)
    WHERE NULLIF(btrim(module_key.value), '') IS NOT NULL
  )
  SELECT NULLIF(COALESCE(jsonb_agg(normalized.module_key ORDER BY normalized.module_key), '[]'::jsonb), '[]'::jsonb)
  FROM normalized
  JOIN allowed_modules USING (module_key);
$$;


ALTER FUNCTION "public"."normalize_invited_module_keys"("p_modules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_invoice_ap_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.ap_status = 'approved'
    AND COALESCE(NEW.status, 'processing') IN ('processing', 'pending_review', 'validated', 'pending_approval', 'flagged') THEN
    NEW.status := 'approved';
  ELSIF NEW.ap_status = 'scheduled'
    AND COALESCE(NEW.status, 'processing') IN ('processing', 'pending_review', 'validated', 'pending_approval', 'approved') THEN
    NEW.status := 'scheduled';
  END IF;

  IF NEW.status = 'approved' THEN
    NEW.ap_status := 'approved';
  ELSIF NEW.status = 'scheduled' THEN
    NEW.ap_status := 'scheduled';
  ELSIF NEW.status = 'paid' THEN
    NEW.ap_status := 'paid';
    NEW.payment_status := 'paid';
  ELSIF NEW.status = 'rejected' THEN
    IF COALESCE(NEW.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      OR COALESCE(NEW.paid_amount, 0) > 0 THEN
      RAISE EXCEPTION 'Rejected invoices cannot carry paid or in-flight payment state';
    END IF;
    NEW.ap_status := 'rejected';
  END IF;

  IF NEW.payment_status = 'paid'
    AND NEW.status <> 'extracting' THEN
    NEW.status := 'paid';
    NEW.ap_status := 'paid';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_invoice_ap_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_product_category_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_category_type text;
  v_accounting_category text;
  v_should_set_accounting boolean := false;
BEGIN
  IF NULLIF(trim(COALESCE(NEW.category, '')), '') IS NULL
    OR lower(trim(NEW.category)) = 'uncategorized' THEN
    NEW.category := public.derive_product_category(NULL, NEW.name);
    IF NEW.category <> 'Uncategorized' THEN
      NEW.category_source := COALESCE(NULLIF(NEW.category_source, ''), 'rules');
      NEW.category_confidence := COALESCE(NEW.category_confidence, 75);
      NEW.category_review_status := COALESCE(NULLIF(NEW.category_review_status, ''), 'approved');
    END IF;
  END IF;

  v_category_type := public.derive_product_category_type(NEW.accounting_category, NEW.category, NEW.name);
  v_accounting_category := public.product_accounting_category_for_type(v_category_type, NEW.category);

  v_should_set_accounting :=
    TG_OP = 'INSERT'
    OR NULLIF(trim(COALESCE(NEW.accounting_category, '')), '') IS NULL
    OR (NEW.accounting_category = '5100' AND v_accounting_category <> '5110');

  IF TG_OP = 'UPDATE' THEN
    v_should_set_accounting := v_should_set_accounting
      OR (
        COALESCE(OLD.category, '') IS DISTINCT FROM COALESCE(NEW.category, '')
        AND COALESCE(OLD.accounting_category, '') = COALESCE(NEW.accounting_category, '')
      );
  END IF;

  IF v_should_set_accounting THEN
    NEW.accounting_category := v_accounting_category;
  END IF;

  IF NULLIF(trim(COALESCE(NEW.category, '')), '') IS NULL
    OR lower(trim(NEW.category)) = 'uncategorized' THEN
    NEW.category_review_status := 'pending';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_product_category_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_product_report_unit"("p_unit" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('ea', 'each', 'unit', 'units') THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('cs', 'case', 'cases') THEN 'Case'
    WHEN lower(trim(p_unit)) IN ('lb', 'lbs', 'pound', 'pounds') THEN 'Pound'
    WHEN lower(trim(p_unit)) IN ('oz', 'ounce', 'ounces') THEN 'Ounce'
    WHEN lower(trim(p_unit)) IN ('gal', 'gallon', 'gallons') THEN 'Gallon'
    WHEN lower(trim(p_unit)) IN ('qt', 'quart', 'quarts') THEN 'Quart'
    WHEN lower(trim(p_unit)) IN ('pt', 'pint', 'pints') THEN 'Pint'
    WHEN lower(trim(p_unit)) IN ('floz', 'fl oz', 'fluid ounce', 'fluid ounces') THEN 'Fluid Ounce'
    WHEN lower(trim(p_unit)) IN ('kg', 'kilogram', 'kilograms') THEN 'Kilogram'
    WHEN lower(trim(p_unit)) IN ('g', 'gram', 'grams') THEN 'Gram'
    WHEN lower(trim(p_unit)) IN ('box', 'boxes') THEN 'Box'
    WHEN lower(trim(p_unit)) IN ('bag', 'bags') THEN 'Bag'
    WHEN lower(trim(p_unit)) IN ('btl', 'bottle', 'bottles') THEN 'Bottle'
    WHEN lower(trim(p_unit)) IN ('can', 'cans') THEN 'Can'
    ELSE initcap(trim(p_unit))
  END;
$$;


ALTER FUNCTION "public"."normalize_product_report_unit"("p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_product_unit_label"("p_unit" "text", "p_quantity" numeric DEFAULT NULL::numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_unit text := upper(regexp_replace(trim(COALESCE(p_unit, '')), '[^A-Z]', '', 'g'));
  v_plural boolean := COALESCE(p_quantity, 2) <> 1;
BEGIN
  IF v_unit = '' THEN
    RETURN NULL;
  END IF;

  RETURN CASE
    WHEN v_unit IN ('EA', 'EACH', 'EACHES', 'CT', 'COUNT', 'CN') THEN 'Each'
    WHEN v_unit IN ('CS', 'CASE', 'CASES') THEN 'Case'
    WHEN v_unit IN ('LB', 'LBS', 'POUND', 'POUNDS') THEN CASE WHEN v_plural THEN 'Pounds' ELSE 'Pound' END
    WHEN v_unit IN ('OZ', 'OZS', 'OUNCE', 'OUNCES') THEN CASE WHEN v_plural THEN 'Ounces' ELSE 'Ounce' END
    WHEN v_unit IN ('GA', 'GAL', 'GALS', 'GALLON', 'GALLONS') THEN CASE WHEN v_plural THEN 'Gallons' ELSE 'Gallon' END
    WHEN v_unit IN ('L', 'LT', 'LTR', 'LTRS', 'LITER', 'LITERS', 'LITRE', 'LITRES') THEN CASE WHEN v_plural THEN 'Liters' ELSE 'Liter' END
    WHEN v_unit IN ('ML', 'MLS', 'MILLILITER', 'MILLILITERS') THEN CASE WHEN v_plural THEN 'Milliliters' ELSE 'Milliliter' END
    WHEN v_unit IN ('G', 'GM', 'GRAM', 'GRAMS') THEN CASE WHEN v_plural THEN 'Grams' ELSE 'Gram' END
    WHEN v_unit IN ('KG', 'KGS', 'KILOGRAM', 'KILOGRAMS') THEN CASE WHEN v_plural THEN 'Kilograms' ELSE 'Kilogram' END
    WHEN v_unit IN ('BTL', 'BTLS', 'BOTTLE', 'BOTTLES') THEN CASE WHEN v_plural THEN 'Bottles' ELSE 'Bottle' END
    WHEN v_unit IN ('CAN', 'CANS') THEN CASE WHEN v_plural THEN 'Cans' ELSE 'Can' END
    WHEN v_unit IN ('BAG', 'BAGS') THEN CASE WHEN v_plural THEN 'Bags' ELSE 'Bag' END
    WHEN v_unit IN ('BOX', 'BOXES', 'BX') THEN CASE WHEN v_plural THEN 'Boxes' ELSE 'Box' END
    WHEN v_unit IN ('PK', 'PKG', 'PACK', 'PACKAGE') THEN CASE WHEN v_plural THEN 'Packs' ELSE 'Pack' END
    WHEN v_unit IN ('DOZ', 'DOZEN') THEN 'Dozen'
    WHEN v_unit IN ('FLAT', 'FLATS') THEN CASE WHEN v_plural THEN 'Flats' ELSE 'Flat' END
    WHEN v_unit IN ('CUP', 'CUPS') THEN CASE WHEN v_plural THEN 'Cups' ELSE 'Cup' END
    WHEN v_unit IN ('QT', 'QTS', 'QUART', 'QUARTS') THEN CASE WHEN v_plural THEN 'Quarts' ELSE 'Quart' END
    ELSE initcap(lower(v_unit))
  END;
END;
$$;


ALTER FUNCTION "public"."normalize_product_unit_label"("p_unit" "text", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_recipe_category_slug"("p_value" "text") RETURNS "text"
