CREATE OR REPLACE FUNCTION "public"."notify_business_verification_review_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_admin RECORD;
  v_title TEXT;
  v_message TEXT;
  v_run_id UUID;
BEGIN
  IF NEW.verification_status NOT IN ('pending_review', 'failed', 'rejected') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND COALESCE(OLD.verification_status, '') = NEW.verification_status THEN
    RETURN NEW;
  END IF;

  v_title := CASE
    WHEN NEW.verification_status = 'rejected' THEN 'Business verification rejected'
    WHEN NEW.verification_status = 'failed' THEN 'Business verification needs changes'
    ELSE 'Business verification pending review'
  END;
  v_message := CASE
    WHEN NEW.verification_status = 'rejected' THEN COALESCE(NULLIF(NEW.rejection_reason, ''), 'Your business verification was rejected.')
    WHEN NEW.verification_status = 'failed' THEN COALESCE(NULLIF(NEW.rejection_reason, ''), 'Your business verification could not be approved. Please review and resubmit.')
    ELSE 'Your business verification is pending platform admin review.'
  END;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  VALUES (NEW.user_id, NEW.organization_id, 'system', v_title, v_message, false);

  FOR v_admin IN SELECT id FROM public.profiles WHERE role = 'platform_admin'
  LOOP
    INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
    VALUES (
      v_admin.id,
      NEW.organization_id,
      'system',
      v_title,
      COALESCE(NEW.legal_business_name, 'Tenant') || ' requires onboarding follow-up: ' || NEW.verification_status,
      false
    );
  END LOOP;

  v_run_id := public.get_or_create_onboarding_run(NEW.user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    NEW.user_id,
    'business_verification',
    CASE
      WHEN NEW.verification_status = 'rejected' THEN 'rejected_notification_queued'
      WHEN NEW.verification_status = 'failed' THEN 'failed_notification_queued'
      ELSE 'pending_review_notification_queued'
    END,
    NEW.verification_status,
    jsonb_build_object('verification_id', NEW.id)
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_business_verification_review_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_expired_owner_invitations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invitation RECORD;
  v_admin RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_invitation IN
    SELECT i.*
    FROM public.invitations i
    WHERE i.role IN ('org_manager', 'tenant_super_admin', 'owner', 'org_owner')
      AND i.accepted_at IS NULL
      AND i.closed_at IS NULL
      AND i.expires_at IS NOT NULL
      AND i.expires_at <= now()
      AND i.expired_notified_at IS NULL
  LOOP
    FOR v_admin IN SELECT id FROM public.profiles WHERE role = 'platform_admin'
    LOOP
      INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
      VALUES (
        v_admin.id,
        v_invitation.organization_id,
        'system',
        'Owner onboarding invitation expired',
        'The owner invitation for ' || v_invitation.email || ' expired and needs follow-up or reissue.',
        false
      );
    END LOOP;

    UPDATE public.invitations
    SET expired_notified_at = now()
    WHERE id = v_invitation.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'expired_invitations_notified', v_count);
END;
$$;


ALTER FUNCTION "public"."notify_expired_owner_invitations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_webhook_dispatcher"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM net.http_post(
    url := current_setting('app.settings.webhook_dispatcher_url', true),
    headers := '{"Content-Type":"application/json"}'::jsonb,
    body := jsonb_build_object('queue_id', NEW.id)
  )
  WHERE current_setting('app.settings.webhook_dispatcher_url', true) IS NOT NULL
    AND current_setting('app.settings.webhook_dispatcher_url', true) <> '';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_webhook_dispatcher"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."org_remove_member"("target_user_id" "uuid", "target_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
BEGIN
  caller_role := public.get_auth_role();

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_manager, tenant_super_admin, or platform_admin can remove users';
  END IF;

  IF public.is_platform_admin() THEN
    caller_org := COALESCE(target_org_id, public.get_auth_org());
  ELSE
    caller_org := public.get_auth_org();
    IF target_org_id IS NOT NULL AND target_org_id != caller_org THEN
      RAISE EXCEPTION 'Cannot remove members from another organization';
    END IF;
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  DELETE FROM public.organization_members
  WHERE user_id = target_user_id AND organization_id = caller_org;

  DELETE FROM public.brand_members
  WHERE user_id = target_user_id
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);

  DELETE FROM public.location_members
  WHERE user_id = target_user_id
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  PERFORM public.log_audit_event(jsonb_build_object(
    'organization_id', caller_org,
    'user_id', auth.uid(),
    'action', 'org_member_removed',
    'table_name', 'organization_members',
    'entity_type', 'user',
    'entity_id', target_user_id::text,
    'record_id', target_user_id::text,
    'details', jsonb_build_object('removed_user_id', target_user_id, 'removed_from_org', caller_org)
  ));

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."org_remove_member"("target_user_id" "uuid", "target_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."override_vendor_banking_callback"("p_request_id" "uuid", "p_override_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
BEGIN
  IF NULLIF(btrim(COALESCE(p_override_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Override reason is required';
  END IF;

  SELECT * INTO v_request
  FROM public.vendor_banking_change_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'Banking change request not found';
  END IF;

  IF NOT public.reference_scope_writable(v_request.organization_id, v_request.brand_id, v_request.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_change_requests
     SET callback_status = 'skipped_override',
         override_by = auth.uid(),
         override_reason = p_override_reason,
         override_at = now(),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_request_id
   RETURNING * INTO v_request;

  UPDATE public.vendor_banking_details
     SET callback_status = 'confirmed',
         verification_state = 'verified',
         verified_at = COALESCE(verified_at, now()),
         is_default = CASE
           WHEN v_request.request_reason IN ('onboarding', 'vendor_requested_update')
             OR NOT EXISTS (
               SELECT 1
               FROM public.vendor_banking_details existing
               WHERE existing.vendor_id = v_request.vendor_id
                 AND existing.is_default = true
                 AND existing.is_active = true
                 AND existing.deleted_at IS NULL
                 AND existing.id IS DISTINCT FROM v_request.banking_detail_id
             )
           THEN true
           ELSE is_default
         END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = v_request.banking_detail_id
   RETURNING * INTO v_bank;

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_request.vendor_id,
    'callback_override',
    'banking_verified',
    'admin',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'override_reason', p_override_reason
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_request.vendor_id,
    'banking_row_id', v_bank.id,
    'change_request_id', v_request.id,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status,
    'is_default', v_bank.is_default
  );
END;
$$;


ALTER FUNCTION "public"."override_vendor_banking_callback"("p_request_id" "uuid", "p_override_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."business_verifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "organization_id" "uuid",
    "legal_business_name" "text" NOT NULL,
    "business_type" "text" NOT NULL,
    "identifier_type" "text" NOT NULL,
    "identifier_last4" "text",
    "provider_name" "text" NOT NULL,
    "provider_reference_id" "text",
    "verification_status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "trust_score" integer,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "rejection_reason" "text",
    "tax_identifier_secret_id" "uuid",
    CONSTRAINT "business_verifications_identifier_type_check" CHECK (("identifier_type" = ANY (ARRAY['ein'::"text", 'ssn'::"text"]))),
    CONSTRAINT "business_verifications_trust_score_check" CHECK ((("trust_score" >= 0) AND ("trust_score" <= 100))),
    CONSTRAINT "business_verifications_verification_status_check" CHECK (("verification_status" = ANY (ARRAY['pending_review'::"text", 'verified'::"text", 'failed'::"text", 'rejected'::"text"])))
);

ALTER TABLE ONLY "public"."business_verifications" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."business_verifications" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."platform_business_verification_reviews"() RETURNS SETOF "public"."business_verifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'platform_admin role required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT bv.*
  FROM public.business_verifications bv
  WHERE bv.verification_status IN ('pending_review', 'failed', 'verified', 'rejected')
  ORDER BY bv.created_at DESC
  LIMIT 200;
END;
$$;


ALTER FUNCTION "public"."platform_business_verification_reviews"() OWNER TO "postgres";


