ALTER TABLE "public"."onboarding_hierarchy_submissions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."platform_hierarchy_review_queue"() RETURNS SETOF "public"."onboarding_hierarchy_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'platform_admin role required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT * FROM public.onboarding_hierarchy_submissions
  WHERE status IN ('pending_review', 'rejected', 'failed')
  ORDER BY created_at DESC
  LIMIT 200;
END;
$$;


