CREATE OR REPLACE FUNCTION "public"."prevent_self_role_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Skip this check when called from SECURITY DEFINER functions (like RPC handlers).
  -- In SECURITY DEFINER context, the session_user is the function owner (postgres),
  -- not the authenticated user. We trust SECURITY DEFINER functions to validate properly.
  IF session_user = 'postgres' OR current_user = 'postgres' THEN
    RETURN NEW;
  END IF;

  -- In normal RLS context: if the user is updating their own profile,
  -- prevent changes to sensitive fields (admins go through profiles_update_admin policy)
  IF NEW.id = auth.uid() THEN
    NEW.role := OLD.role;
    NEW.organization_id := OLD.organization_id;
    NEW.brand_id := OLD.brand_id;
    NEW.location_id := OLD.location_id;
    NEW.access_level := OLD.access_level;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_self_role_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_audit_log"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF (TG_OP = 'DELETE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data)
        VALUES (OLD.organization_id, OLD.brand_id, OLD.location_id, v_user_id, 'DELETE', TG_TABLE_NAME, OLD.id, row_to_json(OLD)::jsonb);
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'UPDATE', TG_TABLE_NAME, NEW.id, row_to_json(OLD)::jsonb, row_to_json(NEW)::jsonb);
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'INSERT', TG_TABLE_NAME, NEW.id, row_to_json(NEW)::jsonb);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."process_audit_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_onboarding_audit_log"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor UUID := auth.uid();
  v_old JSONB;
  v_new JSONB;
  v_row JSONB;
  v_org_id UUID;
  v_record_id UUID;
  v_target_user_id UUID;
  v_entity_id TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(OLD));
    v_row := COALESCE(to_jsonb(OLD), '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(OLD));
    v_new := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(NEW));
    v_row := COALESCE(to_jsonb(NEW), '{}'::jsonb);
  ELSE
    v_new := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(NEW));
    v_row := COALESCE(to_jsonb(NEW), '{}'::jsonb);
  END IF;

  IF v_row ? 'id'
     AND COALESCE(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_record_id := (v_row->>'id')::UUID;
    v_entity_id := v_row->>'id';
  ELSE
    v_entity_id := COALESCE(v_row->>'id', TG_TABLE_NAME);
  END IF;

  IF v_row ? 'user_id'
     AND COALESCE(v_row->>'user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'user_id')::UUID;
  ELSIF TG_TABLE_NAME = 'profiles'
     AND v_row ? 'id'
     AND COALESCE(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'id')::UUID;
  ELSIF v_row ? 'target_user_id'
     AND COALESCE(v_row->>'target_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'target_user_id')::UUID;
  END IF;

  v_org_id := public.resolve_onboarding_audit_org_id(v_row);

  INSERT INTO public.audit_logs (
    organization_id,
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    entity_type,
    entity_id,
    module,
    details
  ) VALUES (
    v_org_id,
    COALESCE(v_actor, v_target_user_id),
    TG_OP,
    TG_TABLE_NAME,
    v_record_id,
    v_old,
    v_new,
    TG_TABLE_NAME,
    v_entity_id,
    'onboarding',
    jsonb_build_object(
      'source', 'onboarding_audit_trigger',
      'target_user_id', v_target_user_id,
      'actor_user_id', v_actor,
      'redacted_fields', CASE
        WHEN TG_TABLE_NAME = 'profiles' THEN jsonb_build_array('onboarding_draft')
        WHEN TG_TABLE_NAME = 'onboarding_contact_otps' THEN jsonb_build_array('code_hash', 'provider_reference_id')
        WHEN TG_TABLE_NAME = 'tenant_payment_authorizations' THEN jsonb_build_array('signature_payload', 'signature_storage_path', 'consent_text')
        WHEN TG_TABLE_NAME = 'onboarding_bank_accounts' THEN jsonb_build_array('banking_secret_id')
        WHEN TG_TABLE_NAME = 'invitations' THEN jsonb_build_array('token', 'invite_token', 'invitation_token', 'raw_token')
        ELSE '[]'::jsonb
      END
    )::TEXT
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."process_onboarding_audit_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sales_to_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_recipe_id UUID;
    r RECORD;
    v_inventory_id UUID;
    v_old_qty NUMERIC(10,2);
    v_new_qty NUMERIC(10,2);
    v_movement_qty NUMERIC(10,2);
BEGIN
    -- Find mapped recipe
    SELECT recipe_id INTO v_recipe_id 
    FROM public.pos_menu_mapping 
    WHERE pos_item_id = NEW.pos_item_id AND organization_id = NEW.organization_id
    LIMIT 1;

    -- If there's a mapping, deplete ingredients
    IF v_recipe_id IS NOT NULL THEN
        FOR r IN 
            SELECT p.product_id AS prod_text_id, ri.quantity AS recipe_qty
            FROM public.recipe_ingredients ri
            JOIN public.products p ON p.id = ri.product_id
            WHERE ri.recipe_id = v_recipe_id AND ri.organization_id = NEW.organization_id
        LOOP
            -- Find inventory record by product_id (text)
            SELECT id, current_quantity 
            INTO v_inventory_id, v_old_qty 
            FROM public.inventory 
            WHERE product_id = r.prod_text_id AND organization_id = NEW.organization_id
            LIMIT 1;

            IF v_inventory_id IS NOT NULL THEN
                -- Calculate movement quantity (theoretical consumption)
                v_movement_qty := r.recipe_qty * NEW.quantity_sold;
                v_new_qty := COALESCE(v_old_qty, 0) - v_movement_qty;

                -- Update inventory
                UPDATE public.inventory 
                SET current_quantity = v_new_qty, updated_at = now()
                WHERE id = v_inventory_id;

                -- Insert into inventory_movements
                INSERT INTO public.inventory_movements (
                    organization_id, location_id, inventory_id, movement_type, 
                    quantity, source_type, source_id, previous_quantity, new_quantity
                ) VALUES (
                    NEW.organization_id, NEW.location_id, v_inventory_id, 'recipe_consumption',
                    -v_movement_qty, 'pos_sale', NEW.id, COALESCE(v_old_qty, 0), v_new_qty
                );
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_pos_sales_to_inventory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."product_accounting_category_for_type"("p_category_type" "text", "p_category" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE COALESCE(NULLIF(btrim(p_category_type), ''), 'Other')
    WHEN 'Beer' THEN '5230'
    WHEN 'Wine' THEN '5240'
    WHEN 'Liquor' THEN '5220'
    WHEN 'N-A Bev' THEN '5210'
    WHEN 'Retail' THEN '5300'
    WHEN 'Food' THEN CASE
      WHEN lower(COALESCE(p_category, '')) LIKE '%poultry%' THEN '5120'
      WHEN lower(COALESCE(p_category, '')) LIKE '%seafood%' THEN '5130'
      WHEN lower(COALESCE(p_category, '')) LIKE '%dairy%' THEN '5140'
      WHEN lower(COALESCE(p_category, '')) LIKE '%produce%' THEN '5150'
      WHEN lower(COALESCE(p_category, '')) LIKE '%frozen%' THEN '5160'
      WHEN lower(COALESCE(p_category, '')) LIKE '%grocery%' THEN '5170'
      ELSE '5110'
    END
    ELSE '5110'
  END;
$$;


ALTER FUNCTION "public"."product_accounting_category_for_type"("p_category_type" "text", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."product_unit_is_generic"("p_unit" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL
    OR lower(trim(p_unit)) IN ('ea', 'each', 'other', 'unit', 'units');
$$;


