CREATE OR REPLACE FUNCTION "public"."product_write_allowed"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_user_org_id uuid;
  v_user_tenant_id uuid;
  v_user_brand_id uuid;
  v_user_location_id uuid;
  v_target_tenant_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT
    public.normalize_app_role(p.role),
    p.organization_id,
    p.tenant_id,
    p.brand_id,
    p.location_id
    INTO v_role, v_user_org_id, v_user_tenant_id, v_user_brand_id, v_user_location_id
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_user_tenant_id IS NULL AND v_user_org_id IS NOT NULL THEN
    SELECT o.tenant_id INTO v_user_tenant_id
    FROM public.organizations o
    WHERE o.id = v_user_org_id;
  END IF;

  SELECT o.tenant_id INTO v_target_tenant_id
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_user_tenant_id IS NOT NULL AND v_target_tenant_id = v_user_tenant_id;
  END IF;

  IF v_user_org_id IS DISTINCT FROM p_organization_id THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN p_brand_id IS NULL OR v_user_brand_id = p_brand_id;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN p_location_id IS NULL OR v_user_location_id = p_location_id;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."product_write_allowed"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_profile_security_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role OR
     NEW.organization_id IS DISTINCT FROM OLD.organization_id OR
     NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR
     NEW.brand_id IS DISTINCT FROM OLD.brand_id OR
     NEW.location_id IS DISTINCT FROM OLD.location_id OR
     NEW.access_level IS DISTINCT FROM OLD.access_level OR
     NEW.access_permissions IS DISTINCT FROM OLD.access_permissions OR
     NEW.invoice_approval_limit IS DISTINCT FROM OLD.invoice_approval_limit OR
     NEW.has_unlimited_approval IS DISTINCT FROM OLD.has_unlimited_approval THEN

    IF current_setting('role') IN ('authenticated', 'anon')
       AND current_setting('app.trusted_profile_write', true) IS DISTINCT FROM 'on' THEN
       RAISE EXCEPTION '42501: Privilege escalation attempt detected. You cannot modify roles, permissions, approval limits, or organization bindings.'
         USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_profile_security_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_approved_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- If status changed to approved and it's not already in the queue
    IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
        INSERT INTO public.accounting_export_queue (
            organization_id,
            entity_type,
            entity_id,
            status
        ) VALUES (
            NEW.organization_id,
            'invoice',
            NEW.id,
            'ready'
        ) ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


