CREATE OR REPLACE FUNCTION "public"."queue_edi_transmission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Only queue for approved orders that are being sent
    IF NEW.status = 'sent' AND OLD.status != 'sent' THEN
        -- Insert a pending EDI transmission log
        INSERT INTO public.edi_transmissions (
            organization_id,
            order_id,
            payload,
            status
        ) VALUES (
            NEW.organization_id,
            NEW.id,
            jsonb_build_object(
                'po_number', NEW.order_number,
                'vendor', NEW.vendor_name,
                'total', NEW.total_amount,
                'items', NEW.items,
                'timestamp', now()
            ),
            'pending'
        );
    END IF;
    RETURN NEW;
END;
$$;


