CREATE OR REPLACE FUNCTION "public"."queue_webhook_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_type TEXT;
    v_org_id UUID;
    v_payload JSONB;
    v_table_name TEXT;
BEGIN
    SELECT relname INTO v_table_name FROM pg_class WHERE oid = pg_partition_root(TG_RELID);
    v_event_type := COALESCE(v_table_name, TG_TABLE_NAME) || '.' || lower(TG_OP);

    IF TG_OP = 'DELETE' THEN
        v_payload := row_to_json(OLD)::jsonb;
    ELSE
        v_payload := row_to_json(NEW)::jsonb;
    END IF;

    -- Try to get organization_id from the record
    BEGIN
        v_org_id := (v_payload->>'organization_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN COALESCE(NEW, OLD); -- Skip if no organization_id
    END;

    IF v_org_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Find endpoints subscribed to this event or '*'
    INSERT INTO public.webhook_events_queue (organization_id, endpoint_id, event_type, payload)
    SELECT we.organization_id, we.id, v_event_type, v_payload
    FROM public.webhook_endpoints we
    JOIN public.webhook_subscriptions ws ON we.id = ws.endpoint_id
    WHERE we.organization_id = v_org_id
      AND we.status = 'active'
      AND (ws.event_type = v_event_type OR ws.event_type = '*');

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."queue_webhook_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_recipe_cost_tree"("p_recipe_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid;
  v_total numeric := 0;
  v_yield numeric := 1;
  v_unit text := 'each';
  v_version integer;
  v_parent record;
begin
  select organization_id into v_org from public.recipes where id = p_recipe_id;
  if v_org is null or v_org <> public.get_my_org() then raise exception 'Recipe is outside the active organization'; end if;

  select coalesce(sum(coalesce(unit_cost_snapshot,0) * quantity / nullif(yield_percentage / 100.0,0)),0)
    into v_total from public.recipe_ingredients where recipe_id = p_recipe_id;
  select quantity, unit into v_yield, v_unit from public.recipe_yields
    where recipe_id = p_recipe_id and is_primary order by created_at limit 1;
  v_yield := coalesce(nullif(v_yield,0),1);

  update public.recipes set total_ingredient_cost=v_total, total_cost=v_total,
    cost_per_serving=v_total/v_yield, costing_version=costing_version+1, last_costed_at=now(), updated_at=now()
    where id=p_recipe_id returning costing_version into v_version;
  update public.recipe_yields set cost_per_unit=v_total/nullif(quantity,0), updated_at=now()
    where recipe_id=p_recipe_id;
  insert into public.recipe_cost_snapshots(organization_id,recipe_id,costing_version,total_cost,primary_yield_quantity,primary_yield_unit,cost_per_yield_unit,ingredient_snapshot)
    select v_org,p_recipe_id,v_version,v_total,v_yield,v_unit,v_total/v_yield,
      coalesce((select jsonb_agg(to_jsonb(ri) order by sort_order) from public.recipe_ingredients ri where ri.recipe_id=p_recipe_id),'[]'::jsonb);

  for v_parent in select distinct recipe_id from public.recipe_ingredients where sub_recipe_id=p_recipe_id loop
    update public.recipe_ingredients ri set unit_cost_snapshot=r.cost_per_serving, updated_at=now()
      from public.recipes r where ri.recipe_id=v_parent.recipe_id and ri.sub_recipe_id=r.id;
    perform public.recalculate_recipe_cost_tree(v_parent.recipe_id);
  end loop;
end;
$$;


ALTER FUNCTION "public"."recalculate_recipe_cost_tree"("p_recipe_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_recipe_costs_on_price_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.recipes r
     SET total_cost = COALESCE((
           SELECT sum(COALESCE(ri.quantity, 0) * COALESCE(NEW.latest_price, 0))
           FROM public.recipe_ingredients ri
           WHERE ri.recipe_id = r.id
             AND ri.product_id = NEW.id
         ), r.total_cost),
         cost_per_serving = CASE
           WHEN COALESCE(r.yield_quantity, 0) > 0 THEN COALESCE((
             SELECT sum(COALESCE(ri.quantity, 0) * COALESCE(NEW.latest_price, 0))
             FROM public.recipe_ingredients ri
             WHERE ri.recipe_id = r.id
               AND ri.product_id = NEW.id
           ), r.total_cost) / r.yield_quantity
           ELSE r.cost_per_serving
         END,
         updated_at = now()
   WHERE EXISTS (
     SELECT 1 FROM public.recipe_ingredients ri
     WHERE ri.recipe_id = r.id
       AND ri.product_id = NEW.id
   );

  UPDATE public.recipes r
     SET total_cost = public.calculate_recipe_cost(r.id),
         updated_at = now()
   WHERE r.ingredients @> jsonb_build_array(jsonb_build_object('product_id', NEW.id::text));

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."recalculate_recipe_costs_on_price_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_purchase_order"("p_organization_id" "uuid", "p_location_id" "uuid", "p_order_id" "uuid", "p_received_quantities" "jsonb", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_order record;
  v_item jsonb;
  v_expected numeric;
  v_received numeric;
  v_key text;
  v_receiving_items jsonb := '[]'::jsonb;
  v_has_discrepancy boolean := false;
  v_has_short boolean := false;
  v_order_status text;
  v_receiving_status text;
  v_receiving_id uuid;
  v_inventory_id uuid;
  v_unit text;
  v_unit_cost numeric;
  v_previous_quantity numeric;
  v_previous_value numeric;
  v_current_inventory public.inventory;
  v_product_uuid uuid;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_location_id, true);

  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location is required to receive a purchase order';
  END IF;

  SELECT * INTO v_order
  FROM public.auto_orders
  WHERE id = p_order_id
    AND organization_id = p_organization_id
    AND location_id = p_location_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Order not found for active location';
  END IF;

  IF COALESCE(v_order.status, '') IN ('received', 'partially_received') OR EXISTS (
    SELECT 1 FROM public.receivings r
    WHERE r.organization_id = p_organization_id
      AND r.order_id = p_order_id
  ) THEN
    RAISE EXCEPTION 'Purchase order has already been received';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_order.items)
  LOOP
    v_key := COALESCE(v_item->>'product_id', v_item->>'inventory_id', v_item->>'product_name');
    v_expected := COALESCE((v_item->>'approved_quantity')::numeric, (v_item->>'suggested_quantity')::numeric, (v_item->>'quantity')::numeric, 0);
    v_received := CASE WHEN p_received_quantities ? v_key THEN (p_received_quantities->>v_key)::numeric ELSE v_expected END;
    v_has_discrepancy := v_has_discrepancy OR v_received <> v_expected;
    v_has_short := v_has_short OR v_received < v_expected;
    v_receiving_items := v_receiving_items || jsonb_build_object(
      'product_id', v_item->>'product_id',
      'inventory_id', v_item->>'inventory_id',
      'product_name', v_item->>'product_name',
      'unit', COALESCE(v_item->>'unit', 'ea'),
      'unit_price', COALESCE((v_item->>'unit_price')::numeric, (v_item->>'price')::numeric, 0),
      'expected_quantity', v_expected,
      'received_quantity', v_received,
      'discrepancy', v_expected - v_received,
      'receiving_status', CASE WHEN v_received = v_expected THEN 'matched' WHEN v_received > v_expected THEN 'over' ELSE 'short' END
    );
  END LOOP;

  v_order_status := CASE WHEN v_has_short THEN 'partially_received' ELSE 'received' END;
  v_receiving_status := CASE WHEN v_has_discrepancy THEN 'discrepancy' ELSE 'received' END;

  INSERT INTO public.receivings (
    organization_id, location_id, order_id, vendor_id, status, items, received_by, received_date
  ) VALUES (
    p_organization_id, p_location_id, p_order_id, v_order.vendor_id, v_receiving_status,
    v_receiving_items, COALESCE(p_user_id, auth.uid()), now()
  )
  RETURNING id INTO v_receiving_id;

  UPDATE public.auto_orders
     SET status = v_order_status,
         last_workflow_step = CASE WHEN v_has_discrepancy THEN 'receiving_discrepancy' ELSE 'received' END,
         updated_at = now()
   WHERE id = p_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_receiving_items)
  LOOP
    v_received := (v_item->>'received_quantity')::numeric;
    IF v_received <= 0 THEN
      CONTINUE;
    END IF;

    v_unit := COALESCE(v_item->>'unit', 'ea');
    v_unit_cost := COALESCE((v_item->>'unit_price')::numeric, 0);
    v_product_uuid := CASE WHEN COALESCE(v_item->>'product_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_item->>'product_id')::uuid ELSE NULL END;
    v_current_inventory := NULL;

    IF v_item ? 'inventory_id' AND NULLIF(v_item->>'inventory_id', '') IS NOT NULL THEN
      SELECT * INTO v_current_inventory
      FROM public.inventory
      WHERE id = (v_item->>'inventory_id')::uuid
        AND organization_id = p_organization_id
        AND location_id = p_location_id
        AND deleted_at IS NULL
      FOR UPDATE;
    END IF;

    IF v_current_inventory.id IS NULL AND NULLIF(v_item->>'product_id', '') IS NOT NULL THEN
      SELECT * INTO v_current_inventory
      FROM public.inventory
      WHERE organization_id = p_organization_id
        AND location_id = p_location_id
        AND deleted_at IS NULL
        AND (
          product_id = v_item->>'product_id'
          OR internal_product_id = v_product_uuid
        )
      ORDER BY CASE WHEN internal_product_id = v_product_uuid THEN 0 ELSE 1 END, created_at
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_current_inventory.id IS NULL THEN
      SELECT * INTO v_current_inventory
      FROM public.inventory
      WHERE lower(product_name) = lower(v_item->>'product_name')
        AND organization_id = p_organization_id
        AND location_id = p_location_id
        AND deleted_at IS NULL
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_current_inventory.id IS NOT NULL THEN
      v_inventory_id := v_current_inventory.id;
      v_previous_quantity := COALESCE(v_current_inventory.current_quantity, 0);
      v_previous_value := COALESCE(v_current_inventory.current_value, 0);

      UPDATE public.inventory
         SET current_quantity = v_previous_quantity + v_received,
             unit_cost = CASE
               WHEN (v_previous_quantity + v_received) > 0
               THEN ((v_previous_quantity * COALESCE(unit_cost, 0)) + (v_received * COALESCE(NULLIF(v_unit_cost, 0), unit_cost, 0))) / (v_previous_quantity + v_received)
               ELSE COALESCE(NULLIF(v_unit_cost, 0), unit_cost, 0)
             END,
             current_value = (v_previous_quantity + v_received) * CASE
               WHEN (v_previous_quantity + v_received) > 0
               THEN ((v_previous_quantity * COALESCE(unit_cost, 0)) + (v_received * COALESCE(NULLIF(v_unit_cost, 0), unit_cost, 0))) / (v_previous_quantity + v_received)
               ELSE COALESCE(NULLIF(v_unit_cost, 0), unit_cost, 0)
             END,
             previous_quantity = v_previous_quantity,
             previous_value = v_previous_value,
             updated_at = now()
       WHERE id = v_inventory_id;
    ELSE
      v_previous_quantity := 0;
      INSERT INTO public.inventory (
        organization_id, brand_id, location_id, product_id, internal_product_id, product_name,
        current_quantity, current_unit, unit_cost, current_value, accounting_category,
        par_level, reorder_point, previous_quantity, previous_value
      ) VALUES (
        p_organization_id, v_order.brand_id, p_location_id,
        COALESCE(NULLIF(v_item->>'product_id', ''), 'PRD-' || extract(epoch from now())::text),
        v_product_uuid, v_item->>'product_name', v_received, v_unit, v_unit_cost,
        v_received * v_unit_cost, 'food', 0, 0, 0, 0
      )
      RETURNING id INTO v_inventory_id;
    END IF;

    INSERT INTO public.receiving_items (
      receiving_id, organization_id, location_id, product_id, quantity_received,
      expected_quantity, discrepancy_quantity, unit, unit_cost, status
    ) VALUES (
      v_receiving_id, p_organization_id, p_location_id, v_product_uuid, v_received,
      COALESCE((v_item->>'expected_quantity')::numeric, 0),
      COALESCE((v_item->>'discrepancy')::numeric, 0),
      v_unit, v_unit_cost, v_item->>'receiving_status'
    );

    INSERT INTO public.inventory_movements (
      organization_id, location_id, inventory_id, movement_type, quantity,
      source_type, source_id, previous_quantity, new_quantity, created_by
    ) VALUES (
      p_organization_id, p_location_id, v_inventory_id, 'purchase_order',
      v_received, 'receiving', v_receiving_id, v_previous_quantity,
      v_previous_quantity + v_received, COALESCE(p_user_id, auth.uid())
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'receiving_id', v_receiving_id, 'has_discrepancy', v_has_discrepancy, 'order_status', v_order_status);
END;
$_$;


ALTER FUNCTION "public"."receive_purchase_order"("p_organization_id" "uuid", "p_location_id" "uuid", "p_order_id" "uuid", "p_received_quantities" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recipe_dependency_would_cycle"("p_recipe_id" "uuid", "p_candidate_child_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with recursive descendants(id) as (
    select p_candidate_child_id
    union
    select ri.sub_recipe_id
    from public.recipe_ingredients ri join descendants d on ri.recipe_id = d.id
    where ri.sub_recipe_id is not null
      and ri.organization_id = public.get_my_org()
  )
  select p_recipe_id = p_candidate_child_id or exists(select 1 from descendants where id = p_recipe_id);
$$;


ALTER FUNCTION "public"."recipe_dependency_would_cycle"("p_recipe_id" "uuid", "p_candidate_child_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_invoice_lines"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id UUID;
  v_po_id UUID;
  v_line RECORD;
  v_match JSONB;
  v_status TEXT;
  v_reconciled_count INTEGER := 0;
  v_variance_count INTEGER := 0;
BEGIN
  SELECT organization_id, purchase_order_id
    INTO v_org_id, v_po_id
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  DELETE FROM public.invoice_line_matches
  WHERE invoice_line_id IN (
    SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id
  );

  DELETE FROM public.reconciliation_variances
  WHERE invoice_id = p_invoice_id;

  IF v_po_id IS NOT NULL THEN
    v_match := public.get_three_way_match_status(v_po_id);
    v_status := COALESCE(v_match->>'match_status', 'unmatched');
  ELSE
    v_match := jsonb_build_object('match_status', 'missing_po');
    v_status := 'missing_po';
  END IF;

  FOR v_line IN SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id LOOP
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (
      v_org_id,
      v_line.id,
      CASE WHEN v_status = 'matched' THEN 'exact' ELSE 'variance' END,
      CASE WHEN v_status = 'matched' THEN 1.0 ELSE 0.5 END
    );

    v_reconciled_count := v_reconciled_count + 1;

    IF v_status = 'missing_po' THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, COALESCE(v_line.total_price, 0), COALESCE(v_line.total_price, 0));
      v_variance_count := v_variance_count + 1;
    END IF;

    IF v_status IN ('price_variance', 'critical_variance') THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (
          v_org_id,
          p_invoice_id,
          v_line.id,
          'price',
          NULL,
          COALESCE(v_line.total_price, 0),
          COALESCE((v_match->>'variance_amount')::numeric, 0)
        );
      v_variance_count := v_variance_count + 1;
    END IF;

    IF v_status IN ('quantity_variance', 'critical_variance') THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (
          v_org_id,
          p_invoice_id,
          v_line.id,
          'quantity',
          COALESCE((v_match->>'po_quantity')::numeric, 0),
          COALESCE((v_match->>'received_quantity')::numeric, 0),
          ABS(COALESCE((v_match->>'po_quantity')::numeric, 0) - COALESCE((v_match->>'received_quantity')::numeric, 0))
        );
      v_variance_count := v_variance_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'reconciled_lines', v_reconciled_count,
    'variance_count', v_variance_count,
    'match_status', v_status,
    'match', v_match
  );
END;
$$;


ALTER FUNCTION "public"."reconcile_invoice_lines"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_ad_hoc_vendor_payment"("p_vendor_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_memo" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_vendor RECORD;
  v_bill_id UUID;
  v_ledger_payment_id UUID;
  v_source_payment_id UUID;
  v_key TEXT;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  SELECT id, organization_id, name
    INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  PERFORM public.assert_financial_actor(v_vendor.organization_id);

  v_key := v_vendor.organization_id::TEXT || ':' || COALESCE(
    NULLIF(p_idempotency_key, ''),
    'ad-hoc-' || v_vendor.id::TEXT || '-' || p_amount::TEXT || '-' || COALESCE(p_memo, '')
  );
  v_source_payment_id := extensions.uuid_generate_v5('00000000-0000-0000-0000-000000000000'::UUID, v_key);

  SELECT id
    INTO v_ledger_payment_id
  FROM public.ledger_payments
  WHERE source_payment_id = v_source_payment_id
    AND organization_id = v_vendor.organization_id;

  IF v_ledger_payment_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'ledger_payment_id', v_ledger_payment_id, 'source_payment_id', v_source_payment_id, 'idempotent', true);
  END IF;

  INSERT INTO public.payments (
    id,
    organization_id,
    vendor_id,
    vendor_name,
    amount,
    status,
    payment_method,
    payment_date,
    notes,
    created_by
  ) VALUES (
    v_source_payment_id,
    v_vendor.organization_id,
    v_vendor.id,
    v_vendor.name,
    p_amount,
    'completed',
    COALESCE(NULLIF(p_payment_method, ''), 'manual'),
    CURRENT_DATE,
    p_memo,
    auth.uid()
  )
  ON CONFLICT (id) DO UPDATE
     SET updated_at = now()
  RETURNING id INTO v_source_payment_id;

  INSERT INTO public.ledger_bills (
    organization_id,
    vendor_id,
    invoice_id,
    subtotal,
    tax,
    total,
    due_date,
    status
  ) VALUES (
    v_vendor.organization_id,
    v_vendor.id,
    NULL,
    p_amount,
    0,
    p_amount,
    CURRENT_DATE,
    'paid'
  )
  RETURNING id INTO v_bill_id;

  INSERT INTO public.ledger_payments (
    organization_id,
    bill_id,
    payment_account_id,
    payment_method,
    amount,
    payment_date,
    status,
    created_by,
    source_payment_id
  ) VALUES (
    v_vendor.organization_id,
    v_bill_id,
    NULL,
    COALESCE(NULLIF(p_payment_method, ''), 'manual'),
    p_amount,
    now(),
    'completed',
    auth.uid(),
    v_source_payment_id
  )
  RETURNING id INTO v_ledger_payment_id;

  INSERT INTO public.ledger_entries (
    organization_id,
    account_code,
    debit,
    credit,
    reference_type,
    reference_id
  ) VALUES
    (v_vendor.organization_id, '2000', p_amount, 0, 'payment', v_ledger_payment_id),
    (v_vendor.organization_id, '1000', 0, p_amount, 'payment', v_ledger_payment_id);

  RETURN jsonb_build_object(
    'success', true,
    'ledger_payment_id', v_ledger_payment_id,
    'bill_id', v_bill_id,
    'source_payment_id', v_source_payment_id,
    'idempotent', false
  );
END;
$$;


ALTER FUNCTION "public"."record_ad_hoc_vendor_payment"("p_vendor_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_memo" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_ad_hoc_vendor_payment"("p_vendor_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_memo" "text", "p_idempotency_key" "text") IS 'Tenant-safe ad-hoc vendor payment RPC with deterministic source payment idempotency and valid ledger_payments.source_payment_id FK and canonical ledger entry reference type.';



CREATE OR REPLACE FUNCTION "public"."record_invoice_anomaly_review"("p_invoice_id" "uuid", "p_anomaly_type" "text", "p_decision" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_review_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_decision NOT IN ('opened_for_review', 'accepted_historical', 'finance_cleanup_requested') THEN
    RAISE EXCEPTION 'Unsupported invoice anomaly decision %', p_decision;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  INSERT INTO public.invoice_anomaly_reviews (
    invoice_id,
    organization_id,
    brand_id,
    location_id,
    anomaly_type,
    decision,
    notes,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
    p_decision,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_review_id;

  UPDATE public.invoices
     SET validation_results = COALESCE(validation_results, '{}'::jsonb)
       || jsonb_build_object(
            'invoice_anomaly_review',
            jsonb_build_object(
              'decision', p_decision,
              'anomaly_type', COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
              'reviewed_by', auth.uid(),
              'reviewed_at', now(),
              'notes', p_notes
            )
          ),
         updated_at = now()
   WHERE id = v_invoice.id;

  RETURN jsonb_build_object(
    'success', true,
    'review_id', v_review_id,
    'decision', p_decision
  );
END;
$$;


ALTER FUNCTION "public"."record_invoice_anomaly_review"("p_invoice_id" "uuid", "p_anomaly_type" "text", "p_decision" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_payment_method" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
  v_existing_payment_id UUID;
  v_remaining NUMERIC;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  IF NULLIF(trim(COALESCE(p_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Payment reference is required';
  END IF;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF v_invoice.status = 'rejected' OR v_invoice.ap_status = 'rejected' THEN
    RAISE EXCEPTION 'Rejected invoices cannot receive payments';
  END IF;

  SELECT id
    INTO v_existing_payment_id
  FROM public.payments
  WHERE invoice_id = p_invoice_id
    AND transaction_id = p_reference
    AND COALESCE(status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
  LIMIT 1;

  IF v_existing_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'Payment reference % has already been recorded for this invoice', p_reference;
  END IF;

  IF NOT public.is_invoice_payment_ready(
    v_invoice.status,
    v_invoice.ap_status,
    v_invoice.payment_status,
    v_invoice.paid_amount,
    v_invoice.total_amount
  ) THEN
    RAISE EXCEPTION 'Invoice must be approved and unpaid before recording payment';
  END IF;

  v_remaining := GREATEST(0, COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0));
  IF p_amount > v_remaining THEN
    RAISE EXCEPTION 'Payment amount % exceeds remaining balance %', p_amount, v_remaining;
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  v_new_status := CASE
    WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE public.invoices
     SET paid_amount = v_new_paid_amount,
         payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
         status = v_new_status,
         ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
         payment_reference = p_reference,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id, vendor_id, vendor_name, invoice_number, amount, payment_method,
    status, transaction_id, payment_date, payment_account_id, organization_id,
    brand_id, location_id, created_by
  ) VALUES (
    v_invoice.id, v_invoice.vendor_id, v_invoice.vendor_name,
    v_invoice.invoice_number, p_amount, p_payment_method, 'completed',
    p_reference, CURRENT_DATE, v_invoice.payment_account_id,
    v_invoice.organization_id, v_invoice.brand_id, v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  PERFORM public.log_invoice_audit_event(
    v_invoice.id,
    'payment_recorded',
    'Payment recorded through tenant-safe financial RPC',
    to_jsonb(v_invoice),
    jsonb_build_object(
      'payment_id', v_payment_id,
      'amount', p_amount,
      'payment_method', p_payment_method,
      'reference', p_reference,
      'status', v_new_status
    )
  );

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;


ALTER FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_payment_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_validation_state_on_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_failures text[];
BEGIN
  IF COALESCE(NEW.status, '') NOT IN ('pending_approval', 'approved')
     AND COALESCE(NEW.ap_status, '') NOT IN ('pending_approval', 'approved') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND COALESCE(OLD.status, '') = COALESCE(NEW.status, '')
     AND COALESCE(OLD.ap_status, '') = COALESCE(NEW.ap_status, '') THEN
    RETURN NEW;
  END IF;

  v_failures := public.invoice_hard_validation_failures(NEW.id);

  NEW.validation_results := COALESCE(NEW.validation_results, '{}'::jsonb)
    || jsonb_build_object(
      'approval_validation_checked_at', now(),
      'approval_validation_failures', to_jsonb(v_failures),
      'approval_validation_acknowledgement_required', COALESCE(array_length(v_failures, 1), 0) > 0
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."record_invoice_validation_state_on_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_onboarding_event"("p_run_id" "uuid", "p_user_id" "uuid", "p_step_key" "text", "p_event_type" "text", "p_status" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.profiles
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_step_events (
    run_id,
    user_id,
    organization_id,
    step_key,
    event_type,
    status,
    metadata
  )
  VALUES (
    p_run_id,
    p_user_id,
    v_org_id,
    p_step_key,
    p_event_type,
    p_status,
    COALESCE(p_metadata, '{}'::jsonb)
  );

  UPDATE public.onboarding_workflow_runs
  SET current_step = p_step_key,
      organization_id = COALESCE(organization_id, v_org_id),
      last_activity_at = now(),
      metadata = metadata || jsonb_build_object('last_event', p_event_type)
  WHERE id = p_run_id;
END;
$$;


ALTER FUNCTION "public"."record_onboarding_event"("p_run_id" "uuid", "p_user_id" "uuid", "p_step_key" "text", "p_event_type" "text", "p_status" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payment_ledger"("p_organization_id" "uuid", "p_bill_id" "uuid", "p_source_payment_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_payment_date" timestamp with time zone, "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_ledger_payment_id UUID;
BEGIN
  IF NOT public.is_platform_admin() AND NOT (public.is_manager_or_above() AND public.get_my_org() = p_organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT id INTO v_ledger_payment_id
  FROM public.ledger_payments
  WHERE source_payment_id = p_source_payment_id;

  IF v_ledger_payment_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'ledger_payment_id', v_ledger_payment_id,
      'message', 'Payment already recorded.'
    );
  END IF;

  INSERT INTO public.ledger_payments (
    organization_id, bill_id, source_payment_id, payment_method,
    amount, payment_date, status, created_by
  ) VALUES (
    p_organization_id, p_bill_id, p_source_payment_id, p_payment_method,
    p_amount, p_payment_date, 'completed', p_user_id
  )
  RETURNING id INTO v_ledger_payment_id;

  INSERT INTO public.ledger_entries (
    organization_id, account_code, debit, credit, reference_type, reference_id
  ) VALUES
    (p_organization_id, '2000', p_amount, 0, 'payment', p_source_payment_id),
    (p_organization_id, '1000', 0, p_amount, 'payment', p_source_payment_id);

  RETURN jsonb_build_object('success', true, 'ledger_payment_id', v_ledger_payment_id);
END;
$$;


ALTER FUNCTION "public"."record_payment_ledger"("p_organization_id" "uuid", "p_bill_id" "uuid", "p_source_payment_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_payment_date" timestamp with time zone, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payment_provider_event"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.payment_provider_events (
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    provider,
    provider_event_type,
    provider_event_ref,
    owner_type,
    owner_id,
    bank_account_id,
    payment_id,
    invoice_id,
    status,
    payload
  )
  VALUES (
    NULLIF(p_payload->>'tenant_id', '')::uuid,
    NULLIF(p_payload->>'organization_id', '')::uuid,
    NULLIF(p_payload->>'brand_id', '')::uuid,
    NULLIF(p_payload->>'location_id', '')::uuid,
    COALESCE(NULLIF(p_payload->>'provider', ''), 'internal'),
    COALESCE(NULLIF(p_payload->>'provider_event_type', ''), 'generic_event'),
    NULLIF(p_payload->>'provider_event_ref', ''),
    NULLIF(p_payload->>'owner_type', ''),
    NULLIF(p_payload->>'owner_id', '')::uuid,
    NULLIF(p_payload->>'bank_account_id', '')::uuid,
    NULLIF(p_payload->>'payment_id', '')::uuid,
    NULLIF(p_payload->>'invoice_id', '')::uuid,
    COALESCE(NULLIF(p_payload->>'status', ''), 'received'),
    COALESCE(p_payload->'payload', '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_payment_provider_event"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_recipe_margin_alert_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  old_cost numeric := coalesce(old.cost_per_serving, 0);
  new_cost numeric := coalesce(new.cost_per_serving, 0);
  old_price numeric := coalesce(old.selling_price, 0);
  new_price numeric := coalesce(new.selling_price, 0);
  old_target numeric := 100 - coalesce(old.target_margin_percent, 70);
  new_target numeric := 100 - coalesce(new.target_margin_percent, 70);
  old_plate numeric := case when old_price > 0 then old_cost / old_price * 100 else null end;
  new_plate numeric := case when new_price > 0 then new_cost / new_price * 100 else null end;
  old_alert text := coalesce(old.margin_alert_status, case when coalesce(old.margin_alert_enabled, false) then 'active' else 'none' end);
  new_alert text := coalesce(new.margin_alert_status, case when coalesce(new.margin_alert_enabled, false) then 'active' else 'none' end);
  actor uuid := auth.uid();
begin
  if new_cost is distinct from old_cost then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'cost_changed', 'Unit cost changed', jsonb_build_object('cost', old_cost), jsonb_build_object('cost', new_cost), new_plate, new_target, actor);
  end if;

  if new_price is distinct from old_price then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'price_changed', 'Menu price changed', jsonb_build_object('price', old_price), jsonb_build_object('price', new_price), new_plate, new_target, actor);
  end if;

  if new_target is distinct from old_target then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'target_changed', 'Plate-cost target changed', jsonb_build_object('target_percent', old_target), jsonb_build_object('target_percent', new_target), new_plate, new_target, actor);
  end if;

  if new_alert is distinct from old_alert then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'monitoring_changed', 'Cost monitoring changed', jsonb_build_object('status', old_alert), jsonb_build_object('status', new_alert), new_plate, new_target, actor);
  end if;

  if new_alert = 'active' and new_plate is not null then
    if (old_alert <> 'active' or old_plate is null or old_plate <= old_target) and new_plate > new_target then
      insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
      values (new.organization_id, new.id, 'threshold_exceeded', 'Plate cost exceeded its configured target', jsonb_build_object('plate_cost_percent', old_plate, 'target_percent', old_target), jsonb_build_object('plate_cost_percent', new_plate, 'target_percent', new_target), new_plate, new_target, actor);
    elsif old_alert = 'active' and old_plate > old_target and new_plate <= new_target then
      insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
      values (new.organization_id, new.id, 'threshold_recovered', 'Plate cost returned within its configured target', jsonb_build_object('plate_cost_percent', old_plate, 'target_percent', old_target), jsonb_build_object('plate_cost_percent', new_plate, 'target_percent', new_target), new_plate, new_target, actor);
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."record_recipe_margin_alert_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redact_onboarding_audit_payload"("p_table_name" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_payload JSONB := COALESCE(p_payload, '{}'::jsonb);
BEGIN
  IF p_payload IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_table_name = 'profiles' THEN
    v_payload := v_payload - 'onboarding_draft';
    IF p_payload ? 'onboarding_draft' THEN
      v_payload := v_payload || jsonb_build_object('onboarding_draft_redacted', true);
    END IF;
  END IF;

  IF p_table_name = 'onboarding_contact_otps' THEN
    v_payload := v_payload - 'code_hash' - 'provider_reference_id';
  END IF;

  IF p_table_name = 'tenant_payment_authorizations' THEN
    v_payload := v_payload - 'signature_payload' - 'signature_storage_path' - 'consent_text';
  END IF;

  IF p_table_name = 'onboarding_bank_accounts' THEN
    v_payload := v_payload - 'banking_secret_id';
  END IF;

  IF p_table_name = 'invitations' THEN
    v_payload := v_payload - 'token' - 'invite_token' - 'invitation_token' - 'raw_token';
  END IF;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."redact_onboarding_audit_payload"("p_table_name" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reference_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
  v_active_location_brand_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  -- Tenant / organization isolation: never leak across organizations.
  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM v_org_id THEN
    RETURN false;
  END IF;

  -- Organization-level reference row (shared across the org catalog).
  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN true;
  END IF;

  -- Brand-shared and location-specific rows still require an active location.
  IF v_location_id IS NULL THEN
    RETURN false;
  END IF;

  -- Location-specific reference row: exact match.
  IF p_location_id IS NOT NULL THEN
    RETURN p_location_id = v_location_id;
  END IF;

  -- Brand-shared reference row (location intentionally NULL): visible when it matches the
  -- brand of the caller's currently active location.
  IF p_brand_id IS NOT NULL THEN
    SELECT l.brand_id INTO v_active_location_brand_id
    FROM public.locations l
    WHERE l.id = v_location_id;

    RETURN p_brand_id IS NOT NULL AND p_brand_id = v_active_location_brand_id;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."reference_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_deleted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reference_scope_writable"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_role_required" "text" DEFAULT 'ground_staff'::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  v_role := public.get_auth_role();

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    RETURN public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id);
  END IF;

  IF p_organization_id IS DISTINCT FROM public.get_auth_org() THEN
    RETURN false;
  END IF;

  IF p_location_id IS NOT NULL THEN
    IF v_role NOT IN ('location_manager', 'branch_manager', 'org_manager') THEN
      RETURN false;
    END IF;

    IF p_role_required = 'branch_manager' AND v_role = 'location_manager' THEN
      RETURN false;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.locations l
      WHERE l.id = p_location_id
        AND l.organization_id = p_organization_id
        AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
    ) THEN
      RETURN false;
    END IF;

    RETURN p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id);
  END IF;

  IF p_brand_id IS NOT NULL THEN
    IF v_role NOT IN ('branch_manager', 'org_manager') THEN
      RETURN false;
    END IF;

    RETURN p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."reference_scope_writable"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_deleted_at" timestamp with time zone, "p_role_required" "text") OWNER TO "postgres";


