CREATE OR REPLACE FUNCTION "public"."refresh_vendor_item_mapping_status"("p_vendor_item_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_verified_count INTEGER;
  v_suggested_count INTEGER;
BEGIN
  SELECT
    COUNT(*) FILTER (WHERE is_verified = true),
    COUNT(*)
  INTO v_verified_count, v_suggested_count
  FROM public.vendor_item_mappings
  WHERE vendor_item_id = p_vendor_item_id;

  UPDATE public.vendor_items
  SET mapping_status = CASE
      WHEN v_verified_count > 0 THEN 'verified'
      WHEN v_suggested_count > 0 THEN 'suggested'
      ELSE 'unmapped'
    END,
    updated_at = now()
  WHERE id = p_vendor_item_id;
END;
$$;


ALTER FUNCTION "public"."refresh_vendor_item_mapping_status"("p_vendor_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_invoice_document"("p_storage_path" "text", "p_file_name" "text", "p_file_type" "text" DEFAULT NULL::"text", "p_file_size" bigint DEFAULT NULL::bigint, "p_file_hash" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'upload'::"text", "p_invoice_id" "uuid" DEFAULT NULL::"uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_document_id uuid;
BEGIN
  v_org_id := COALESCE(p_organization_id, public.get_my_org());

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  PERFORM public.assert_org_actor(v_org_id);

  IF p_storage_path IS NULL OR p_file_name IS NULL THEN
    RAISE EXCEPTION 'storage_path and file_name are required';
  END IF;

  INSERT INTO public.invoice_documents (
    organization_id, invoice_id, storage_path, file_name, file_type, file_size, file_hash, source, created_by
  ) VALUES (
    v_org_id, p_invoice_id, p_storage_path, p_file_name, p_file_type, p_file_size, p_file_hash, p_source, auth.uid()
  )
  RETURNING id INTO v_document_id;

  RETURN v_document_id;
END;
$$;


ALTER FUNCTION "public"."register_invoice_document"("p_storage_path" "text", "p_file_name" "text", "p_file_type" "text", "p_file_size" bigint, "p_file_hash" "text", "p_source" "text", "p_invoice_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reissue_owner_invitation"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_old public.invitations%ROWTYPE;
  v_new public.invitations%ROWTYPE;
  v_token TEXT := encode(gen_random_bytes(32), 'hex');
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT * INTO v_old FROM public.invitations WHERE id = p_invitation_id;
  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  UPDATE public.invitations SET closed_at = now() WHERE id = p_invitation_id;

  INSERT INTO public.invitations (
    tenant_id, organization_id, email, role, token, invited_by, expires_at, metadata, status
  )
  VALUES (
    v_old.tenant_id,
    v_old.organization_id,
    v_old.email,
    v_old.role,
    v_token,
    auth.uid(),
    now() + interval '7 days',
    COALESCE(v_old.metadata, '{}'::jsonb) || jsonb_build_object('reissued_from', v_old.id),
    COALESCE(v_old.status, 'pending')
  )
  RETURNING * INTO v_new;

  RETURN jsonb_build_object('success', true, 'invitation_id', v_new.id, 'token', v_new.token, 'expires_at', v_new.expires_at);
END;
$$;


ALTER FUNCTION "public"."reissue_owner_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_business_verification"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required';
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'rejected',
      rejection_reason = p_reason,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('admin_reason', p_reason),
      updated_at = now()
  WHERE id = (
    SELECT id FROM public.business_verifications
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 1
  );

  UPDATE public.profiles
  SET business_verification_status = 'rejected',
      onboarding_status = 'blocked',
      onboarding_current_step = 'business_verification',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'reject_business_verification', p_reason);

  -- Notification is handled by trg_notify_business_verification_review_state (fires on the
  -- verification_status UPDATE above) -- do not insert one here too, or the tenant gets two.

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'business_verification', 'admin_rejected', 'rejected', jsonb_build_object('actor_user_id', v_actor, 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$$;


ALTER FUNCTION "public"."reject_business_verification"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_onboarding_hierarchy"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required';
  END IF;

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'rejected', rejection_reason = p_reason, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  UPDATE public.profiles
  SET hierarchy_review_status = 'rejected',
      onboarding_status = 'blocked',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Workspace setup rejected', p_reason, false);

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'admin_rejected', 'rejected', jsonb_build_object('actor_user_id', auth.uid(), 'reason', p_reason));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$$;


ALTER FUNCTION "public"."reject_onboarding_hierarchy"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


