CREATE OR REPLACE FUNCTION "public"."reject_product_change"("p_product_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT v_existing.pending_approval THEN
    RAISE EXCEPTION 'This product has no pending change to reject';
  END IF;

  IF public.get_auth_role() NOT IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to reject product changes';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to reject this product change';
  END IF;

  IF v_existing.pending_action = 'create' THEN
    -- Undo the creation: soft-delete it, there's no prior state to revert to.
    UPDATE public.products SET
      deleted_at = now(), deleted_by = auth.uid(),
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSIF v_existing.pending_action = 'update' THEN
    -- Revert every column back to the pre-change snapshot.
    UPDATE public.products SET
      name = (v_existing.pending_snapshot->>'name'),
      product_id = (v_existing.pending_snapshot->>'product_id'),
      description = (v_existing.pending_snapshot->>'description'),
      category = (v_existing.pending_snapshot->>'category'),
      accounting_category = (v_existing.pending_snapshot->>'accounting_category'),
      is_inventoried = (v_existing.pending_snapshot->>'is_inventoried')::boolean,
      is_tax_exempt = (v_existing.pending_snapshot->>'is_tax_exempt')::boolean,
      report_by_unit = (v_existing.pending_snapshot->>'report_by_unit'),
      base_unit = (v_existing.pending_snapshot->>'base_unit'),
      latest_price = (v_existing.pending_snapshot->>'latest_price')::numeric,
      location_specific = (v_existing.pending_snapshot->>'location_specific')::boolean,
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSE
    -- pending delete rejected: cancel the delete request, product stays as-is.
    UPDATE public.products SET
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  END IF;

  IF p_reason IS NOT NULL THEN
    PERFORM public.log_audit_event(jsonb_build_object(
      'organization_id', v_existing.organization_id,
      'user_id', auth.uid(),
      'action', 'product_change_rejected',
      'table_name', 'products',
      'record_id', p_product_id::text,
      'entity_type', 'product',
      'entity_id', p_product_id::text,
      'details', jsonb_build_object('reason', p_reason, 'rejected_action', v_existing.pending_action)
    ));
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."reject_product_change"("p_product_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_invoice_funds"("p_invoice_id" "uuid", "p_payout_method" "text" DEFAULT 'dwolla_ach'::"text", "p_payment_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
  v_payment_method TEXT;
  v_final_account_id UUID;
  v_payment_id UUID;
  v_account_org UUID;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'processing', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Invoice is already paid or processing';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before releasing funds';
  END IF;

  v_final_account_id := COALESCE(p_payment_account_id, v_invoice.payment_account_id);

  IF v_final_account_id IS NULL THEN
    RAISE EXCEPTION 'A payment account is required to release funds';
  END IF;

  SELECT organization_id
    INTO v_account_org
  FROM public.payment_accounts
  WHERE id = v_final_account_id
    AND is_active IS DISTINCT FROM false;

  IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_invoice.organization_id THEN
    RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
  END IF;

  IF p_payout_method = 'dwolla_ach' THEN
    v_payment_method := 'bank_transfer';
  ELSIF p_payout_method IN ('checkbook_digital', 'checkbook_physical') THEN
    v_payment_method := 'check';
  ELSE
    RAISE EXCEPTION 'Invalid payout method';
  END IF;

  UPDATE public.invoices
     SET payment_status = 'processing',
         status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
         payment_account_id = v_final_account_id,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    payout_status,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0),
    v_payment_method,
    'pending',
    'processing',
    CURRENT_DATE,
    v_final_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'invoice_id', p_invoice_id,
    'organization_id', v_invoice.organization_id,
    'payment_id', v_payment_id,
    'payout_method', p_payout_method
  );
END;
$$;


ALTER FUNCTION "public"."release_invoice_funds"("p_invoice_id" "uuid", "p_payout_method" "text", "p_payment_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_product_barcode"("p_barcode_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.product_barcodes%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.product_barcodes WHERE id = p_barcode_id AND deleted_at IS NULL;
  IF v_row.id IS NULL THEN
    RETURN true;
  END IF;
  IF NOT public.product_write_allowed(v_row.organization_id, v_row.brand_id, v_row.location_id) THEN
    RAISE EXCEPTION 'Not authorized to remove product barcodes';
  END IF;
  UPDATE public.product_barcodes
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_barcode_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."remove_product_barcode"("p_barcode_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_product_count_unit"("p_count_unit_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count_unit public.product_count_units%ROWTYPE;
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_count_unit
  FROM public.product_count_units
  WHERE id = p_count_unit_id
    AND deleted_at IS NULL;

  IF v_count_unit.id IS NULL THEN
    RETURN true;
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = v_count_unit.product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  UPDATE public.product_count_units
     SET deleted_at = now(),
         is_active = false,
         updated_at = now()
   WHERE id = p_count_unit_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."remove_product_count_unit"("p_count_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_invoice_credit_workflow"("p_invoice_id" "uuid", "p_requested_amount" numeric, "p_reason" "text", "p_photo_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
  v_credit RECORD;
  v_new_total NUMERIC;
BEGIN
  IF COALESCE(p_requested_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Credit amount must be greater than zero';
  END IF;

  IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Credit reason is required';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_org_actor(v_invoice.organization_id);

  INSERT INTO public.credit_requests (
    organization_id,
    location_id,
    invoice_id,
    vendor_id,
    requested_amount,
    reason,
    photo_url,
    status,
    created_by
  ) VALUES (
    v_invoice.organization_id,
    v_invoice.location_id,
    v_invoice.id,
    v_invoice.vendor_id,
    p_requested_amount,
    trim(p_reason),
    p_photo_url,
    'pending',
    auth.uid()
  )
  RETURNING * INTO v_credit;

  v_new_total := GREATEST(0, COALESCE(v_invoice.total_amount, 0) - p_requested_amount);

  UPDATE public.invoices
     SET total_amount = v_new_total,
         status = 'needs_review',
         credit_applied = COALESCE(credit_applied, 0) + p_requested_amount,
         credit_reason = trim(p_reason),
         updated_at = now()
   WHERE id = v_invoice.id;

  INSERT INTO public.audit_logs (
    organization_id,
    user_id,
    action,
    table_name,
    record_id,
    details
  ) VALUES (
    v_invoice.organization_id,
    auth.uid(),
    'credit_request_created',
    'invoices',
    v_invoice.id,
    jsonb_build_object(
      'credit_request_id', v_credit.id,
      'requested_amount', p_requested_amount,
      'reason', trim(p_reason),
      'vendor_id', v_invoice.vendor_id
    )::TEXT
  );

  RETURN to_jsonb(v_credit);
END;
$$;


ALTER FUNCTION "public"."request_invoice_credit_workflow"("p_invoice_id" "uuid", "p_requested_amount" numeric, "p_reason" "text", "p_photo_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_invoice_credit_workflow"("p_invoice_id" "uuid", "p_requested_amount" numeric, "p_reason" "text", "p_photo_url" "text") IS 'Tenant-safe credit request workflow. Inserts credit request, short-pays invoice, and writes audit log atomically.';



