CREATE OR REPLACE FUNCTION "public"."request_onboarding_contact_otp"("p_channel" "text", "p_target" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  RAISE EXCEPTION 'Secure OTP delivery provider is not configured yet. Configure server-side email/SMS delivery before enabling onboarding contact OTP.';
END;
$$;


ALTER FUNCTION "public"."request_onboarding_contact_otp"("p_channel" "text", "p_target" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_onboarding_hierarchy_resubmit"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Tell the tenant what needs to change';
  END IF;

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'failed', rejection_reason = p_reason, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  UPDATE public.profiles
  SET hierarchy_review_status = 'failed',
      onboarding_status = 'blocked',
      onboarding_current_step = 'hierarchy_setup',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Workspace setup needs changes', p_reason, false);

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'more_info_requested', 'failed', jsonb_build_object('actor_user_id', auth.uid(), 'reason', p_reason));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'failed');
END;
$$;


ALTER FUNCTION "public"."request_onboarding_hierarchy_resubmit"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_onboarding_more_info"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'failed',
      rejection_reason = p_reason,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('more_info_reason', p_reason),
      updated_at = now()
  WHERE id = (
    SELECT id FROM public.business_verifications
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 1
  );

  UPDATE public.profiles
  SET business_verification_status = 'failed',
      onboarding_status = 'blocked',
      onboarding_current_step = 'business_verification',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'request_more_info', p_reason);

  -- Notification is handled by trg_notify_business_verification_review_state (fires on the
  -- verification_status UPDATE above) -- do not insert one here too, or the tenant gets two.

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'business_verification', 'more_info_requested', 'failed', jsonb_build_object('actor_user_id', v_actor, 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'status', 'failed');
END;
$$;


ALTER FUNCTION "public"."request_onboarding_more_info"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


