    AS $$
  SELECT CASE
    WHEN p_business_type IN ('sole_proprietor', 'independent_contractor') THEN 'ssn'
    ELSE 'ein'
  END;
$$;


ALTER FUNCTION "public"."required_tax_identifier_type_for_business_type"("p_business_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_onboarding_audit_org_id"("p_row" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_org_id UUID;
  v_user_id UUID;
BEGIN
  IF p_row ? 'organization_id'
     AND COALESCE(p_row->>'organization_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN (p_row->>'organization_id')::UUID;
  END IF;

  IF p_row ? 'user_id'
     AND COALESCE(p_row->>'user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_user_id := (p_row->>'user_id')::UUID;
  ELSIF p_row ? 'id'
     AND COALESCE(p_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_user_id := (p_row->>'id')::UUID;
  END IF;

  IF v_user_id IS NOT NULL THEN
    SELECT organization_id INTO v_org_id
    FROM public.profiles
    WHERE id = v_user_id;
  END IF;

  RETURN v_org_id;
END;
$_$;


ALTER FUNCTION "public"."resolve_onboarding_audit_org_id"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_payment_provider_config"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT public.is_platform_admin()
      AND p_organization_id IS NOT NULL
      AND p_organization_id != public.get_auth_org()
    THEN jsonb_build_object(
      'collection_provider', 'not_configured',
      'payout_provider', 'not_configured',
      'check_provider', 'checkbook',
      'enabled', false,
      'settings', '{}'::jsonb
    )
    ELSE COALESCE((
      SELECT jsonb_build_object(
        'id', ppc.id,
        'tenant_id', ppc.tenant_id,
        'organization_id', ppc.organization_id,
        'brand_id', ppc.brand_id,
        'location_id', ppc.location_id,
        'collection_provider', ppc.collection_provider,
        'payout_provider', ppc.payout_provider,
        'check_provider', ppc.check_provider,
        'enabled', ppc.enabled,
        'settings', ppc.settings
      )
      FROM public.payment_provider_configs ppc
      WHERE ppc.enabled = true
        AND ppc.deleted_at IS NULL
        AND (ppc.tenant_id IS NULL OR ppc.tenant_id = p_tenant_id)
        AND (ppc.organization_id IS NULL OR ppc.organization_id = p_organization_id)
        AND (ppc.brand_id IS NULL OR ppc.brand_id = p_brand_id)
        AND (ppc.location_id IS NULL OR ppc.location_id = p_location_id)
      ORDER BY
        CASE WHEN ppc.location_id IS NOT NULL THEN 1 ELSE 0 END DESC,
        CASE WHEN ppc.brand_id IS NOT NULL THEN 1 ELSE 0 END DESC,
        CASE WHEN ppc.organization_id IS NOT NULL THEN 1 ELSE 0 END DESC,
        CASE WHEN ppc.tenant_id IS NOT NULL THEN 1 ELSE 0 END DESC,
        ppc.updated_at DESC
      LIMIT 1
    ), jsonb_build_object(
      'collection_provider', 'not_configured',
      'payout_provider', 'not_configured',
      'check_provider', 'checkbook',
      'enabled', false,
      'settings', '{}'::jsonb
    ))
  END;
$$;


ALTER FUNCTION "public"."resolve_payment_provider_config"("p_tenant_id" "uuid", "p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_performance_location_timezone"("p_organization_id" "uuid", "p_location_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_timezone text;
BEGIN
  SELECT NULLIF(btrim(l.timezone), '')
    INTO v_timezone
  FROM public.locations l
  WHERE l.organization_id = p_organization_id
    AND l.id = p_location_id
    AND l.deleted_at IS NULL;

  IF v_timezone IS NULL THEN
    RETURN 'UTC';
  END IF;

  IF EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_timezone) THEN
    RETURN v_timezone;
  END IF;

  RETURN 'UTC';
END;
$$;


ALTER FUNCTION "public"."resolve_performance_location_timezone"("p_organization_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_price_variance"("p_vendor_item_id" "uuid", "p_update_product" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_vendor_item RECORD;
    v_product_id UUID;
BEGIN
    -- Get the vendor item
    SELECT * INTO v_vendor_item FROM public.vendor_items WHERE id = p_vendor_item_id;
    
    IF v_vendor_item IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vendor item not found');
    END IF;
    
    -- Clear the flag
    UPDATE public.vendor_items 
    SET price_variance_flag = false, updated_at = NOW() 
    WHERE id = p_vendor_item_id;
    
    -- Optionally update master product
    IF p_update_product THEN
        -- Find mapped internal product
        SELECT internal_product_id INTO v_product_id 
        FROM public.vendor_item_mappings 
        WHERE vendor_item_id = p_vendor_item_id 
        LIMIT 1;
        
        IF v_product_id IS NOT NULL THEN
            UPDATE public.products 
            SET latest_price = v_vendor_item.last_price, updated_at = NOW() 
            WHERE id = v_product_id;
        END IF;
    END IF;

    RETURN jsonb_build_object('success', true, 'updated_product_id', v_product_id);
END;
$$;


ALTER FUNCTION "public"."resolve_price_variance"("p_vendor_item_id" "uuid", "p_update_product" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_username_email"("p_username" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_normalized text := lower(btrim(p_username));
  v_email text;
BEGIN
  IF v_normalized IS NULL OR v_normalized = '' THEN
    RETURN NULL;
  END IF;

  SELECT email INTO v_email FROM public.profiles WHERE username = v_normalized LIMIT 1;
  RETURN v_email;
END;
$$;


ALTER FUNCTION "public"."resolve_username_email"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_product"("p_product_id" "uuid") RETURNS "public"."products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to restore this product';
  END IF;

  UPDATE public.products
     SET deleted_at = NULL,
         deleted_by = NULL,
         restored_at = now(),
         restored_by = auth.uid(),
         status = COALESCE(NULLIF(status, ''), 'active'),
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_product;

  UPDATE public.inventory
     SET deleted_at = NULL,
         deleted_by = NULL,
         updated_at = now()
   WHERE organization_id = v_product.organization_id
     AND (
       internal_product_id = v_product.id
       OR (NULLIF(product_id, '') IS NOT NULL AND product_id = v_product.product_id)
     );

  RETURN v_product;
END;
$$;


ALTER FUNCTION "public"."restore_product"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_vendor"("p_vendor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  -- deleted_at IS NOT NULL, so reference_scope_writable would reject it outright (a soft-deleted
  -- row is never writable) -- check org/brand/location authorization directly instead, the same
  -- way the scope helper would for an active row.
  SELECT * INTO v_vendor FROM public.vendors WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF v_vendor.deleted_at IS NULL THEN
    RAISE EXCEPTION 'Vendor is not archived';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendors SET deleted_at = NULL WHERE id = p_vendor_id;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type)
  VALUES (p_vendor_id, 'vendor_restored', auth.uid(), 'admin');
END;
$$;


ALTER FUNCTION "public"."restore_vendor"("p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reveal_my_tax_identifier"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret_id UUID;
  v_identifier_type TEXT;
  v_decrypted TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT tax_identifier_secret_id, identifier_type
  INTO v_secret_id, v_identifier_type
  FROM public.business_verifications
  WHERE user_id = v_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'No stored tax identifier to reveal';
  END IF;

  SELECT decrypted_secret INTO v_decrypted
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_decrypted IS NULL THEN
    RAISE EXCEPTION 'Stored tax identifier could not be decrypted';
  END IF;

  RETURN jsonb_build_object(
    'identifier_type', v_identifier_type,
    'full_identifier', (v_decrypted::jsonb)->>'full_identifier'
  );
END;
$$;


ALTER FUNCTION "public"."reveal_my_tax_identifier"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_vendor_tax_information"("p_tax_row_id" "uuid", "p_verification_status" "text", "p_verification_method" "text" DEFAULT 'manual_review'::"text", "p_failure_reason" "text" DEFAULT NULL::"text", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tax public.vendor_tax_information%ROWTYPE;
  v_status text := lower(btrim(COALESCE(p_verification_status, '')));
  v_method text := lower(btrim(COALESCE(p_verification_method, 'manual_review')));
BEGIN
  IF v_status NOT IN ('verified', 'failed', 'mismatch') THEN
    RAISE EXCEPTION 'Invalid tax verification status: %', p_verification_status;
  END IF;

  IF v_method NOT IN ('irs_tin_match', 'business_registry_lookup', 'manual_review') THEN
    RAISE EXCEPTION 'Invalid tax verification method: %', p_verification_method;
  END IF;

  SELECT * INTO v_tax
  FROM public.vendor_tax_information
  WHERE id = p_tax_row_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_tax.id IS NULL THEN
    RAISE EXCEPTION 'Vendor tax information not found';
  END IF;

  IF NOT public.reference_scope_writable(v_tax.organization_id, v_tax.brand_id, v_tax.location_id, v_tax.deleted_at, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_tax_information
     SET verification_status = v_status,
         verification_method = v_method,
         verification_checked_at = now(),
         verification_failure_reason = CASE WHEN v_status = 'verified' THEN NULL ELSE p_failure_reason END,
         w9_status = CASE WHEN v_status = 'verified' THEN 'verified' ELSE 'rejected' END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_tax_row_id
   RETURNING * INTO v_tax;

  IF v_tax.w9_document_id IS NOT NULL THEN
    UPDATE public.vendor_documents
       SET status = CASE WHEN v_status = 'verified' THEN 'on_file' ELSE 'rejected' END,
           reviewed_by = auth.uid(),
           reviewed_at = now(),
           review_notes = p_review_notes,
           updated_by = auth.uid(),
           updated_at = now()
     WHERE id = v_tax.w9_document_id;
  END IF;

  UPDATE public.vendors
     SET business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
         onboarding_status = CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
         updated_at = now()
   WHERE id = v_tax.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_tax.vendor_id,
    CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
    CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
    'admin',
    jsonb_build_object('tax_row_id', v_tax.id, 'verification_method', v_method)
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_tax.vendor_id,
    'tax_row_id', v_tax.id,
    'verification_status', v_tax.verification_status,
    'w9_status', v_tax.w9_status
  );
END;
$$;


ALTER FUNCTION "public"."review_vendor_tax_information"("p_tax_row_id" "uuid", "p_verification_status" "text", "p_verification_method" "text", "p_failure_reason" "text", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_custom_report"("p_metrics" "text"[], "p_dimension" "text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_modules" "text"[] DEFAULT NULL::"text"[], "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org UUID;
  v_start DATE := COALESCE(p_start_date, CURRENT_DATE - INTERVAL '30 days');
  v_end DATE := COALESCE(p_end_date, CURRENT_DATE);
  v_modules TEXT[] := COALESCE(NULLIF(p_modules, ARRAY[]::TEXT[]), ARRAY['invoices','payments','products','inventory','recipes','performance','audit_logs']);
  v_allowed_modules CONSTANT TEXT[] := ARRAY['invoices','payments','products','inventory','recipes','performance','audit_logs'];
  v_allowed_metrics CONSTANT TEXT[] := ARRAY[
    'invoice_count','invoice_total_amount','invoice_approved_count','invoice_unpaid_count','invoice_tax_amount',
    'payment_count','payment_amount','payment_completed_amount','payment_failed_count',
    'product_count','inventoried_product_count','avg_latest_price','products_with_price_count',
    'inventory_value','inventory_quantity','low_stock_count','inventory_waste','cogs',
    'recipe_count','avg_recipe_cost','avg_suggested_price','avg_cost_per_serving',
    'sales_revenue','pos_transaction_count','labor_cost','prime_cost','gross_profit',
    'audit_event_count','audit_insert_count','audit_update_count','audit_delete_count'
  ];
  v_result JSONB;
  v_bad TEXT;
BEGIN
  v_org := CASE WHEN auth.role() = 'service_role' THEN p_organization_id ELSE public.get_auth_org() END;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context is required';
  END IF;

  IF v_start > v_end THEN
    RAISE EXCEPTION 'start date must be on or before end date';
  END IF;

  IF p_dimension NOT IN ('date', 'week', 'month', 'location', 'status', 'category', 'module') THEN
    RAISE EXCEPTION 'unsupported report dimension: %', p_dimension;
  END IF;

  SELECT value INTO v_bad
  FROM unnest(v_modules) AS value
  WHERE value <> ALL(v_allowed_modules)
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'unsupported report module: %', v_bad;
  END IF;

  SELECT value INTO v_bad
  FROM unnest(COALESCE(p_metrics, ARRAY[]::TEXT[])) AS value
  WHERE value <> ALL(v_allowed_metrics)
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'unsupported report metric: %', v_bad;
  END IF;

  WITH invoice_rows AS (
    SELECT
      'invoices'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, NULLIF(i.location, ''), 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(i.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(i.source, ''), 'invoice')
        WHEN 'module' THEN 'Invoices'
      END AS dimension,
      jsonb_build_object(
        'invoice_count', COUNT(*)::NUMERIC,
        'invoice_total_amount', COALESCE(SUM(i.total_amount), 0)::NUMERIC,
        'invoice_approved_count', COUNT(*) FILTER (WHERE i.status IN ('approved','paid'))::NUMERIC,
        'invoice_unpaid_count', COUNT(*) FILTER (WHERE COALESCE(i.payment_status, 'unpaid') <> 'paid')::NUMERIC,
        'invoice_tax_amount', COALESCE(SUM(i.tax_amount), 0)::NUMERIC
      ) AS metrics
    FROM public.invoices i
    LEFT JOIN public.locations l ON l.id = i.location_id
    WHERE 'invoices' = ANY(v_modules)
      AND i.organization_id = v_org
      AND COALESCE(i.invoice_date, i.created_at::DATE) BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), payment_rows AS (
    SELECT
      'payments'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(p.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(p.payment_method, ''), 'payment')
        WHEN 'module' THEN 'Payments'
      END AS dimension,
      jsonb_build_object(
        'payment_count', COUNT(*)::NUMERIC,
        'payment_amount', COALESCE(SUM(p.amount), 0)::NUMERIC,
        'payment_completed_amount', COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'completed'), 0)::NUMERIC,
        'payment_failed_count', COUNT(*) FILTER (WHERE p.status = 'failed')::NUMERIC
      ) AS metrics
    FROM public.payments p
    LEFT JOIN public.locations l ON l.id = p.location_id
    WHERE 'payments' = ANY(v_modules)
      AND p.organization_id = v_org
      AND COALESCE(p.payment_date, p.created_at::DATE) BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), product_rows AS (
    SELECT
      'products'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(p.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', p.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', p.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Org Catalog')
        WHEN 'status' THEN COALESCE(NULLIF(p.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(p.category, ''), NULLIF(p.accounting_category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Products'
      END AS dimension,
      jsonb_build_object(
        'product_count', COUNT(*)::NUMERIC,
        'inventoried_product_count', COUNT(*) FILTER (WHERE COALESCE(p.is_inventoried, false))::NUMERIC,
        'avg_latest_price', COALESCE(AVG(p.latest_price), 0)::NUMERIC,
        'products_with_price_count', COUNT(*) FILTER (WHERE COALESCE(p.latest_price, 0) > 0)::NUMERIC
      ) AS metrics
    FROM public.products p
    LEFT JOIN public.locations l ON l.id = p.location_id
    WHERE 'products' = ANY(v_modules)
      AND p.organization_id = v_org
      AND p.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), inventory_rows AS (
    SELECT
      'inventory'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(inv.updated_at, inv.created_at)::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(inv.updated_at, inv.created_at)), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(inv.updated_at, inv.created_at)), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, NULLIF(inv.location, ''), 'Unassigned')
        WHEN 'status' THEN CASE WHEN COALESCE(inv.current_quantity, 0) <= COALESCE(inv.reorder_point, inv.par_level, 0) THEN 'low_stock' ELSE 'in_stock' END
        WHEN 'category' THEN COALESCE(NULLIF(inv.category, ''), NULLIF(inv.accounting_category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Inventory'
      END AS dimension,
      jsonb_build_object(
        'inventory_value', COALESCE(SUM(inv.current_value), 0)::NUMERIC,
        'inventory_quantity', COALESCE(SUM(inv.current_quantity), 0)::NUMERIC,
        'low_stock_count', COUNT(*) FILTER (WHERE COALESCE(inv.current_quantity, 0) <= COALESCE(inv.reorder_point, inv.par_level, 0))::NUMERIC,
        'inventory_waste', 0::NUMERIC,
        'cogs', 0::NUMERIC
      ) AS metrics
    FROM public.inventory inv
    LEFT JOIN public.locations l ON l.id = inv.location_id
    WHERE 'inventory' = ANY(v_modules)
      AND inv.organization_id = v_org
      AND COALESCE(inv.updated_at, inv.created_at)::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), inventory_movement_rows AS (
    SELECT
      'inventory'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(im.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', im.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', im.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(im.movement_type, ''), 'movement')
        WHEN 'category' THEN COALESCE(NULLIF(base.category, ''), 'Movement')
        WHEN 'module' THEN 'Inventory'
      END AS dimension,
      jsonb_build_object(
        'inventory_waste', COALESCE(SUM(CASE WHEN im.movement_type IN ('wastage','spoilage') THEN ABS(im.quantity) * COALESCE(base.unit_cost, 0) ELSE 0 END), 0)::NUMERIC,
        'cogs', COALESCE(SUM(CASE WHEN im.quantity < 0 THEN ABS(im.quantity) * COALESCE(base.unit_cost, 0) ELSE 0 END), 0)::NUMERIC
      ) AS metrics
    FROM public.inventory_movements im
    LEFT JOIN public.inventory base ON base.id = im.inventory_id
    LEFT JOIN public.locations l ON l.id = im.location_id
    WHERE 'inventory' = ANY(v_modules)
      AND im.organization_id = v_org
      AND im.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), recipe_rows AS (
    SELECT
      'recipes'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(r.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', r.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', r.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Recipe Library')
        WHEN 'status' THEN COALESCE(NULLIF(r.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(r.category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Recipes'
      END AS dimension,
      jsonb_build_object(
        'recipe_count', COUNT(*)::NUMERIC,
        'avg_recipe_cost', COALESCE(AVG(r.total_cost), 0)::NUMERIC,
        'avg_suggested_price', COALESCE(AVG(r.suggested_price), 0)::NUMERIC,
        'avg_cost_per_serving', COALESCE(AVG(r.cost_per_serving), 0)::NUMERIC
      ) AS metrics
    FROM public.recipes r
    LEFT JOIN public.locations l ON l.id = r.location_id
    WHERE 'recipes' = ANY(v_modules)
      AND r.organization_id = v_org
      AND r.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), performance_sales_rows AS (
    SELECT
      'performance'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(po.order_date::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', po.order_date), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', po.order_date), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(po.status, ''), 'order')
        WHEN 'category' THEN 'POS Sales'
        WHEN 'module' THEN 'Performance'
      END AS dimension,
      jsonb_build_object(
        'sales_revenue', COALESCE(SUM(po.total_amount), 0)::NUMERIC,
        'pos_transaction_count', COUNT(*)::NUMERIC,
        'gross_profit', COALESCE(SUM(po.total_amount), 0)::NUMERIC
      ) AS metrics
    FROM public.pos_orders po
    LEFT JOIN public.locations l ON l.id = po.location_id
    WHERE 'performance' = ANY(v_modules)
      AND po.organization_id = v_org
      AND po.order_date::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), performance_labor_rows AS (
    SELECT
      'performance'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(es.shift_start::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', es.shift_start), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', es.shift_start), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(es.status, ''), 'shift')
        WHEN 'category' THEN 'Labor'
        WHEN 'module' THEN 'Performance'
      END AS dimension,
      jsonb_build_object(
        'labor_cost', COALESCE(SUM(es.labor_cost), 0)::NUMERIC,
        'prime_cost', COALESCE(SUM(es.labor_cost), 0)::NUMERIC,
        'gross_profit', -COALESCE(SUM(es.labor_cost), 0)::NUMERIC
      ) AS metrics
    FROM public.employee_shifts es
    LEFT JOIN public.locations l ON l.id = es.location_id
    WHERE 'performance' = ANY(v_modules)
      AND es.organization_id = v_org
      AND es.shift_start::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), audit_rows AS (
    SELECT
      'audit_logs'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(a.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', a.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', a.created_at), 'YYYY-MM')
        WHEN 'location' THEN 'Organization'
        WHEN 'status' THEN COALESCE(NULLIF(a.action, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(a.table_name, ''), 'unknown_table')
        WHEN 'module' THEN 'Audit Logs'
      END AS dimension,
      jsonb_build_object(
        'audit_event_count', COUNT(*)::NUMERIC,
        'audit_insert_count', COUNT(*) FILTER (WHERE upper(a.action) = 'INSERT')::NUMERIC,
        'audit_update_count', COUNT(*) FILTER (WHERE upper(a.action) = 'UPDATE')::NUMERIC,
        'audit_delete_count', COUNT(*) FILTER (WHERE upper(a.action) = 'DELETE')::NUMERIC
      ) AS metrics
    FROM public.audit_logs a
    WHERE 'audit_logs' = ANY(v_modules)
      AND a.organization_id = v_org
      AND a.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), unioned AS (
    SELECT * FROM invoice_rows
    UNION ALL SELECT * FROM payment_rows
    UNION ALL SELECT * FROM product_rows
    UNION ALL SELECT * FROM inventory_rows
    UNION ALL SELECT * FROM inventory_movement_rows
    UNION ALL SELECT * FROM recipe_rows
    UNION ALL SELECT * FROM performance_sales_rows
    UNION ALL SELECT * FROM performance_labor_rows
    UNION ALL SELECT * FROM audit_rows
  ), merged AS (
    SELECT
      module,
      dimension,
      SUM(COALESCE((metrics->>'invoice_count')::NUMERIC, 0)) AS invoice_count,
      SUM(COALESCE((metrics->>'invoice_total_amount')::NUMERIC, 0)) AS invoice_total_amount,
      SUM(COALESCE((metrics->>'invoice_approved_count')::NUMERIC, 0)) AS invoice_approved_count,
      SUM(COALESCE((metrics->>'invoice_unpaid_count')::NUMERIC, 0)) AS invoice_unpaid_count,
      SUM(COALESCE((metrics->>'invoice_tax_amount')::NUMERIC, 0)) AS invoice_tax_amount,
      SUM(COALESCE((metrics->>'payment_count')::NUMERIC, 0)) AS payment_count,
      SUM(COALESCE((metrics->>'payment_amount')::NUMERIC, 0)) AS payment_amount,
      SUM(COALESCE((metrics->>'payment_completed_amount')::NUMERIC, 0)) AS payment_completed_amount,
      SUM(COALESCE((metrics->>'payment_failed_count')::NUMERIC, 0)) AS payment_failed_count,
      SUM(COALESCE((metrics->>'product_count')::NUMERIC, 0)) AS product_count,
      SUM(COALESCE((metrics->>'inventoried_product_count')::NUMERIC, 0)) AS inventoried_product_count,
      SUM(COALESCE((metrics->>'avg_latest_price')::NUMERIC, 0)) AS avg_latest_price,
      SUM(COALESCE((metrics->>'products_with_price_count')::NUMERIC, 0)) AS products_with_price_count,
      SUM(COALESCE((metrics->>'inventory_value')::NUMERIC, 0)) AS inventory_value,
      SUM(COALESCE((metrics->>'inventory_quantity')::NUMERIC, 0)) AS inventory_quantity,
      SUM(COALESCE((metrics->>'low_stock_count')::NUMERIC, 0)) AS low_stock_count,
      SUM(COALESCE((metrics->>'inventory_waste')::NUMERIC, 0)) AS inventory_waste,
      SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS cogs,
      SUM(COALESCE((metrics->>'recipe_count')::NUMERIC, 0)) AS recipe_count,
      SUM(COALESCE((metrics->>'avg_recipe_cost')::NUMERIC, 0)) AS avg_recipe_cost,
      SUM(COALESCE((metrics->>'avg_suggested_price')::NUMERIC, 0)) AS avg_suggested_price,
      SUM(COALESCE((metrics->>'avg_cost_per_serving')::NUMERIC, 0)) AS avg_cost_per_serving,
      SUM(COALESCE((metrics->>'sales_revenue')::NUMERIC, 0)) AS sales_revenue,
      SUM(COALESCE((metrics->>'pos_transaction_count')::NUMERIC, 0)) AS pos_transaction_count,
      SUM(COALESCE((metrics->>'labor_cost')::NUMERIC, 0)) AS labor_cost,
      SUM(COALESCE((metrics->>'prime_cost')::NUMERIC, 0)) + SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS prime_cost,
      SUM(COALESCE((metrics->>'gross_profit')::NUMERIC, 0)) - SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS gross_profit,
      SUM(COALESCE((metrics->>'audit_event_count')::NUMERIC, 0)) AS audit_event_count,
      SUM(COALESCE((metrics->>'audit_insert_count')::NUMERIC, 0)) AS audit_insert_count,
      SUM(COALESCE((metrics->>'audit_update_count')::NUMERIC, 0)) AS audit_update_count,
      SUM(COALESCE((metrics->>'audit_delete_count')::NUMERIC, 0)) AS audit_delete_count
    FROM unioned
    WHERE dimension IS NOT NULL
    GROUP BY module, dimension
  )
  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'module', module,
    'dimension', dimension,
    'invoice_count', CASE WHEN 'invoice_count' = ANY(p_metrics) THEN invoice_count END,
    'invoice_total_amount', CASE WHEN 'invoice_total_amount' = ANY(p_metrics) THEN invoice_total_amount END,
    'invoice_approved_count', CASE WHEN 'invoice_approved_count' = ANY(p_metrics) THEN invoice_approved_count END,
    'invoice_unpaid_count', CASE WHEN 'invoice_unpaid_count' = ANY(p_metrics) THEN invoice_unpaid_count END,
    'invoice_tax_amount', CASE WHEN 'invoice_tax_amount' = ANY(p_metrics) THEN invoice_tax_amount END,
    'payment_count', CASE WHEN 'payment_count' = ANY(p_metrics) THEN payment_count END,
    'payment_amount', CASE WHEN 'payment_amount' = ANY(p_metrics) THEN payment_amount END,
    'payment_completed_amount', CASE WHEN 'payment_completed_amount' = ANY(p_metrics) THEN payment_completed_amount END,
    'payment_failed_count', CASE WHEN 'payment_failed_count' = ANY(p_metrics) THEN payment_failed_count END,
    'product_count', CASE WHEN 'product_count' = ANY(p_metrics) THEN product_count END,
    'inventoried_product_count', CASE WHEN 'inventoried_product_count' = ANY(p_metrics) THEN inventoried_product_count END,
    'avg_latest_price', CASE WHEN 'avg_latest_price' = ANY(p_metrics) THEN avg_latest_price END,
    'products_with_price_count', CASE WHEN 'products_with_price_count' = ANY(p_metrics) THEN products_with_price_count END,
    'inventory_value', CASE WHEN 'inventory_value' = ANY(p_metrics) THEN inventory_value END,
    'inventory_quantity', CASE WHEN 'inventory_quantity' = ANY(p_metrics) THEN inventory_quantity END,
    'low_stock_count', CASE WHEN 'low_stock_count' = ANY(p_metrics) THEN low_stock_count END,
    'inventory_waste', CASE WHEN 'inventory_waste' = ANY(p_metrics) THEN inventory_waste END,
    'cogs', CASE WHEN 'cogs' = ANY(p_metrics) THEN cogs END,
    'recipe_count', CASE WHEN 'recipe_count' = ANY(p_metrics) THEN recipe_count END,
    'avg_recipe_cost', CASE WHEN 'avg_recipe_cost' = ANY(p_metrics) THEN avg_recipe_cost END,
    'avg_suggested_price', CASE WHEN 'avg_suggested_price' = ANY(p_metrics) THEN avg_suggested_price END,
    'avg_cost_per_serving', CASE WHEN 'avg_cost_per_serving' = ANY(p_metrics) THEN avg_cost_per_serving END,
    'sales_revenue', CASE WHEN 'sales_revenue' = ANY(p_metrics) THEN sales_revenue END,
    'pos_transaction_count', CASE WHEN 'pos_transaction_count' = ANY(p_metrics) THEN pos_transaction_count END,
    'labor_cost', CASE WHEN 'labor_cost' = ANY(p_metrics) THEN labor_cost END,
    'prime_cost', CASE WHEN 'prime_cost' = ANY(p_metrics) THEN prime_cost END,
    'gross_profit', CASE WHEN 'gross_profit' = ANY(p_metrics) THEN gross_profit END,
    'audit_event_count', CASE WHEN 'audit_event_count' = ANY(p_metrics) THEN audit_event_count END,
    'audit_insert_count', CASE WHEN 'audit_insert_count' = ANY(p_metrics) THEN audit_insert_count END,
    'audit_update_count', CASE WHEN 'audit_update_count' = ANY(p_metrics) THEN audit_update_count END,
    'audit_delete_count', CASE WHEN 'audit_delete_count' = ANY(p_metrics) THEN audit_delete_count END
  )) ORDER BY module, dimension), '[]'::JSONB)
  INTO v_result
  FROM merged;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."run_custom_report"("p_metrics" "text"[], "p_dimension" "text", "p_start_date" "date", "p_end_date" "date", "p_modules" "text"[], "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_bar_item_release1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") RETURNS "public"."recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id','')::uuid;
  v_id uuid := nullif(p_recipe->>'id','')::uuid;
  v_recipe public.recipes; v_row jsonb; v_equipment_id uuid; v_child uuid; v_type uuid := nullif(p_recipe->>'recipe_type_id','')::uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then raise exception 'Not authorized to save Bar Items'; end if;
  if coalesce(trim(p_recipe->>'name'),'')='' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields)<>'array' or jsonb_array_length(p_yields)=0 then raise exception 'At least one yield is required'; end if;
  if (select count(*) from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) and coalesce((x->>'quantity')::numeric,0)>0) <> 1 then raise exception 'Exactly one positive primary yield is required'; end if;
  if v_type is not null and not exists(select 1 from public.recipe_types where id=v_type and organization_id=v_org and kind='beverage') then raise exception 'Bar Item type must be a beverage Recipe type'; end if;
  for v_row in select value from jsonb_array_elements(coalesce(p_recipe->'ingredients','[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if coalesce((v_row->>'missing_conversion')::boolean,false) then raise exception 'A required unit conversion is missing'; end if;
    if v_child is not null and v_id is not null and public.recipe_dependency_would_cycle(v_id,v_child) then raise exception 'Circular Recipe dependency detected'; end if;
  end loop;

  if v_id is null then
    insert into public.recipes(organization_id,brand_id,location_id,name,description,category,status,recipe_type_id,yield_quantity,yield_unit,yield_percentage,ingredients,instructions,selling_price,target_margin_percent,margin_alert_enabled,total_ingredient_cost,total_cost,cost_per_serving,is_batch,shelf_life_quantity,shelf_life_unit,created_by)
    values(v_org,nullif(p_recipe->>'brand_id','')::uuid,nullif(p_recipe->>'location_id','')::uuid,trim(p_recipe->>'name'),nullif(p_recipe->>'description',''),'beverage',coalesce(nullif(p_recipe->>'status',''),'active'),v_type,
      (select (x->>'quantity')::numeric from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),(select x->>'unit' from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),100,coalesce(p_recipe->'ingredients','[]'::jsonb),coalesce(p_recipe->>'instructions',''),coalesce(nullif(p_recipe->>'selling_price','')::numeric,0),coalesce(nullif(p_recipe->>'target_margin_percent','')::numeric,70),coalesce((p_recipe->>'margin_alert_enabled')::boolean,true),0,0,0,false,nullif(p_recipe->>'shelf_life_quantity','')::numeric,nullif(p_recipe->>'shelf_life_unit',''),auth.uid()) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes set name=trim(p_recipe->>'name'),description=nullif(p_recipe->>'description',''),category='beverage',status=coalesce(nullif(p_recipe->>'status',''),'active'),recipe_type_id=v_type,
      ingredients=coalesce(p_recipe->'ingredients','[]'::jsonb),instructions=coalesce(p_recipe->>'instructions',''),selling_price=coalesce(nullif(p_recipe->>'selling_price','')::numeric,0),target_margin_percent=coalesce(nullif(p_recipe->>'target_margin_percent','')::numeric,70),margin_alert_enabled=coalesce((p_recipe->>'margin_alert_enabled')::boolean,true),is_batch=false,shelf_life_quantity=nullif(p_recipe->>'shelf_life_quantity','')::numeric,shelf_life_unit=nullif(p_recipe->>'shelf_life_unit',''),updated_at=now()
      where id=v_id and organization_id=v_org and category='beverage' and not coalesce(is_batch,false) returning * into v_recipe;
    if v_recipe.id is null then raise exception 'Bar Item not found'; end if;
  end if;

  delete from public.recipe_yields where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(p_yields) loop insert into public.recipe_yields(organization_id,recipe_id,quantity,unit,is_primary,cost_per_unit) values(v_org,v_id,(v_row->>'quantity')::numeric,trim(v_row->>'unit'),coalesce((v_row->>'is_primary')::boolean,false),nullif(v_row->>'cost_per_unit','')::numeric); end loop;
  delete from public.recipe_location_visibility where recipe_id=v_id;
  if coalesce(p_visibility->>'mode','all')='selected' then for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids','[]'::jsonb)) loop insert into public.recipe_location_visibility(organization_id,recipe_id,location_id,is_visible) select v_org,v_id,trim(both '"' from v_row::text)::uuid,true from public.locations l where l.id=trim(both '"' from v_row::text)::uuid and l.organization_id=v_org; end loop; end if;
  delete from public.recipe_equipment_assignments where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names,'[]'::jsonb)) loop insert into public.recipe_equipment_catalog(organization_id,name) values(v_org,trim(both '"' from v_row::text)) on conflict(organization_id,lower(name)) do update set is_active=true,updated_at=now() returning id into v_equipment_id; insert into public.recipe_equipment_assignments(organization_id,recipe_id,equipment_id) values(v_org,v_id,v_equipment_id) on conflict do nothing; end loop;
  delete from public.recipe_preparation_steps where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps,'[]'::jsonb)) loop insert into public.recipe_preparation_steps(organization_id,recipe_id,step_number,instruction,notes) values(v_org,v_id,(v_row->>'step_number')::integer,trim(v_row->>'instruction'),nullif(v_row->>'notes','')); end loop;
  delete from public.recipe_location_prices where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_location_prices,'[]'::jsonb)) loop insert into public.recipe_location_prices(organization_id,recipe_id,location_id,price) select v_org,v_id,(v_row->>'location_id')::uuid,(v_row->>'price')::numeric from public.locations l where l.id=(v_row->>'location_id')::uuid and l.organization_id=v_org; end loop;
  perform public.recalculate_recipe_cost_tree(v_id);
  select * into v_recipe from public.recipes where id=v_id;
  return v_recipe;
end; $$;


ALTER FUNCTION "public"."save_bar_item_release1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_bar_item_release1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") IS 'Atomically saves tenant-scoped beverage Recipes and shared Recipe child records.';



CREATE OR REPLACE FUNCTION "public"."save_business_verification_draft"("p_payload" "jsonb", "p_step" "text" DEFAULT 'business_information'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_step TEXT := COALESCE(NULLIF(btrim(p_step), ''), 'business_information');
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  UPDATE public.profiles
  SET onboarding_draft = COALESCE(p_payload, '{}'::jsonb),
      onboarding_status = CASE WHEN onboarding_status = 'completed' THEN onboarding_status ELSE 'in_progress' END,
      onboarding_current_step = v_step,
      updated_at = now()
  WHERE id = v_user_id;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(v_run_id, v_user_id, v_step, 'draft_saved', 'in_progress', jsonb_build_object('source', 'business_verification'));

  RETURN jsonb_build_object('success', true, 'current_step', v_step);
END;
$$;


ALTER FUNCTION "public"."save_business_verification_draft"("p_payload" "jsonb", "p_step" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_inventory_count_session"("p_organization_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_count_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_scope_key" "text" DEFAULT 'all'::"text", "p_type" "text" DEFAULT 'Inventory'::"text", "p_count_date" "date" DEFAULT CURRENT_DATE, "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_session_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.count_sessions;
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_total numeric := 0;
  v_item_count integer := 0;
BEGIN
  PERFORM public.assert_inventory_rpc_access(p_organization_id, p_location_id, false);

  SELECT COALESCE(SUM(COALESCE((item->>'value')::numeric, 0)), 0), COUNT(*)
    INTO v_total, v_item_count
  FROM jsonb_array_elements(v_items) AS item;

  IF p_session_id IS NOT NULL THEN
    UPDATE public.count_sessions
       SET location_id = p_location_id,
           brand_id = p_brand_id,
           count_sheet_id = p_count_sheet_id,
           scope_key = COALESCE(NULLIF(p_scope_key, ''), 'all'),
           type = COALESCE(NULLIF(p_type, ''), 'Inventory'),
           count_date = COALESCE(p_count_date, CURRENT_DATE),
           items = v_items,
           counted_data = v_items,
           total_value = v_total,
           item_count = v_item_count,
           status = 'saved',
           saved_at = COALESCE(saved_at, now()),
           updated_at = now(),
           counted_by = COALESCE(p_user_id, auth.uid(), counted_by),
           created_by = COALESCE(created_by, p_user_id, auth.uid())
     WHERE id = p_session_id
       AND organization_id = p_organization_id
       AND deleted_at IS NULL
       AND status <> 'closed'
     RETURNING * INTO v_row;
  END IF;

  IF v_row.id IS NULL THEN
    INSERT INTO public.count_sessions (
      organization_id, location_id, brand_id, count_sheet_id, scope_key, type,
      count_date, items, counted_data, total_value, item_count, status,
      saved_at, updated_at, counted_by, created_by
    ) VALUES (
      p_organization_id, p_location_id, p_brand_id, p_count_sheet_id,
      COALESCE(NULLIF(p_scope_key, ''), 'all'), COALESCE(NULLIF(p_type, ''), 'Inventory'),
      COALESCE(p_count_date, CURRENT_DATE), v_items, v_items, v_total, v_item_count,
      'saved', now(), now(), COALESCE(p_user_id, auth.uid()), COALESCE(p_user_id, auth.uid())
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."save_inventory_count_session"("p_organization_id" "uuid", "p_location_id" "uuid", "p_brand_id" "uuid", "p_count_sheet_id" "uuid", "p_scope_key" "text", "p_type" "text", "p_count_date" "date", "p_items" "jsonb", "p_user_id" "uuid", "p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_invoice_allocation_splits"("p_original_allocation_id" "uuid", "p_splits" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_original RECORD;
  v_split JSONB;
  v_inserted JSONB;
BEGIN
  IF jsonb_typeof(COALESCE(p_splits, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Splits must be a JSON array';
  END IF;

  SELECT *
    INTO v_original
  FROM public.invoice_allocations
  WHERE id = p_original_allocation_id
  FOR UPDATE;

  IF v_original.id IS NULL THEN
    RAISE EXCEPTION 'Allocation not found';
  END IF;

  PERFORM public.assert_org_actor(v_original.organization_id);

  DELETE FROM public.invoice_allocations
  WHERE id = p_original_allocation_id;

  FOR v_split IN SELECT * FROM jsonb_array_elements(p_splits) LOOP
    INSERT INTO public.invoice_allocations (
      invoice_id,
      organization_id,
      allocation_type,
      category_name,
      gl_code,
      location_id,
      amount,
      percentage
    ) VALUES (
      v_original.invoice_id,
      v_original.organization_id,
      v_original.allocation_type,
      v_split->>'category_name',
      v_split->>'gl_code',
      v_original.location_id,
      COALESCE((v_split->>'amount')::NUMERIC, 0),
      NULLIF(v_split->>'percentage', '')::NUMERIC
    );
  END LOOP;

  SELECT COALESCE(jsonb_agg(to_jsonb(ia) ORDER BY ia.created_at), '[]'::jsonb)
    INTO v_inserted
  FROM public.invoice_allocations ia
  WHERE ia.invoice_id = v_original.invoice_id
    AND ia.organization_id = v_original.organization_id;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."save_invoice_allocation_splits"("p_original_allocation_id" "uuid", "p_splits" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_invoice_workflow"("p_invoice_id" "uuid" DEFAULT NULL::"uuid", "p_invoice" "jsonb" DEFAULT '{}'::"jsonb", "p_line_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_existing public.invoices%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_payload JSONB;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_actor_role TEXT;
  v_locked BOOLEAN := false;
BEGIN
  v_payload := COALESCE(p_invoice, '{}'::jsonb)
    - 'id'
    - 'created_at'
    - 'updated_at'
    - 'deleted_at'
    - 'deleted_by'
    - 'vendor_address';

  IF p_invoice_id IS NULL THEN
    v_org_id := NULLIF(v_payload->>'organization_id', '')::UUID;

    IF v_org_id IS NULL THEN
      v_org_id := public.get_my_org();
      v_payload := jsonb_set(v_payload, '{organization_id}', to_jsonb(v_org_id), true);
    END IF;

    PERFORM public.assert_org_actor(v_org_id);

    v_actor_role := public.get_auth_role();
    v_brand_id := NULLIF(v_payload->>'brand_id', '')::UUID;
    v_location_id := NULLIF(v_payload->>'location_id', '')::UUID;

    IF (v_brand_id IS NULL OR v_location_id IS NULL)
      AND v_actor_role IN ('location_manager', 'ground_staff') THEN
      SELECT COALESCE(v_brand_id, p.brand_id), COALESCE(v_location_id, p.location_id)
        INTO v_brand_id, v_location_id
      FROM public.profiles p
      WHERE p.id = auth.uid();

      IF v_brand_id IS NULL AND v_location_id IS NOT NULL THEN
        SELECT l.brand_id
          INTO v_brand_id
        FROM public.locations l
        WHERE l.id = v_location_id;
      END IF;

      IF v_brand_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{brand_id}', to_jsonb(v_brand_id), true);
      END IF;
      IF v_location_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{location_id}', to_jsonb(v_location_id), true);
      END IF;
    END IF;

    IF v_brand_id IS NULL OR v_location_id IS NULL THEN
      RAISE EXCEPTION 'Invoice requires brand and location context';
    END IF;

    v_invoice := jsonb_populate_record(NULL::public.invoices, v_payload);

    INSERT INTO public.invoices (
      vendor_name, invoice_number, total_amount, status, account_number, subtotal,
      organization_id, location_id, payment_status, vendor_id, due_date,
      delivery_fee, fuel_surcharge, other_charges, tax_amount, currency, source,
      file_url, line_items, validation_results, validation_notes, approved_by,
      approved_date, location, created_by, extraction_method, raw_text,
      purchase_order_number, invoice_date, payment_terms, file_destination,
      purchase_order_id, matched_order_id, match_status, brand_id, ap_status,
      action_required_reason, action_required_details, assigned_reviewer_id,
      payment_account_id, scheduled_payment_date, closed_at, closed_by,
      ap_metadata, paid_amount, payment_reference, credit_applied, credit_reason,
      version_number, ap_routing_destination, ap_routing_resolved_at
    ) VALUES (
      v_invoice.vendor_name, v_invoice.invoice_number, v_invoice.total_amount,
      COALESCE(v_invoice.status, 'pending_review'), v_invoice.account_number,
      v_invoice.subtotal, v_org_id, v_invoice.location_id,
      COALESCE(v_invoice.payment_status, 'unpaid'), v_invoice.vendor_id,
      v_invoice.due_date, v_invoice.delivery_fee, v_invoice.fuel_surcharge,
      v_invoice.other_charges, v_invoice.tax_amount, COALESCE(v_invoice.currency, 'USD'),
      v_invoice.source, v_invoice.file_url, COALESCE(v_invoice.line_items, '[]'::jsonb),
      COALESCE(v_invoice.validation_results, '{}'::jsonb), v_invoice.validation_notes,
      v_invoice.approved_by, v_invoice.approved_date, v_invoice.location,
      COALESCE(v_invoice.created_by, auth.uid()), v_invoice.extraction_method,
      v_invoice.raw_text, v_invoice.purchase_order_number, v_invoice.invoice_date,
      v_invoice.payment_terms, v_invoice.file_destination, v_invoice.purchase_order_id,
      v_invoice.matched_order_id, v_invoice.match_status, v_invoice.brand_id,
      COALESCE(v_invoice.ap_status, 'processing'), v_invoice.action_required_reason,
      v_invoice.action_required_details, v_invoice.assigned_reviewer_id,
      v_invoice.payment_account_id, v_invoice.scheduled_payment_date,
      v_invoice.closed_at, v_invoice.closed_by, COALESCE(v_invoice.ap_metadata, '{}'::jsonb),
      COALESCE(v_invoice.paid_amount, 0), v_invoice.payment_reference,
      COALESCE(v_invoice.credit_applied, 0), v_invoice.credit_reason,
      COALESCE(v_invoice.version_number, 1), v_invoice.ap_routing_destination,
      v_invoice.ap_routing_resolved_at
    )
    RETURNING * INTO v_invoice;
  ELSE
    SELECT *
      INTO v_existing
    FROM public.invoices
    WHERE id = p_invoice_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION 'Invoice not found';
    END IF;

    PERFORM public.assert_org_actor(v_existing.organization_id);

    v_locked := v_existing.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
      OR v_existing.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
      OR COALESCE(v_existing.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
      OR COALESCE(v_existing.paid_amount, 0) > 0;

    IF v_locked THEN
      v_payload := v_payload - 'line_items';
    END IF;

    IF v_payload ? 'organization_id'
      AND NULLIF(v_payload->>'organization_id', '')::UUID IS DISTINCT FROM v_existing.organization_id THEN
      RAISE EXCEPTION 'Invoice organization cannot be changed';
    END IF;

    v_invoice := jsonb_populate_record(v_existing, v_payload);

    IF v_invoice.brand_id IS NULL OR v_invoice.location_id IS NULL THEN
      RAISE EXCEPTION 'Invoice requires brand and location context';
    END IF;

    UPDATE public.invoices
       SET vendor_name = v_invoice.vendor_name,
           invoice_number = v_invoice.invoice_number,
           total_amount = v_invoice.total_amount,
           status = v_invoice.status,
           account_number = v_invoice.account_number,
           subtotal = v_invoice.subtotal,
           location_id = v_invoice.location_id,
           payment_status = v_invoice.payment_status,
           vendor_id = v_invoice.vendor_id,
           due_date = v_invoice.due_date,
           delivery_fee = v_invoice.delivery_fee,
           fuel_surcharge = v_invoice.fuel_surcharge,
           other_charges = v_invoice.other_charges,
           tax_amount = v_invoice.tax_amount,
           currency = v_invoice.currency,
           source = v_invoice.source,
           file_url = v_invoice.file_url,
           line_items = v_invoice.line_items,
           validation_results = v_invoice.validation_results,
           validation_notes = v_invoice.validation_notes,
           approved_by = v_invoice.approved_by,
           approved_date = v_invoice.approved_date,
           location = v_invoice.location,
           extraction_method = v_invoice.extraction_method,
           raw_text = v_invoice.raw_text,
           purchase_order_number = v_invoice.purchase_order_number,
           invoice_date = v_invoice.invoice_date,
           payment_terms = v_invoice.payment_terms,
           file_destination = v_invoice.file_destination,
           purchase_order_id = v_invoice.purchase_order_id,
           matched_order_id = v_invoice.matched_order_id,
           match_status = v_invoice.match_status,
           brand_id = v_invoice.brand_id,
           ap_status = v_invoice.ap_status,
           action_required_reason = v_invoice.action_required_reason,
           action_required_details = v_invoice.action_required_details,
           assigned_reviewer_id = v_invoice.assigned_reviewer_id,
           payment_account_id = v_invoice.payment_account_id,
           scheduled_payment_date = v_invoice.scheduled_payment_date,
           closed_at = v_invoice.closed_at,
           closed_by = v_invoice.closed_by,
           ap_metadata = v_invoice.ap_metadata,
           paid_amount = v_invoice.paid_amount,
           payment_reference = v_invoice.payment_reference,
           credit_applied = v_invoice.credit_applied,
           credit_reason = v_invoice.credit_reason,
           version_number = COALESCE(v_existing.version_number, 1) + 1,
           ap_routing_destination = v_invoice.ap_routing_destination,
           ap_routing_resolved_at = v_invoice.ap_routing_resolved_at,
           updated_at = now()
     WHERE id = p_invoice_id
     RETURNING * INTO v_invoice;
  END IF;

  IF NOT v_locked
    AND jsonb_typeof(COALESCE(p_line_items, '[]'::jsonb)) = 'array'
    AND jsonb_array_length(COALESCE(p_line_items, '[]'::jsonb)) > 0 THEN
    PERFORM public.upsert_invoice_line_items(v_invoice.id, p_line_items);
  END IF;

  RETURN to_jsonb(v_invoice);
END;
$$;


ALTER FUNCTION "public"."save_invoice_workflow"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_line_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_invoice_workflow"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_line_items" "jsonb") IS 'Tenant-safe invoice create/update RPC that saves invoice header and line items in one guarded transaction.';



CREATE OR REPLACE FUNCTION "public"."save_menu_item_phase1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") RETURNS "public"."recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id', '')::uuid;
  v_id uuid := nullif(p_recipe->>'id', '')::uuid;
  v_recipe public.recipes;
  v_row jsonb;
  v_equipment_id uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then
    raise exception 'Not authorized to save menu items';
  end if;
  if coalesce(trim(p_recipe->>'name'), '') = '' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields) <> 'array' or jsonb_array_length(p_yields) = 0 then raise exception 'At least one yield is required'; end if;

  if v_id is null then
    insert into public.recipes (
      organization_id, brand_id, location_id, name, description, category, status,
      recipe_type_id, yield_quantity, yield_unit, yield_percentage, ingredients,
      instructions, selling_price, target_margin_percent, margin_alert_enabled,
      total_ingredient_cost, total_packaging_cost, labor_cost, total_cost,
      cost_per_serving, is_batch, shelf_life_quantity, shelf_life_unit, created_by
    ) values (
      v_org, nullif(p_recipe->>'brand_id', '')::uuid, nullif(p_recipe->>'location_id', '')::uuid,
      trim(p_recipe->>'name'), nullif(p_recipe->>'description', ''), coalesce(nullif(p_recipe->>'category', ''), 'other'),
      coalesce(nullif(p_recipe->>'status', ''), 'active'), nullif(p_recipe->>'recipe_type_id', '')::uuid,
      (p_yields->0->>'quantity')::numeric, p_yields->0->>'unit', 100,
      coalesce(p_recipe->'ingredients', '[]'::jsonb), coalesce(p_recipe->>'instructions', ''),
      coalesce(nullif(p_recipe->>'selling_price', '')::numeric, 0),
      coalesce(nullif(p_recipe->>'target_margin_percent', '')::numeric, 70),
      coalesce((p_recipe->>'margin_alert_enabled')::boolean, true),
      coalesce(nullif(p_recipe->>'total_ingredient_cost', '')::numeric, 0), 0, 0,
      coalesce(nullif(p_recipe->>'total_cost', '')::numeric, 0),
      coalesce(nullif(p_recipe->>'cost_per_serving', '')::numeric, 0), false,
      nullif(p_recipe->>'shelf_life_quantity', '')::numeric, nullif(p_recipe->>'shelf_life_unit', ''), auth.uid()
    ) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes
    set
      brand_id = nullif(p_recipe->>'brand_id', '')::uuid,
      location_id = nullif(p_recipe->>'location_id', '')::uuid,
      name = trim(p_recipe->>'name'),
      description = nullif(p_recipe->>'description', ''),
      category = coalesce(nullif(p_recipe->>'category', ''), 'other'),
      status = coalesce(nullif(p_recipe->>'status', ''), 'active'),
      recipe_type_id = nullif(p_recipe->>'recipe_type_id', '')::uuid,
      yield_quantity = (p_yields->0->>'quantity')::numeric,
      yield_unit = p_yields->0->>'unit',
      yield_percentage = 100,
      ingredients = coalesce(p_recipe->'ingredients', '[]'::jsonb),
      instructions = coalesce(p_recipe->>'instructions', ''),
      selling_price = coalesce(nullif(p_recipe->>'selling_price', '')::numeric, 0),
      target_margin_percent = coalesce(nullif(p_recipe->>'target_margin_percent', '')::numeric, 70),
      margin_alert_enabled = coalesce((p_recipe->>'margin_alert_enabled')::boolean, true),
      total_ingredient_cost = coalesce(nullif(p_recipe->>'total_ingredient_cost', '')::numeric, 0),
      total_cost = coalesce(nullif(p_recipe->>'total_cost', '')::numeric, 0),
      cost_per_serving = coalesce(nullif(p_recipe->>'cost_per_serving', '')::numeric, 0),
      is_batch = false,
      shelf_life_quantity = nullif(p_recipe->>'shelf_life_quantity', '')::numeric,
      shelf_life_unit = nullif(p_recipe->>'shelf_life_unit', ''),
      updated_at = now()
    where id = v_id
      and organization_id = v_org
      and not coalesce(is_batch, false)
    returning * into v_recipe;

    if v_recipe.id is null then
      raise exception 'Menu Item not found';
    end if;
  end if;

  delete from public.recipe_yields where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(p_yields)
  loop
    insert into public.recipe_yields (organization_id, recipe_id, quantity, unit, is_primary, cost_per_unit)
    values (v_org, v_id, (v_row->>'quantity')::numeric, trim(v_row->>'unit'), coalesce((v_row->>'is_primary')::boolean, false), nullif(v_row->>'cost_per_unit', '')::numeric);
  end loop;

  delete from public.recipe_location_visibility where recipe_id = v_id;
  if coalesce(p_visibility->>'mode', 'all') = 'selected' then
    for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids', '[]'::jsonb))
    loop
      insert into public.recipe_location_visibility (organization_id, recipe_id, location_id, is_visible)
      select v_org, v_id, trim(both '"' from v_row::text)::uuid, true
      from public.locations l
      where l.id = trim(both '"' from v_row::text)::uuid and l.organization_id = v_org;
    end loop;
  end if;

  delete from public.recipe_equipment_assignments where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names, '[]'::jsonb))
  loop
    insert into public.recipe_equipment_catalog (organization_id, name)
    values (v_org, trim(both '"' from v_row::text))
    on conflict (organization_id, lower(name)) do update set is_active = true, updated_at = now()
    returning id into v_equipment_id;
    insert into public.recipe_equipment_assignments (organization_id, recipe_id, equipment_id)
    values (v_org, v_id, v_equipment_id) on conflict do nothing;
  end loop;

  delete from public.recipe_preparation_steps where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb))
  loop
    insert into public.recipe_preparation_steps (organization_id, recipe_id, step_number, instruction, notes)
    values (v_org, v_id, (v_row->>'step_number')::integer, trim(v_row->>'instruction'), nullif(v_row->>'notes', ''));
  end loop;

  delete from public.recipe_location_prices where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_location_prices, '[]'::jsonb))
  loop
    insert into public.recipe_location_prices (organization_id, recipe_id, location_id, price)
    select v_org, v_id, (v_row->>'location_id')::uuid, (v_row->>'price')::numeric
    from public.locations l
    where l.id = (v_row->>'location_id')::uuid and l.organization_id = v_org;
  end loop;

  return v_recipe;
end;
$$;


ALTER FUNCTION "public"."save_menu_item_phase1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_menu_item_phase1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_location_prices" "jsonb") IS 'Atomically creates or updates a tenant-scoped Menu Item and its Recipe-owned child records.';



CREATE OR REPLACE FUNCTION "public"."save_prepared_item_release1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_ingredients" "jsonb") RETURNS "public"."recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id','')::uuid;
  v_id uuid := nullif(p_recipe->>'id','')::uuid;
  v_recipe public.recipes;
  v_row jsonb;
  v_equipment_id uuid;
  v_child uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then
    raise exception 'Not authorized to save Prepared Items';
  end if;
  if coalesce(trim(p_recipe->>'name'),'')='' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields)<>'array' or jsonb_array_length(p_yields)=0 then raise exception 'At least one yield is required'; end if;
  if not exists(select 1 from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false)) then raise exception 'A primary yield is required'; end if;

  for v_row in select value from jsonb_array_elements(coalesce(p_ingredients,'[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if v_child is not null and v_id is not null and public.recipe_dependency_would_cycle(v_id,v_child) then
      raise exception 'Circular Prepared Item dependency detected';
    end if;
    if coalesce((v_row->>'missing_conversion')::boolean,false) then raise exception 'A required unit conversion is missing'; end if;
  end loop;

  if v_id is null then
    insert into public.recipes(organization_id,brand_id,location_id,name,description,category,status,recipe_type_id,
      yield_quantity,yield_unit,yield_percentage,ingredients,instructions,total_ingredient_cost,total_cost,cost_per_serving,is_batch,shelf_life_quantity,shelf_life_unit,created_by)
    values(v_org,nullif(p_recipe->>'brand_id','')::uuid,nullif(p_recipe->>'location_id','')::uuid,trim(p_recipe->>'name'),nullif(p_recipe->>'description',''),
      'other',coalesce(nullif(p_recipe->>'status',''),'active'),nullif(p_recipe->>'recipe_type_id','')::uuid,
      (select (x->>'quantity')::numeric from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),
      (select x->>'unit' from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),100,p_ingredients,
      coalesce(p_recipe->>'instructions',''),0,0,0,true,nullif(p_recipe->>'shelf_life_quantity','')::numeric,nullif(p_recipe->>'shelf_life_unit',''),auth.uid()) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes set name=trim(p_recipe->>'name'),description=nullif(p_recipe->>'description',''),status=coalesce(nullif(p_recipe->>'status',''),'active'),
      recipe_type_id=nullif(p_recipe->>'recipe_type_id','')::uuid,ingredients=p_ingredients,instructions=coalesce(p_recipe->>'instructions',''),is_batch=true,
      shelf_life_quantity=nullif(p_recipe->>'shelf_life_quantity','')::numeric,shelf_life_unit=nullif(p_recipe->>'shelf_life_unit',''),updated_at=now()
      where id=v_id and organization_id=v_org returning * into v_recipe;
    if v_recipe.id is null then raise exception 'Prepared Item not found'; end if;
  end if;

  for v_row in select value from jsonb_array_elements(coalesce(p_ingredients,'[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if v_child is not null and public.recipe_dependency_would_cycle(v_id,v_child) then raise exception 'Circular Prepared Item dependency detected'; end if;
  end loop;

  delete from public.recipe_yields where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(p_yields) loop
    insert into public.recipe_yields(organization_id,recipe_id,quantity,unit,is_primary,cost_per_unit)
    values(v_org,v_id,(v_row->>'quantity')::numeric,trim(v_row->>'unit'),coalesce((v_row->>'is_primary')::boolean,false),null);
  end loop;
  delete from public.recipe_location_visibility where recipe_id=v_id;
  if coalesce(p_visibility->>'mode','all')='selected' then
    for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids','[]'::jsonb)) loop
      insert into public.recipe_location_visibility(organization_id,recipe_id,location_id,is_visible)
      select v_org,v_id,trim(both '"' from v_row::text)::uuid,true from public.locations l
      where l.id=trim(both '"' from v_row::text)::uuid and l.organization_id=v_org;
    end loop;
  end if;
  delete from public.recipe_equipment_assignments where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names,'[]'::jsonb)) loop
    insert into public.recipe_equipment_catalog(organization_id,name) values(v_org,trim(both '"' from v_row::text))
      on conflict(organization_id,lower(name)) do update set is_active=true,updated_at=now() returning id into v_equipment_id;
    insert into public.recipe_equipment_assignments(organization_id,recipe_id,equipment_id) values(v_org,v_id,v_equipment_id) on conflict do nothing;
  end loop;
  delete from public.recipe_preparation_steps where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps,'[]'::jsonb)) loop
    insert into public.recipe_preparation_steps(organization_id,recipe_id,step_number,instruction,notes)
    values(v_org,v_id,(v_row->>'step_number')::integer,trim(v_row->>'instruction'),nullif(v_row->>'notes',''));
  end loop;

  perform public.recalculate_recipe_cost_tree(v_id);
  select * into v_recipe from public.recipes where id=v_id;
  return v_recipe;
end;
$$;


ALTER FUNCTION "public"."save_prepared_item_release1"("p_recipe" "jsonb", "p_yields" "jsonb", "p_visibility" "jsonb", "p_equipment_names" "jsonb", "p_steps" "jsonb", "p_ingredients" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_secure_integration_credential"("p_organization_id" "uuid", "p_provider" "text", "p_metadata" "jsonb", "p_secret" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_id UUID;
  v_integration_id UUID;
  v_result JSONB;
BEGIN
  -- Validate permissions
  IF NOT public.is_platform_admin() AND NOT (public.is_manager_or_above() AND public.get_my_org() = p_organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Store secret in vault
  SELECT id INTO v_secret_id FROM vault.secrets WHERE name = p_provider || '_' || p_organization_id::text;
  IF v_secret_id IS NOT NULL THEN
    -- Update existing secret (pgsodium/vault does not support direct update easily, so delete and insert)
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;
  
  SELECT * INTO v_secret_id FROM vault.create_secret(p_secret, p_provider || '_' || p_organization_id::text, 'Email IMAP Password');

  -- Update or insert integration
  SELECT id INTO v_integration_id FROM public.integrations WHERE organization_id = p_organization_id AND provider = p_provider;
  
  -- Create new metadata with secret_id instead of raw password
  p_metadata = p_metadata - 'password' || jsonb_build_object('secret_id', v_secret_id);

  IF v_integration_id IS NOT NULL THEN
    UPDATE public.integrations SET metadata = p_metadata WHERE id = v_integration_id RETURNING jsonb_build_object('id', id, 'metadata', metadata) INTO v_result;
  ELSE
    INSERT INTO public.integrations (organization_id, provider, metadata, is_active) VALUES (p_organization_id, p_provider, p_metadata, true) RETURNING jsonb_build_object('id', id, 'metadata', metadata) INTO v_result;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_secure_integration_credential"("p_organization_id" "uuid", "p_provider" "text", "p_metadata" "jsonb", "p_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_invoice_payment"("p_invoice_id" "uuid", "p_payment_account_id" "uuid", "p_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice RECORD;
  v_account_org UUID;
BEGIN
  SELECT id, organization_id, status, payment_status, ap_status, ap_routing_destination
    INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  SELECT organization_id
    INTO v_account_org
  FROM public.payment_accounts
  WHERE id = p_payment_account_id
    AND is_active IS DISTINCT FROM false;

  IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_invoice.organization_id THEN
    RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
  END IF;

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot be scheduled for payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before scheduling payment';
  END IF;

  UPDATE public.invoices
     SET payment_account_id = p_payment_account_id,
         scheduled_payment_date = p_date,
         status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
         ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;


ALTER FUNCTION "public"."schedule_invoice_payment"("p_invoice_id" "uuid", "p_payment_account_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_payment_batch"("p_vendor_id" "uuid", "p_payment_account_id" "uuid", "p_scheduled_date" "date", "p_invoice_ids" "uuid"[], "p_amounts" numeric[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_scheduled_payment_id UUID;
  v_total NUMERIC := 0;
  v_invoice RECORD;
  v_organization_id UUID;
  v_account_org UUID;
BEGIN
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice is required';
  END IF;

  IF array_length(p_invoice_ids, 1) <> array_length(p_amounts, 1) THEN
    RAISE EXCEPTION 'Invoice and amount arrays must have the same length';
  END IF;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    SELECT id, organization_id, vendor_id, status, payment_status, ap_routing_destination
      INTO v_invoice
      FROM public.invoices
     WHERE id = p_invoice_ids[v_index]
     FOR UPDATE;

    IF v_invoice.id IS NULL THEN
      RAISE EXCEPTION 'Invoice % not found', p_invoice_ids[v_index];
    END IF;

    IF v_index = 1 THEN
      v_organization_id := v_invoice.organization_id;
      PERFORM public.assert_financial_actor(v_organization_id);

      SELECT organization_id
        INTO v_account_org
      FROM public.payment_accounts
      WHERE id = p_payment_account_id
        AND is_active IS DISTINCT FROM false;

      IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_organization_id THEN
        RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
      END IF;
    ELSIF v_invoice.organization_id IS DISTINCT FROM v_organization_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the same organization';
    END IF;

    IF v_invoice.vendor_id IS DISTINCT FROM p_vendor_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the selected vendor';
    END IF;

    IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
      RAISE EXCEPTION 'Invoice % is not routed to Payments', v_invoice.id;
    END IF;

    IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
      RAISE EXCEPTION 'Paid invoice % cannot be scheduled', v_invoice.id;
    END IF;

    IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
      RAISE EXCEPTION 'Invoice % must be approved before scheduling payment', v_invoice.id;
    END IF;

    IF COALESCE(p_amounts[v_index], 0) <= 0 THEN
      RAISE EXCEPTION 'Scheduled amount must be greater than zero';
    END IF;

    v_total := v_total + p_amounts[v_index];
  END LOOP;

  INSERT INTO public.scheduled_payments (
    organization_id,
    vendor_id,
    payment_account_id,
    total_amount,
    scheduled_date,
    status,
    created_by
  ) VALUES (
    v_organization_id,
    p_vendor_id,
    p_payment_account_id,
    v_total,
    p_scheduled_date,
    'scheduled',
    auth.uid()
  ) RETURNING id INTO v_scheduled_payment_id;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    INSERT INTO public.scheduled_payment_invoices (
      scheduled_payment_id,
      invoice_id,
      amount_applied
    ) VALUES (
      v_scheduled_payment_id,
      p_invoice_ids[v_index],
      p_amounts[v_index]
    );

    UPDATE public.invoices
       SET scheduled_payment_date = p_scheduled_date,
           payment_account_id = p_payment_account_id,
           status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
           ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
           updated_at = now()
     WHERE id = p_invoice_ids[v_index];
  END LOOP;

  RETURN v_scheduled_payment_id;
END;
$$;


ALTER FUNCTION "public"."schedule_payment_batch"("p_vendor_id" "uuid", "p_payment_account_id" "uuid", "p_scheduled_date" "date", "p_invoice_ids" "uuid"[], "p_amounts" numeric[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_due_date_reminders"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_setting RECORD;
  v_profile RECORD;
  v_invoice RECORD;
BEGIN
  FOR v_setting IN
    SELECT user_id, organization_id, reminder_days
    FROM public.invoice_reminder_settings
    WHERE enabled = true
  LOOP
    SELECT role, organization_id, brand_id, location_id
      INTO v_profile
    FROM public.profiles
    WHERE id = v_setting.user_id
      AND deleted_at IS NULL;

    IF v_profile.role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_invoice IN
      SELECT i.id, i.due_date, (i.due_date - CURRENT_DATE) AS days_out
      FROM public.invoices i
      WHERE i.deleted_at IS NULL
        AND i.organization_id = v_setting.organization_id
        AND COALESCE(i.payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
        AND i.due_date IS NOT NULL
        AND (i.due_date - CURRENT_DATE) = ANY(v_setting.reminder_days)
        AND (
          v_profile.role IN ('org_manager', 'tenant_super_admin', 'platform_admin')
          OR (
            v_profile.role = 'branch_manager'
            AND (
              i.brand_id = v_profile.brand_id
              OR i.location_id IN (SELECT l.id FROM public.locations l WHERE l.brand_id = v_profile.brand_id)
            )
          )
          OR (
            v_profile.role IN ('location_manager', 'ground_staff')
            AND i.location_id = v_profile.location_id
          )
        )
    LOOP
      INSERT INTO public.invoice_reminder_log (invoice_id, user_id, reminder_day)
      VALUES (v_invoice.id, v_setting.user_id, v_invoice.days_out)
      ON CONFLICT (invoice_id, user_id, reminder_day) DO NOTHING;

      IF FOUND THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, is_read, metadata)
        VALUES (
          v_setting.user_id,
          v_setting.organization_id,
          'invoice',
          CASE WHEN v_invoice.days_out <= 0 THEN 'Invoice overdue' ELSE 'Invoice due soon' END,
          CASE WHEN v_invoice.days_out <= 0
            THEN format('An invoice was due on %s and is still unpaid.', to_char(v_invoice.due_date, 'Mon DD, YYYY'))
            ELSE format('An invoice is due in %s day%s (%s).', v_invoice.days_out, CASE WHEN v_invoice.days_out = 1 THEN '' ELSE 's' END, to_char(v_invoice.due_date, 'Mon DD, YYYY'))
          END,
          false,
          jsonb_build_object('invoice_id', v_invoice.id, 'due_in_days', v_invoice.days_out, 'skip_channel_dispatch', true)
        );
      END IF;
    END LOOP;
  END LOOP;

  -- Trigger the email side (plain SQL can't call Resend). Same secure-dispatch pattern as
  -- dispatch_webhook_queue(): read the functions URL/service key from
  -- private.workflow_runtime_settings rather than hardcoding credentials in this function.
  DECLARE
    v_functions_url text;
    v_service_role_key text;
    v_url text;
  BEGIN
    SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
    SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

    IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
      v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/send-due-date-reminder-emails';

      PERFORM net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END;
$$;


ALTER FUNCTION "public"."send_due_date_reminders"() OWNER TO "postgres";


