  parent_org_id UUID;
BEGIN
  SELECT i.organization_id
  INTO parent_org_id
  FROM public.invoices i
  WHERE i.id = NEW.invoice_id;

  IF parent_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice % does not exist', NEW.invoice_id;
