BEGIN
  RETURN public.hard_delete_invoice_workflow(p_invoice_id);
END;
$$;


ALTER FUNCTION "public"."soft_delete_invoice_workflow"("p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."soft_delete_invoice_workflow"("p_invoice_id" "uuid") IS 'Compatibility wrapper. Invoice deletion is now hard delete via hard_delete_invoice_workflow.';



CREATE OR REPLACE FUNCTION "public"."soft_delete_product_safe"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  SELECT * INTO v_existing
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF NOT public.product_write_allowed(v_existing.organization_id, v_existing.brand_id, v_existing.location_id) THEN
    RAISE EXCEPTION 'Not authorized to delete this product';
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_existing.organization_id)
    AND NOT COALESCE(v_existing.pending_approval, false);

  IF v_needs_approval THEN
    UPDATE public.products
       SET pending_approval = true,
           pending_action = 'delete',
           pending_snapshot = to_jsonb(v_existing),
           submitted_by = auth.uid(),
           submitted_at = now(),
           updated_at = now()
     WHERE id = p_product_id;

    RETURN jsonb_build_object('success', true, 'pending_approval', true);
  END IF;

  UPDATE public.products
     SET deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
   WHERE id = p_product_id;

  UPDATE public.inventory
     SET deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
   WHERE organization_id = v_existing.organization_id
     AND deleted_at IS NULL
     AND (internal_product_id = v_existing.id OR product_id = v_existing.product_id);

  RETURN jsonb_build_object('success', true, 'pending_approval', false);
END;
$$;


ALTER FUNCTION "public"."soft_delete_product_safe"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_product_import"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_file_name" "text" DEFAULT NULL::"text", "p_file_hash" "text" DEFAULT NULL::"text", "p_rows" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_job public.product_import_jobs%ROWTYPE;
  v_row jsonb;
  v_row_number integer := 0;
  v_errors text[];
  v_status text;
  v_valid_count integer := 0;
  v_invalid_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF NOT public.product_write_allowed(p_organization_id, p_brand_id, p_location_id) THEN
    RAISE EXCEPTION 'Not authorized to import products for this scope';
  END IF;
  IF jsonb_typeof(COALESCE(p_rows, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Rows must be a JSON array';
  END IF;

  INSERT INTO public.product_import_jobs (
    organization_id, brand_id, location_id, file_name, file_hash, created_by, summary
  ) VALUES (
    p_organization_id, p_brand_id, p_location_id, p_file_name, p_file_hash, auth.uid(), '{}'::jsonb
  )
  ON CONFLICT (organization_id, file_hash)
  DO UPDATE SET
    file_name = EXCLUDED.file_name,
    brand_id = EXCLUDED.brand_id,
    location_id = EXCLUDED.location_id,
    status = 'validated',
    created_by = auth.uid(),
    created_at = now(),
    committed_at = NULL,
    summary = '{}'::jsonb
  RETURNING * INTO v_job;

  DELETE FROM public.product_import_rows WHERE job_id = v_job.id;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows)
  LOOP
    v_row_number := v_row_number + 1;
    v_errors := ARRAY[]::text[];

    IF NULLIF(btrim(COALESCE(v_row->>'name', v_row->>'Product Name', v_row->>'product_name', '')), '') IS NULL THEN
      v_errors := array_append(v_errors, 'Product name is required');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'product_id', v_row->>'Product ID', v_row->>'sku', '')), '') IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.products p
        WHERE p.organization_id = p_organization_id
          AND p.deleted_at IS NULL
          AND lower(btrim(p.product_id)) = lower(btrim(COALESCE(v_row->>'product_id', v_row->>'Product ID', v_row->>'sku')))
      ) THEN
      v_errors := array_append(v_errors, 'Product ID already exists');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'latest_price', v_row->>'Latest Price', '')), '') IS NOT NULL
      AND btrim(COALESCE(v_row->>'latest_price', v_row->>'Latest Price')) !~ '^(0|[1-9][0-9]*)(\.[0-9]+)?$' THEN
      v_errors := array_append(v_errors, 'Latest price must be a non-negative number');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'is_inventoried', v_row->>'On Inventory', '')), '') IS NOT NULL
      AND lower(btrim(COALESCE(v_row->>'is_inventoried', v_row->>'On Inventory'))) <> ALL (ARRAY['true','false','yes','no','1','0']) THEN
      v_errors := array_append(v_errors, 'On Inventory must be true/false, yes/no, or 1/0');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'is_tax_exempt', v_row->>'Tax Exempt', '')), '') IS NOT NULL
      AND lower(btrim(COALESCE(v_row->>'is_tax_exempt', v_row->>'Tax Exempt'))) <> ALL (ARRAY['true','false','yes','no','1','0']) THEN
      v_errors := array_append(v_errors, 'Tax Exempt must be true/false, yes/no, or 1/0');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'accounting_category', v_row->>'Accounting Category', '')), '') IS NOT NULL
      AND btrim(COALESCE(v_row->>'accounting_category', v_row->>'Accounting Category')) <> ALL (ARRAY[
        'food','beverage','supplies','equipment','packaging','cleaning','other',
        'food_cogs','beverage_cogs','merchandise_cogs',
        '5100','5110','5120','5130','5140','5150','5160','5170',
        '5200','5210','5220','5230','5240','5300'
      ]::text[]) THEN
      v_errors := array_append(v_errors, 'Accounting category is not allowed');
    END IF;

    v_status := CASE WHEN array_length(v_errors, 1) IS NULL THEN 'valid' ELSE 'invalid' END;
    IF v_status = 'valid' THEN
      v_valid_count := v_valid_count + 1;
    ELSE
      v_invalid_count := v_invalid_count + 1;
    END IF;

    INSERT INTO public.product_import_rows (job_id, row_number, payload, status, errors)
    VALUES (v_job.id, v_row_number, v_row, v_status, v_errors);
  END LOOP;

  UPDATE public.product_import_jobs
     SET summary = jsonb_build_object(
       'total_rows', v_row_number,
       'valid_rows', v_valid_count,
       'invalid_rows', v_invalid_count
     )
   WHERE id = v_job.id
   RETURNING * INTO v_job;

  RETURN jsonb_build_object(
    'job_id', v_job.id,
    'summary', v_job.summary,
    'rows', (
      SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.row_number), '[]'::jsonb)
      FROM public.product_import_rows r
      WHERE r.job_id = v_job.id
    )
  );
END;
$_$;


ALTER FUNCTION "public"."stage_product_import"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_file_name" "text", "p_file_hash" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_invoice_extraction_workflow"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_functions_url TEXT;
  v_service_role_key TEXT;
  v_url TEXT;
  v_headers JSONB;
  v_payload JSONB;
  v_request_id BIGINT;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.assert_org_actor(v_invoice.organization_id);

  IF v_invoice.status NOT IN ('extracting', 'uploading', 'extract_failed') THEN
    RETURN jsonb_build_object(
      'success', true,
      'queued', false,
      'reason', 'invoice_not_extractable',
      'status', v_invoice.status
    );
  END IF;

  IF v_invoice.status = 'extracting'
     AND v_invoice.extraction_started_at IS NOT NULL
     AND v_invoice.extraction_started_at > now() - interval '5 minutes' THEN
    RETURN jsonb_build_object(
      'success', true,
      'queued', false,
      'reason', 'extraction_already_running',
      'status', v_invoice.status,
      'extraction_started_at', v_invoice.extraction_started_at
    );
  END IF;

  UPDATE public.invoices
     SET status = 'extracting',
         ap_status = 'processing',
         extraction_started_at = NULL,
         validation_results = COALESCE(validation_results, '{}'::jsonb) - 'error',
         updated_at = now()
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;

  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for invoice extraction dispatch';
  END IF;

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/invoice-processing';

  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', 'INSERT',
    'table', 'invoices',
    'schema', 'public',
    'record', row_to_json(v_invoice),
    'old_record', NULL
  );

  SELECT net.http_post(
    url := v_url,
    body := v_payload,
    headers := v_headers,
    timeout_milliseconds := 180000
  ) INTO v_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'queued', true,
    'request_id', v_request_id,
    'invoice_id', v_invoice.id
  );
END;
$$;


ALTER FUNCTION "public"."start_invoice_extraction_workflow"("p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_invoice_extraction_workflow"("p_invoice_id" "uuid") IS 'Tenant-safe workflow entrypoint that enqueues invoice extraction through pg_net after validating invoice access.';



CREATE OR REPLACE FUNCTION "public"."store_bank_account_secret"("p_bank_account_id" "uuid", "p_account_number" "text", "p_routing_number" "text", "p_fingerprint_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_secret_name text := 'bank_' || p_bank_account_id::text;
  v_secret_id uuid;
  v_row public.bank_accounts%ROWTYPE;
  v_account text;
  v_routing text;
  v_payload text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.bank_accounts
  WHERE id = p_bank_account_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Bank account row % not found', p_bank_account_id;
  END IF;

  v_account := regexp_replace(COALESCE(p_account_number, ''), '\D', '', 'g');
  v_routing := regexp_replace(COALESCE(p_routing_number, ''), '\D', '', 'g');

  IF v_account !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number is required';
  END IF;

  IF v_routing !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_fingerprint_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A backend-generated fingerprint hash is required';
  END IF;

  v_payload := jsonb_build_object(
    'account_number', v_account,
    'routing_number', v_routing,
    'account_holder_name', v_row.account_holder_name,
    'account_type', v_row.account_type
  )::text;

  SELECT id INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT * INTO v_secret_id
  FROM vault.create_secret(v_payload, v_secret_name, 'provider-neutral bank account');

  UPDATE public.bank_accounts
     SET secret_id = v_secret_id,
         account_last4 = right(v_account, 4),
         routing_last4 = right(v_routing, 4),
         fingerprint_hash = p_fingerprint_hash,
         updated_at = now()
   WHERE id = p_bank_account_id;

  RETURN jsonb_build_object(
    'bank_account_id', p_bank_account_id,
    'secret_id', v_secret_id,
    'account_last4', right(v_account, 4),
    'routing_last4', right(v_routing, 4)
  );
END;
$_$;


ALTER FUNCTION "public"."store_bank_account_secret"("p_bank_account_id" "uuid", "p_account_number" "text", "p_routing_number" "text", "p_fingerprint_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_onboarding_bank_secret"("p_bank_account_id" "uuid", "p_account_number" "text", "p_routing_number" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID;
  v_secret_id UUID;
  v_secret_name TEXT;
  v_payload TEXT;
BEGIN
  SELECT user_id INTO v_user_id
  FROM public.onboarding_bank_accounts
  WHERE id = p_bank_account_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;

  v_secret_name := 'onboarding-bank-' || p_bank_account_id::text;
  v_payload := jsonb_build_object(
    'onboarding_bank_account_id', p_bank_account_id,
    'user_id', v_user_id,
    'account_number', p_account_number,
    'routing_number', p_routing_number,
    'stored_at', now()
  )::text;

  SELECT vault.create_secret(v_payload, v_secret_name, 'tenant onboarding banking')
    INTO v_secret_id;

  UPDATE public.onboarding_bank_accounts
  SET banking_secret_id = v_secret_id
  WHERE id = p_bank_account_id;

  RETURN v_secret_id;
END;
$$;


