CREATE OR REPLACE FUNCTION "public"."store_payment_account_banking_secret"("p_account_id" "uuid", "p_account" "text", "p_routing" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_name text := 'pabank_' || p_account_id::text;
  v_secret_id uuid;
  v_row public.payment_accounts%ROWTYPE;
  v_payload text;
  v_last4 text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.payment_accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Payment account % not found', p_account_id;
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_account, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Account number is required';
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Routing number is required';
  END IF;

  v_last4 := right(regexp_replace(p_account, '\D', '', 'g'), 4);
  v_payload := jsonb_build_object('account', p_account, 'routing', p_routing)::text;

  -- Same convention as store_vendor_banking_secret: Vault name keyed on the account row id.
  SELECT id
    INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT *
    INTO v_secret_id
  FROM vault.create_secret(v_payload, v_secret_name, 'payment account banking');

  UPDATE public.payment_accounts
     SET banking_secret_id = v_secret_id,
         last_four = v_last4,
         updated_at = now()
   WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'account_id', p_account_id,
    'banking_secret_id', v_secret_id,
    'last_four', v_last4
  );
END;
$$;


ALTER FUNCTION "public"."store_payment_account_banking_secret"("p_account_id" "uuid", "p_account" "text", "p_routing" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_tax_identifier_secret"("p_business_verification_id" "uuid", "p_identifier_type" "text", "p_full_identifier" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID;
  v_secret_id UUID;
  v_secret_name TEXT;
  v_payload TEXT;
BEGIN
  SELECT user_id INTO v_user_id
  FROM public.business_verifications
  WHERE id = p_business_verification_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Business verification not found';
  END IF;

  v_secret_name := 'onboarding-tax-id-' || p_business_verification_id::text || '-' || extract(epoch from clock_timestamp())::text;
  v_payload := jsonb_build_object(
    'business_verification_id', p_business_verification_id,
    'user_id', v_user_id,
    'identifier_type', p_identifier_type,
    'full_identifier', p_full_identifier,
    'stored_at', now()
  )::text;

  SELECT vault.create_secret(v_payload, v_secret_name, 'tenant onboarding tax identifier')
    INTO v_secret_id;

  UPDATE public.business_verifications
  SET tax_identifier_secret_id = v_secret_id
  WHERE id = p_business_verification_id;

  RETURN v_secret_id;
END;
$$;


