CREATE OR REPLACE FUNCTION "public"."store_vendor_banking_secret"("p_banking_row_id" "uuid", "p_account" "text", "p_routing" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_name text := 'vbank_' || p_banking_row_id::text;
  v_secret_id uuid;
  v_row public.vendor_banking_details%ROWTYPE;
  v_payload text;
  v_last4 text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.vendor_banking_details
  WHERE id = p_banking_row_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Vendor banking row % not found', p_banking_row_id;
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_account, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Account number is required';
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Routing number is required';
  END IF;

  v_last4 := right(regexp_replace(p_account, '\D', '', 'g'), 4);
  v_payload := jsonb_build_object('account', p_account, 'routing', p_routing)::text;

  -- Ponytail: the Vault name is keyed on the banking row id, not vendor/org id,
  -- so a vendor's multiple accounts cannot overwrite each other's secrets.
  SELECT id
    INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT *
    INTO v_secret_id
  FROM vault.create_secret(v_payload, v_secret_name, 'vendor banking');

  UPDATE public.vendor_banking_details
     SET banking_secret_id = v_secret_id,
         account_last4 = v_last4,
         updated_at = now()
   WHERE id = p_banking_row_id;

  RETURN jsonb_build_object(
    'banking_row_id', p_banking_row_id,
    'banking_secret_id', v_secret_id,
    'account_last4', v_last4
  );
END;
$$;


ALTER FUNCTION "public"."store_vendor_banking_secret"("p_banking_row_id" "uuid", "p_account" "text", "p_routing" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_vendor_tax_secret"("p_tax_row_id" "uuid", "p_tax_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret_name text := 'vtax_' || p_tax_row_id::text;
  v_secret_id uuid;
  v_row public.vendor_tax_information%ROWTYPE;
  v_last4 text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.vendor_tax_information
  WHERE id = p_tax_row_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Vendor tax row % not found', p_tax_row_id;
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_tax_id, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Tax id is required';
  END IF;

  v_last4 := public.mask_tax_identifier(p_tax_id);

  -- Ponytail: the Vault name is keyed on the tax row id, not vendor/org id,
  -- so later vendor tax records do not collide with earlier records.
  SELECT id
    INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT *
    INTO v_secret_id
  FROM vault.create_secret(p_tax_id, v_secret_name, 'vendor tax id');

  UPDATE public.vendor_tax_information
     SET tax_secret_id = v_secret_id,
         tax_id_last4 = v_last4,
         updated_at = now()
   WHERE id = p_tax_row_id;

  RETURN jsonb_build_object(
    'tax_row_id', p_tax_row_id,
    'tax_secret_id', v_secret_id,
    'tax_id_last4', v_last4
  );
END;
$$;


ALTER FUNCTION "public"."store_vendor_tax_secret"("p_tax_row_id" "uuid", "p_tax_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_business_verification"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_full_identifier TEXT;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_full_identifier := CASE WHEN v_identifier_required THEN regexp_replace(COALESCE(p_payload->>'taxIdentifier', ''), '\D', '', 'g') ELSE NULL END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata,
    reviewed_by,
    reviewed_at,
    rejection_reason,
    updated_at
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    ),
    NULL,
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (user_id) WHERE user_id IS NOT NULL DO UPDATE
  SET legal_business_name = EXCLUDED.legal_business_name,
      business_type = EXCLUDED.business_type,
      identifier_type = EXCLUDED.identifier_type,
      identifier_last4 = EXCLUDED.identifier_last4,
      provider_name = EXCLUDED.provider_name,
      provider_reference_id = EXCLUDED.provider_reference_id,
      verification_status = EXCLUDED.verification_status,
      trust_score = EXCLUDED.trust_score,
      metadata = EXCLUDED.metadata,
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejection_reason = NULL,
      updated_at = now()
  RETURNING id INTO v_verification_id;

  IF v_identifier_required AND length(COALESCE(v_full_identifier, '')) > 0 THEN
    PERFORM public.store_tax_identifier_secret(v_verification_id, v_identifier_type, v_full_identifier);
  END IF;

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;


ALTER FUNCTION "public"."submit_business_verification"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_onboarding_bank_account"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_bank_id UUID;
  v_run_id UUID;
  v_account_number TEXT;
  v_routing_number TEXT;
  v_is_default BOOLEAN;
  v_billing_source TEXT;
  v_scope TEXT;
  v_scope_id UUID;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_account_number := regexp_replace(COALESCE(p_payload->>'account_number', ''), '[^0-9]', '', 'g');
  v_routing_number := regexp_replace(COALESCE(p_payload->>'routing_number', ''), '[^0-9]', '', 'g');
  v_is_default := COALESCE((p_payload->>'is_default')::boolean, false)
    OR NOT EXISTS (
      SELECT 1 FROM public.onboarding_bank_accounts
      WHERE user_id = v_user_id AND status <> 'inactive'
    );
  v_billing_source := COALESCE(NULLIF(p_payload->>'billing_address_source', ''), 'business');
  v_scope := NULLIF(p_payload->>'assignment_scope', '');
  v_scope_id := NULLIF(p_payload->>'assignment_id', '')::uuid;

  IF NULLIF(btrim(COALESCE(p_payload->>'bank_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Bank name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_payload->>'account_holder_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Account holder name is required';
  END IF;

  IF COALESCE(p_payload->>'account_type', '') NOT IN ('checking', 'savings') THEN
    RAISE EXCEPTION 'Account type must be checking or savings';
  END IF;

  IF length(v_routing_number) <> 9 THEN
    RAISE EXCEPTION 'Routing number must be 9 digits';
  END IF;

  IF length(v_account_number) < 4 OR length(v_account_number) > 17 THEN
    RAISE EXCEPTION 'Account number must be between 4 and 17 digits';
  END IF;

  IF v_scope IS NULL OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Select which organization, brand, or location this bank account belongs to';
  END IF;

  IF v_scope = 'organization' THEN
    SELECT om.organization_id INTO v_org_id
    FROM public.organization_members om
    WHERE om.user_id = v_user_id AND om.organization_id = v_scope_id;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that organization';
    END IF;
  ELSIF v_scope = 'brand' THEN
    SELECT b.organization_id, b.brand_id INTO v_org_id, v_brand_id
    FROM public.brand_members bm
    JOIN public.brands b ON b.brand_id = bm.brand_id
    WHERE bm.user_id = v_user_id AND bm.brand_id = v_scope_id;

    IF v_brand_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that brand';
    END IF;
  ELSIF v_scope = 'location' THEN
    SELECT l.organization_id, l.brand_id, l.id INTO v_org_id, v_brand_id, v_location_id
    FROM public.location_members lm
    JOIN public.locations l ON l.id = lm.location_id
    WHERE lm.user_id = v_user_id AND lm.location_id = v_scope_id;

    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that location';
    END IF;
  ELSE
    RAISE EXCEPTION 'Assignment scope must be organization, brand, or location';
  END IF;

  IF v_is_default THEN
    UPDATE public.onboarding_bank_accounts
    SET is_default = false
    WHERE user_id = v_user_id AND status <> 'inactive';
  END IF;

  INSERT INTO public.onboarding_bank_accounts (
    user_id,
    organization_id,
    brand_id,
    location_id,
    bank_name,
    account_holder_name,
    account_type,
    nickname,
    routing_number_last4,
    account_number_last4,
    billing_address_source,
    billing_address_line1,
    billing_address_line2,
    billing_address_city,
    billing_address_state,
    billing_address_postal_code,
    billing_address_country,
    is_default,
    status,
    metadata
  )
  VALUES (
    v_user_id,
    v_org_id,
    v_brand_id,
    v_location_id,
    btrim(p_payload->>'bank_name'),
    btrim(p_payload->>'account_holder_name'),
    p_payload->>'account_type',
    NULLIF(btrim(COALESCE(p_payload->>'nickname', '')), ''),
    right(v_routing_number, 4),
    right(v_account_number, 4),
    v_billing_source,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line1', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line2', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_city', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_state', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_postal_code', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_country', '')), '') END,
    v_is_default,
    'pending_signature',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  )
  RETURNING id INTO v_bank_id;

  PERFORM public.store_onboarding_bank_secret(v_bank_id, v_account_number, v_routing_number);

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'bank_account_submitted',
    'pending_signature',
    jsonb_build_object('onboarding_bank_account_id', v_bank_id)
  );

  RETURN (
    SELECT jsonb_build_object(
      'success', true,
      'bank_account', jsonb_build_object(
        'id', id,
        'organization_id', organization_id,
        'brand_id', brand_id,
        'location_id', location_id,
        'bank_name', bank_name,
        'account_holder_name', account_holder_name,
        'account_type', account_type,
        'nickname', nickname,
        'routing_number_last4', routing_number_last4,
        'account_number_last4', account_number_last4,
        'billing_address_source', billing_address_source,
        'is_default', is_default,
        'status', status
      )
    )
    FROM public.onboarding_bank_accounts
    WHERE id = v_bank_id
  );
END;
$$;


ALTER FUNCTION "public"."submit_onboarding_bank_account"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_onboarding_hierarchy_for_review"("p_user_id" "uuid", "p_hierarchy" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_business_status text;
  v_payment_verified boolean;
  v_pending_payment_metadata jsonb;
  v_usps_address_validation_enabled boolean;
  v_submission_id uuid;
  v_run_id uuid;
BEGIN
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Not authorized to submit hierarchy for another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('free_plan', 'stripe') THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  PERFORM public.validate_onboarding_hierarchy_payload(p_hierarchy);

  SELECT usps_address_validation_enabled
  INTO v_usps_address_validation_enabled
  FROM public.platform_onboarding_settings
  WHERE id = true;

  IF COALESCE(v_usps_address_validation_enabled, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'USPS address validation must be enabled before address onboarding can be submitted';
  END IF;

  INSERT INTO public.onboarding_hierarchy_submissions (user_id, hierarchy_payload, status, rejection_reason, reviewed_by, reviewed_at)
  VALUES (p_user_id, p_hierarchy, 'pending_review', NULL, NULL, NULL)
  ON CONFLICT (user_id) DO UPDATE
  SET hierarchy_payload = EXCLUDED.hierarchy_payload,
      status = 'pending_review',
      rejection_reason = NULL,
      reviewed_by = NULL,
      reviewed_at = NULL,
      updated_at = now()
  RETURNING id INTO v_submission_id;

  UPDATE public.profiles
  SET hierarchy_review_status = 'pending_review',
      onboarding_status = 'pending_review',
      onboarding_current_step = 'hierarchy_review',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  SELECT p.id, 'system', 'Tenant workspace pending review',
         COALESCE(p.full_name, p.email, 'A tenant') || ' submitted an organization hierarchy for review.', false
  FROM public.profiles p WHERE p.role = 'platform_admin';

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'submitted', 'pending_review', jsonb_build_object('submission_id', v_submission_id));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'pending_review', 'submission_id', v_submission_id);
END;
$$;


ALTER FUNCTION "public"."submit_onboarding_hierarchy_for_review"("p_user_id" "uuid", "p_hierarchy" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_vendor_banking_via_link"("p_token" "text", "p_account" "text", "p_routing" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
BEGIN
  SELECT * INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  IF regexp_replace(COALESCE(p_account, ''), '\D', '', 'g') !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number (4-17 digits) is required';
  END IF;

  IF regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g') !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF v_token.intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = v_token.vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'pending',
    'pending',
    false,
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_bank.id,
    v_reason,
    v_token.created_by,
    'on_file_contact',
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_request;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted',
         updated_at = now(),
         updated_by = v_token.created_by
   WHERE id = v_token.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_type, metadata
  ) VALUES (
    v_token.vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    'vendor',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'token_id', v_token.id,
      'intent', v_token.intent
    )
  );

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor banking callback required',
      'A vendor submitted banking details. Call the phone number already on file before paying this account.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'change_request_id', v_request.id,
        'token_id', v_token.id,
        'intent', v_token.intent
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_token.intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$_$;


ALTER FUNCTION "public"."submit_vendor_banking_via_link"("p_token" "text", "p_account" "text", "p_routing" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."switch_user_context"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_role text;
  v_tenant_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = p_organization_id;

  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_organization_id
    AND user_id = v_user_id;

  IF v_role IS NULL AND public.get_auth_role() = 'tenant_super_admin' AND v_tenant_id = public.get_auth_tenant() THEN
    v_role := 'tenant_super_admin';
  END IF;

  IF v_role IS NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'User is not a member of this organization';
  END IF;

  IF v_role IS NULL THEN
    v_role := 'platform_admin';
  END IF;

  v_role := public.normalize_app_role(v_role);

  IF p_brand_id IS NOT NULL
     AND NOT (p_brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))) THEN
    RAISE EXCEPTION 'Brand % not in your accessible scope', p_brand_id;
  END IF;

  IF p_location_id IS NOT NULL
     AND NOT (p_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))) THEN
    RAISE EXCEPTION 'Location % not in your accessible scope', p_location_id;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      organization_id = p_organization_id,
      brand_id = p_brand_id,
      location_id = p_location_id,
      role = v_role,
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', p_organization_id,
    'brand_id', p_brand_id,
    'location_id', p_location_id
  );
END;
$$;


ALTER FUNCTION "public"."switch_user_context"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_auth_metadata_from_profile"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_profile record;
BEGIN
  SELECT
    role,
    tenant_id,
    organization_id,
    brand_id,
    location_id
  INTO v_profile
  FROM public.profiles
  WHERE id = p_user_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', COALESCE(v_profile.role, ''),
    'tenant_id', COALESCE(v_profile.tenant_id::text, ''),
    'organization_id', COALESCE(v_profile.organization_id::text, ''),
    'brand_id', COALESCE(v_profile.brand_id::text, ''),
    'location_id', COALESCE(v_profile.location_id::text, '')
  )
  WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."sync_auth_metadata_from_profile"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_dim_product"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO public.dim_product (source_product_id, product_code, name, category, latest_price, organization_id, location_id)
    VALUES (NEW.id, NEW.product_id, NEW.name, NEW.category, NEW.latest_price, NEW.organization_id, NEW.location_id)
    ON CONFLICT (source_product_id) DO UPDATE SET
        product_code = EXCLUDED.product_code,
        name = EXCLUDED.name,
        category = EXCLUDED.category,
        latest_price = EXCLUDED.latest_price,
        organization_id = EXCLUDED.organization_id,
        location_id = EXCLUDED.location_id;
    RETURN NEW;
END;
$$;


