CREATE OR REPLACE FUNCTION "public"."sync_purchase_card_spend"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.refresh_purchase_card_spend(OLD.card_id);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.card_id IS DISTINCT FROM NEW.card_id THEN
    PERFORM public.refresh_purchase_card_spend(OLD.card_id);
  END IF;

  PERFORM public.refresh_purchase_card_spend(NEW.card_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_purchase_card_spend"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_recipe_ingredients_from_jsonb"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  ing record;
  v_product_id uuid;
  v_sub_recipe_id uuid;
begin
  delete from public.recipe_ingredients where recipe_id = new.id;
  if new.ingredients is not null and jsonb_typeof(new.ingredients) = 'array' then
    for ing in select value, ordinality from jsonb_array_elements(new.ingredients) with ordinality
    loop
      v_product_id := nullif(ing.value->>'product_id', '')::uuid;
      v_sub_recipe_id := nullif(ing.value->>'sub_recipe_id', '')::uuid;
      if v_product_id is not null or v_sub_recipe_id is not null then
        insert into public.recipe_ingredients (
          organization_id, recipe_id, product_id, sub_recipe_id, quantity, unit,
          yield_percentage, cost_unit, unit_cost_snapshot, notes, sort_order
        ) values (
          new.organization_id, new.id, v_product_id, v_sub_recipe_id,
          coalesce(nullif(ing.value->>'quantity', '')::numeric, 0), ing.value->>'unit',
          coalesce(nullif(ing.value->>'yield_percentage', '')::numeric, 100),
          ing.value->>'cost_unit', coalesce(nullif(ing.value->>'unit_cost', '')::numeric, 0),
          nullif(ing.value->>'notes', ''), ing.ordinality - 1
        );
      end if;
    end loop;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_recipe_ingredients_from_jsonb"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_recipe_margin_alert_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.margin_alert_status is distinct from old.margin_alert_status then
    new.margin_alert_enabled := new.margin_alert_status = 'active';
  elsif tg_op = 'UPDATE' and new.margin_alert_enabled is distinct from old.margin_alert_enabled then
    new.margin_alert_status := case when new.margin_alert_enabled then 'active' else 'none' end;
  else
    new.margin_alert_status := coalesce(
      new.margin_alert_status,
      case when coalesce(new.margin_alert_enabled, false) then 'active' else 'none' end
    );
    new.margin_alert_enabled := new.margin_alert_status = 'active';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_recipe_margin_alert_lifecycle"() OWNER TO "postgres";


