CREATE OR REPLACE FUNCTION "public"."tenant_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM v_org_id THEN
    RETURN false;
  END IF;

  -- Org-level tier (ledger_entries): unaffected by this change.
  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN v_role IN ('org_manager', 'tenant_super_admin');
  END IF;

  -- Every other row: exact match against whichever location this caller currently has
  -- active, for every role including location_manager/ground_staff (unchanged for them).
  RETURN p_location_id IS NOT NULL AND p_location_id = v_location_id;
END;
$$;


ALTER FUNCTION "public"."tenant_scope_visible"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_deleted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tenant_scope_writable"("p_organization_id" "uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_allow_ground_staff" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  v_role := public.get_auth_role();

  IF v_role = 'ground_staff' AND NOT p_allow_ground_staff THEN
    RETURN false;
  END IF;

  IF v_role NOT IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RETURN false;
  END IF;

  RETURN public.tenant_scope_visible(
    p_organization_id,
    p_brand_id,
    p_location_id,
    p_deleted_at
  );
END;
$$;


ALTER FUNCTION "public"."tenant_scope_writable"("p_organization_id" "uuid", "p_brand_id" "uuid", "p_location_id" "uuid", "p_deleted_at" timestamp with time zone, "p_allow_ground_staff" boolean) OWNER TO "postgres";


