CREATE OR REPLACE FUNCTION "public"."transfer_from_scope_writable"("p_organization_id" "uuid", "p_from_location_id" "uuid", "p_deleted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.is_manager_or_above()
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


ALTER FUNCTION "public"."transfer_from_scope_writable"("p_organization_id" "uuid", "p_from_location_id" "uuid", "p_deleted_at" timestamp with time zone) OWNER TO "postgres";


