CREATE OR REPLACE FUNCTION "public"."update_onboarding_verification_settings"("p_ein_enabled" boolean, "p_ssn_enabled" boolean, "p_usps_address_validation_enabled" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_settings public.platform_onboarding_settings%ROWTYPE;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.platform_onboarding_settings
  SET ein_verification_enabled = COALESCE(p_ein_enabled, ein_verification_enabled),
      ssn_verification_enabled = COALESCE(p_ssn_enabled, ssn_verification_enabled),
      usps_address_validation_enabled = COALESCE(p_usps_address_validation_enabled, usps_address_validation_enabled)
  WHERE id = true
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'success', true,
    'ein_verification_enabled', v_settings.ein_verification_enabled,
    'ssn_verification_enabled', v_settings.ssn_verification_enabled,
    'usps_address_validation_enabled', v_settings.usps_address_validation_enabled,
    'updated_at', v_settings.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."update_onboarding_verification_settings"("p_ein_enabled" boolean, "p_ssn_enabled" boolean, "p_usps_address_validation_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_details"("p_product_id" "uuid", "p_name" "text", "p_restops_product_id" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_accounting_category" "text" DEFAULT NULL::"text", "p_is_inventoried" boolean DEFAULT NULL::boolean, "p_is_tax_exempt" boolean DEFAULT NULL::boolean, "p_report_by_unit" "text" DEFAULT NULL::"text", "p_base_unit" "text" DEFAULT NULL::"text", "p_latest_price" numeric DEFAULT NULL::numeric, "p_location_specific" boolean DEFAULT NULL::boolean, "p_report_unit_quantity" numeric DEFAULT NULL::numeric, "p_report_unit_source_price" numeric DEFAULT NULL::numeric, "p_expected_version" integer DEFAULT NULL::integer) RETURNS "public"."products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_updated public.products%ROWTYPE;
  v_category text;
  v_accounting_category text;
  v_category_changed boolean;
  v_needs_approval boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF p_expected_version IS NOT NULL AND p_expected_version <> COALESCE(v_product.version_number, 1) THEN
    RAISE EXCEPTION 'Product was changed by another session. Refresh and try again.';
  END IF;
  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;
  IF NULLIF(btrim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  v_category := NULLIF(btrim(COALESCE(p_category, '')), '');
  v_accounting_category := NULLIF(btrim(COALESCE(p_accounting_category, '')), '');
  v_category_changed :=
    COALESCE(v_product.category, '') IS DISTINCT FROM COALESCE(v_category, '')
    OR COALESCE(v_product.accounting_category, '') IS DISTINCT FROM COALESCE(v_accounting_category, '');
  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_product.organization_id)
    AND NOT COALESCE(v_product.pending_approval, false);

  UPDATE public.products
     SET name = upper(btrim(p_name)),
         product_id = NULLIF(btrim(COALESCE(p_restops_product_id, '')), ''),
         description = NULLIF(btrim(COALESCE(p_description, '')), ''),
         category = v_category,
         accounting_category = v_accounting_category,
         is_tax_exempt = COALESCE(p_is_tax_exempt, false),
         report_by_unit = NULLIF(btrim(COALESCE(p_report_by_unit, '')), ''),
         base_unit = NULLIF(btrim(COALESCE(p_base_unit, '')), ''),
         latest_price = COALESCE(p_latest_price, 0),
         location_specific = COALESCE(p_location_specific, false),
         report_unit_quantity = GREATEST(COALESCE(p_report_unit_quantity, report_unit_quantity, 1), 0.0001),
         report_unit_source_price = COALESCE(p_report_unit_source_price, report_unit_source_price, p_latest_price, latest_price, 0),
         pending_approval = CASE WHEN v_needs_approval THEN true ELSE pending_approval END,
         pending_action = CASE WHEN v_needs_approval THEN 'update' ELSE pending_action END,
         pending_snapshot = CASE WHEN v_needs_approval THEN to_jsonb(v_product) ELSE pending_snapshot END,
         submitted_by = CASE WHEN v_needs_approval THEN auth.uid() ELSE submitted_by END,
         submitted_at = CASE WHEN v_needs_approval THEN now() ELSE submitted_at END,
         category_source = CASE WHEN v_category_changed THEN 'manual' ELSE category_source END,
         category_review_status = CASE WHEN v_category_changed THEN 'approved' ELSE category_review_status END,
         category_reviewed_at = CASE WHEN v_category_changed THEN now() ELSE category_reviewed_at END,
         category_reviewed_by = CASE WHEN v_category_changed THEN auth.uid() ELSE category_reviewed_by END,
         suggested_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_category END,
         suggested_category_type = CASE WHEN v_category_changed THEN NULL ELSE suggested_category_type END,
         suggested_accounting_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_accounting_category END,
         category_reason = CASE WHEN v_category_changed THEN NULL ELSE category_reason END,
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_updated;

  IF p_is_inventoried IS NOT NULL AND p_is_inventoried IS DISTINCT FROM v_product.is_inventoried THEN
    PERFORM public.set_product_inventory_tracking(p_product_id, p_is_inventoried);
    SELECT * INTO v_updated FROM public.products WHERE id = p_product_id;
  ELSIF p_is_inventoried IS NOT NULL THEN
    UPDATE public.products
       SET is_inventoried = p_is_inventoried, updated_at = now()
     WHERE id = p_product_id
     RETURNING * INTO v_updated;
  END IF;

  UPDATE public.inventory
     SET unit_cost = COALESCE(v_updated.latest_price, unit_cost),
         current_unit = COALESCE(NULLIF(v_updated.report_by_unit, ''), current_unit),
         report_by = COALESCE(NULLIF(v_updated.report_by_unit, ''), report_by),
         category = COALESCE(NULLIF(v_updated.category, ''), category),
         accounting_category = COALESCE(NULLIF(v_updated.accounting_category, ''), accounting_category),
         updated_at = now()
   WHERE organization_id = v_updated.organization_id
     AND deleted_at IS NULL
     AND (internal_product_id = v_updated.id OR product_id = v_updated.product_id);

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."update_product_details"("p_product_id" "uuid", "p_name" "text", "p_restops_product_id" "text", "p_description" "text", "p_category" "text", "p_accounting_category" "text", "p_is_inventoried" boolean, "p_is_tax_exempt" boolean, "p_report_by_unit" "text", "p_base_unit" "text", "p_latest_price" numeric, "p_location_specific" boolean, "p_report_unit_quantity" numeric, "p_report_unit_source_price" numeric, "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recipe_category"("p_category_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."recipe_categories"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
  v_name text := trim(COALESCE(p_name, ''));
  v_slug text;
  v_old public.recipe_categories;
  v_row public.recipe_categories;
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() OR NOT public.is_manager_or_above() THEN
    RAISE EXCEPTION 'Not authorized to update recipe categories';
  END IF;

  IF p_category_id IS NULL THEN
    RAISE EXCEPTION 'Category id is required';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'Category name is required';
  END IF;

  SELECT *
  INTO v_old
  FROM public.recipe_categories rc
  WHERE rc.id = p_category_id
    AND rc.organization_id = v_org
    AND rc.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category not found';
  END IF;

  v_slug := public.normalize_recipe_category_slug(v_name);
  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'Category name is invalid';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.recipe_categories rc
    WHERE rc.organization_id = v_org
      AND rc.deleted_at IS NULL
      AND rc.id <> v_old.id
      AND (lower(rc.slug) = v_slug OR lower(rc.name) = lower(v_name))
  ) THEN
    RAISE EXCEPTION 'A category with this name already exists';
  END IF;

  UPDATE public.recipe_categories rc
  SET
    name = v_name,
    slug = v_slug,
    description = NULLIF(trim(COALESCE(p_description, '')), ''),
    is_active = COALESCE(p_is_active, rc.is_active),
    updated_at = now()
  WHERE rc.id = v_old.id
  RETURNING * INTO v_row;

  -- Keep recipe assignments when slug changes (recipes store category as slug text).
  IF lower(v_old.slug) IS DISTINCT FROM lower(v_row.slug) THEN
    UPDATE public.recipes r
    SET
      category = v_row.slug,
      updated_at = now()
    WHERE r.organization_id = v_org
      AND r.deleted_at IS NULL
      AND lower(COALESCE(r.category, '')) = lower(v_old.slug);

    -- If a default seed slug was vacated by rename, leave a soft-deleted tombstone
    -- so ensure_default_recipe_categories does not recreate the old default.
    IF lower(v_old.slug) IN ('appetizer', 'main_course', 'dessert', 'beverage', 'side', 'sauce')
       AND NOT EXISTS (
         SELECT 1
         FROM public.recipe_categories rc
         WHERE rc.organization_id = v_org
           AND lower(rc.slug) = lower(v_old.slug)
       )
    THEN
      INSERT INTO public.recipe_categories (
        organization_id, name, slug, description, display_order, is_active, is_system, deleted_at
      )
      VALUES (
        v_org,
        v_old.name,
        v_old.slug,
        v_old.description,
        v_old.display_order,
        false,
        true,
        now()
      );
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."update_recipe_category"("p_category_id" "uuid", "p_name" "text", "p_description" "text", "p_is_active" boolean, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF to_jsonb(NEW) ? 'updated_at' THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('updated_at', now()));
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_approval_limit"("target_user_id" "uuid", "new_limit" numeric, "p_unlimited" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_target record;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'Target user is required';
  END IF;

  IF new_limit IS NULL OR new_limit < 0 THEN
    RAISE EXCEPTION 'Approval limit must be non-negative';
  END IF;

  IF target_user_id = v_actor_id THEN
    RAISE EXCEPTION 'Users cannot set their own approval limit';
  END IF;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id,
         COALESCE(invoice_approval_limit, 0) AS invoice_approval_limit
    INTO v_actor
  FROM public.profiles
  WHERE id = v_actor_id
    AND deleted_at IS NULL;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id
    INTO v_target
  FROM public.profiles
  WHERE id = target_user_id
    AND deleted_at IS NULL;

  IF v_actor.id IS NULL THEN
    RAISE EXCEPTION 'Actor profile not found';
  END IF;

  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'Target profile not found';
  END IF;

  IF v_actor.role <> 'platform_admin'
    AND v_actor.role <> 'tenant_super_admin'
    AND v_actor.organization_id IS DISTINCT FROM v_target.organization_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your organization';
  END IF;

  IF v_actor.role = 'tenant_super_admin'
    AND v_actor.tenant_id IS DISTINCT FROM v_target.tenant_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your tenant';
  END IF;

  IF v_actor.role NOT IN ('platform_admin', 'tenant_super_admin')
    AND new_limit > v_actor.invoice_approval_limit THEN
    RAISE EXCEPTION 'Cannot grant approval limit % above your own limit %',
      new_limit, v_actor.invoice_approval_limit;
  END IF;

  IF v_actor.role = 'platform_admin' THEN
    IF v_target.role = 'platform_admin' THEN
      RAISE EXCEPTION 'Platform admins cannot set peer platform admin limits';
    END IF;
  ELSIF v_actor.role = 'tenant_super_admin' THEN
    IF v_target.role = 'tenant_super_admin' THEN
      RAISE EXCEPTION 'Tenant super admins cannot set peer limits';
    END IF;
  ELSIF v_actor.role = 'org_manager' THEN
    IF v_target.role <> 'branch_manager' THEN
      RAISE EXCEPTION 'Org managers may only set branch manager approval limits';
    END IF;
  ELSIF v_actor.role = 'branch_manager' THEN
    IF v_target.role <> 'location_manager' THEN
      RAISE EXCEPTION 'Branch managers may only set location manager approval limits';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.get_my_accessible_brand_ids() b(id)
      WHERE b.id = COALESCE(
        v_target.brand_id,
        (SELECT l.brand_id FROM public.locations l WHERE l.id = v_target.location_id)
      )
    ) THEN
      RAISE EXCEPTION 'Target user is outside your brand scope';
    END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient role to set approval limits';
  END IF;

  UPDATE public.profiles
     SET invoice_approval_limit = new_limit,
         has_unlimited_approval = p_unlimited,
         updated_at = now()
   WHERE id = target_user_id;
END;
$$;


ALTER FUNCTION "public"."update_user_approval_limit"("target_user_id" "uuid", "new_limit" numeric, "p_unlimited" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_vendor_ap_routing"("p_vendor_id" "uuid", "p_ap_routing_preference" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'reconciliation'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  target_org UUID;
  old_preference TEXT;
  updated_vendor JSONB;
BEGIN
  IF p_vendor_id IS NULL THEN
    RAISE EXCEPTION 'vendor id is required';
  END IF;

  IF p_ap_routing_preference NOT IN ('payments', 'storage', 'accounting', 'manual_paid_only') THEN
    RAISE EXCEPTION 'Invalid AP routing preference: %', p_ap_routing_preference;
  END IF;

  IF NOT public.is_manager_or_above() AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'Insufficient permissions to update vendor AP routing';
  END IF;

  target_org := COALESCE(p_organization_id, public.get_my_org());

  IF target_org IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (
    public.is_platform_admin()
    OR (SELECT auth.role()) = 'service_role'
    OR target_org = public.get_my_org()
  ) THEN
    RAISE EXCEPTION 'Organization is outside caller tenant scope';
  END IF;

  SELECT ap_routing_preference
  INTO old_preference
  FROM public.vendors
  WHERE id = p_vendor_id
    AND organization_id = target_org;

  IF old_preference IS NULL THEN
    RAISE EXCEPTION 'Vendor not found for organization';
  END IF;

  UPDATE public.vendors
     SET ap_routing_preference = p_ap_routing_preference,
         ap_routing_updated_at = now(),
         ap_routing_updated_by = auth.uid(),
         file_routing_preference = CASE
           WHEN p_ap_routing_preference IN ('payments', 'storage', 'accounting') THEN p_ap_routing_preference
           ELSE file_routing_preference
         END
   WHERE id = p_vendor_id
     AND organization_id = target_org
   RETURNING to_jsonb(public.vendors.*)
   INTO updated_vendor;

  INSERT INTO public.audit_logs (
    organization_id, user_id, action, table_name, record_id, module,
    entity_type, entity_id, field_changed, old_value, new_value, details, created_at
  ) VALUES (
    target_org, auth.uid(), 'vendor_ap_routing_changed', 'vendors', p_vendor_id, 'reconciliation',
    'vendor', p_vendor_id::TEXT, 'ap_routing_preference', old_preference, p_ap_routing_preference,
    'Vendor AP routing changed from ' || old_preference || ' to ' || p_ap_routing_preference || ' via ' || COALESCE(p_source, 'reconciliation'),
    now()
  );

  RETURN updated_vendor;
END;
$$;


ALTER FUNCTION "public"."update_vendor_ap_routing"("p_vendor_id" "uuid", "p_ap_routing_preference" "text", "p_organization_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_vendor_metrics_on_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Entering the "spent" lifecycle (approved or paid -- normalize_invoice_ap_state can jump an
  -- update straight from approved to paid in the same statement, so NEW.status may already be
  -- 'paid' the first time this invoice is ever seen as spent).
  IF NEW.status IN ('approved', 'paid') AND (OLD.status IS NULL OR OLD.status NOT IN ('approved', 'paid')) THEN
    UPDATE public.vendors
    SET total_spent = total_spent + NEW.total_amount,
        unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Leaving the "spent" lifecycle entirely (rejected/flagged/reverted -- NOT just moving between
  -- approved and paid) while not soft-deleted: back out total spend, and back out unpaid_ap too
  -- if it hadn't already been paid off.
  IF OLD.status IN ('approved', 'paid') AND NEW.status NOT IN ('approved', 'paid') AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  -- Entering paid: remove from outstanding AP.
  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS NULL OR OLD.payment_status != 'paid') THEN
    UPDATE public.vendors
    SET unpaid_ap = GREATEST(unpaid_ap - NEW.total_amount, 0)
    WHERE id = NEW.vendor_id;
  END IF;

  -- Payment reversed on a still-approved-or-paid invoice: it's outstanding again.
  IF OLD.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM 'paid'
     AND NEW.status IN ('approved', 'paid') AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Soft-deleting an approved-or-paid invoice: back out the same as leaving that lifecycle.
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND OLD.status IN ('approved', 'paid') THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_vendor_metrics_on_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_invoice_line_items"("p_invoice_id" "uuid", "p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_item RECORD;
  v_incoming_ids UUID[] := ARRAY[]::UUID[];
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.invoices
  WHERE id = p_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    id UUID,
    inventory_item_id TEXT,
    internal_product_id UUID,
    item_name TEXT,
    quantity NUMERIC,
    unit_price NUMERIC,
    total_price NUMERIC,
    vendor_item_code TEXT,
    vendor_unit TEXT,
    pack_size TEXT
  ) LOOP
    IF v_item.id IS NULL THEN
      v_item.id := gen_random_uuid();

      INSERT INTO public.invoice_line_items (
        id, invoice_id, organization_id, inventory_item_id, internal_product_id,
        item_name, quantity, unit_price, total_price, vendor_item_code, vendor_unit, pack_size
      ) VALUES (
        v_item.id, p_invoice_id, v_org_id, v_item.inventory_item_id, v_item.internal_product_id,
        v_item.item_name, v_item.quantity, v_item.unit_price, v_item.total_price,
        v_item.vendor_item_code, v_item.vendor_unit, NULLIF(v_item.pack_size, '')
      );
    ELSE
      UPDATE public.invoice_line_items
         SET inventory_item_id = v_item.inventory_item_id,
             internal_product_id = v_item.internal_product_id,
             item_name = v_item.item_name,
             quantity = v_item.quantity,
             unit_price = v_item.unit_price,
             total_price = v_item.total_price,
             vendor_item_code = v_item.vendor_item_code,
             vendor_unit = v_item.vendor_unit,
             pack_size = NULLIF(v_item.pack_size, '')
       WHERE id = v_item.id
         AND invoice_id = p_invoice_id;
    END IF;

    v_incoming_ids := array_append(v_incoming_ids, v_item.id);
  END LOOP;

  DELETE FROM public.invoice_line_items
   WHERE invoice_id = p_invoice_id
     AND id <> ALL(v_incoming_ids);
END;
$$;


ALTER FUNCTION "public"."upsert_invoice_line_items"("p_invoice_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."budget_targets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "brand_id" "uuid",
    "location_id" "uuid",
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "category" "text" NOT NULL,
    "target_amount" numeric DEFAULT 0 NOT NULL,
    "target_percent" numeric,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

ALTER TABLE ONLY "public"."budget_targets" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."budget_targets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_location_performance_budget"("p_organization_id" "uuid", "p_location_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_category" "text", "p_target_amount" numeric) RETURNS "public"."budget_targets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_existing_id uuid;
  v_result public.budget_targets;
BEGIN
  PERFORM public.assert_performance_location_access(
    p_organization_id, p_location_id, true
  );

  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RAISE EXCEPTION 'A valid budget period is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(trim(p_category), '') IS NULL THEN
    RAISE EXCEPTION 'Budget category is required' USING ERRCODE = '22023';
  END IF;
  IF p_target_amount IS NULL OR p_target_amount < 0 THEN
    RAISE EXCEPTION 'Budget amount must be non-negative' USING ERRCODE = '22023';
  END IF;

  SELECT l.brand_id INTO v_brand_id
  FROM public.locations l
  WHERE l.id = p_location_id
    AND l.organization_id = p_organization_id;

  SELECT bt.id INTO v_existing_id
  FROM public.budget_targets bt
  WHERE bt.organization_id = p_organization_id
    AND bt.location_id = p_location_id
    AND bt.brand_id IS NOT DISTINCT FROM v_brand_id
    AND bt.period_start = p_period_start
    AND bt.period_end = p_period_end
    AND bt.category = trim(p_category)
  ORDER BY bt.updated_at DESC NULLS LAST, bt.created_at DESC NULLS LAST
  LIMIT 1;

  IF v_existing_id IS NULL THEN
    INSERT INTO public.budget_targets (
      organization_id,
      brand_id,
      location_id,
      period_start,
      period_end,
      category,
      target_amount,
      target_percent,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      v_brand_id,
      p_location_id,
      p_period_start,
      p_period_end,
      trim(p_category),
      p_target_amount,
      NULL,
      auth.uid(),
      auth.uid()
    )
    RETURNING * INTO v_result;
  ELSE
    UPDATE public.budget_targets
    SET target_amount = p_target_amount,
        target_percent = NULL,
        updated_by = auth.uid(),
        updated_at = now()
    WHERE id = v_existing_id
    RETURNING * INTO v_result;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."upsert_location_performance_budget"("p_organization_id" "uuid", "p_location_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_category" "text", "p_target_amount" numeric) OWNER TO "postgres";


