CREATE OR REPLACE FUNCTION "public"."upsert_product_barcode"("p_product_id" "uuid", "p_barcode" "text", "p_symbology" "text" DEFAULT 'unknown'::"text") RETURNS "public"."product_barcodes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_row public.product_barcodes%ROWTYPE;
BEGIN
  SELECT * INTO v_product FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to edit product barcodes';
  END IF;
  IF NULLIF(btrim(COALESCE(p_barcode, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Barcode is required';
  END IF;

  INSERT INTO public.product_barcodes (
    organization_id, brand_id, location_id, product_id, barcode, symbology, created_by, deleted_at, deleted_by
  ) VALUES (
    v_product.organization_id, v_product.brand_id, v_product.location_id, v_product.id,
    btrim(p_barcode), COALESCE(NULLIF(btrim(p_symbology), ''), 'unknown'), auth.uid(), NULL, NULL
  )
  ON CONFLICT (organization_id, barcode)
  DO UPDATE SET
    product_id = EXCLUDED.product_id,
    brand_id = EXCLUDED.brand_id,
    location_id = EXCLUDED.location_id,
    symbology = EXCLUDED.symbology,
    deleted_at = NULL,
    deleted_by = NULL
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_product_barcode"("p_product_id" "uuid", "p_barcode" "text", "p_symbology" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."product_count_units" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "brand_id" "uuid",
    "location_id" "uuid",
    "product_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "normalized_name" "text" NOT NULL,
    "quantity" numeric DEFAULT 1 NOT NULL,
    "unit" "text" NOT NULL,
    "unit_price" numeric DEFAULT 0 NOT NULL,
    "source_quantity" numeric DEFAULT 1 NOT NULL,
    "source_unit" "text" NOT NULL,
    "source_price" numeric DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "product_count_units_quantity_check" CHECK (("quantity" > (0)::numeric)),
    CONSTRAINT "product_count_units_source_quantity_check" CHECK (("source_quantity" > (0)::numeric))
);


ALTER TABLE "public"."product_count_units" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_product_count_unit"("p_product_id" "uuid", "p_name" "text", "p_quantity" numeric, "p_unit" "text", "p_unit_price" numeric, "p_source_quantity" numeric, "p_source_unit" "text", "p_source_price" numeric) RETURNS "public"."product_count_units"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_normalized_name text;
  v_existing_id uuid;
  v_count_unit public.product_count_units%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  v_normalized_name := lower(trim(COALESCE(p_name, '')));

  IF v_normalized_name = '' THEN
    RAISE EXCEPTION 'Count unit name is required';
  END IF;

  IF COALESCE(p_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Count unit quantity must be greater than zero';
  END IF;

  IF COALESCE(p_source_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Source package quantity must be greater than zero';
  END IF;

  SELECT id
    INTO v_existing_id
  FROM public.product_count_units
  WHERE organization_id = v_product.organization_id
    AND product_id = v_product.id
    AND normalized_name = v_normalized_name
    AND deleted_at IS NULL
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.product_count_units
       SET brand_id = v_product.brand_id,
           location_id = v_product.location_id,
           name = trim(p_name),
           quantity = p_quantity,
           unit = trim(p_unit),
           unit_price = COALESCE(p_unit_price, 0),
           source_quantity = p_source_quantity,
           source_unit = trim(p_source_unit),
           source_price = COALESCE(p_source_price, 0),
           is_active = true,
           updated_at = now()
     WHERE id = v_existing_id
     RETURNING * INTO v_count_unit;
  ELSE
    INSERT INTO public.product_count_units (
      organization_id,
      brand_id,
      location_id,
      product_id,
      name,
      normalized_name,
      quantity,
      unit,
      unit_price,
      source_quantity,
      source_unit,
      source_price,
      is_active,
      created_by
    )
    VALUES (
      v_product.organization_id,
      v_product.brand_id,
      v_product.location_id,
      v_product.id,
      trim(p_name),
      v_normalized_name,
      p_quantity,
      trim(p_unit),
      COALESCE(p_unit_price, 0),
      p_source_quantity,
      trim(p_source_unit),
      COALESCE(p_source_price, 0),
      true,
      auth.uid()
    )
    RETURNING * INTO v_count_unit;
  END IF;

  RETURN v_count_unit;
END;
$$;


ALTER FUNCTION "public"."upsert_product_count_unit"("p_product_id" "uuid", "p_name" "text", "p_quantity" numeric, "p_unit" "text", "p_unit_price" numeric, "p_source_quantity" numeric, "p_source_unit" "text", "p_source_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_invoice"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_line_discrepancies jsonb := '[]'::jsonb;
  v_total_discrepancies jsonb := '[]'::jsonb;
  v_discrepancies jsonb := '[]'::jsonb;
  v_line record;
  v_expected_line_total numeric;
  v_line_sum numeric := 0;
  v_expected_total numeric;
  v_result jsonb;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND public.tenant_scope_visible(organization_id, brand_id, location_id, deleted_at);

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice % not found or not visible', p_invoice_id;
  END IF;

  FOR v_line IN
    SELECT id, quantity, unit_price, total_price
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
  LOOP
    v_expected_line_total := COALESCE(v_line.quantity, 0) * COALESCE(v_line.unit_price, 0);
    v_line_sum := v_line_sum + COALESCE(v_line.total_price, 0);

    -- ponytail: fixed 0.01 epsilon assumes 2-decimal money and is not
    -- currency-aware. Upgrade path: derive epsilon from currency scale.
    IF abs(v_expected_line_total - COALESCE(v_line.total_price, 0)) >= 0.01 THEN
      v_line_discrepancies := v_line_discrepancies || jsonb_build_array(
        jsonb_build_object(
          'line_id', v_line.id,
          'field', 'total_price',
          'expected', v_expected_line_total,
          'got', COALESCE(v_line.total_price, 0)
        )
      );
    END IF;
  END LOOP;

  IF abs(v_line_sum - COALESCE(v_invoice.subtotal, 0)) >= 0.01 THEN
    v_total_discrepancies := v_total_discrepancies || jsonb_build_array(
      jsonb_build_object(
        'field', 'subtotal',
        'expected', v_line_sum,
        'got', COALESCE(v_invoice.subtotal, 0)
      )
    );
  END IF;

  v_expected_total :=
    COALESCE(v_invoice.subtotal, 0)
    + COALESCE(v_invoice.tax_amount, 0)
    + COALESCE(v_invoice.fuel_surcharge, 0)
    + COALESCE(v_invoice.delivery_fee, 0)
    + COALESCE(v_invoice.other_charges, 0);

  IF abs(v_expected_total - COALESCE(v_invoice.total_amount, 0)) >= 0.01 THEN
    v_total_discrepancies := v_total_discrepancies || jsonb_build_array(
      jsonb_build_object(
        'field', 'total_amount',
        'expected', v_expected_total,
        'got', COALESCE(v_invoice.total_amount, 0)
      )
    );
  END IF;

  v_discrepancies := v_line_discrepancies || v_total_discrepancies;

  v_result := jsonb_build_object(
    'line_math', CASE WHEN jsonb_array_length(v_line_discrepancies) = 0 THEN 'pass' ELSE 'fail' END,
    'total_math', CASE WHEN jsonb_array_length(v_total_discrepancies) = 0 THEN 'pass' ELSE 'fail' END,
    'discrepancies', v_discrepancies
  );

  UPDATE public.invoices
     SET validation_results = COALESCE(validation_results, '{}'::jsonb) || v_result,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."validate_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_onboarding_address_payload"("p_address" "jsonb", "p_label" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_country text := lower(btrim(COALESCE(p_address->>'country', 'United States')));
  v_postal text := btrim(COALESCE(p_address->>'postalCode', p_address->>'zipCode', p_address->>'zip', ''));
BEGIN
  IF p_address IS NULL OR COALESCE(jsonb_typeof(p_address), 'null') <> 'object' THEN
    RAISE EXCEPTION '% must be an address object', p_label;
  END IF;

  IF NULLIF(btrim(COALESCE(p_address->>'line1', '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_address->>'city', '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_address->>'state', '')), '') IS NULL
     OR NULLIF(v_postal, '') IS NULL
     OR NULLIF(btrim(COALESCE(p_address->>'country', '')), '') IS NULL THEN
    RAISE EXCEPTION '% must include line 1, city, state, postal code, and country', p_label;
  END IF;

  IF v_country IN ('us', 'usa', 'united states', 'united states of america')
     AND v_postal !~ '^\d{5}(-?\d{4})?$' THEN
    RAISE EXCEPTION '% postal code is invalid', p_label;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."validate_onboarding_address_payload"("p_address" "jsonb", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_onboarding_hierarchy_payload"("p_hierarchy" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_org_name text;
  v_brand_name text;
  v_location_name text;
  v_org_address jsonb;
  v_org_mailing jsonb;
  v_brand_address jsonb;
  v_location_business jsonb;
  v_location_mailing jsonb;
BEGIN
  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    IF v_org_name IS NULL OR NULLIF(btrim(org_item->>'slug'), '') IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    v_org_address := NULLIF(COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}'), 'null'::jsonb);
    IF v_org_address IS NOT NULL THEN
      PERFORM public.validate_onboarding_address_payload(v_org_address, 'Organization ' || v_org_name || ' business/service address');
      v_org_mailing := CASE
        WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
        ELSE NULLIF(org_item#>'{metadata,organization_mailing_address}', 'null'::jsonb)
      END;
      PERFORM public.validate_onboarding_address_payload(v_org_mailing, 'Organization ' || v_org_name || ' mailing address');
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      v_brand_address := NULLIF(brand_item#>'{metadata,brand_address}', 'null'::jsonb);
      IF v_brand_address IS NOT NULL THEN
        PERFORM public.validate_onboarding_address_payload(v_brand_address, 'Brand ' || v_brand_name || ' address');
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        v_location_business := location_item->'business_address';
        v_location_mailing := location_item->'mailing_address';
        PERFORM public.validate_onboarding_address_payload(v_location_business, 'Location ' || v_location_name || ' business/service address');
        PERFORM public.validate_onboarding_address_payload(v_location_mailing, 'Location ' || v_location_name || ' mailing address');
      END LOOP;
    END LOOP;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."validate_onboarding_hierarchy_payload"("p_hierarchy" "jsonb") OWNER TO "postgres";


