    "tax_amount" numeric(10,2),
    "currency" "text" DEFAULT 'USD'::"text",
    "source" "text" DEFAULT 'manual_upload'::"text",
    "file_url" "text",
    "line_items" "jsonb" DEFAULT '[]'::"jsonb",
    "validation_results" "jsonb" DEFAULT '{}'::"jsonb",
    "validation_notes" "text",
    "approved_by" "uuid",
    "approved_date" timestamp with time zone,
    "location" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "extraction_method" "text",
    "raw_text" "text",
    "vendor_address" "text",
    "purchase_order" "text",
    "invoice_date" "date",
    "payment_terms" "text",
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "file_destination" "text" DEFAULT 'storage'::"text",
    "purchase_order_id" "uuid",
    "matched_order_id" "uuid",
    "match_status" "text" DEFAULT 'unmatched'::"text",
    "brand_id" "uuid" NOT NULL,
    "ap_status" "text" DEFAULT 'processing'::"text" NOT NULL,
    "action_required_reason" "text",
    "action_required_details" "text",
    "assigned_reviewer_id" "uuid",
    "payment_account_id" "uuid",
    "scheduled_payment_date" "date",
    "closed_at" timestamp with time zone,
    "closed_by" "uuid",
    "ap_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "paid_amount" numeric(12,2) DEFAULT 0,
    "payment_reference" "text",
    "credit_applied" numeric(12,2) DEFAULT 0,
    "credit_reason" "text",
    "version_number" integer DEFAULT 1 NOT NULL,
    "ap_routing_destination" "text",
    "ap_routing_resolved_at" timestamp with time zone,
    "extraction_started_at" timestamp with time zone,
    "purchase_order_number" "text",
    "tenant_id" "uuid" NOT NULL,
    CONSTRAINT "invoices_ap_routing_destination_check" CHECK ((("ap_routing_destination" IS NULL) OR ("ap_routing_destination" = ANY (ARRAY['payments'::"text", 'storage'::"text", 'accounting'::"text", 'manual_paid_only'::"text"])))),
    CONSTRAINT "invoices_ap_status_check" CHECK (("ap_status" = ANY (ARRAY['processing'::"text", 'action_required'::"text", 'pending_approval'::"text", 'approved'::"text", 'scheduled'::"text", 'paid'::"text", 'closed'::"text", 'rejected'::"text"]))),
    CONSTRAINT "invoices_file_destination_check" CHECK (("file_destination" = ANY (ARRAY['storage'::"text", 'payments'::"text"]))),
    CONSTRAINT "invoices_payment_status_check" CHECK ((("payment_status" IS NULL) OR ("payment_status" = ANY (ARRAY['unpaid'::"text", 'partial'::"text", 'pending'::"text", 'paid'::"text", 'auto_pay'::"text", 'processing'::"text"])))),
    CONSTRAINT "invoices_status_check" CHECK (("status" = ANY (ARRAY['uploading'::"text", 'extracting'::"text", 'extract_failed'::"text", 'pending_review'::"text", 'validated'::"text", 'pending_approval'::"text", 'approved'::"text", 'scheduled'::"text", 'partially_paid'::"text", 'paid'::"text", 'rejected'::"text", 'duplicate'::"text", 'flagged'::"text"])))
);

