    "onboarding_status" "text" DEFAULT 'not_started'::"text",
    "onboarding_current_step" "text" DEFAULT 'business_verification'::"text",
    "onboarding_completed_at" timestamp with time zone,
    "coupon_code" "text",
    "trial_ends_at" timestamp with time zone,
    "business_email" "text",
    "business_email_verified_at" timestamp with time zone,
    "business_phone" "text",
