    CONSTRAINT "profiles_business_verification_status_check" CHECK (("business_verification_status" = ANY (ARRAY['not_started'::"text", 'pending_review'::"text", 'verified'::"text", 'failed'::"text", 'rejected'::"text"]))),
    CONSTRAINT "profiles_hierarchy_review_status_check" CHECK ((("hierarchy_review_status" IS NULL) OR ("hierarchy_review_status" = ANY (ARRAY['pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'failed'::"text"])))),
    CONSTRAINT "profiles_onboarding_status_check" CHECK (("onboarding_status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'blocked'::"text"]))),
    CONSTRAINT "profiles_payment_method_type_check" CHECK ((("payment_method_type" IS NULL) OR ("payment_method_type" = ANY (ARRAY['card'::"text", 'ach'::"text", 'free_plan'::"text", 'mock_subscription'::"text", 'stripe_subscription'::"text", 'trial_coupon'::"text"])))),
    CONSTRAINT "profiles_role_check" CHECK (("role" = ANY (ARRAY['ground_staff'::"text", 'location_manager'::"text", 'branch_manager'::"text", 'org_manager'::"text", 'tenant_super_admin'::"text", 'platform_admin'::"text"]))),
    CONSTRAINT "profiles_tax_identifier_type_check" CHECK ((("tax_identifier_type" IS NULL) OR ("tax_identifier_type" = ANY (ARRAY['ein'::"text", 'ssn'::"text"])))),
    CONSTRAINT "profiles_username_format_check" CHECK ((("username" IS NULL) OR ("username" ~ '^[a-z0-9_]{3,24}$'::"text")))
);

