CREATE OR REPLACE VIEW "public"."health_monitor" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."organizations") AS "total_orgs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."profiles") AS "total_users",
    ( SELECT "count"(*) AS "count"
           FROM "public"."invoices") AS "total_invoices",
    "public"."get_auth_role"() AS "active_role",
    "public"."get_auth_org"() AS "active_org_id";


ALTER VIEW "public"."health_monitor" OWNER TO "postgres";


