         SELECT "i"."id",
            "i"."organization_id",
            "i"."brand_id",
            "i"."location_id",
            "i"."tenant_id",
            "i"."invoice_number",
            "i"."vendor_name",
            "i"."status",
            "i"."ap_status",
            "i"."payment_status",
            "i"."paid_amount",
            "i"."total_amount",
                CASE
                    WHEN (("i"."status" = 'rejected'::"text") AND (COALESCE("i"."payment_status", 'unpaid'::"text") = ANY (ARRAY['partial'::"text", 'paid'::"text", 'auto_pay'::"text", 'processing'::"text"]))) THEN 'rejected_invoice_has_payment_state'::"text"
                    WHEN (("i"."status" = 'rejected'::"text") AND (COALESCE("i"."paid_amount", (0)::numeric) > (0)::numeric)) THEN 'rejected_invoice_has_paid_amount'::"text"
                    WHEN (("i"."status" = 'approved'::"text") AND ("i"."ap_status" IS DISTINCT FROM 'approved'::"text")) THEN 'approved_status_ap_status_desync'::"text"
                    WHEN (("i"."status" = 'scheduled'::"text") AND ("i"."ap_status" IS DISTINCT FROM 'scheduled'::"text")) THEN 'scheduled_status_ap_status_desync'::"text"
                    WHEN (("i"."status" = 'paid'::"text") AND (("i"."ap_status" IS DISTINCT FROM 'paid'::"text") OR ("i"."payment_status" IS DISTINCT FROM 'paid'::"text"))) THEN 'paid_status_desync'::"text"
                    WHEN (("i"."status" = 'rejected'::"text") AND ("i"."ap_status" IS DISTINCT FROM 'rejected'::"text")) THEN 'rejected_status_ap_status_desync'::"text"
                    ELSE NULL::"text"
                END AS "anomaly_type",
            "i"."updated_at"
           FROM "public"."invoices" "i"
          WHERE ("i"."deleted_at" IS NULL)
        )
 SELECT "a"."id",
    "a"."organization_id",
    "a"."brand_id",
    "a"."location_id",
    "a"."tenant_id",
    "a"."invoice_number",
    "a"."vendor_name",
    "a"."status",
    "a"."ap_status",
    "a"."payment_status",
    "a"."paid_amount",
    "a"."total_amount",
    "a"."anomaly_type",
    "latest_review"."decision" AS "latest_review_decision",
    "latest_review"."created_at" AS "latest_reviewed_at",
    "a"."updated_at"
   FROM ("invoice_anomalies" "a"
     LEFT JOIN LATERAL ( SELECT "r"."decision",
            "r"."created_at"
           FROM "public"."invoice_anomaly_reviews" "r"
          WHERE (("r"."invoice_id" = "a"."id") AND ("r"."anomaly_type" = "a"."anomaly_type"))
          ORDER BY "r"."created_at" DESC
         LIMIT 1) "latest_review" ON (true))
  WHERE (("a"."anomaly_type" IS NOT NULL) AND (COALESCE("latest_review"."decision", ''::"text") <> ALL (ARRAY['accepted_historical'::"text", 'finance_cleanup_requested'::"text"])));


ALTER VIEW "public"."invoice_production_anomalies" OWNER TO "postgres";


