    "provider" "text" NOT NULL,
    "provider_fee_type" "text" DEFAULT 'other'::"text" NOT NULL,
    "base_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "provider_fee_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "platform_markup_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "total_fee_amount" numeric(12,2) GENERATED ALWAYS AS (("provider_fee_amount" + "platform_markup_amount")) STORED,
    "total_debit_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "fee_formula" "text",
    "fee_policy_id" "uuid",
    "contract_version" "text",
    "displayed_to_user_at" timestamp with time zone,
    "accepted_by_user_id" "uuid",
    "accepted_by_user_at" timestamp with time zone,
    "provider_balance_transaction_ref" "text",
    "provider_reported_fee_amount" numeric(12,2),
    "reconciliation_status" "text" DEFAULT 'expected'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "payment_fee_events_fee_paid_by_check" CHECK (("fee_paid_by" = ANY (ARRAY['client'::"text", 'vendor'::"text", 'platform'::"text"]))),
    CONSTRAINT "payment_fee_events_payer_type_check" CHECK (("payer_type" = ANY (ARRAY['client'::"text", 'vendor'::"text", 'platform'::"text"]))),
    CONSTRAINT "payment_fee_events_provider_fee_type_check" CHECK (("provider_fee_type" = ANY (ARRAY['ach_debit'::"text", 'connect_payout'::"text", 'bank_validation'::"text", 'failed_payment'::"text", 'dispute'::"text", 'active_account'::"text", 'other'::"text"]))),
    CONSTRAINT "payment_fee_events_reconciliation_status_check" CHECK (("reconciliation_status" = ANY (ARRAY['expected'::"text", 'matched'::"text", 'mismatch'::"text", 'adjusted'::"text"])))
);

