ALTER TABLE "public"."payment_fee_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."payment_fee_counters" AS
 SELECT "tenant_id",
    "organization_id",
    "brand_id",
    "location_id",
    "provider",
    ("date_trunc"('month'::"text", "created_at"))::"date" AS "month",
    (COALESCE("sum"("total_fee_amount") FILTER (WHERE ("fee_paid_by" = 'client'::"text")), (0)::numeric))::numeric(12,2) AS "total_fees_charged_to_clients",
    (COALESCE("sum"("total_fee_amount") FILTER (WHERE ("fee_paid_by" = 'platform'::"text")), (0)::numeric))::numeric(12,2) AS "total_fees_paid_by_platform",
    (COALESCE("sum"("provider_fee_amount"), (0)::numeric))::numeric(12,2) AS "total_provider_fees",
    ((COALESCE("sum"("total_fee_amount") FILTER (WHERE ("fee_paid_by" = 'client'::"text")), (0)::numeric))::numeric(12,2) - (COALESCE("sum"("provider_fee_amount"), (0)::numeric))::numeric(12,2)) AS "net_fee_recovery",
    "count"(*) AS "fee_event_count"
   FROM "public"."payment_fee_events"
  GROUP BY "tenant_id", "organization_id", "brand_id", "location_id", "provider", (("date_trunc"('month'::"text", "created_at"))::"date");


ALTER VIEW "public"."payment_fee_counters" OWNER TO "postgres";


