ALTER TABLE "public"."tenant_registry" OWNER TO "postgres";


COMMENT ON TABLE "public"."tenant_registry" IS 'Historical shared-public tenancy registry. Legacy schema-per-tenant schemas were archived into public.tenant_schema_retirement_archive and dropped.';



COMMENT ON COLUMN "public"."tenant_registry"."schema_name" IS 'Deprecated. Null after schema-per-tenant retirement; prior schema names are retained in metadata.retired_schema_name.';



COMMENT ON COLUMN "public"."tenant_registry"."status" IS 'Provisioning lifecycle: planned, provisioning, active, migrating, failed, archived.';



COMMENT ON COLUMN "public"."tenant_registry"."read_mode" IS 'Core default is public. tenant_schema/dual are deprecated migration states and must not be used for new tenants.';



COMMENT ON COLUMN "public"."tenant_registry"."write_mode" IS 'Core default is public. tenant_schema/dual are deprecated migration states and must not be used for new tenants.';



