COMMENT ON COLUMN "public"."vendors"."file_routing_preference" IS 'Default destination for files related to this vendor (storage or payments)';



COMMENT ON COLUMN "public"."vendors"."ap_routing_preference" IS 'Controls where newly approved invoices from this vendor route: payments, storage, accounting, or manual_paid_only.';



CREATE OR REPLACE VIEW "public"."vw_slow_queries" WITH ("security_invoker"='true') AS
 SELECT "calls",
    "round"((("total_exec_time" / ("calls")::double precision))::numeric, 2) AS "avg_time_ms",
    "round"(("total_exec_time")::numeric, 2) AS "total_time_ms",
    "round"(((((100)::double precision * "total_exec_time") / "sum"("total_exec_time") OVER ()))::numeric, 2) AS "percentage_overall",
    "query"
   FROM "extensions"."pg_stat_statements"
  WHERE (("calls" > 100) AND (("total_exec_time" / ("calls")::double precision) > (50)::double precision))
  ORDER BY ("round"((("total_exec_time" / ("calls")::double precision))::numeric, 2)) DESC
 LIMIT 50;


ALTER VIEW "public"."vw_slow_queries" OWNER TO "postgres";


